window.CNB_DATA=window.CNB_DATA||{};window.CNB_DATA["inv"]={"key":"inv","title":"Investiční zprostředkovatel","topics":["Právní úprava a dohled kapitálového trhu","Fondy kolektivního investování","Finanční trh a finanční matematika","Dluhopisy a peněžní trh","Akcie a akciové trhy","Deriváty","Ochrana investora a pravidla jednání","Portfolio, riziko a investiční strategie","Právní základy","Daně","Ostatní"],"questions":[{"id":"19359.1","t":"s","q":"Finanční trh je nedílnou součástí:","o":["Peněžního trhu.","Kapitálového trhu.","Trhu s cizími měnami.","Finančního systému."],"c":[3],"p":1,"e":"Finanční trh sestává z peněžního trhu, kapitálového trhu, trhu s cizími měnami a trhu drahých kovů a je nedílnou součástí finančního systému ekonomiky.","tp":2},{"id":"19360.1","t":"s","q":"Trh cenných papírů slouží:","o":["K nákupu a prodeji výhradně krátkodobých cenných papírů.","K nákupu a prodeji výhradně dlouhodobých cenných papírů.","K nákupu a prodeji krátkodobých a dlouhodobých cenných papírů.","K nákupu a prodeji drahých kovů."],"c":[2],"p":1,"e":"Trh cenných papírů zahrnuje krátkodobé cenné papíry obchodované na peněžním trhu, ale i dlouhodobé obchodované na kapitálovém trhu.","tp":0},{"id":"19361.1","t":"s","q":"Finanční trh napomáhá:","o":["Rozkládat riziko na velké množství pojištěnců.","Vracet nevyužité peníze (úspory) zpět do ekonomického systému a tím podporovat ekonomický růst.","Potlačovat korupci.","Vytvářet právní řád."],"c":[1],"p":1,"e":"Finanční trhy umožňují, aby finanční systém začleňoval do peněžního okruhu ekonomického systému volné (nevyužívané) peněžní prostředky. Jeho prvotním posláním tudíž není ani pojišťování rizik, ani vytváření právního řádu a ani boj proti korupci.","tp":2},{"id":"19362.1","t":"s","q":"Finanční trhy:","o":["Umožňují rozkládat riziko na velké množství pojištěnců.","Jsou nedílnou součástí jim nadřazeného kapitálového trhu.","Transformují peněžní přebytky na různé druhy finančních nároků, čímž umožňují přeměnu dnešních příjmů na předpokládané vyšší příjmy budoucí.","Jsou nedílnou součástí jim nadřazeného peněžního trhu."],"c":[2],"p":1,"e":"Finanční trhy transformují peněžní přebytky na různé druhy finančních nároků, čímž umožňují přeměnu dnešních příjmů na předpokládané vyšší příjmy budoucí. To znamená, že se na nich obchodují finanční investiční nástroje a jejich nedílnou součástí jsou proto také peněžní a kapitálové trhy; nikoli však pojistný trh.","tp":2},{"id":"19363.1","t":"s","q":"Hotovostní peníze:","o":["Nesou běžný výnos.","Nelze je považovat za kapitál (resp. investiční nástroj či investiční instrument), protože nenesou výnos.","Nesou kapitálový výnos.","Nesou běžný i kapitálový výnos."],"c":[1],"p":2,"e":"Peníze nenesou výnos a tudíž nejde o kapitál, na který je lze ovšem přeměnit jejich investováním. Proto jejich držbou nemohou jejich vlastníci získat ani běžný, ani kapitálový výnos.","tp":2},{"id":"19364.1","t":"s","q":"Na peněžním trhu se na rozdíl od trhu kapitálového obchodují:","o":["Výhradně majetkové cenné papíry.","Výhradně dluhové cenné papíry.","Výhradně dlouhodobé cenné papíry.","Výhradně dlouhodobé úvěry."],"c":[1],"p":2,"e":"Peněžní trh je ve srovnání s trhem kapitálovým krátkodobým trhem, na kterém se obchodují cenné papíry a úvěry se splatností do jednoho roku. Z cenných papírů se jedná výhradně o dluhové cenné papíry (směnky, státní pokladniční poukázky).","tp":2},{"id":"19365.2","t":"s","q":"Depozitní funkce finančního trhu:","o":["Umožňuje ekonomickým subjektům získávat potřebné volné peněžní prostředky.","Umožňuje provádění finančních investic, neboli přeměnu peněz na finanční kapitál.","Poskytuje ekonomickým subjektům ochranu před kreditním rizikem.","Umožňuje ekonomickým subjektům platit, neboli obchodovat."],"c":[1],"p":2,"e":"Depozitní funkce finančního systému umožňuje ekonomickým subjektům provádět finanční investice, neboli přeměňovat peníze na finanční kapitál. Vedle ní však finanční systém plní celou řadu dalších funkcí, jako jsou funkce kreditní (umožňující získat potřebné peněžní zdroje), funkce uchování bohatství, funkce ochrany proti riziku, funkce platební, funkce likvidity nebo funkce politická (regulační). Přesto, že všechny funkce finančního systému funkčně částečně souvisejí, tak je ekonomická teorie definuje každou samostatně a každou jinak. Depozitní funkce umožňuje ekonomickým subjektům ukládat (investovat) přebytečnou likviditu, nicméně nechrání klienta před kreditním rizikem.","tp":2},{"id":"19366.1","t":"s","q":"Kreditní funkce finančního trhu:","o":["Snižuje riziko podnikání.","Umožňuje ekonomickým subjektům uchovávat své bohatství v likvidní formě.","Umožňuje provádění finančních investic, neboli přeměnu peněz na finanční kapitál.","Umožňuje ekonomickým subjektům získávat potřebné volné peněžní prostředky."],"c":[3],"p":2,"e":"Kreditní funkce finančního systému umožňuje ekonomickým subjektům získávat potřebné volné peněžní prostředky. Netýká se však ani snižování podnikatelských rizik, ani investování a způsobů či možností placení.","tp":2},{"id":"19368.1","t":"s","q":"Nejvyšší stupeň likvidity vykazují:","o":["Směnky.","Akcie.","Peněžní prostředky (resp. oběživo).","Dluhopisy."],"c":[2],"p":2,"e":"Peněžní prostředky jsou nejlikvidnějším finančním aktivem vůbec. Na rozdíl od nich finanční investiční nástroje sice poskytují investorům výnosy, ale žádný z nich nemá takovou likviditu jako peníze.","tp":2},{"id":"19370.1","t":"s","q":"Finanční systém:","o":["Je vždy nedílnou součástí některého ekonomického systému (neboli ekonomiky).","Je nedílnou součástí kapitálového trhu.","Je nedílnou součástí finančního trhu.","Je nedílnou součástí peněžního trhu."],"c":[0],"p":3,"e":"Každý finanční systém je vždy nedílnou součástí některého systému ekonomického. A jelikož je jeho nedílnou součástí trh finanční, tak do něj logicky spadají i trh peněžní a trh kapitálový.","tp":2},{"id":"19375.1","t":"s","q":"Běžný výnos spojený s vlastnictvím investičního nástroje lze chápat jako:","o":["Výnos plynoucí z obchodování spočívající v rozdílu jeho kupní a prodejní ceny.","Cash flow plynoucí z jeho vlastnictví.","Výnos po odpočtu inflace.","Výnos po odpočtu vynaložených investičních nákladů a daní."],"c":[1],"p":3,"e":"Z vlastnictví finančních investičních nástrojů plynou investorům běžné výnosy (např. úrok či dividendy). Jde o \"cash flow\" (neboli nominální výnosy) plynoucí z jejich držby, neboli z \"vlastnictví\" investorem. Z toho vyplývá, že běžné výnosy nezávisejí na obchodovatelnosti či neobchodovatelnosti předmětných investičních instrumentů.","tp":2},{"id":"19376.1","t":"s","q":"Kapitálový výnos získaný z investičního nástroje (instrumentu) lze chápat takto:","o":["Jedná se o cash flow plynoucí z jeho držby.","Jde o celkový výnos po odpočtu vynaložených investičních nákladů a daní.","Jde o celkový výnos po odpočtu inflace.","Jde o výnos z obchodování investičního nástroje plynoucí z rozdílu jeho kupní a prodejní ceny."],"c":[3],"p":3,"e":"Jde o výnos, jež lze získat pouze z obchodovatelných investičních nástrojů (instrumentů) spočívající v rozdílu jejich kupních a prodejních cen.","tp":2},{"id":"19377.1","t":"s","q":"Celkový (nominální) výnos získaný z investičního instrumentu lze chápat takto:","o":["Jde o poměr součtu všech výnosů za určité období vůči vynaloženým nákladům.","Jde o součet jednotlivých běžných výnosů a výnosu kapitálového za určité období.","Jde o výnos plynoucí z rozdílu jeho kupní a prodejní ceny.","Jde o kapitálový výnos po odpočtu inflace."],"c":[1],"p":3,"e":"Celkový výnos lze obecně chápat jako součet jednotlivých běžných výnosů plynoucích z předmětného investičního instrumentu a výnosu kapitálového (pokud se investiční instrument prodal) za určité období. Podrobněji lze ovšem rozlišovat výnosy nominální a reálné (po odpočtu vynaložených nákladů), resp. výnosy nominální a reálné (po odpočtu vlivu inflace).","tp":2},{"id":"19378.1","t":"s","q":"S rostoucí inflací (nad nominální úrokovou míru):","o":["Reálná úroková míra klesá.","Kupní síla peněz se zvyšuje.","Nominální úroková míra klesá pod reálnou úrokovou míru.","Nemohou být reálné výnosy nikdy záporné."],"c":[0],"p":3,"e":"Inflace snižuje reálné výnosy investora a v případě nízkých nominálních úrokových sazeb a vyšší inflace může být reálný výnos i záporný. Jinými slovy to znamená, že inflace snižuje kupní sílu peněz, přičemž její vliv může být dokonce tak silný, že převýší (nominální) výnosy plynoucí z investice.","tp":2},{"id":"19379.1","t":"s","q":"Vnitřní hodnotu cenného papíru lze chápat takto:","o":["Je to kurz.","Jde o tržní cenu.","Jde o tzv. teoretickou (spravedlivou) hodnotu podle vlastního přesvědčení investora.","Jde o tržní cenu jež vzniká na organizovaných trzích."],"c":[2],"p":4,"e":"Vnitřní hodnota představuje spravedlivou teoretickou hodnotu cenného papíru podle přesvědčení konkrétního investora, jež vzniká na základě jím provedené fundamentální analýzy. Naproti tomu kurzy (resp. tržní ceny) cenných papírů vznikají na základě střetu agregované nabídky a poptávky, takže představují tržní ocenění cenných papírů (neboli ceny, za které se cenné papíry skutečně obchodují).","tp":0},{"id":"19380.1","t":"s","q":"Lze považovat současnou hodnotu investičního nástroje za jeho vnitřní hodnotu?","o":["Ano, pokud ji investor (resp. analytik) za vnitřní hodnotu považuje.","V žádném případě.","Nikoli, za vnitřní hodnotu lze považovat pouze aktuální kurz.","Záleží to na legislativě příslušného státu."],"c":[0],"p":4,"e":"Vnitřní hodnotu investičního nástroje lze chápat jako teoretickou \"spravedlivou\" hodnotu dle vlastního přesvědčení investora.","tp":2},{"id":"19381.1","t":"s","q":"Čistou současnou hodnotou investičního nástroje rozumíme:","o":["Roční výnos dosažený z investičního nástroje po odpočtu daní.","Současnou hodnotu investičního nástroje po odpočtu inflace.","Současnou hodnotu investičního nástroje po odpočtu investičních nákladů.","Aktuální tržní cenu investičního nástroje po odpočtu investičních nákladů."],"c":[2],"p":4,"e":"Čistá současná hodnota investice vyjadřuje rozdíl mezi součtem diskontovaných peněžních příjmů získaných za dobu jejího trvání a náklady na její pořízení.","tp":2},{"id":"19382.2","t":"s","q":"S růstem požadované výnosnosti investice:","o":["Klesá její riziko.","Roste její riziko.","Klesá její likvidita.","Roste její likvidita."],"c":[1],"p":4,"e":"Dle základního investičního trojúhelníku pokud požaduje investor vyšší výnos, musí být ochoten podstoupit vyšší míru rizika. Na druhou stranu nelze tvrdit, že s růstem výnosu roste či klesá likvidita investice.","tp":2},{"id":"19383.2","t":"s","q":"Likviditu finančních investičních instrumentů lze chápat jako:","o":["Rychlost, s níž lze finančně investiční instrument přeměnit na hotové peníze.","Míru volatility finančních investičních nástrojů.","Schopnost emitenta dostát svým závazkům.","Rychlost vypořádání burzovních obchodů."],"c":[0],"p":4,"e":"Likviditou lze rozumět rychlost, s jakou lze předmětný investiční instrument bezeztrátově přeměnit zpět na peníze.","tp":2},{"id":"19384.2","t":"s","q":"Přepočet (resp. převod) současné hodnoty (např. bankovního vkladu) na jeho budoucí hodnotu se označuje jako:","o":["Diskontování.","Odúročení.","Úročení.","Hedging."],"c":[2],"p":5,"e":"Přepočet (převod) současné hodnoty (např. bankovního vkladu) na jeho budoucí hodnotu se v teorii i v praxi označuje jako úročení, jehož opakem je odúročení, či diskontování. A pokud jde o hedging (zajištění), tak ten nemá s přepočtem současné hodnoty na budoucí hodnotu nic společného.","tp":2},{"id":"19385.1","t":"s","q":"Diskontováním se rozumí:","o":["Přepočet budoucích cash flow plynoucích z investičního nástroje v jednotlivých letech na současnou hodnotu.","Přepočet nominální hodnoty investičních nástrojů na hodnotu reálnou.","Přepočet současných cash flow plynoucích z investičního nástroje na budoucí hodnotu.","Složené úročení cash flow plynoucích z investičního nástroje v jednotlivých letech na budoucí hodnotu."],"c":[0],"p":5,"e":"Diskontováním rozumíme přepočet budoucích cash flow plynoucích z investičního nástroje v jednotlivých letech na současnou hodnotu.","tp":2},{"id":"19386.1","t":"s","q":"Je-li čistá současná hodnota cenného papíru podstatně vyšší než nula (je výrazně plusová):","o":["Je vhodné cenný papír prodat.","Je vhodné cenný papír koupit.","Je nutno cenný papír urychleně prodat.","Cenný papír se jeví jako příliš drahý."],"c":[1],"p":5,"e":"Je-li čistá současná hodnota cenného papíru podstatně vyšší než nula, jeví se podle této metody cenný papír jako podhodnocený a tudíž vhodný ke koupi.","tp":0},{"id":"19391.1","t":"s","q":"Budoucí hodnota 3leté investice ve výši P = 30 000 Kč (současná hodnota) je při úrokové sazbě r = 4 % p. a. a při použití složeného úročení rovna:","o":["32 438,67 Kč.","32 983,56 Kč.","33 745,92 Kč.","34 672,78 Kč."],"c":[2],"p":5,"e":"Budoucí hodnota FV se vypočte při použití složeného úročení ze vztahu FV = P (1+r)^n, kde n je počet let.","tp":2},{"id":"19392.1","t":"s","q":"Současná hodnota částky FV = 20 000 Kč (budoucí hodnota) je pro 4letou investici při úrokové sazbě r = 3 % p. a. a při použití složeného úročení rovna:","o":["17 189,12 Kč.","17 355,98 Kč.","17 575,22 Kč.","17 769,74 Kč."],"c":[3],"p":5,"e":"Současná hodnota PV se vypočte při použití složeného úročení ze vztahu PV = FV/(1+r)^n, kde n je počet let.","tp":2},{"id":"19393.1","t":"s","q":"Budoucí hodnota 4leté investice ve výši P = 50 000 Kč (současná hodnota) je rovna FV = 55 000 Kč. Výnosnost (v %) této investice je při použití jednoduchého úročení rovna:","o":["2 % p. a.","2,5 % p. a.","3 % p. a.","3,5 % p. a."],"c":[1],"p":6,"e":"Výnosnost y se vypočte při použití jednoduchého úročení ze vztahu FV = P (1+y.n), kde n je počet let.","tp":2},{"id":"19394.1","t":"s","q":"Budoucí hodnota 5leté investice ve výši P = 20 000 Kč (současná hodnota) je při úrokové sazbě r = 1 % p. a. a při použití složeného úročení rovna:","o":["21 020,20 Kč.","21 132,63 Kč.","21 187,15 Kč.","21 284,45 Kč."],"c":[0],"p":6,"e":"Budoucí hodnota FV se vypočte při použití složeného úročení ze vztahu FV = P (1+r)^n, kde n je počet let.","tp":2},{"id":"19395.1","t":"s","q":"Současná hodnota částky FV = 100 000 Kč (budoucí hodnota) je pro 5letou investici při úrokové sazbě r = 2 % p. a. a při použití složeného úročení rovna:","o":["88 912,79 Kč.","89 454,15 Kč.","90 573,08 Kč.","91 973,81 Kč."],"c":[2],"p":6,"e":"Současná hodnota PV se vypočte při použití složeného úročení ze vztahu PV = FV/(1+r)^n, kde n je počet let.","tp":2},{"id":"19396.1","t":"s","q":"Budoucí hodnota 3leté investice ve výši P = 30 000 Kč (současná hodnota) je rovna FV = 34 000 Kč. Výnosnost této investice je při použití složeného úročení rovna:","o":["3,78 % p. a.","4,03 % p. a.","4,26 % p. a.","4,88 % p. a."],"c":[2],"p":6,"e":"Výnosnost y se vypočte při použití složeného úročení ze vztahu FV = P (1+y)^n, kde n je počet let.","tp":2},{"id":"19397.1","t":"s","q":"Budoucí hodnota 2leté investice ve výši P = 20 000 Kč (současná hodnota) je rovna FV = 22 000. Anualizovaná výnosnost této investice je při použití jednoduchého úročení rovna:","o":["2,50 % p. a.","5 % p. a.","7,5 % p. a.","10 % p. a."],"c":[1],"p":6,"e":"Budoucí hodnota FV se vypočte při použití jednoduchého úročení ze vztahu FV = P (1+r.n), kde n je počet let.","tp":2},{"id":"19398.2","t":"s","q":"Současná hodnota částky FV = 384 000 Kč (budoucí hodnota) je pro 4letou investici při úrokové sazbě r = 5 % p. a. a při použití jednoduchého úročení rovna:","o":["320 000 Kč.","340 000 Kč.","360 000 Kč.","380 000 Kč."],"c":[0],"p":7,"e":"Současná hodnota PV se vypočte při použití jednoduchého úročení ze vztahu PV = FV/(1+r.n), kde n je počet let","tp":2},{"id":"19399.1","t":"s","q":"Poměr sumy leasingových splátek a pořizovací ceny předmětu leasingu se nazývá:","o":["Leasingové ažio.","Leasingový multiplikátor.","Leasingový výnos.","Leasingový koeficient."],"c":[3],"p":7,"e":"Leasingový koeficient je definován jako poměr sumy splátek a pořizovací ceny, ostatní pojmy (leasingové ažio, leasingový multiplikátor a leasingový výnos) jsou uměle vytvořené a v těchto spojeních se nepoužívají.","tp":2},{"id":"19400.1","t":"s","q":"Roční splátka u 3letého leasingu s nulovým navýšením je rovna 800 000 Kč. Při pořizovací ceně P = 3 000 000 Kč byla akontace ve výši:","o":["0,1.","0,15.","0,2.","0,25."],"c":[2],"p":7,"e":"V případě leasingu s nulovým navýšením je součet leasingových splátek a akontace roven pořizovací ceně předmětu leasingu. Součet leasingových splátek je roven 2 400 000, a tedy akontace je rovna 600 000 Kč, což činí 20 % z pořizovací ceny.","tp":2},{"id":"19401.3","t":"s","q":"Leasingový koeficient u 10letého leasingu je roven LK = 1,40 při pořizovací ceně P = 500 000 Kč. Výše roční splátky bude ve výši:","o":["50 000 Kč.","70 000 Kč.","100 000 Kč.","140 000 Kč."],"c":[1],"p":7,"e":"Celkově zaplacená suma v 10 splátkách je dána součinem pořizovací ceny a leasingového koeficientu, tedy 500 000 . 1,4 = 700 000 Kč - proto výše jedné splátky je 70 000 Kč (= 700 000 /10)","tp":2},{"id":"19402.1","t":"s","q":"Výše roční leasingové splátky u 5letého leasingu je rovna 300 000 Kč při celkové pořizovací ceně P = 1 200 000 Kč. Leasingový koeficient je roven:","o":["0,25.","0,6.","1,25.","1,5."],"c":[2],"p":7,"e":"Leasingový koeficient je definován jako poměr sumy splátek a pořizovací ceny zboží, tedy LK = 1 500 000 / 1 200 000 = 1,25.","tp":2},{"id":"19408.1","t":"s","q":"Na kapitálovém trhu se obchodují:","o":["Dlouhodobé finanční investiční nástroje.","Cizí měny.","Drahé kovy.","Krátkodobé finanční investiční nástroje."],"c":[0],"p":8,"e":"Na kapitálovém trhu se obchodují dlouhodobé finanční investiční nástroje se splatností delší než jeden rok.","tp":2},{"id":"19409.1","t":"s","q":"Investiční cenné papíry lze z ekonomického (nikoli však z právního) hlediska chápat takto:","o":["Jde o zvláštní komoditu.","Jedná se o převoditelné, a tudíž obchodovatelné finanční investiční nástroje.","Jde o specifické druhy kryptoměn.","Jedná se o jiný název (synonyma) finančních nástrojů."],"c":[1],"p":8,"e":"Jedná se o převoditelné, a tudíž i obchodovatelné finanční investiční nástroje, jež jsou právními dokumenty, které investorům přisuzují příslušná, s nimi spojená práva.","tp":0},{"id":"19410.1","t":"s","q":"Valutový trh je součástí:","o":["Devizového trhu.","Trhu s cizími měnami.","Peněžního trhu.","Kapitálového trhu."],"c":[1],"p":8,"e":"Valuty představují hotovostní formu cizích měn. Valutové trhy tak společně s trhy devizovými tvoří trh s cizími měnami.","tp":2},{"id":"19411.1","t":"s","q":"Sekundární trh cenných papírů se vyznačuje tím, že:","o":["Umožňuje obchodovat výhradně market makerům.","Zvyšuje likviditu na něm obchodovaných emisí cenných papírů a na základě střetu agregované nabídky a poptávky se na něm vytváří \"kurz\".","Umožňuje vstup nových emisí cenných papírů na finanční trh.","Umožňuje externí financování společností prostřednictvím emitování cenných papírů."],"c":[1],"p":8,"e":"Na sekundárním trhu cenných papírů se obchodují již dříve vydané a do oběhu uvedené cenné papíry, které prodávají jejich vlastníci novým nabyvatelům.","tp":0},{"id":"19412.1","t":"s","q":"Součástí finančního trhu nejsou:","o":["Trhy dluhopisů.","Trhy pojistných instrumentů.","Akciové trhy.","Devizové trhy."],"c":[1],"p":8,"e":"Pojišťovací instrumenty nepatří mezi finanční investiční instrumenty.","tp":2},{"id":"19413.1","t":"s","q":"Na promptních (spotových) burzách cenných papírů se obchodují:","o":["Akcie.","Burzovní opce.","Futures.","Indexy."],"c":[0],"p":9,"e":"Na promptních (spotových) burzách se obchodují investiční nástroje, kdy tento obchod je vypořádán \"ihned\", resp. v čase T+2, či T+3 dle vypořádacích podmínek burzy. Na rozdíl na termínových burzách se obchodují termínové nástroje (futures, opce), kdy vlastní vypořádání obchodu na termínové burze je obdobné jako na spotových burzách, ale liší se obchodovanýcm nástrojem. proto se např. na promptní burze v Praze neobchodují futures či opce.","tp":4},{"id":"19414.2","t":"s","q":"Na termínových derivátových burzách vznikají kontrakty typu futures či opční kontrakty:","o":["Metodou tendru.","Emitováním cenných papírů.","Vypisováním.","Tzv. \"otevíráním pozic\"."],"c":[3],"p":9,"e":"Všechny \"otevřené (dlouhé a naproti tomu krátké) pozice\" eviduje po celou dobu jejich trvání clearingové centrum burzy.","tp":5},{"id":"19415.1","t":"s","q":"OTC-trhy jsou považovány za:","o":["Trhy organizované.","Trhy burzovní.","Trhy neorganizované.","Trhy státní."],"c":[2],"p":9,"e":"Jde o tzv. \"prodej přes přepážku\" nejčastěji prostřednictvím obchodních bank.","tp":2},{"id":"19416.2","t":"s","q":"Jako \"tržní kurz\" se označuje cena, jež vznikla:","o":["Na OTC-trhu.","Při smluvním obchodě.","Na organizovaném burzovním trhu.","Jednostranným vyhlášením."],"c":[2],"p":9,"e":"\"Kurz\" vzniká na organizovaných burzovních trzích na základě střetu agregované nabídky s agregovanou poptávkou.","tp":2},{"id":"19417.1","t":"s","q":"Za burzy cenných papírů jsou považovány:","o":["Sekundární veřejné neorganizované trhy.","Sekundární veřejné organizované a regulované trhy.","Primární veřejné organizované trhy.","OTC-trhy."],"c":[1],"p":9,"e":"Burzy, neboli \"organizátoři regulovaných trhů\" jsou licencovanými finančními institucemi. Jejich podnikatelskou činností je organizování trhu s investičními instrumenty, neboli agregace nabídky a poptávky na nich obchodovaných investičních instrumentů, párování zavedených objednávek (obchodních příkazů) a zabezpečení jejich vypořádání. Tato jejich činnost přispívá jednak k tvorbě transparentních tržních cen (v daném případě označovaných jako kurzy), jednak ke zvyšování likvidity trhu. Současně je ovšem zapotřebí zdůraznit, že pokud se jedná o burzy cenných papírů, tak jsou organizátory sekundárních trhu cenných papírů, což znamená, že se na nich obchoduje s již dříve vydanými cennými papíry, které prodávají jejich současní držitelé novým nabyvatelům.","tp":0},{"id":"19418.1","t":"s","q":"Měnový trh, označovaný jako \"Forex\" (foreign exchange) lze považovat za:","o":["Celosvětovou měnovou burzu.","Devizovou burzu v USA.","Instituci provozovanou Evropskou centrální bankou.","Globální mezinárodní decentralizovaný OTC-trh."],"c":[3],"p":10,"e":"Měnový trh, označovaný jako \"Forex\" je všeobecně považován za globální mezinárodní decentralizovaný OTC-trh, jenž je tvořen celosvětovou sítí elektronických komunikačních systémů, jimiž jsou vzájemně propojeny jednotlivé finanční instituce, jejichž prostřednictvím zde mohou obchodovat i všechny ostatní ekonomické subjekty.","tp":2},{"id":"19426.1","t":"s","q":"Fondy kvalifikovaných investorů:","o":["Jsou přístupné pouze institucionálním investorům.","Nesmí být v ČR nabízeny.","Jsou zvláštním typem investičních fondů, nepodléhajících přísné regulaci.","Jsou přístupné i retailovým investorům, pokud prokáží dokončené vysokoškolské vzdělání."],"c":[2],"p":10,"e":"Fondy kvalifikovaných investorů nejsou určeny pro veřejnost, nýbrž pouze pro omezený počet tzv. kvalifikovaných investorů (zpravidla pro finanční instituce či movité a odborně způsobilé jedince). Nejsou totiž přísně regulovány a dozorovány. Minimální investice jednotlivce je 1 mil. Kč.","tp":1},{"id":"19427.1","t":"s","q":"Fondy kolektivního investování rozumíme:","o":["Neregulované majetkové fondy.","Přísně regulované a dozorované fondy určené pro širokou veřejnost.","Fondy poskytující kapitálové životní pojištění.","Neregulované strukturované fondy."],"c":[1],"p":10,"e":"Fondy kolektivního investování jsou určeny pro širokou veřejnost, a proto jsou přísně regulovány a dozorovány.","tp":1},{"id":"19429.1","t":"s","q":"Brokerské společnosti, resp. činnost brokera se poskytováním svých služeb nejvíce blíží službám, které poskytuje:","o":["Obchodník s cennými papíry.","Penzijní fond.","Zajišťovna.","Podílový fond."],"c":[0],"p":10,"e":"Podnikatelskou činností brokerských a dealerských společností je obchodování s cennými papíry a dalšími druhy investičních instrumentů, jakož i provádění dalších investičních činností a služeb v rozsahu udělené licence. V ČR se označují jako obchodníci s cennými papíry.","tp":1},{"id":"19431.3","t":"s","q":"Emitentem cenných papírů může být:","o":["Pouze právnická osoba.","Pouze fyzická osoba.","Fyzická či právnická osoba.","Pouze subjekt, který získal povolení od ČNB k vydání cenného papíru."],"c":[2],"p":10,"e":"Emitentem se rozumí právnická (či případně fyzická) osoba, jež vydala (emitovala) ucelenou emisi vzájemně zastupitelných cenných papírů (z nichž vyplývají stejná práva).","tp":0},{"id":"19432.1","t":"s","q":"Investorem rozumíme ekonomický subjekt:","o":["Jenž vydal směnku.","Jenž si za své peníze koupil nějaký investiční instrument, čímž je přeměnil na kapitál.","Jenž si za své peníze zakoupil předmět dlouhodobé spotřeby.","Jenž se komerčně pojistil."],"c":[1],"p":11,"e":"Peníze se přeměňují na kapitál jejich investováním.","tp":3},{"id":"19434.1","t":"s","q":"Zajišťovnami lze rozumět finanční instituce, které se specializují na zajištění, neboli na:","o":["Hedging.","Pojišťování penzijních fondů.","Pojišťování bankovních vkladů.","Pojišťování pojišťoven."],"c":[3],"p":11,"e":"Jako zajišťovny se označují specializované pojišťovací instituce, které se specializují na poskytování zajištění, neboli na \"pojišťování pojišťoven\".","tp":1},{"id":"19439.1","t":"s","q":"Regulací rozumíme:","o":["Dohled.","Stanovení souboru závazných pravidel a norem.","Kontrolu dodržování závazných pravidel.","Státní kontrolu."],"c":[1],"p":11,"e":"Regulací lze rozumět stanovení souboru závazných pravidel a norem.","tp":0},{"id":"19440.1","t":"s","q":"Dohledem (resp. dozorem) rozumíme:","o":["Regulaci.","Finanční kontrolu.","Kontrolu dodržování obecně závazných pravidel a případné vynucování jejich plnění.","Vedení trestního řízení při objasňování kriminální činnosti."],"c":[2],"p":11,"e":"Dohledem (dozorem) lze všeobecně rozumět kontrolu dodržování obecně závazných pravidel a případné vynucování jejich plnění.","tp":0},{"id":"19442.1","t":"s","q":"V České republice existuje:","o":["Plně neintegrovaný (tzv. nejednotný) dohled na finančním trhu.","Specializovaný funkcionální systém dohledu na finančním trhu.","Plně integrovaný (tzv. jednotný) dohled na finančním trhu.","Specializovaný cílový systém dohledu na finančním trhu."],"c":[2],"p":11,"e":"V České republice existuje od roku 2006 plně integrovaný jednotný dohled, vykonávaný Českou národní bankou.","tp":0},{"id":"19443.1","t":"s","q":"Dohledová činnost:","o":["Je určena k zabraňování krachů jednotlivých finančních institucí.","Nesmí nahrazovat úlohy vlastníků a managerů.","Částečně nahrazuje vymezené činnosti orgánů činných v trestním řízení.","Částečně nahrazuje úlohy managerů finančních institucí."],"c":[1],"p":12,"e":"Dohled není určen k zabraňování krachů jednotlivých společností, nesmí nahrazovat úlohy jejich vlastníků a managerů a nesmí nahrazovat činnost orgánů činných v trestním řízení.","tp":0},{"id":"19444.1","t":"s","q":"Za vrcholové regulátory (neboli regulátory nejvyššího stupně) lze považovat:","o":["Vlády jako navrhovatele a předkladatele zákonů a zákonodárné orgány (parlamenty) jako jejich schvalovatele.","Centrální banky.","Profesní organizace.","Nejvyšší soud."],"c":[0],"p":12,"e":"Za vrcholové regulátory lze považovat vlády (či případně parlamenty) jednotlivých států, jež mají právo navrhovat a schvalovat znění zákonů v jednotlivých zemích.","tp":0},{"id":"19445.1","t":"s","q":"Samoregulace finančních institucí znamená:","o":["Zřízení útvaru interního auditu ve finanční instituci.","Zvyšování kvalifikace zaměstnanců.","Zvýšená kontrola vedoucích zaměstnanců společnosti prostřednictvím zástupců odborových organizací.","Dobrovolné členství společností v účelově vytvářených profesních organizacích."],"c":[3],"p":12,"e":"Samoregulaci finančních institucí lze chápat jako jejich dobrovolné členství v účelově vytvářených \"profesních organizacích\". Tím na sebe berou odpovědnost za dodržování jejich pravidel, zvyšují si důvěru u obchodních partnerů a získávají možnost podílet se na tvorbě nových předpisů v oblasti regulace a dohledu.","tp":0},{"id":"19447.2","t":"s","q":"Systémové riziko ve finančním systému lze chápat jako:","o":["Riziko výpadku funkčnosti výpočetní a přenosové techniky.","Riziko možného selhání celého finančního systému související s náhlou ztrátou důvěry investorů ve stabilitu finančních trhů a tím i v jednotlivé finanční instituce a finanční nástroje.","Riziko nezpracování klientova požadavku či jeho chybné zpracování.","Riziko úniku insider informations."],"c":[1],"p":12,"e":"Systémové riziko ve finančním systému představuje možnost selhání celého finančního systému související s náhlou ztrátou důvěry investorů ve stabilitu finančních trhů a tím i v jednotlivé finanční instituce a finanční nástroje. Představuje nejvýznamnější druh rizika.","tp":2},{"id":"19449.1","t":"s","q":"Výkon funkce věřitele poslední instance byl vytvořen za účelem omezení systémového rizika:","o":["V pojišťovacím sektoru.","V bankovním sektoru.","V sektoru finančních konglomerátů.","V sektoru investičních služeb."],"c":[1],"p":12,"e":"Výkon funkce věřitele poslední instance vykonávají centrální banky za účelem omezení systémového rizika v bankovním sektoru.","tp":2},{"id":"19450.2","t":"s","q":"Regulaci a dohled nad kapitálovým trhem v ČR vykonává:","o":["Komise pro cenné papíry.","Asociace pro kapitálový trh.","Česká národní banka.","Komise pro dohled nad kapitálovým trhem."],"c":[2],"p":13,"e":"Česká národní banka je podle zákona č. 6/1993 Sb., o České národní bance, orgánem vykonávajícím dohled nad finančním trhem v České republice. ČNB tedy provádí dohled nad bankovním sektorem, družstevními záložnami, kapitálovým trhem, pojišťovnictvím, penzijními společnostmi, fondy penzijních společností, směnárnami a dohled nad institucemi v oblasti platebního styku. Stanovuje pravidla, která chrání stabilitu bankovního sektoru, kapitálového trhu, pojišťovnictví a sektoru penzijních fondů. Systematicky reguluje, dohlíží a popřípadě postihuje nedodržování stanovených pravidel.","tp":0},{"id":"19455.3","t":"s","q":"Obchodník s cennými papíry je:","o":["Právnická osoba, jejíž podnikatelskou činností je poskytování investičních služeb v rozsahu od ČNB udělené licence.","Fyzická osoba (živnostník), která má jako předmět podnikání uvedeno obchodování s cennými papíry","Právnická osoba, která má v licenci od ministerstva financí uvedeno prodej a nákup cenných papírů","Fyzická osoba, která je jedním z vlastníků společnosti obchodující na základě licence ČNB"],"c":[0],"p":13,"e":"Ustanovuje § 5 odst 1.a další Zákona o podnikání na kapitálovém trhu (ZPKT), č. 256/2004 Sb., dále Oldřich Rejnuš, Finanční trhy 4. rozšířené vydání, GRADA Publishing, Praha, 2014, ISBN 978-80-247-3671-6, str. 117.","tp":0},{"id":"19456.4","t":"s","q":"Obchodník s cennými papíry je:","o":["Fyzická osoba oprávněná provádět pokyny k obchodům s investičními nástroji samostatně bez pokynu klienta na jeho účet.","Společnost oprávněná provádět obchody s inv. nástroji na pokyn a účet svých klientů, ale i např. asset management, který dělá bez pokynu zákazníka v rámci smluvního ujednání.","Společnost oprávněná provádět pokyny k obchodům s investičními nástroji pro svého klienta bez jeho pokynu na jeho účet.","Společnost oprávněná provádět pokyny k obchodům s investičními nástroji, která bez nutného pokynu klienta operuje samostatně na jeho účet."],"c":[1],"p":13,"e":"Obchodník s cennými papíry je licencovaná společnost, oprávněná provádět obchody s investičními nástroji na svůj účet nebo na základě pokynu na účet svého zákazníka.","tp":0},{"id":"19457.4","t":"s","q":"Mezi Investiční cenné papíry patří:","o":["Platební nástroje.","Cenné papíry, ze kterých nevyplývá právo na vypořádání v penězích.","Cenné papíry, které jsou obchodovatelné na kapitálovém trhu.","Depozitní poukázky nepředstavující vlastnické právo k cenným papírům."],"c":[2],"p":13,"e":"Ustanovuje tak § 3 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19458.3","t":"s","q":"Investiční společnost je právnická osoba:","o":["Jejíž hlavní náplní činnosti je kontrola aktivit depozitáře podílového fondu.","Která je považována za nedostatečného samostatného správce fondů kolektivního investování.","Která se jako obhospodařovatel majetku soustředí především na komoditní trhy.","Která vytváří a obhospodařuje podílové fondy, a nebo obhospodařuje investiční fondy na základě smlouvy o obhospodařování."],"c":[3],"p":13,"e":"Investiční společnosti jsou považovány za nejvýznamnější obhospodařovatele finančních aktiv v souladu se svou licencí.","tp":1},{"id":"19459.4","t":"s","q":"Komoditní burzy jsou charakteristické tím, že se:","o":["Na nich vždy obchoduje i s akciemi.","Na na nich obchoduje stejnorodé, neboli zaměnitelné zboží.","Uzavřené kontrakty vypořádávají v řádu dnů.","Na nich neuzavírají termínové kontrakty."],"c":[1],"p":14,"e":"Jedná se klasickou systemizaci burz podle předmětného zaměření jejich činnosti.","tp":4},{"id":"19460.5","t":"s","q":"Banka, která má příslušné povolení jí udělené Českou národní bankou, jako obchodník s cennými papíry:","o":["Může poskytovat hlavní i vedlejší investiční služby","Může poskytovat pouze vedlejší investiční služby","Může poskytovat pouze hlavní investiční služby, avšak pokud má současně i povolení k činnosti OCP, pak i doplňkové inv. služby.","Nemůže působit, tedy nesmí poskytovat žádné investiční služby"],"c":[2],"p":14,"e":"Ustanovují tak § 4 a 5 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19461.8","t":"s","q":"Vázaný zástupce investičního zprostředkovatele (VZIZ):","o":["Je oprávněn poskytovat mimo jiné přijímání a předávání pokynů, které smí poskytovat investiční zprostředkovatel, a investiční služby.","Není oprávněn poskytovat investiční služby, které smí poskytovat investiční zprostředkovatel.","Je oprávněn poskytovat investiční služby dle vlastního rozhodnutí.","Je oprávněn poskytovat investiční služby na základě zvláštního oprávnění ministerstva financí."],"c":[0],"p":14,"e":"Lze odvodit z § 4 zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., a zákona č. 240/2013 Sb., o investičních společnostech a investičních fondech. Za dvě zákonem povolené hlavní investiční služby pro vázaného zástupce investičního zprostředkovatele je považováno přijímání a předávání pokynů týkajících se investičních nástrojů a umisťování investičních nástrojů bez závazku jejich upsání.","tp":0},{"id":"19462.6","t":"s","q":"Vázaný zástupce může vykonávat činnost:","o":["Současně pro jednoho obchodníka s cennými papíry, jednoho investičního zástupce a jednu investiční společnost.","Pouze pro jednoho (včetně možné zahraniční osoby) zastoupeného - obchodníka s cennými papíry nebo investičního zástupce nebo investiční společnost.","Maximálně pro dva zastoupené z následujících - obchodníka s cennými papíry, investičního zástupce, investiční společnost.","Pro neomezený počet zastoupených z následujících - obchodníka s cennými papíry, investičního zástupce, investiční společnost."],"c":[1],"p":14,"e":"Dle zákona o podnikání na kapitálovém trhu vázaný zástupce vykonává činnosti výhradně pro jednoho zastoupeného.","tp":0},{"id":"19463.1","t":"s","q":"Investiční zprostředkovatel může vykonávat činnost:","o":["Pouze pro jeden ze subjektů, kterým je podle zákona oprávněn předávat pokyny týkající se investičních nástrojů.","Pouze pro jednoho obchodníka s cennými papíry nebo jednu investiční společnost .","Pro libovolný počet subjektů, kterým je podle zákona oprávněn předávat pokyny týkající se investičních nástrojů.","Pro obchodníka s cennými papíry, jiného investičního zprostředkovatele nebo jinou investiční společnost."],"c":[2],"p":14,"e":"Uvedeno v § 29 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19464.2","t":"s","q":"Vázaný zástupce jako fyzická osoba může poskytovat investiční poradenství:","o":["Pouze osobně.","Osobně nebo prostřednictvím investiční společnosti.","Osobně nebo prostřednictvím jiného vázaného zástupce.","Osobně nebo prostřednictvím svého zaměstnance."],"c":[3],"p":15,"e":"Podle zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., může být vázaný zástupce při jednání se zákazníkem nebo potenciálním zákazníkem v rámci poskytování investičních služeb zastoupen pouze svým pracovníkem.","tp":0},{"id":"19465.1","t":"s","q":"Investiční zprostředkovatel může poskytovat služby:","o":["Pouze na území České republiky.","Všude, kde působí poskytovatel investičních nástrojů, které zprostředkovává.","Pouze na území členských států EU.","Po předchozím oznámení ČNB kdekoliv na světě."],"c":[0],"p":15,"e":"Uvedeno v § 29 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., a § 79 Zákona č. 427/2011 Sb., o doplňkovém penzijním spoření.","tp":0},{"id":"19466.1","t":"s","q":"Vázaný zástupce investičního zprostředkovatele:","o":["Může do svého poradenství zahrnout finanční deriváty jen se souhlasem investičního zprostředkovatele.","Nesmí do svého poradenství zahrnout finanční deriváty.","Může do svého poradenství zahrnout finanční deriváty, jen pokud má příslušnou odbornou zkoušku.","Může do svého poradenství zahrnout finanční deriváty, jen pokud s tím souhlasí zákazník."],"c":[1],"p":15,"e":"Ustanovuje tak Zákon o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., §29","tp":0},{"id":"19467.3","t":"s","q":"Vázaný zástupce, který odbornost prokáže složením zkoušky \"Investiční poradce pro kolektivní investování\", může do svého poradenství zahrnout:","o":["Pouze nástroje kolektivního investování a investiční cenné papíry (akcie, dluhopisy).","Pouze nástroje kolektivního investování.","Libovolné investiční nástroje ale jen v rozsahu inv. nástrojů zastoupeného.","Pouze vybrané investiční nástroje schválené ČNB k nabízení ve státech Evropské unie."],"c":[2],"p":15,"e":"Ustanovuje tak § 29, odst.3 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb,v aktuálním znění. Viz také úřední sdělení ČNB, kterým zkoušku IPKI (Investiční poradce pro kolektivní investování) uznává pro celý rozsah nástrojů dle § 29 odst. 3 ZPKT.","tp":0},{"id":"19468.2","t":"s","q":"Vázaný zástupce musí alespoň mimo jiné splňovat podmínku:","o":["Základního vzdělání.","Vysokoškolského vzdělání.","Absolvování rekvalifikačního kurzu.","Středoškolského vzdělání s maturitou."],"c":[3],"p":15,"e":"Ustanovuje tak Zákon o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb, §29. Nutno vzít v potaz též přechodné ustanovení 14 novely ZPKT.","tp":0},{"id":"19477.9","t":"s","q":"Burzovní obchody členíme mimo jiné i z hlediska časové prodlevy ve vypořádání obchodů na obchody spotové a termínové. Spotové obchody jsou charakterizovány takto:","o":["Vypořádání těchto obchodů probíhá v řádu týdnů.","Vypořádání těchto obchodů probíhá v řádu měsíců.","Vypořádání těchto obchodů probíhá v řádu dnů.","Vypořádání těchto obchodů probíhá v řádu let."],"c":[2],"p":16,"e":"Na finančních trzích rozlišujeme druhy obchodů (a tedy i burz) podle toho, jak dalece se liší okamžik uzavření obchodu od okamžiku jeho skutečného fyzického vypořádání a jaké ostatní vlivy na obchod mohou působit.","tp":4},{"id":"19478.2","t":"s","q":"Obchody s investičními nástroji na komoditní burze typu promptní jsou charakteristické tím, že:","o":["Vypořádání probíhá na základě včasného on-line souhlasu dohledového orgánu.","Vypořádání probíhá pouze na základě včasného elektronického souhlasu prodávajícího.","Vypořádání probíhá pouze na základě včasného elektronického souhlasu kupujícího.","Vypořádání probíhá s poměrně krátkým časovým odstupem, obvykle několik málo dnů."],"c":[3],"p":16,"e":"Jde o typ obchodu v řádu T+X, kde X je počet dní, obvykle v nízkém počtu, záleží na místních zvyklostech a požadavcích obchodníků (nejde o technickou způsobilost burz v rychlosti vypořádání).","tp":4},{"id":"19479.8","t":"s","q":"Mezi zákonné požadavky na obchodníka s cennými papíry (OCP) mimo jiné patří:","o":["Pokud OCP hodlá pověřit výkonem některých činností jinou osobu, musí to uvést v plánu obchodní činnosti.","OCP může mít sídlo v jiné členské zemi mimo ČR.","OCP musí mít právní formu pouze akciové společnosti.","OCP nesmí poskytovat další služby na finančním trhu, nesouvisející s jeho hlavní náplní činnosti."],"c":[0],"p":16,"e":"Odpověď vychází ze Zákona č. 256/2004 Sb., o podnikání na kap. trhu, § 6. Správná odpověď vychází z odst. 1 písm g). Dle odst. 1 písm. b) musí mít sídlo v ČR. Dle odst. 1 písm. a) nemusí být jen akciová společnost, ale i s ručením omezeným. Dle § 6a může vykonávat i jinou podnikatelskou činnost po jejím zaregistrování ČNB.","tp":0},{"id":"19480.2","t":"s","q":"Burzy cenných papírů jsou:","o":["Ekonomické, organizační a technické systémy, působící v rámci centrálních bank na kapitálovém trhu při plnění stanovených úkolů.","Ekonomické, organizační a technické systémy, působící v rámci kapitálového trhu.","Společnosti s ručením omezeným, působící při obchodech na primárním kapitálovém trhu.","Obchodní platformy vyřizující na vlastní riziko a vlastní účet koordinované požadavky obchodníků s cennými papíry."],"c":[1],"p":16,"e":"Burzy cenných papírů je možno definovat jako relativně samostatné ekonomické a technické systémy, působící v rámci kapitálového trhu. Burzy nepůsobí v rámci centrálních bank, ani neplní zadané úkoly. Burzy představují především sekundární trh. Dle Zákona č. 256/2004 Sb., o podnikání na kap. trhu, § 41 odst. 3 písm. b) nesmí obchodovat na vlastní účet.","tp":2},{"id":"19481.2","t":"s","q":"Z hlediska předmětu obchodu se burzy obvykle rozdělují na:","o":["Burzy akciové, burzy dluhopisové a hotovostní burza.","Burzy primárních emisí, burzy sekundárních emisí, burzy clearingové.","Burzy cenných papírů, burzy devizové, burzy komoditní.","Burzy diskontovaných promptních aktiv a pákových derivátů."],"c":[2],"p":16,"e":"Burzy se dělí na burzy cenných papírů, kde se obchodují akcie a dluhopisy, burzy devizové, kde se obchodují měny a burzy komoditní, kde se obvykle obchodují termínované kontrakty na komodity. Ostatní výčty používají termíny, které se pro popisování předmětu obchodování burz nepoužívají.","tp":4},{"id":"19482.3","t":"s","q":"Propojené společnosti, které podnikají v různých oblastech finančních služeb (bankovnictví, pojišťovnictví, investiční služby) regulované dle zákona č. 377/2005 Sb. se nazývají:","o":["Bankovní skupiny.","Investiční holdingy.","Finanční kartely.","Finanční konglomeráty."],"c":[3],"p":17,"e":"Vzájemně propojená skupina společností (osob), které podnikají v různých oblastech finančních služeb (bankovnictví, pojišťovnictví, investiční služby) se nazývá finanční konglomerát. Regulace a právní úpravy, které se jich týkají jsou v Zákoně 377/2005 Sb., o Finančních konglomerátech. Ostatní odpovědi jsou buď termíny, které se nepoužívají, nebo nejsou předmětem tohoto zákona.","tp":0},{"id":"19483.3","t":"s","q":"Mezi úkoly Centrálního depozitáře cenných papírů ČR nepatří:","o":["Vést centrální evidenci cenných papírů v České republice.","Udělovat licence obchodníkům s cennými papíry pro vypořádání přeshraničních obchodů v EU.","Přidělovat cenným papírům mezinárodní identifikační označení (ISIN).","Provozovat vypořádací systém."],"c":[1],"p":17,"e":"Ustanovuje tak zákon o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., (provozovatel vypořádacího systému s neodvolatelností vypořádání) a provozní řád CDCP, a.s.","tp":0},{"id":"19484.3","t":"s","q":"Provozovatel vypořádacího systému s neodvolatelností vypořádání stanoví pravidla systému. Tato pravidla upravují alespoň:","o":["Podmínky účasti ve vypořádacím systému s neodvolatelností vypořádání, které musí být transparentní a musí obsahovat objektivní kritéria pro přístup k systému.","Okamžik, od kterého lze příkaz k vypořádání jednostranně odvolat.","Způsob a podmínky operativního rušení závazků vyplývajících z účasti ve vypořádacím systému s neodvolatelností vypořádání.","Opatření, která může provozovatel vypořádacího systému s neodvolatelností vypořádání ve stanovené lhůtě odvolat."],"c":[0],"p":17,"e":"Ustanovují tak § 85-89 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19485.1","t":"s","q":"Účet, na kterém jsou u subjektů činných v rámci investičních trhů evidovány investiční nástroje, se zpravidla nazývá:","o":["Majetkový účet.","Maržový účet.","Účet vlastníků nebo účet zákazníků.","Investiční účet."],"c":[2],"p":17,"e":"Otázka vychází ze zavedené ekonomické praxe a lze ji rovněž vyvodit z Nového občanského zákoníku, NOZ, zákon č. 89/2012 Sb.","tp":2},{"id":"19486.5","t":"s","q":"Garanční fond obchodníků s cennými papíry:","o":["Je státním fondem a vztahují se na něj právní předpisy upravující pojišťovnictví.","Garanční fond se nezapisuje do obchodního rejstříku.","Peněžní prostředky Garančního fondu nesmějí být investovány.","Přijímá příspěvky od obchodníků s cennými papíry a zajišťuje vyplácení náhrad z Garančního fondu."],"c":[3],"p":17,"e":"Postupy upravuje §128 a násl. Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19488.3","t":"s","q":"Co znamená zkratka ISIN?","o":["Zkratka pro investiční společnost s proměnným základním kapitálem.","Identifikační označení podle mezinárodního systému číslování pro identifikaci cenných papírů a zaknihovaných cenných papírů.","Zkratka na NYSE (The New York Stock Exchange) pro investiční společnosti specializované na obchodování s technologickými internetovými a informačními systémy.","Zkratka doporučená FESE (Federation of European Securities Exchanges) pro Centrální depozitář cenných papírů pro označování podílových listů určitých fondů."],"c":[1],"p":18,"e":"ISIN je zkratka pro označení emise veřejně obchodovatelných cenných papírů a znamená International Securities Identification Number. Tento mezinárodní systém je upraven normou ISO-6166. ISIN je dvanáctimístný alfanumerický kód, kde první dvě pozice představují zkratku země emitenta (CZ ? Česká republika). Tato zkratka je upravena v ISO 3166.","tp":0},{"id":"19496.1","t":"s","q":"O investičním zprostředkovateli (IZ) ohledně poskytování inv. služeb přijímání a předávání pokynů týkajících se inv. nástrojů (zprostředkování) a inv. poradenství týkající se inv. nástrojů platí:","o":["Každý IZ musí poskytovat obě dvě tyto hlavní investiční služby.","IZ smí poskytovat vždy pouze jednu z těchto dvou investičních služeb.","IZ je oprávněn poskytovat některou nebo obě dvě tyto investiční služby; žádnou jinou hlavní investiční službu však nesmí poskytovat.","IZ vždy poskytuje zprostředkování; inv. poradenství je doplňková investiční služba."],"c":[2],"p":18,"e":"Investiční zprostředkovatel je oprávněn poskytovat pouze hlavní investiční služby uvedené v § 4 odst. 2 písm. a) (přijímání a předávání pokynů týkajících se inv. nástrojů) nebo e) ZPKT (inv. poradenství), tzn. IZ je oprávněn, nikoliv povinen, poskytovat obě tyto služby.","tp":0},{"id":"19497.1","t":"s","q":"Vázaný zástupce při poskytování investičních služeb:","o":["Může vykonávat činnost samostatně bez vazby na jiný subjekt (inv. zprostředkovatele, obchodníka s cennými papíry, atp.).","Může vykonávat činnost pro více zastoupených (inv. zprostředkovatele, obchodníka s cennými papíry, atp.).","Vykonává činnost pro zastoupeného (inv. zprostředkovatele, obchodníka s cennými papíry, atp.), avšak za výkon své činnosti je klientům přímo odpovědný .","Vykonává činnost pro zastoupeného (inv. zprostředkovatele, obchodníka s cennými papíry, atp.), který odpovídá za výkon jeho činnosti vůči klientům."],"c":[3],"p":18,"e":"VZ vykonává činnost pro zastoupeného na základě uzavřené smlouvy v písemné formě, a to výhradně pro jednoho zastoupeného. Protiprávní čin, kterého se vázaný zástupce investičního zprostředkovatele dopustil vůči zákazníkovi při své činnosti, zavazuje investičního zprostředkovatele.","tp":0},{"id":"19498.1","t":"s","q":"Vázaný zástupce (fyzická osoba) smí být při jednání se zákazníkem zastoupen:","o":["Pouze svým pracovníkem (zaměstnancem).","Pracovníkem (zaměstnancem) nebo osobou působící na základě živnostenského oprávnění.","Pracovníkem (zaměstnancem) nebo vázaným zástupcem.","Investičním zprostředkovatelem."],"c":[0],"p":18,"e":"Vázaný zástupce může být při jednání se zákazníkem nebo potenciálním zákazníkem v rámci poskytování investičních služeb zastoupen pouze svým pracovníkem. V případě fyzické osoby je pracovníkem osoba, která je s jinou osobou v základním pracovněprávním vztahu.","tp":0},{"id":"19499.1","t":"s","q":"Podezřelým obchodem ve smyslu zákona č. 253/2008 Sb. (AML zákon) je situace, kdy:","o":["Klient se odmítá podrobit kontrole.","Klient užívá finanční prostředky pocházející z výher ze sázkových her.","Klient disponuje prostředky, které řádně nezdanil.","Klient požaduje sjednat investici, která neodpovídá jeho rizikovému profilu z investičního dotazníku."],"c":[0],"p":19,"e":"Podezřelým obchodem se rozumí obchod uskutečněný za okolností vyvolávajících podezření ze snahy o legalizaci výnosů z trestné činnosti nebo podezření, že v obchodu užité prostředky jsou určeny k financování terorismu. Podezřelým je obchod vždy, pokud se klient odmítá podrobit kontrole.","tp":6},{"id":"19501.3","t":"s","q":"Osoba jednající se zákazníkem, která poskytuje inv. službu investiční poradenství nezávisle:","o":["Si nesmí v souvislosti s poskytováním této služby ponechat finanční odměnu, pokud není placena klientem.","Nesmí v souvislosti s poskytováním této služby přijmout finanční odměnu pouze od klienta.","Nesmí v souvislosti s poskytováním této služby přijmout finanční odměnu pouze od poskytovatele či emitenta daného inv. nástroje.","Smí v souvislosti s poskytováním této služby přijmout finanční odměnu, avšak nesmí vést k porušení povinnosti jednat v nejlepším zájmu zákazníka a zákazník o ní musí být informován."],"c":[0],"p":19,"e":"Informuje-li osoba jednající se zákazníky zákazníka o tom, že hlavní investiční službu inv. poradenství poskytuje nezávisle, nesmí si v souvislosti s poskytováním této služby ponechat pobídku ve formě úplaty nebo jiné peněžité výhody.","tp":3},{"id":"19500.3","t":"s","q":"Osoba jednající se zákazníkem musí při poskytování inv. služeb klienta informovat o veškerých nákladech a souvisejících úplatách spojených s investicí. Ohledně obdržené provize platí, že:","o":["O ní není nutné samostatně informovat, pokud byla uhrazena ze vstupního poplatku, o jehož výši byl klient informován.","Postačí informace, že je zprostředkovatel odměňován provizně. Na žádost zákazníka je osoba jednající se zákazníka povinna doplnit o způsob výpočtu provize.","Postačí informace o způsobu výpočtu provize, i když výše provize není známa.","Informace musí obsahovat přesnou částku provize - pokud není známá před poskytnutím investiční služby, musí být uveden způsob jejího výpočtu a její přesná výše uvedena následně."],"c":[3],"p":19,"e":"Osoba jednající se zákazníky je povinna informovat zákazníka v dostatečném časovém předstihu před poskytnutím inv. služby o existenci, povaze a výši pobídky podle § 15 odst. 4, případně o způsobu jejího výpočtu, nelze-li její výši určit. Pokud nebyla schopna předem zjistit částku pobídky, kterou má přijmout nebo poskytnout, a místo toho sdělila zákazníkovi metodu výpočtu této částky, poskytne svým zákazníkům následně také informace o přesné částce platby nebo výhody, kterou přijala či poskytla.","tp":0},{"id":"19502.1","t":"s","q":"Pokud vázaný zástupce (VZ) přestane splňovat podmínky pro výkon činnosti vázaného zástupce a bez zbytečného odkladu nelze zjednat nápravu:","o":["Je VZ povinen o této skutečnosti bezodkladně informovat ČNB.","Je VZ povinen okamžitě vypovědět smlouvu se zastoupeným.","Je zastoupený povinen vypovědět vázanému zástupci smlouvu; VZ smí ve výpovědní době pouze dokončit rozjednané obchody.","Smlouva se zastoupeným zanikne ze zákona ke dni, kdy VZ přestal splňovat podmínky pro výkon činnosti."],"c":[1],"p":19,"e":"Vázaný zástupce je povinen okamžitě vypovědět závazek ze smlouvy se zastoupeným, přestane-li splňovat podmínky stanovené tímto zákonem pro činnost vázaného zástupce a nelze-li zjednat bez zbytečného odkladu nápravu; doručením výpovědi zastoupenému tento závazek zaniká. Do zjednání nápravy nesmí vázaný zástupce činnost vykonávat.","tp":0},{"id":"19503.2","t":"s","q":"Profesionální zákazník je (neuvažujte profesionálního zákazníka na žádost):","o":["Zákazník, který investuje částku převyšující 125 000 EUR, resp. její ekvivalent v příslušné měně.","Zákazník, který má dostatečné zkušenosti s investováním, jelikož působil po dobu alespoň 5 let v investiční společnosti nebo v obchodníkovi s cennými papíry.","Zákazník, který se sám za profesionálního zákazníka prohlásí a současně potvrdí, že má dostatečné znalosti a zkušenosti v oblasti investic.","Některá z osob explicitně vyjmenovaných v zákoně o podnikání na kapitálovém trhu (např. banka, pojišťovna, penzijní společnost apod.)."],"c":[3],"p":20,"e":"Profesionálním zákazníkem se rozumí osoby vyjmenované v § 2a ZPKT. Text otázky záměrně nemíří na profesionálního zákazníka na žádost dle § 2b ZPKT, které by otázku významným způsobem zkomplikovalo. Nehledě na skutečnost, že pojem profesionálního zákazníka a profesionálního zákazníka na žádost je tímto jednoznačně oddělena. Zároveň je text nesprávných odpovědí záměrně formulován takovým způsobem, aby nemohlo u uchazeče dojít k omylu, že je tázán na splnění předpokladů profesionálního zákazníka na žádost.","tp":6},{"id":"19504.2","t":"s","q":"Vázaný zástupce, který je právnickou osobou, smí poskytovat investiční služby:","o":["Pouze prostřednictvím svého statutárního orgánu.","Prostřednictvím svého statutárního orgánu nebo svého zaměstnance.","Prostřednictvím svého statutárního orgánu nebo svého vázaného zástupce.","Vázaný zástupce nemůže být právnickou osobou."],"c":[1],"p":20,"e":"Vázaný zástupce může být při jednání se zákazníkem nebo potenciálním zákazníkem v rámci poskytování investičních služeb zastoupen pouze svým pracovníkem. Právnickou osobu zastupuje její statutární orgán. Mezi pojem pracovníka řadí ZPKT ve svém § 2 odst. 1 písm. m) zejména zaměstnance, prokuristu, člena orgánu právnické osoby.","tp":0},{"id":"19505.1","t":"s","q":"Investiční zprostředkovatel smí při poskytování investičních služeb:","o":["Provádět pokyny.","Předávat pokyny.","Přijímat investiční nástroje zákazníků.","Přijímat peněžní prostředky zákazníků, za předpokladu, že je k tomu zmocněn emitentem investičního nástroje."],"c":[1],"p":20,"e":"Investiční zprostředkovatel je oprávněn poskytovat pouze hlavní investiční služby uvedené v § 4 odst. 2 písm. a) nebo e), tedy přijímání a předávání pokynů a investiční poradenství týkající se investičních nástrojů. Nesmí v souvislosti s poskytováním investičních služeb přijímat peněžní prostředky nebo investiční nástroje zákazníků.","tp":0},{"id":"19507.1","t":"s","q":"Povinnost nahradit škodu způsobenou zákazníkovi vázaným zástupcem investičního zprostředkovatele při poskytování investiční služby má:","o":["Vázaný zástupce.","Investiční zprostředkovatel.","Vázaný zástupce i investiční zprostředkovatel - podle toho, u kterého z nich zákazník nárok uplatní.","Garanční fond obchodníků s cennými papíry."],"c":[1],"p":20,"e":"Protiprávní čin, kterého se vázaný zástupce investičního zprostředkovatele dopustil vůči zákazníkovi při své činnosti, zavazuje investičního zprostředkovatele.","tp":0},{"id":"19508.1","t":"s","q":"Podmínku důvěryhodnosti přestane splňovat osoba jednající se zákazníky, která:","o":["Je pravomocně odsouzena pro úmyslný trestný čin.","Se dostane do exekuce.","Nesplní odbornou zkoušku.","Začne vykonávat činnost na finančním trhu pro jiného zastoupeného, než pod kterým je zapsána v registru vedeném ČNB."],"c":[0],"p":21,"e":"Za důvěryhodnou osobu činnou u poskytovatele investičních služeb ČNB nepovažuje osobu, která byla pravomocně odsouzena za trestný čin spáchaný úmyslně. § 197 ZKPT nijak pojem důvěryhodnosti nevysvětluje a používá obecné sousloví \"předpoklad řádného výkonu činnosti\", který vyžaduje další výklad. Vodítkem pro posouzení důvěryhodnosti pak zůstává zmíněné Úřední sdělení ČNB.","tp":0},{"id":"19509.1","t":"s","q":"Na žádost klienta může identifikaci klienta ve smyslu zákona č. 253/2008 Sb. (AML zákon) provést:","o":["Notář.","Advokát.","Soud.","Česká národní banka."],"c":[0],"p":21,"e":"Na žádost klienta nebo povinné osoby může identifikaci klienta provést notář nebo kontaktní místo veřejné správy.","tp":6},{"id":"19510.1","t":"s","q":"Zjistí-li povinná osoba ve smyslu zákona č. 253/2008 Sb., (AML zákon) v souvislosti se svou činností podezřelý obchod, oznámí to:","o":["České národní bance.","Policii ČR.","Finančnímu analytickému úřadu.","Finančnímu úřadu."],"c":[2],"p":21,"e":"Zjistí-li povinná osoba ve smyslu zákona č. 253/2008 Sb., (AML zákon) v souvislosti se svou činností podezřelý obchod, oznámí to Finančnímu analytickému úřadu.","tp":6},{"id":"19517.1","t":"s","q":"Dohled nad investičními společnostmi a investičními fondy vykonává v České republice:","o":["Komise pro cenné papíry.","Ministerstvo financí.","Česká národní banka.","Česká národní banka a ministerstvo financí."],"c":[2],"p":21,"e":"Dohled nad investičními společnostmi a investičními fondy vykonává Česká národní banka.","tp":0},{"id":"19518.1","t":"s","q":"Zaknihovaný cenný papír:","o":["Je cenný papír v listinné podobě, který se převádí rubopisem.","Je cenný papír, který je nahrazen zápisem do příslušné evidence a převádí se změnou zápisu v této evidenci.","Je cenný papír, který nelze převést.","Je historická forma cenného papíru, který se dnes už téměř nevyskytuje."],"c":[1],"p":21,"e":"Zaknihovaný cenný papír je takový cenný papír, který je nahrazen zápisem do příslušné evidence a nelze jej převést jinak než změnou zápisu v této evidenci.","tp":0},{"id":"19519.1","t":"s","q":"O dluhopisu platí:","o":["Je s ním spojeno právo na splacení dlužné částky odpovídající jeho jmenovité hodnotě.","Jde-li o korporátní dluhopis, je s ním vždy spojeno právo účasti a rozhodování na valné hromadě.","Představuje podíl na společnosti jeho emitenta.","V případě insolvence emitenta je vlastníkovi dluhopisu poskytnuta náhrada z Garančního fondu OCP."],"c":[0],"p":22,"e":"Dluhopis je cenný papír nebo zaknihovaný cenný papír vydaný podle českého práva, s nímž je spojeno právo na splacení určité dlužné částky odpovídající jmenovité hodnotě jeho emitentem, a to najednou nebo postupně k určitému okamžiku, a popřípadě i další práva plynoucí ze zákona nebo z emisních podmínek dluhopisu.","tp":3},{"id":"19520.1","t":"s","q":"Postup při vydání dluhopisu je předmětem zákona:","o":["Č. 190/2004 Sb. o dluhopisech.","Č. 591/1992 Sb. o cenných papírech.","Č. 256/2004 Sb. o podnikání na kapitálovém trhu.","Není předmětem žádného zákona, ale je upraven metodikou České národní banky."],"c":[0],"p":22,"e":"Postup při vydání dluhopisů je upraven v zákoně č. 190/2004 Sb. o dluhopisech.","tp":3},{"id":"19521.1","t":"s","q":"Česká národní banka v oblasti kapitálového trhu:","o":["Vydává zákony.","Vydává vyhlášky na základě a k provedení zákonů.","Vydává pouze obecná doporučení, která nejsou právně závazná (např. úřední sdělení, stanoviska, benchmarky, apod.).","Vydává pravomocná rozhodnutí ohledně spáchání trestného činu subjektem kapitálového trhu."],"c":[1],"p":22,"e":"ČNB smí vydávat vyhlášky k provedení a na základě zmocnění uvedeného v konkrétních právních předpisech (zákonech).","tp":2},{"id":"19522.1","t":"s","q":"Investiční zprostředkovatel je oprávněn poskytovat investiční služby ve vztahu:","o":["K jakýmkoliv dluhopisům.","Pouze k těm dluhopisům, ke kterým byl vydán prospekt (nebo srovnatelný dokument).","Pouze k hypotečním zástavním listům.","K hypotečním zástavním listům a k dluhopisům, ke kterým byl vydán prospekt (nebo srovnatelný dokument)."],"c":[3],"p":22,"e":"Investiční zprostředkovatel je oprávněn poskytovat investiční služby pouze ve vztahu k: dluhopisům vydaným Českou republikou, hypotečním zástavním listům nebo dluhopisům, ke kterým byl vydán prospekt nebo srovnatelný dokument.","tp":0},{"id":"19523.1","t":"s","q":"O podřízeném dluhopisu platí:","o":["Pohledávka s ním spojená bude v případě úpadku či likvidace emitenta uspokojena až po uspokojení všech ostatních pohledávek, s výjimkou pohledávek, které jsou vázány stejnou nebo obdobnou podmínkou podřízenosti.","Jeho výnos se odvíjí od hospodářského výsledku emitenta.","Jeho nabídka je omezena pouze investorům, kteří zakoupili obdobný dluhopis v předchozí tranši.","Jedná se o dluhopis, k němuž nebyl vydán prospekt."],"c":[0],"p":22,"e":"Podřízený dluhopis je dluhopis, kde v případě vstupu emitenta do likvidace nebo vydání rozhodnutí o úpadku bude pohledávka odpovídající právům s tímto dluhopisem spojeným uspokojena až po uspokojení všech ostatních pohledávek, s výjimkou pohledávek, které jsou vázány stejnou nebo obdobnou podmínkou podřízenosti.","tp":3},{"id":"19524.1","t":"s","q":"V případě, že dojde k úpadku emitenta dluhopisu:","o":["Může být investorovi vyplacena náhrada za vzniklou újmu z Garančního fondu obchodníků s cennými papíry.","Může být investorovi vyplacena náhrada za vzniklou újmu z Garančního fondu obchodníků s cennými papíry, avšak pouze za předpokladu, že dluhopis zakoupil prostřednictvím OCP.","Může být investorovi vyplacena náhrada za vzniklou újmu z Garančního fondu emitentů dluhových cenných papírů.","Investorovi žádná kompenzace z garančního fondu nenáleží."],"c":[3],"p":23,"e":"Garanční fond zabezpečuje záruční systém, ze kterého se vyplácejí náhrady zákazníkům obchodníka s cennými papíry, který není schopen plnit své dluhy vůči svým zákazníkům.","tp":3},{"id":"19525.2","t":"s","q":"V případě, že klient podá podnět (stížnost) k prošetření na činnost subjektu podléhajícího dohledu v oblasti kapitálového trhu České národní bance, je ČNB oprávněna:","o":["Zahájit správní řízení se subjektem dohledu a udělit mu pokutu.","Zahájit správní řízení se subjektem dohledu, avšak pokud dojde k závěru, že byl spáchán přestupek, musí věc předat Policii ČR.","Provést kontrolu na místě; správní řízení vůči subjektu dohledu není oprávněna vést.","Pravomocně rozhodnout o právech a povinnostech subjektu dohledu, včetně případného uložení povinnosti nahradit klientovi způsobenou škodu."],"c":[0],"p":23,"e":"ČNB projednává přestupky podle zákona o dohledu v oblasti kapitálového trhu, přičemž za spáchání přestupku může udělit pokutu nebo opatření k nápravě.","tp":0},{"id":"19526.1","t":"s","q":"Dluhopis na řad:","o":["Nelze vydat.","Nelze převést.","Znamená, že je na něm uvedeno jméno oprávněné osoby.","Znamená, že je v zaknihované podobě."],"c":[2],"p":23,"e":"Listinný dluhopis je cenným papírem na řad. Cenný papír na řad obsahuje jméno oprávněné osoby.","tp":3},{"id":"19528.2","t":"s","q":"Za jednu emisi dluhopisů se považuje emise souboru dluhopisů vydaných:","o":["Jedním emitentem se stejnou splatností.","Jedním emitentem se stejným okamžikem emise a se stejnou splatností.","Na základě stejných emisních podmínek, v jeden okamžik emise a se stejnou splatností.","Jinými emitenty, na základě obdobných emisních podmínek, v jeden okamžik emise a se stejnou splatností."],"c":[2],"p":23,"e":"Dle § 2 odst. 4 zákona o dluhopisech se emisí dluhopisů rozumí soubor dluhopisů vydávaných na základě týchž emisních podmínek a majících stejný okamžik emise a stejný okamžik splatnosti. Výkladem dospějeme k závěru, že ač zákon výslovně neuvádí požadavek, aby za jednu emisi byla považována emise stejného/jednoho emitenta, rozhodně nelze považovat za jednu emisi, emisi dluhopisů různých emitentů na základě stejných emisních podmínek, kdy by emisní podmínky nemohly být totožné, protože by se lišily minimálně v různých osobách emitenta, což je podstatnou náležitosti dluhopisu.","tp":3},{"id":"19529.1","t":"s","q":"Právo na výnos z dluhopisu:","o":["Může být od dluhopisu odděleno vždy.","Nemůže být od dluhopisu odděleno a lze jej uplatnit vždy jen s dluhopisem.","Nemusí být spojeno s kupónem jako cenným papírem a lze jej tak uplatnit i bez kupónu.","Může být od dluhopisu odděleno, pokud to emisní podmínky nevylučují, ale musí být spojeno s kupónem jako cenným papírem, který určuje jaké právo je s ním spojeno a kdy je možné jej uplatnit."],"c":[3],"p":24,"e":"Pokud to emisní podmínky nevylučují, může být právo na výnos dluhopisu od dluhopisu odděleno a spojeno s kupónem jako cenným papírem nebo zaknihovaným cenným papírem vydaným k uplatnění tohoto práva. Na každém z kupónů dluhopisu musí být vyznačeno, jaké právo je s ním spojeno, a den, který je rozhodný pro uplatnění tohoto práva. Z uvedeného vyplývá, že právo na výnos dluhopisu je buď spojeno s dluhopisem jako cenným papírem anebo je možné ho oddělit a spojit s jiným cenným papírem tzv. kupónem, který představuje toto právo na výnos z dluhopisu a kupón je tak cenným papírem odvozeným od jiného cenného papíru.","tp":3},{"id":"19527.1","t":"s","q":"Aby mohl být dluhopis považován za řádně vydaný musí mít alespoň tyto náležitosti (uvažujeme běžný listinný dluhopis):","o":["Identifikaci emitenta a vlastníka dluhopisu, podpis emitenta a jmenovitou hodnotu dluhopisu představující dlužnou částku.","Identifikaci emitenta a vlastníka dluhopisu, podpis emitenta, jmenovitou hodnotu dluhopisu představující dlužnou částku, určení výnosu a okamžik splatnosti.","Identifikaci emitenta a jeho podpis, jmenovitou hodnotu dluhopisu představující dlužnou částku, určení výnosu a okamžik splatnosti.","Identifikaci emitenta a vlastníka dluhopisu, jmenovitou hodnotu dluhopisu představující dlužnou částku, určení výnosu a okamžik splatnosti."],"c":[1],"p":24,"e":"Dle zákona o dluhopisech jsou minimálními nezbytnými náležitostmi dluhopisu následující údaje: c) údaje identifikující emitenta,d) jmenovitou hodnotu jako dlužnou částku; e) výnos dluhopisu, nebo údaj o tom, že výnos je určen rozdílem mezi jmenovitou hodnotou dluhopisu a jeho nižším emisním kurzem; anebo je z dluhopisu aspoň zřejmé, že dluhopis je bez výnosu nebo kde se lze s tím, jak je výnos určen, seznámit,f) datum nebo jiný okamžik splacení (dále jen \"datum splatnosti\") dlužné částky (splacení dluhopisu), g) údaje identifikující vlastníka dluhopisu, h) podpis emitenta.","tp":3},{"id":"19530.1","t":"s","q":"Česká národní banka je oprávněna:","o":["Zveřejňovat jakékoliv údaje o probíhajícím dohledu nad kapitálovým trhem.","Zveřejňovat jakákoli rozhodnutí, která učiní při výkonu dohledu nad kapitálovým trhem, zejména pak rozhodnutí o uložení sankce či nápravném opatření.","Zveřejňovat pouze pravomocná či vykonatelná rozhodnutí, která učiní při výkonu dohledu nad kapitálovým trhem.","Zveřejňovat pouze ta rozhodnutí, která učiní při výkonu dohledu nad kapitálovým trhem a u nichž obdrží souhlas se zveřejněním od subjektů, jichž se rozhodnutí týká."],"c":[2],"p":24,"e":"ČNB je oprávněna zveřejňovat pouze pravomocná či vykonatelná rozhodnutí, která učiní při výkonu dohledu nad kapitálovým trhem.","tp":0},{"id":"19531.1","t":"s","q":"Zaměstnanci České národní banky a další osoby, které se podílejí na výkonu dohledu nad kapitálovým trhem jsou povinni:","o":["Zachovávat mlčenlivost o všech informacích, o kterých se dozvěděli v souvislosti s výkonem dohledu nad kapitálovým trhem.","Zachovávat mlčenlivost o všech informacích, o kterých se dozvěděli v souvislosti s výkonem dohledu nad kapitálovým trhem, jen za předpokladu, že by zveřejnění takové informace mohlo zásadním způsobem ohrozit stabilitu kapitálového trhu.","Zachovávat mlčenlivost o všech informacích, o kterých se dozvěděli v souvislosti s výkonem dohledu nad kapitálovým trhem mimo jiné s výjimkou poskytnutí informací Kanceláři prezidenta republiky za účelem posouzení možného dopadu změn na kapitálovém trhu do majetku ve správě Pražského hradu.","Zachovávat mlčenlivost o všech informacích, o kterých se dozvěděli v souvislosti s výkonem dohledu nad kapitálovým trhem s výjimkou případů, kdy jim k poskytnutí udělí výjimku ministr financí."],"c":[0],"p":24,"e":"Zaměstnanci a další osoby, které se podílejí na výkonu dohledu nad kapitálovým trhem jsou povinni zachovávat mlčenlivost s výjimkou případů uvedených v zákoně.","tp":2},{"id":"19538.1","t":"s","q":"Do společného jmění manželů v zákonném režimu patří:","o":["Peníze získané prodejem akcií ve výlučném vlastnictví jednoho z manželů.","Dividendy z akcií nakoupených jedním z manželů v době před vznikem manželství.","Dluhopisy nabyté darem jedním z manželů v době trvání manželství.","Úvěr na koupi podílových listů z doby před vznikem manželství."],"c":[1],"p":25,"e":"Součástí společného jmění (SJ) je to, čeho nabyl jeden z manželů nebo čeho nabyli oba manželé společně za trvání manželství, s výjimkou mj. toho, co slouží osobní potřebě jednoho z manželů, nebo toho, co nabyl darem, děděním nebo odkazem jen jeden z manželů. Součástí SJ je zisk z toho, co náleží výhradně jednomu z manželů. Součástí SJ jsou dluhy převzaté za trvání manželství, ledaže se týkají majetku, který náleží výhradně jednomu z manželů.","tp":4},{"id":"19539.1","t":"s","q":"Plná moc musí mít písemnou formu:","o":["V případě smluvního zastupování ohledně písemného právního jednání.","V případě jakéhokoliv právního jednání v zastoupení.","Vždy v případě jednání zaměstnance za zaměstnavatele.","V případě zastupování obchodní společnosti svým statutárním orgánem."],"c":[0],"p":25,"e":"Plná moc obsahuje rozsah zmocněncova oprávnění. Netýká-li se zastoupení jen určitého právního jednání, udělí se plná moc v písemné formě. Vyžaduje-li se pro právní jednání zvláštní forma, udělí se v téže formě i plná moc. U ostatních případů se plná moc nevyžaduje, jelikož se jedná o zákonné zastupování.","tp":0},{"id":"19540.1","t":"s","q":"Společnost s ručením omezeným:","o":["Odpovídá za své závazky pouze do výše svého základního kapitálu zapsaného v obchodním rejstříku.","Jedná prostřednictvím valné hromady.","Může vydávat dluhopisy.","Může vydávat akcie."],"c":[2],"p":25,"e":"Obchodní společnost může vydávat korporátní dluhopisy - vychází z definice dluhopisu a z obecné zásady soukromého práva, že to, co není zakázáno, je dovoleno (jedná se v podstatě o přijetí půjčky ze strany obchodní společnosti).","tp":3},{"id":"19541.1","t":"s","q":"Podíl na obchodní společnosti může mít podobu:","o":["Podílového certifikátu.","Tichého společenství.","Akcie.","Dluhopisu."],"c":[2],"p":25,"e":"Akcie představuje podíl na akciové společnosti. Základní kapitál akciové společnosti je rozvržen na určitý počet akcií.","tp":0},{"id":"19542.1","t":"s","q":"Obchodní korporace:","o":["Musí být založena pouze za účelem zisku.","Musí ji založit alespoň dvě osoby.","Nemá vlastní právní osobnost.","Je trestně odpovědná."],"c":[3],"p":25,"e":"Vychází z existence zákona o trestní odpovědnosti právnických osob (viz zdroj). Obchodní korporace může být i jednočlenná (s.r.o.), může být založena i za jiným účelem (kapitálová společnost) a má právní osobnost (subjektivitu).","tp":0},{"id":"19543.1","t":"s","q":"Smlouva je:","o":["Písemná dohoda mezi spotřebitelem a podnikatelem.","Jakékoliv právní jednání, u kterého je shodný projev vůle dvou či více stran zřídit mezi sebou závazek.","Jakékoliv písemné právní jednání, u kterého je shodný projev vůle dvou či více stran zřídit mezi sebou závazek.","Právní jednání, které je jako smluvní typ upraveno v občanském zákoníku nebo jiném právním předpise."],"c":[1],"p":26,"e":"Smlouva je projevem vůle smluvních stran zřídit mezi sebou závazek a řídit se obsahem smlouvy. Smlouva nemusí být písemná, pokud to nevyžaduje zákon či dohoda stran.","tp":8},{"id":"19544.1","t":"s","q":"V případě, že dojde k promlčení práva, znamená to, že:","o":["Právo nadále trvá, avšak pokud dlužník vznese námitku promlčení, nemůže jej soud věřiteli přiznat.","Právo zaniká.","Soud může právo věřiteli přiznat, avšak právo nelze vymáhat exekučně.","Pokud by dlužník plnil, je věřitel povinen plnění vrátit."],"c":[0],"p":26,"e":"Nebylo-li právo vykonáno v promlčecí lhůtě, promlčí se a dlužník není povinen plnit. Plnil-li však dlužník po uplynutí promlčecí lhůty, nemůže požadovat vrácení toho, co plnil. K promlčení soud přihlédne, jen namítne-li dlužník, že je právo promlčeno.","tp":8},{"id":"19545.1","t":"s","q":"Společenská smlouva je:","o":["Smlouva mezi zakladateli obchodní korporace a obchodní korporací.","Smlouva mezi společníky akciové společnosti, která upravuje náplň činnosti jednotlivých společníků ve společnosti.","Smlouva mezi zakladateli, kterou se zakládá obchodní korporace.","Smlouva mezi státem a jeho občany."],"c":[2],"p":26,"e":"Obchodní korporace se zakládá společenskou smlouvou.","tp":0},{"id":"19546.1","t":"s","q":"Svéprávnost:","o":["Má ze zákona fyzická i právnická osoba.","Má pouze fyzická osoba, která dosáhla věku 15 let.","Má pouze fyzická osoba, která dosáhla věku 18 let.","Nabývá nezletilá fyzická osoba v rozsahu přiměřeném rozumové a volní vyspělosti jejího věku."],"c":[3],"p":26,"e":"Plně svéprávným se člověk stává zletilostí. Zletilosti se nabývá dovršením osmnáctého roku věku. Má se za to, že každý nezletilý, který nenabyl plné svéprávnosti, je způsobilý k právním jednáním co do povahy přiměřeným rozumové a volní vyspělosti nezletilých jeho věku.","tp":8},{"id":"19547.1","t":"s","q":"Valná hromada je:","o":["Dozorčí orgán akciové společnosti.","Statutární orgán akciové společnosti.","Nejvyšší orgán akciové společnosti.","Dozorčí orgán společnosti s ručením omezeným."],"c":[2],"p":26,"e":"Valná hromada je nejvyšším orgánem akciové společnosti.","tp":10},{"id":"19548.1","t":"s","q":"O základním kapitálu obchodní korporace (společnosti) platí:","o":["Vypovídá o majetku společnosti.","Je to souhrn vkladů všech společníků.","Nelze jej v průběhu trvání obchodní korporace měnit.","Lze jej v průběhu trvání obchodní korporace navýšit, avšak není možné jej snížit."],"c":[1],"p":27,"e":"Základní kapitál obchodní korporace je souhrn všech vkladů.","tp":0},{"id":"19549.1","t":"s","q":"Součástí společného jmění manželů je:","o":["Věci osobní potřeby jednoho z manželů.","Majetek, který zdědil jeden z manželů za trvání manželství.","Zisk z majetku ve výlučném vlastnictví jednoho z manželů.","Dluhy přesahující běžné potřeby rodiny převzaté jedním z manželů bez souhlasu druhého manžela."],"c":[2],"p":27,"e":"Součástí společného jmění je to, čeho nabyl jeden z manželů nebo čeho nabyli oba manželé společně za trvání manželství, s výjimkou toho, co slouží osobní potřebě jednoho z manželů, co nabyl děděním jen jeden z manželů. Součástí společného jmění je zisk z toho, co náleží výhradně jednomu z manželů. Součástí společného jmění jsou dluhy převzaté za trvání manželství, ledaže je převzal jen jeden z manželů bez souhlasu druhého, aniž se přitom jednalo o obstarávání každodenních nebo běžných potřeb rodiny.","tp":2},{"id":"19550.1","t":"s","q":"Závazek trvá (nezanikne):","o":["Po započtení splatné a vymahatelné pohledávky proti pohledávce druhé strany.","Po odstoupení od smlouvy v souladu se zákonem či ujednáním ve smlouvě.","Při prodlení dlužníka s plněním dluhu.","Stane-li se dluh objektivně nesplnitelným."],"c":[2],"p":27,"e":"Dluží-li si strany vzájemně plnění stejného druhu, může každá z nich prohlásit vůči druhé straně, že svoji pohledávku započítává proti pohledávce druhé strany. K započtení lze přistoupit, jakmile straně vznikne právo požadovat uspokojení vlastní pohledávky a plnit svůj vlastní dluhu. Započtením se obě pohledávky ruší v rozsahu, v jakém se vzájemně kryjí; nekryjí-li se zcela, započte se pohledávka obdobně jako při splnění. Tyto účinky nastávají k okamžiku, kdy se obě pohledávky staly způsobilými k započtení. K započtení jsou způsobilé pohledávky, které lze uplatnit před soudem. Odstoupením od smlouvy se závazek zrušuje od počátku. Stane-li se dluh po vzniku závazku nesplnitelným, zaniká závazek pro nemožnost plnění. Plnění není nemožné, lze-li dluh splnit za ztížených podmínek, s většími náklady, s pomocí jiné osoby nebo až po určené době. Prodlení nezakládá zánik závazku; prodlení věřitele či dlužníka může představovat podstatné porušení smluvních povinností a může tak založit právo druhé smluvní strany na odstoupení od smlouvy.","tp":8},{"id":"19551.1","t":"s","q":"Podíl na zisku v obchodní korporaci:","o":["Lze vždy rozdělit i mezi členy statutárního orgánu.","Lze vždy rozdělit mezi společníky i bez souhlasu valné hromady.","Se stanoví na základě účetní závěrky schválené valnou hromadou.","Lze vyplatit bez souhlasu statutárního orgánu."],"c":[2],"p":27,"e":"Podíl na zisku se stanoví na základě řádné nebo mimořádné účetní závěrky schválené nejvyšším orgánem obchodní korporace. Lze jej rozdělit pouze mezi společníky, ledaže společenská smlouva určí jinak. O vyplacení podílu na zisku rozhoduje statutární orgán.","tp":0},{"id":"19552.1","t":"s","q":"V souvislosti s akciemi platí, že:","o":["Akcii nelze vydat ve formě cenného papíru na doručitele.","Akcii na majitele lze vydat pouze jako zaknihovaný nebo imobilizovaný cenný papír.","Akcie téže společnosti nesmí mít různou jmenovitou hodnotu.","Seznam akcionářů může vést společnost dobrovolně za předpokladu udělení souhlasu akcionáře se svým zápisem do seznamu akcionářů."],"c":[1],"p":28,"e":"Akcie může mít formu cenného papíru na řad (tj. akcie na jméno) nebo na doručitele (tj. akcie na majitele). Akcie na majitele mohou být vydány pouze jako zaknihovaný cenný papír nebo jako imobilizovaný cenný papír. Akcie téže společnosti mohou mít různou jmenovitou hodnotu. Akcie na jméno se zapisuje do seznamu akcionářů, který vede společnost.","tp":4},{"id":"19559.3","t":"s","q":"Fondem kolektivního investování je:","o":["Účastnický penzijní fond.","Fond kvalifikovaných investorů.","Svěřenský fond.","Standardní fond."],"c":[3],"p":28,"e":"ZISIF definuje investiční fondy jako fondy kolektivního investování, které se dále dělí na standardní a speciální fondy, a fondy kvalifikovaných investorů.","tp":1},{"id":"19560.2","t":"s","q":"V čem se liší speciální fond od standardního fondu kolektivního investování?","o":["V majetku speciálního fondu může být zahrnuto více typů aktiv, například komodity nebo nemovitosti.","Za určitých okolnosti může speciální fond překračovat investiční limity uvedené ve Statutu fondu.","Speciální fond je určen výhradně pro běžné, retailové investory.","Speciální fond je určen výhradně pro institucionální investory."],"c":[0],"p":28,"e":"Dle nařízení vlády o investování investičních fondů a o technikách k jejich obhospodařování mohou speciální fondy a fondy kvalifikovaných investorů investovat do širší skupiny aktiv než standardní fondy.","tp":1},{"id":"19561.1","t":"s","q":"Jak je označován investiční fond přijatý k obchodování na burze, který kopíruje podkladové aktivum (obvykle index)?","o":["Takový fond neexistuje. Fondy nemohou být obchodovány na burze.","Publicly-traded Fund.","Exchange-traded Fund.","Stock Market Fund."],"c":[2],"p":28,"e":"Burzovně obchodované fondy jsou označovány výrazem exchange-traded fund (ETF).","tp":4},{"id":"19562.1","t":"s","q":"Který zákon upravuje pojem \"investiční fond\"?","o":["Zákon č. 256/2004 Sb. o podnikání na kapitálovém trhu.","Zákon č. 240/2013 Sb. o investičních společnostech a investičních fondech.","Zákon č. 89/2012 Sb. občanský zákoník.","Zákon č. 21/1992 Sb. o bankách."],"c":[1],"p":28,"e":"Investiční fondy upravuje Zákon o investičních společnostech a investičních fondech.","tp":8},{"id":"19563.2","t":"s","q":"Co je základní charakteristikou ETF?","o":["Cenné papíry vydávané ETF jsou obchodovány na veřejných burzách.","Náklady těchto fondů jsou vždy vyšší než náklady standardních fondů kolektivního investování.","Jedná se o fondy, které vždy využívají aktivní investiční strategii.","Jedná se o fondy, které nejsou obchodované na veřejných burzách."],"c":[0],"p":29,"e":"Základní charakteristikou je to, že obchody probíhají na burze. Odráží to i zkratka ETF - exchange-traded funds.","tp":1},{"id":"19564.3","t":"s","q":"Na rozdíl od otevřeného podílového fondu, podílník uzavřeného podílového fondu:","o":["Pokud to není uvedeno ve statutu, nemá zpravidla právo na odkoupení podílového listu na účet fondu.","Nemá právo na podílu na majetku fondu.","Může realizovat při odkoupení podílového listu ztrátu.","Nesmí své podílové listy odprodat jinému podílníkovi."],"c":[0],"p":29,"e":"Specifikem uzavřených fondů je omezení práva zpětného odkupu na účet fondu.","tp":1},{"id":"19565.2","t":"s","q":"Kvalifikovaným investorem můžeme chápat:","o":["Jakéhokoliv investora s investicí vyšší než 125 000 EUR.","Investora, jehož investice je rovna nebo vyšší než 125 000 EUR nebo je rovna nebo vyšší než 1 000 000 Kč pokud tato investice odpovídá finančnímu zázemí, investičním cílům, znalostem a zkušenostem investora.","Jakéhokoliv investora jehož investice nepřevýší 3 500 000 Kč.","Jakéhokoliv investora s investicí, která je rovna nebo vyšší než 125 000 EUR, nebo je rovna nebo vyšší než 1 000 000 Kč, pokud investor investuje do konzervativních investičních nástrojů."],"c":[1],"p":29,"e":"ZISIF definuje kvalifikovaného investora mimo jiné z pohledu výše investované částky 125 tis. EUR, resp. 1 mil. Kč za splnění podmínek přiměřenosti a vhodnosti.","tp":6},{"id":"19566.2","t":"s","q":"Minimální investice do fondu kvalifikovaných investorů je:","o":["1 000 000 Kč, pokud investor prohlásí, že si je vědom rizik spojených s investováním do daného fondu.","125 000 EUR, pokud investor prohlásí, že si je vědom rizik spojených s investováním do daného fondu.","1 000 000 Kč, pokud administrátor fondu potvrdí, že investice odpovídá finančnímu zázemí, investičním cílům, znalostem a zkušenostem investora, a investor prohlásí, že si je vědom rizik spojených s investováním do daného fondu.","125 000 EUR, pokud investice odpovídá finančnímu zázemí, investičním cílům, znalostem a zkušenostem investora."],"c":[2],"p":29,"e":"ZISIF připouští minimální investici 1 mil. Kč, pokud je však pro investora přiměřená a vhodná.","tp":1},{"id":"19567.2","t":"s","q":"Speciální fond kolektivního investování:","o":["Je určen pouze pro kvalifikované investory.","Smí investovat do širšího spektra investičních nástrojů než standardní fond kolektivního investování.","Smí investovat do užšího spektra investičních nástrojů než standardní fond kolektivního investování.","Je limitován minimální investicí 1 000 000 Kč, případně 125 000 EUR."],"c":[1],"p":29,"e":"Speciální fond může investovat do širší skupiny aktiv než standardní fond.","tp":1},{"id":"19568.1","t":"s","q":"Fondem kolektivního investování (standardním nebo speciálním) může být:","o":["Podílový fond nebo akciová společnost.","Podílový fond, akciová společnost nebo společnost s ručením omezeným.","Jakákoliv právnická osoba, jejímž předmětem činnosti je správa majetku investorů fondů.","Podílový fond, svěřenský fond nebo akciová společnost."],"c":[0],"p":30,"e":"Zákon o investičních společnostech a investičních fondech definuje přípustné právní formy fondu kolektivního investování.","tp":1},{"id":"19570.1","t":"s","q":"Exchange Traded Fund:","o":["Nevydává a neodkupuje akcie jednotlivým investorům při nákupu nebo prodeji.","Vydává vždy nové akcie novým investorům při nákupu na sekundárním trhu.","Vydává akcie pouze v omezeném počtu, po jejich nákupu již nové nelze vydat.","Vydává akcie pouze jednou ročně."],"c":[0],"p":30,"e":"Na rozdíl od investičního fondu ETF nevydává akcie, investoři na sekundárním trhu nakupují již existující akcie.","tp":4},{"id":"19575.1","t":"s","q":"Počáteční kapitál investiční společnosti, která obhospodařuje standardní fond, musí být minimálně:","o":["500 000 EUR.","10 000 EUR.","1 000 000 EUR.","125 000 EUR."],"c":[3],"p":30,"e":"Minimální počáteční kapitál je definován ZISIF.","tp":1},{"id":"19576.1","t":"s","q":"Administrace investičního fondu nezahrnuje tuto činnost:","o":["Vedení účetnictví.","Realizace investičních rozhodnutí.","Oceňování majetku a dluhů.","Compliance a vnitřní audit."],"c":[1],"p":30,"e":"Realizace investičních rozhodnutí je výkonem obhospodařování fondu. Administrativní činnosti taxativně vymezuje ZISIF.","tp":1},{"id":"19577.1","t":"s","q":"Řízení rizik spojených s investováním na účet investičního fondu provádí:","o":["Administrátor investičního fondu.","Česká národní banka.","Obhospodařovatel investičního fondu.","Depozitář investičního fondu."],"c":[2],"p":30,"e":"Řízení rizik je spojeno s výkonem obhospodařování investičního fondu.","tp":1},{"id":"19578.3","t":"s","q":"Obhospodařování fondu nezahrnuje:","o":["Správu majetku fondu.","Investování na účet fondu.","Řízení rizik spojených s investováním.","Vydávání podílových listů nebo akcií fondu."],"c":[3],"p":31,"e":"Vydávání podílových listů spadá pod činnost administrace fondu.","tp":1},{"id":"19579.1","t":"s","q":"Obhospodařovatelem samosprávného investičního fondu je:","o":["Tento fond.","Smluvní obhospodařovatel.","Administrátor fondu.","Správní rada fondu."],"c":[0],"p":31,"e":"Pokud je fond zřízen jako samosprávný, vykonává tuto činnost samostatně.","tp":1},{"id":"19580.1","t":"s","q":"Povolení k činnosti obhospodařovatele fondu vydává:","o":["Investiční společnost.","Česká národní banka.","Ministerstvo financí.","Centrální depozitář cenných papírů."],"c":[1],"p":31,"e":"Obhospodařovatele schvaluje ČNB.","tp":1},{"id":"19581.1","t":"s","q":"Investiční fond:","o":["Smí mít více obhospodařovatelů, maximálně však dva.","Smí mít více obhospodařovatelů, maximálně však tři.","Nesmí mít více než jednoho obhospodařovatele.","Smí mít více obhospodařovatelů, pokud je tato skutečnost uvedena ve statutu fondu."],"c":[2],"p":31,"e":"Každý investiční fond může mít pouze jednoho obhospodařovatele.","tp":1},{"id":"19582.1","t":"s","q":"Podfond investičního fondu:","o":["Musí být obhospodařován stejným obhospodařovatelem jako mateřský investiční fond.","Může být obhospodařován jiným obhospodařovatelem než mateřský investiční fond.","Může být obhospodařován jiným obhospodařovatelem než mateřský investiční fond, pokud mají stejného depozitáře.","Může být obhospodařován jiným obhospodařovatelem než mateřský investiční fond, pokud mají stejného administrátora."],"c":[0],"p":31,"e":"Obhospodařování investičního fondu zahrnuje i obhospodařování podfondů tohoto fondu.","tp":1},{"id":"19583.1","t":"s","q":"Administrátorem standardního fondu kolektivního investování:","o":["Nesmí být jeho obhospodařovatel.","Smí být pouze jeho obhospodařovatel.","Smí být pouze jeho depozitář.","Může být jakákoliv právnická osoba."],"c":[1],"p":32,"e":"Administrátorem standardního fondu může být pouze jeho obhospodařovatel.","tp":1},{"id":"19584.1","t":"s","q":"Vydávání podílových listů investičního fondu zajišťuje:","o":["Administrátor fondu.","Depozitář fondu.","Centrální depozitář cenných papírů.","Česká národní banka."],"c":[0],"p":32,"e":"Administrátor zajišťuje vydávání podílových listů.","tp":1},{"id":"19585.1","t":"s","q":"Reklamace investorů investičního fondu vyřizuje:","o":["Finanční analytický úřad.","Obhospodařovatel fondu.","Depozitář fondu.","Administrátor fondu."],"c":[3],"p":32,"e":"Přijímání stížností a reklamací je jedna z činností administrátora definovaná zákonem.","tp":1},{"id":"19586.1","t":"s","q":"Obhospodařovatelem investičního fondu:","o":["Nesmí být jeho depozitář.","Může být jeho depozitář, pokud je zároveň i jeho administrátorem.","Může být jeho depozitář, pokud zároveň není jeho administrátorem.","Může být jeho depozitář, pokud je tato skutečnost uvedena ve statutu fondu."],"c":[0],"p":32,"e":"Činnost depozitáře a obhospodařovatele jsou neslučitelné.","tp":1},{"id":"19591.1","t":"s","q":"Diverzifikace majetku investičního fondu:","o":["Snižuje investiční riziko.","Zvyšuje investiční riziko.","Nemá na investiční riziko vliv.","Je přípustná pouze u Fondu kvalifikovaných investorů."],"c":[0],"p":32,"e":"S vyšší diverzifikací se snižuje koncentrace majetku a specifické riziko konkrétních aktiv fondu.","tp":1},{"id":"19592.1","t":"s","q":"Za fondy s nejnižším tržním rizikem jsou považovány fondy:","o":["Akciové fondy.","Dluhopisové fondy.","Fondy peněžního trhu.","Smíšené fondy."],"c":[2],"p":33,"e":"Fondy peněžního trhu investují do nástrojů s nejvyšší likviditou a nejmenším tržním rizikem jakými jsou krátkodobé dluhopisy nebo bankovní vklady.","tp":1},{"id":"19593.1","t":"s","q":"K měření vlivu úrokového rizika na cenu dluhopisu používáme ukazatel:","o":["Korelace.","Yield To Maturity.","Sharpe Ratio.","Modifikovaná durace."],"c":[3],"p":33,"e":"Úrokové riziko = riziko změny ceny dluhopisu při změně úrokové sazby. Citlivost ceny dluhopisy na změnu úrokové sazby vyjadřuje durace.","tp":3},{"id":"19594.1","t":"s","q":"Speciální investiční fond investující do nemovitostí bude mít proti standardnímu fondu kolektivního investování investujícímu do akcií společností z nemovitostního sektoru:","o":["Nižší likviditu.","Vyšší likviditu.","Nižší likviditu a vyšší duraci.","Vyšší likviditu a nižší management fee."],"c":[0],"p":33,"e":"Vzhledem k charakteru majetku fondu (fyzické nemovitosti) bude mít fond nižší likviditu než fond investující do akcií, tedy cenných papírů s vysokou likviditou.","tp":1},{"id":"19595.1","t":"s","q":"Ukazatel SRRI vyjadřuje:","o":["Na stupnici 1 - 10 likviditu fondu vycházející z historické volatility fondu.","Na stupnici 1 - 10 rizikovost fondu vycházející z jeho historické volatility.","Na stupnici 1 - 7 rizikovost fondu vycházející z jeho zařazení do definovaných sedmi tříd aktiv.","Na stupnici 1 - 7 rizikovost fondu vycházející z jeho historické volatility."],"c":[3],"p":33,"e":"SRRI vyjadřuje rizikovost fondu na stupnici 1 - 7 od nižší volatility k vyšší. Nástroje peněžního trhu mají typicky nižší volatilitu než akcie, ukazatel SRRI fondu peněžního trhu tedy bude nižší.","tp":1},{"id":"19596.1","t":"s","q":"Jaký bude vztah mezi ukazatelem SRRI běžného fondu peněžního trhu a běžného akciového fondu?","o":["Vzhledem k nižší volatilitě nástrojů peněžního trhu než je volatilita akcií, bude SRRI fondu peněžního trhu nižší.","Vzhledem k nižší volatilitě nástrojů peněžního trhu než je volatilita akcií, bude SRRI fondu peněžního trhu vyšší.","Vzhledem k nižší likviditě nástrojů peněžního trhu než je likvidita akcií, bude SRRI fondu peněžního trhu vyšší.","Vzhledem k vyšší likviditě nástrojů peněžního trhu než je likvidita akcií, bude SRRI fondu peněžního trhu vyšší."],"c":[0],"p":33,"e":"SRRI vyjadřuje rizikovost fondu na stupnici 1 - 7 od nižší volatility k vyšší. Nástroje peněžního trhu mají typicky nižší volatilitu než akcie, ukazatel SRRI fondu peněžního trhu tedy bude nižší.","tp":1},{"id":"19597.3","t":"s","q":"Fond investující do \"high yield\" dluhopisů investuje do:","o":["Státních dluhopisů vyspělých zemí jako USA či Německo.","Dluhopisů s ročním výnosem rovným výnosu příslušných státních dluhopisů.","Dluhopisů s ročním výnosem minimálně 4 %.","Dluhopisů s kreditním ratingem ve spekulativní části ratingové stupnice."],"c":[3],"p":34,"e":"Označení high yield odkazuje na ratingové ohodnocení ve spekulativním pásmu.","tp":3},{"id":"19598.1","t":"s","q":"Fond investující do akcií \"emerging markets\" investuje do:","o":["Akcií společností působících na rozvinutých trzích jako je USA či Německo.","Akcií společností působících na rozvíjejících se trzích (např. některé asijské země).","Akcií společností zdravotnického sektoru.","Akcií společností vykazujících vyšší tempo růstu než průměrné tempo růstu ekonomiky země, kde působí."],"c":[1],"p":34,"e":"Označení emerging markets odkazuje na rozvíjející se ekonomiky, typicky asijské země jako jsou Čína nebo Indie.","tp":4},{"id":"19599.2","t":"s","q":"Fond, který investuje zároveň do dluhopisů, akcií a dalších tříd aktiv bude fondem:","o":["Smíšeným.","Dluhopisovým, pokud nadpoloviční složkou budou dluhopisy.","Akciovým, pokud nadpoloviční složkou budou akcie.","Dluhopisovým, pokud váha dluhopisů nebude nižší než 80 %."],"c":[0],"p":34,"e":"Smíšený fond je fondem, který investuje do různých tříd aktiv.","tp":3},{"id":"19600.1","t":"s","q":"Co udává volatilita fondu?","o":["Míru diversifikace fondu vyjádřenou počtem titulů, do kterých fond investuje.","Rizikovost vyjádřenou nejvyšším možným propadem ceny podílového listu fondu.","Nejvyšší možný očekávatelný anualizovaný výnos fondu.","Směrodatnou odchylku, tedy míru kolísání ceny podílového listu fondu kolem průměru."],"c":[3],"p":34,"e":"Volatilita je vyjádření kolísání ceny PL fondu.","tp":1},{"id":"19601.1","t":"s","q":"Výpočet ukazatele SRRI fondu vychází:","o":["Z volatility fondu (kolísání ceny kolem průměru).","Z průměrné doby do splatnosti dluhopisů v majetku fondu.","Z průměrného kreditního ratingu dluhopisů v majetku fondu.","Z nejvyšší dosažené historické výkonnosti fondu."],"c":[0],"p":34,"e":"SRRI je stupnice rizikovosti dle volatility fondu.","tp":1},{"id":"19602.1","t":"s","q":"Je pravdivé tvrzení, že fondy kvalifikovaných investorů jsou vždy rizikovější než standardní fondy kolektivního investování?","o":["Není, vždy záleží na složení majetku konkrétního fondu a jeho investiční strategii.","Ano je, fondy kvalifikovaných investorů mají díky svým volnějším investičním limitům vždy z podstaty věci větší rizikovost.","Ano je, fondy kvalifikovaných investorů jsou typické svojí agresivní investiční strategií, která cílí na maximalizaci výnosů při vysokém riziku.","Není, je tomu právě naopak. Fondy kvalifikovanějších investorů jsou méně rizikové, protože investují zásadně do méně volatilních aktiv."],"c":[0],"p":35,"e":"Rizikovost je dána volatilitou a ta je dána typem aktiva, do kterého fond investuje. Nezáleží na formě investičního fondu.","tp":1},{"id":"19607.1","t":"s","q":"Co je to systematické riziko?","o":["Jedná se o riziko špatné volby investičního nástroje.","Jedná se o riziko kolapsu informačních systémů řídících kapitálové trhy.","Jedná se o riziko konkrétního investičního nástroje a jeho emitenta.","Jedná se o riziko vyplývající z pohybu trhu jako celku."],"c":[3],"p":35,"e":"Systematické riziko vyplývá z vývoje ekonomiky, postihuje trh jako celek. Nelze jej omezit diverzifikací portfolia.","tp":2},{"id":"19608.2","t":"s","q":"Nemovitost může v majetku vlastnit:","o":["Žádný fond kolektivního investování, pouze fond kvalifikovaných investorů.","Jakýkoliv fond kolektivního investování.","Fond kolektivního investování ve formě standardního fondu.","Fond kolektivního investování ve formě speciálního fondu nemovitostí."],"c":[3],"p":35,"e":"Nemovitostní fondy jsou speciální (NON-UCITS) podílové fondy investující zejména do větších komerčních nemovitostí a to buď přímo nebo prostřednictvím nemovitostních společností.","tp":1},{"id":"19609.2","t":"s","q":"Pokud je ukazatel \"Beta\" u fondu vyšší než jedna:","o":["Při růstu trhu roste výkonnost fondu více než trh.","Při růstu trhu roste výkonnost fondu méně než trh.","Při poklesu trhu výkonnost fondu roste.","Při růstu trhu výkonnost fondu klesá."],"c":[0],"p":35,"e":"\"Beta\" vyjadřuje relativní volatilitu fondu vůči volatilitě trhu. Hodnota jedna znamená, že fond reaguje stejně jako trh. Hodnota větší než jedna znamená, že fond reaguje větším pohybem než je pohyb trhu - tedy více roste při růstu a více klesá při poklesu.","tp":1},{"id":"19610.1","t":"s","q":"Jaký ukazatel využívá portfolio manažer při imunizaci dluhopisového portfolia?","o":["Výnos do splatnosti.","Duraci.","Rating.","Kupon."],"c":[1],"p":35,"e":"Imunizace dluhopisového portfolia spočívá v dosažení takové durace portfolia, která zajistí nulový vliv změny úrokové sazby na portfolio.","tp":3},{"id":"19611.1","t":"s","q":"Imunizací dluhopisového portfolia portfolio manažer odstraňuje:","o":["Tržní riziko.","Riziko likvidity.","Úrokové riziko.","Měnové riziko."],"c":[2],"p":36,"e":"Imunizace dluhopisového portfolia spočívá v dosažení takové durace portfolia, která zajistí nulový vliv změny úrokové sazby na portfolio.","tp":7},{"id":"19612.2","t":"s","q":"Jak velký podíl na majetku standardního investičního fondu mohou tvořit cenné papíry vydané jedním emitentem (není-li ve Statutu výslovně uvedeno jinak)?","o":["10 %.","20 %.","25 %.","5 %."],"c":[3],"p":36,"e":"Maximální investiční limity upravuje příslušná zákonná úprava.","tp":3},{"id":"19613.1","t":"s","q":"Co udává ukazatel \"Beta\" fondu?","o":["Citlivost akcií v portfoliu fondu na pohyb akciového trhu.","Vzájemnou korelaci jednotlivých akcií v portfoliu fondu.","Nadvýnos, který fond dosahuje v porovnání s referenčním akciovým trhem.","Průměrnou volatilitu akcií v portfoliu fondu."],"c":[0],"p":36,"e":"Beta vyjadřuje relativní volatilitu fondu vůči volatilitě trhu. Hodnota jedna znamená, že fond reaguje stejně jako trh. Hodnota větší než jedna znamená, že fond reaguje větším pohybem než je pohyb trhu - tedy více roste při růstu a více klesá při poklesu.","tp":7},{"id":"19614.1","t":"s","q":"Co udává ukazatel \"Alfa\" fondu?","o":["Vzájemnou korelaci jednotlivých akcií v portfoliu fondu.","Nadvýnos, který fond dosahuje v porovnání s referenčním akciovým trhem.","Průměrnou volatilitu akcií v portfoliu fondu.","Citlivost akcií v portfoliu fondu na pohyb akciového trhu."],"c":[1],"p":36,"e":"Alfa vyjadřuje výnos fondu dosažený v porovnání s referenčním trhem.","tp":1},{"id":"19615.1","t":"s","q":"S rostoucím počtem titulů v portfoliu fondu:","o":["Roste diverzifikace portfolia fondu a klesá specifické riziko jednotlivých instrumentů.","Klesá diverzifikace portfolia fondu a klesá specifické riziko jednotlivých instrumentů.","Klesá diverzifikace portfolia fondu a roste specifické riziko jednotlivých instrumentů.","Roste diverzifikace portfolia fondu a roste specifické riziko jednotlivých instrumentů."],"c":[0],"p":36,"e":"Specifické riziko klesá s diverzifikací fondu. Ta je ovlivněna počtem titulů v portfoliu.","tp":7},{"id":"19616.1","t":"s","q":"Do majetku standardního fondu kolektivního investování lze nabýt:","o":["Maximálně 10 % dluhopisů vydaných státem.","Maximálně 50 % dluhopisů vydaných státem.","Maximálně 80 % dluhopisů vydaných státem.","Až 100 % dluhopisů vydaných státem."],"c":[3],"p":37,"e":"Lze investovat až 100 % hodnoty majetku standardního fondu do investičních cenných papírů nebo nástrojů peněžního trhu, které vydal nebo za které převzal záruku stát.","tp":3},{"id":"19618.1","t":"s","q":"YTD (year to date) je vyjádřením:","o":["Průměrné roční výkonnosti.","Výkonnosti za poslední celý ukončený kalendářní (popř. hospodářský) rok.","Výkonnosti od začátku aktuálního kalendářního (popř. hospodářského) roku.","Výkonnosti za posledních 365 dní."],"c":[2],"p":37,"e":"YTD (Year To Date) je vyjádřením výkonnosti od začátku roku ke dni výpočtu.","tp":10},{"id":"19622.1","t":"s","q":"Statut standardního fondu:","o":["Lze změnit pouze se souhlasem České národní banky (pokud se nejedná o výjimky jako je například změna právní úpravy či další výjimky přesně specifikované zákonem).","Nelze po vydání měnit.","Lze kdykoli změnit. Po provedení změny je však nutné do 30 dnů zaslat změněný statut České národní bance.","Lze změnit na základě souhlasu administrátora a obhospodařovatele."],"c":[0],"p":37,"e":"Dle zákona č.240/2013 Sb. změna statutu vždy podléhá předchozímu souhlasu České národní banky až na výjimky uvedené v § 529 odst. 4.","tp":1},{"id":"19623.2","t":"s","q":"Sdělení klíčových informací:","o":["Je nutné vždy poskytnout investorům v listinné podobě.","Je nutné vždy poskytnout investorům v listinné podobě a zároveň zpřístupnit v elektronické podobě.","Lze po splnění určitých podmínek zpřístupnit investorům pouze na internetových stránkách fondu.","Je nepovinný dokument, fond jej nemusí vyhotovit a poskytovat investorům."],"c":[2],"p":37,"e":"Sdělení klíčových podmínek je zákonem vyžadovaný dokument. Po splnění podmínek jej lze zákazníkům poskytnout v listinné podobě, a nebo např. umístněním na webové stránky.","tp":1},{"id":"19624.1","t":"s","q":"Fond kolektivního investování musí vyhotovit výroční zprávu:","o":["Nejpozději do 12 měsíců po skončení účetního období fondu.","Nejpozději do 4 měsíců po skončení účetního období fondu.","Při zahájení a po ukončení činnosti fondu.","Za každé kalendářní čtvrtletí."],"c":[1],"p":37,"e":"Nároky na informační povinnost jsou stanoveny zákonem. Ten ukládá vyhotovení VZ do 4 měsíců po ukončení účetního období.","tp":1},{"id":"19625.1","t":"s","q":"Statut fondu kolektivního investování je uveřejněn:","o":["Na webových stránkách fondu.","Na webových stránkách Ministerstva financí ČR.","Na webových stránkách depozitáře fondu.","Na webových stránkách České národní banky."],"c":[0],"p":38,"e":"Uveřejnění statutu fondu definuje příslušná zákonná úprava.","tp":1},{"id":"19626.1","t":"s","q":"Výroční zpráva fondu kolektivního investování neobsahuje:","o":["Zprávu auditora.","Účetní závěrku.","Zásady pro hospodaření fondu.","Údaje o vývoji aktiv fondu."],"c":[2],"p":38,"e":"Zásady pro hospodaření obsahuje Statut fondu kolektivního investování, ne výroční zpráva.","tp":1},{"id":"19627.1","t":"s","q":"Sdělení klíčových informací slouží investorovi především k:","o":["Výpočtu vstupního poplatku, který aplikuje distributor fondu.","Získání informací o hospodaření fondu.","Určení budoucího výnosu fondu.","Vyhodnocení rizika spojeného s investováním do fondu."],"c":[3],"p":38,"e":"Sdělení klíčových informací je dokument, který obsahuje stručné základní charakteristiky fondu kolektivního investování, nezbytné pro pochopení povahy a rizik spojených s investováním do tohoto fondu, zpracované formou srozumitelnou běžnému investorovi.","tp":1},{"id":"19628.1","t":"s","q":"Statut investičního fondu:","o":["Je dokument obsahující seznam aktiv fondu.","Je dokument, ve kterém svým podpisem investor stvrzuje, že se seznámil s povahou a riziky fondu.","Je dokument, ve kterém správce fondu pravidelně informuje investory o zhodnocení fondu a aktuálním složení portfolia fondu.","Je dokument obsahující stručné charakteristiky fondu nezbytné pro pochopení povahy a rizik fondu."],"c":[3],"p":38,"e":"Statut fondu je dokument sloužící zejména k informaci o orgánech fondu, posouzení investiční strategie a rizikovosti fondu. Je vyhotoven před zahájením činnosti fondu. Rozsah statutu je definován zákonem.","tp":1},{"id":"19629.1","t":"s","q":"Účetní závěrka investičního fondu:","o":["Podléhá ověření auditorem pouze při překročení rozhodných ukazatelů (dle §20 Zákona o účetnictví) a je zveřejněna ve výroční zprávě fondu.","Nepodléhá ověření auditorem a je zveřejněna ve výroční zprávě fondu.","Vždy podléhá ověření auditorem a je zveřejněna ve výroční zprávě fondu.","Vždy podléhá ověření auditorem, je však přístupná pouze investorům fondu a to na vyžádání."],"c":[2],"p":38,"e":"Výroční zpráva fondu vždy obsahuje účetní závěrku fondu ověřenou auditorem a zprávu auditora v plném znění.","tp":1},{"id":"19630.1","t":"s","q":"Sdělení klíčových informací informuje o poměru rizik a výnosů:","o":["Pomocí obecného popisu rizik spojených s investičními nástroji kapitálového trhu.","Pomocí syntetického ukazatele (SRRI).","Pomocí porovnání historických výnosů fondů s historickými výnosy benchmarku.","Pomocí ukazatele Sharpe ratio."],"c":[1],"p":39,"e":"Část sdělení klíčových informací s názvem \"Poměr rizika a výnosů\" obsahuje syntetický ukazatel doplněný slovním vysvětlením ukazatele a jeho hlavních omezení a má podobu souboru kategorií uspořádaných na číselné stupnici.","tp":1},{"id":"19631.1","t":"s","q":"Statut musí mít:","o":["Každý investiční fond.","Každý investiční fond s výjimkou fondu kvalifikovaných investorů.","Každý investiční fond s výjimkou uzavřených podílových fondů.","Každý investiční fond s výjimkou speciálních fondů kolektivního investování."],"c":[0],"p":39,"e":"Statut je povinnou náležitostí každého investičního fondu.","tp":1},{"id":"19632.1","t":"s","q":"Statut investičního fondu vydává:","o":["Obhospodařovatel fondu","Ministerstvo financí","Depozitář fondu","Česká národní banka"],"c":[0],"p":39,"e":"Statut vydává obhospodařovatel fondu","tp":1},{"id":"19633.1","t":"s","q":"Dojde-li ke změně statutu fondu kolektivního investování:","o":["Není nutné ji oznamovat.","Je nutné jej bez zbytečného odkladu zveřejnit na internetových stránkách fondu.","Je za každých okolností nutné získat písemný souhlas všech podílníků či akcionářů fondu.","Je nutné jej zaslat podílníkům či akcionářům fondu."],"c":[1],"p":39,"e":"Dle zákona č.240/2013 Sb. , je změna statutu uveřejňována jeho novým úplným uveřejněním bez zbytečného odkladu na internetových stránkách fondu.","tp":1},{"id":"19638.2","t":"s","q":"Podílový list bude odkoupen administrátorem fondu za:","o":["Částku, která se rovná jeho aktuální hodnotě ke dni, ke kterému obdržel žádost podílníka o odkoupení podílového listu.","Částku, která se rovná jeho aktuální hodnotě ke dni vypořádání prodeje.","Částku, kterou podílník uvedl na pokynu k prodeji.","Částku, která se rovná jeho aktuální hodnotě ke dni podpisu pokynu k prodeji."],"c":[0],"p":39,"e":"Administrátor nakupuje a prodává podílové listy za hodnotu platnou ke dni, ke kterému obdržel žádost podílníka o odkoupení podílového listu.","tp":1},{"id":"19639.1","t":"s","q":"Odkup podílového listu standardního fondu s akciovou investiční strategií zajistí administrátor:","o":["Do tří dnů.","Do 24 hodin.","Do dvou týdnů.","Do jednoho měsíce."],"c":[2],"p":40,"e":"Lhůty pro odkup definuje zákon. Pro standardní fondy (nejedná-li se o fond peněžního trhu) to jsou dva týdny. Tři dny pro fond peněžního trhu, 1 měsíc pro speciální fond mimo nemovitostního. Lhůtu 24 hod. zákon nedefinuje.","tp":1},{"id":"19640.1","t":"s","q":"Podílník uzavřeného podílového fondu:","o":["Má vždy právo na odkoupení podílových listů.","Má právo na odkoupení podílových listů pouze po předchozím oznámení.","Má právo na odkoupení podílových listů pouze se souhlasem administrátora.","Nemá právo na odkoupení podílových listů (není-li uvedeno ve Statutu jinak)."],"c":[3],"p":40,"e":"Dle zákona o investičních společnostech a investičních fondech není s podílovým listem vydaným uzavřeným podílovým fondem spojeno právo podílníka na jeho odkoupení na účet fondu, není-li ve statutu uvedeno jinak.","tp":1},{"id":"19641.1","t":"s","q":"Podílový list fondu zakládá právo podílníka na:","o":["Spolurozhodování o investiční strategii fondu.","Podíl na majetku v podílovém fondu.","Vrácení vložených prostředků.","Minimálním výnosu investice definovaném Statutem fondu."],"c":[1],"p":40,"e":"Podílový list je majetkovým cenným papírem. Zakládá tedy právo na podílu na majetku fondu.","tp":1},{"id":"19642.1","t":"s","q":"Počet listů, který vydává otevřený podílový fond:","o":["Nesmí být vyšší než počet podílníků.","Musí být takový, aby cena jednoho listu nebyla nižší než 1 Kč.","Je dopředu znám.","Není omezen."],"c":[3],"p":40,"e":"Otevřený podílový fond neomezuje počet podílníků, ani vydaných podílových listů.","tp":1},{"id":"19643.1","t":"s","q":"U otevřeného podílového fondu, který investuje jako fond peněžního trhu nebo jako krátkodobý fond peněžního trhu, se vydávají podílové listy:","o":["Minimálně jednou týdně.","Minimálně jednou měsíčně.","Každý pracovní den.","Minimálně jednou ročně."],"c":[2],"p":40,"e":"Dle zákona o investičních společnostech a investičních fondech se u otevřeného podílového fondu, který investuje jako fond peněžního trhu nebo jako krátkodobý fond peněžního trhu, se vydávají podílové listy každý pracovní den.","tp":1},{"id":"19644.1","t":"s","q":"Po odkoupení podílových listů otevřeného podílového fondu od podílníka:","o":["Přechází podílové listy na prvního nového kupujícího.","Jsou podílové listy rozpuštěny mezi zbývající podílníky.","Jsou podílové listy evidovány jako \"bez majitele\".","Podílové listy zanikají."],"c":[3],"p":41,"e":"Podílové listy zanikají jejích odkoupením od podílníka.","tp":1},{"id":"19645.1","t":"s","q":"Hodnota podílového listu:","o":["Je stanovena jako hodnota fondového kapitálu na jednoho podílníka.","Je stanovena jako hodnota fondového kapitálu na jeden podílový list.","Nemůže být nikdy nižší než 1 Kč.","Nemůže být nikdy nižší než počet podílníků ve fondu."],"c":[1],"p":41,"e":"Aktuální hodnota podílového listu je podíl majetku podílového fondu připadající na 1 podílový list.","tp":1},{"id":"19646.1","t":"s","q":"Aktuální hodnotu podílového listu standardního fondu kolektivního investování vypočítá fond:","o":["Ve lhůtě ne delší než 2 týdny.","Vždy pouze k poslednímu dni kalendářního měsíce.","Obratem na vyžádání kteréhokoliv z podílníků fondu.","Pomocí metody průměrování nákladů."],"c":[0],"p":41,"e":"ZISIF stanovuje termín výpočtu hodnoty podílového listu.","tp":1},{"id":"19647.2","t":"s","q":"Standardní fond:","o":["Může vydávat zejména podílové listy nebo akcie.","Může vydávat pouze podílové listy.","Může vydávat pouze akcie.","Může vydávat zejména podílové listy, akcie nebo dluhopisy."],"c":[0],"p":41,"e":"Podílový fond umožňuje vydávat jak akcie, tak podílové listy (v závislosti na právní formě).","tp":1},{"id":"19648.1","t":"s","q":"Podíl investora na majetku fondu představuje:","o":["Konvertibilní akcie.","Investiční akcie.","Prioritní akcie.","Podílová akcie."],"c":[1],"p":41,"e":"Investor fondu je majitelem investiční akcie.","tp":4},{"id":"19649.1","t":"s","q":"Právo na odkoupení na účet fondu je spojeno s:","o":["Zakladatelskou akcií.","Prioritní akcií.","Podílovou akcií.","Investiční akcií."],"c":[3],"p":42,"e":"Právo na odkoupení je vázáno pouze na investiční akcii.","tp":4},{"id":"19654.1","t":"s","q":"Depozitářem fondu kolektivního investování nemůže být:","o":["Banka se sídlem v ČR.","Zahraniční banka s pobočkou v ČR.","Investiční společnost.","Obchodník s cennými papíry po splnění podmínek kapitálové přiměřenosti a s povolením k poskytování investiční služby úschovy a správy investičních nástrojů."],"c":[2],"p":42,"e":"ZISIF definuje osoby, které mohou být depozitářem. Investiční společnost mezi nimi není uvedena.","tp":1},{"id":"19655.1","t":"s","q":"Proč musí mít obhospodařovatel investičního fondu alespoň dvě vedoucí osoby s dostatečnou zkušeností se správou majetku, na který je zaměřena investiční strategie obhospodařovaného investičního fondu?","o":["Proto aby mohla výkon činnosti zcela převzít jedna osoba v případě nepřítomnosti (např. dovolené či nemoci) druhé.","Protože pouze jedna osoba nikdy nemůže mít všechny potřebné znalosti a zkušenosti potřebné pro obhospodařování fondu.","Protože jde o uplatnění tzv. pravidla čtyř očí, jde tedy o to, aby se tyto dvě osoby navzájem kontrolovaly.","Protože více než dvě osoby by neúměrně zvyšovaly náklady obhospodařovatele."],"c":[2],"p":42,"e":"V souladu se ZISIF personální vybavení obhospodařovatele investičního fondu nebo zahraničního investičního fondu musí být přiměřené povaze, rozsahu a složitosti jím vykonávaných činností. Dvě osoby zamezují koncentraci moci u jedné osoby, pomocí kontroly čtyř očí zvyšují kvalitu výkonu činnosti obhospodařovatele.","tp":1},{"id":"19658.1","t":"s","q":"Řídicí a kontrolní systém administrátora investičního fondu:","o":["Je doporučenou, ale nepovinnou součástí výkonu činnosti administrátora.","Omezuje investiční rizika fondu.","Obsahuje investiční strategii fondu.","Obsahuje systém vnitřní kontroly včetně činnosti compliance."],"c":[3],"p":42,"e":"Dle zákona o investičních společnostech a investičních fondech je řídicí a kontrolní systém zaměřen na výkon řádné činnosti administrátora a to včetně systémů vnitřní kontroly.","tp":1},{"id":"19659.1","t":"s","q":"Může být depozitářem investičního fondu jeho obhospodařovatel?","o":["Ne, nikdy.","Ano, pokud to výslovně umožňuje Statut fondu.","Ano, pokud se jedná o Fond kvalifikovaných investorů.","Ano, pokud je obhospodařovatelem fondu banka."],"c":[0],"p":42,"e":"Zákon výslovně uvádí, že depozitářem nesmí být obhospodařovatel.","tp":1},{"id":"19660.1","t":"s","q":"Fond kolektivního investování:","o":["Smí mít více depozitářů, maximálně však tři.","Smí mít více depozitářů maximálně však dva.","Smí mít pouze jednoho depozitáře.","Smí mít více depozitářů, pokud je tato skutečnost uvedena ve statutu fondu."],"c":[2],"p":43,"e":"Každý fond kolektivního investování musí mít pouze jednoho depozitáře.","tp":1},{"id":"19661.1","t":"s","q":"Poměrový ukazatel P/E (Price to Earnings) je údaj, který by měl zveřejňovat:","o":["Akciový fond.","Dluhopisový fond.","Fond peněžního trhu.","Realitní fond."],"c":[0],"p":43,"e":"Poměrový ukazatel P/E souvisí s analýzou akcií, není tudíž relevantní k dluhopisům či realitám.","tp":1},{"id":"19662.2","t":"s","q":"Způsobí-li depozitář fondu kolektivního investování podílníkovi tohoto fondu újmu, je zproštěn povinnosti k náhradě pouze v případě:","o":["Prokáže-li, že újmu nezavinil ani z nedbalosti.","Újma nepřesáhne hodnotu 100 000 Kč.","Jedná se o fond peněžního trhu.","Jedná se o újmu, způsobenou držením zahraničních investičních nástrojů."],"c":[0],"p":43,"e":"Dle zákona o investičních společnostech a investičních fondech se povinnosti k náhradě způsobené újmy depozitář fondu kolektivního investování zprostí jen prokáže-li, že újmu nezavinil ani z nedbalosti.","tp":1},{"id":"19663.1","t":"s","q":"Každý investiční fond může mít:","o":["Neomezený počet administrátorů.","Pouze jednoho administrátora.","Nejvíce dva administrátory.","Nejvíce dva administrátory, ale pouze v případě, že se jedná o tuzemské subjekty."],"c":[1],"p":43,"e":"Zákon o investičních společnostech a investičních fondech stanovuje, že každý investiční fond může mít pouze jednoho administrátora.","tp":1},{"id":"19665.1","t":"s","q":"Notář může být depozitářem:","o":["Pouze standardního fondu.","Pouze fondu kvalifikovaných investorů.","Pouze speciálního fondu.","Pouze fondu peněžního trhu."],"c":[1],"p":43,"e":"Zákon o investičních společnostech a investičních fondech specifikuje osoby, které mohou být depozitářem fondu kvalifikovaných investorů.","tp":1},{"id":"19670.1","t":"s","q":"Ukazatel TER (total expense ratio) označuje:","o":["Celkové náklady fondu v poměru k objemu majetku fondu.","Náklady fondu mimo management fee v poměru k objemu majetku fondu.","Výši management fee fondu v poměru k objemu majetku fondu.","Výši vstupních poplatků fondu v poměru k objemu majetku fondu."],"c":[0],"p":44,"e":"TER je poměrový ukazatel celkových průběžných nákladů fondu k objemu spravovaného majetku.","tp":1},{"id":"19671.1","t":"s","q":"Vstupní poplatek zpravidla slouží:","o":["Jako odměna obhospodařovateli fondu.","Jako odměna administrátorovi fondu.","Jako odměna tomu, kdo fond investorovi prodal.","Jako odměna depozitáři fondu."],"c":[2],"p":44,"e":"Vstupní poplatky běžně slouží jako odměna distributorovi za prodej a poskytnutí poradenského či zprostředkovatelského servisu.","tp":1},{"id":"19672.2","t":"s","q":"Výkonnostní odměnu:","o":["Fond účtuje v absolutní výši, která je uvedena ve statutu fondu.","Fond účtuje v procentuálním vyjádření z dosaženého zisku podle předem stanovených podmínek.","Fond účtuje v absolutní částce při splnění předem stanovených podmínek.","Fond účtuje vždy, pokud za dané období překoná svůj benchmark."],"c":[1],"p":44,"e":"Výkonnostní odměna je vypočtena jako poměrná částka ze zisku nad uvedený benchmark. Je účtována, pokud fond splní předem stanovené podmínky, například překonání nejvyšší historické hodnoty, výnos nad určitou hodnotu apod. Způsob výpočtu výkonnostní hodnoty a podmínky jeho účtování jsou uvedeny ve statutu.","tp":1},{"id":"19673.2","t":"s","q":"Co vyjadřuje ukazatel syntetický TER?","o":["Nákladovost fondu, která zahrnuje i nákladovost fondů držených v majetku fondu.","Nákladovost fondu v poměru k počtu vydaných akcií či podílových listů.","Nákladovost všech podfondů mateřského fondu.","Nákladovost fondu, která zahrnuje i nákladovost investiční společnosti."],"c":[0],"p":44,"e":"Ukazatel celkové nákladovosti fondu (syntetický TER) je definován ve vyhlášce o statutu fondu kolektivního investování.","tp":1},{"id":"19675.1","t":"s","q":"Výstupní poplatek může investor hradit při:","o":["Ukončení činnosti fondu.","Prodeji akcií či podílových listů fondu.","Nákupu akcií či podílových listů fondu.","Změně investiční politiky fondu."],"c":[1],"p":44,"e":"Pokud je výstupní poplatek aplikován, je to při \"vystoupení\" investora z fondu, tedy při prodeji akcií či podílových listů fondu.","tp":1},{"id":"19676.1","t":"s","q":"Vstupní poplatek hradí investor:","o":["Nejpozději do 1 měsíce po nákupu akcií či podílových listů fondu.","Při nákupu akcií či podílových listů fondu.","Při prodeji akcií či podílových listů fondu.","V měsíci následujícím po každém kalendářním čtvrtletí po dobu, kdy je vlastníkem akcií či podílových listů fondu."],"c":[1],"p":45,"e":"Vstupní poplatek strhává distributor fondu investorovi při nákupu akcií či podílových listů fondu z celkové investované částky.","tp":1},{"id":"19678.2","t":"s","q":"Úplata za obhospodařování fondu kolektivního investování se určí zejména:","o":["Podílem z čisté hodnoty fondového kapitálu investičního fondu ke konci kalendářního roku.","Podílem z čistého přírůstku aktiv ke konci obchodního dne.","Podílem z výsledku hospodaření investičního fondu nebo jeho části po zdanění.","Podílem z průměrné hodnoty fondového kapitálu investičního fondu nebo jeho části za účetní období."],"c":[3],"p":45,"e":"Úplata za obhospodařování fondu kolektivního investování se určí zejména podílem z průměrné hodnoty fondového kapitálu investičního fondu nebo jeho části za účetní období.","tp":1},{"id":"19679.1","t":"s","q":"Výkonnostní poplatek:","o":["Může být i záporný v případě záporného výnosu fondu.","Je nulový nebo kladný.","Je účtován při jakémkoliv kladném či záporném zhodnocení fondu.","Je nulový nebo záporný."],"c":[1],"p":45,"e":"Výkonnostní poplatek je vypočten v případě, že výkonnost tohoto fondu přesáhne určený ukazatel (benchmark), s nímž je výkonnost srovnávána. Je tedy buď nulový (při nesplnění) nebo kladný (při splnění).","tp":1},{"id":"19680.1","t":"s","q":"Poplatek za správu akciového fondu:","o":["Je zpravidla vyšší než poplatek za správu fondu peněžního trhu","Nesmí být vyšší než poplatek za správu fondu peněžního trhu stejného správce","Je zpravidla nižší než poplatek za správu fondu peněžního trhu","Nesmí být nižší než poplatek za správu fondu peněžního trhu stejného správce"],"c":[0],"p":45,"e":"Akciové fondy zpravidla účtují výrazně vyšší poplatky za správu než fondy peněžního trhu","tp":1},{"id":"19681.1","t":"s","q":"Celkovou nákladovost fondu vyjadřuje ukazatel:","o":["Průměrný kreditní rating.","SRRI (SyntheticRisk and Reward Indicator).","Průměrný výnos do splatnosti.","TER (total expense ratio)."],"c":[3],"p":45,"e":"Celkovou nákladovost fondu vyjadřuje ukazatel TER.","tp":1},{"id":"19686.3","t":"s","q":"Mezi investiční nástroje nepatří:","o":["Platební nástroje.","Nástroje peněžního trhu.","Investiční cenné papíry.","Cenné papíry kolektivního investování."],"c":[0],"p":46,"e":"Ustanovuje tak Zákon o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., § 3 Investiční nástroje.","tp":2},{"id":"19688.2","t":"s","q":"Základní druhy akcií jsou:","o":["Akcie kuponové a bezkuponové.","Akcie primární a sekundární.","Akcie kmenové a prioritní.","Akcie manažerské a zaměstnanecké."],"c":[2],"p":46,"e":"Ve světě je různé dělení akcií, záleží na legislativě. Prakticky ve všech zemích se však užívá uvedená správná odpověď. Akcie lze obchodovat na primárním a sekundárním trhu, přesto, ale není možné rozlišovat akcie na primární a sekundární. Obdobně, akcie v rámci běžného výnosu nese dividendu, nikoliv kupon jako kuponový dluhopis. Přestože se lze setkat i se zaměstnaneckými akciemi, nejedná se o standardní členění.","tp":4},{"id":"19689.5","t":"s","q":"Efektivnost fungování finančního trhu je charakterizována takto:","o":["Finanční trh by měl zajišťovat co nejvyšší výnos za co nejkratší dobu.","Finanční trh by měl zajišťovat trvalou maximalizaci zisku.","Finanční trh by měl zajišťovat maximální omezení možné ztráty.","Finanční trh by měl fungovat takovým způsobem, aby disponibilní peněžní prostředky byly směrovány do nejziskovějších investičních projektů."],"c":[3],"p":46,"e":"Efektivní reálný trh by měl fungovat tak, aby odrážel všechny nejnovější a všem účastníkům trhu vždy dostupné informace, avšak současně se musejí brát v úvahu tři protichůdně působící parametry z tzv. Trojúhelníku investora - riziko, výnos, likvidita.","tp":2},{"id":"19691.1","t":"s","q":"Základní druhy reálných komoditních investičních nástrojů jsou obvykle členěny na:","o":["Komodity, nemovitosti, movité věci.","Drahé kovy termínové, inertní a kosmopolitní.","Nemovitosti reálné, ve stádiu projektu, historické.","Starožitnosti movité a nemovité."],"c":[0],"p":46,"e":"Jedná se o obvyklé mezinárodně přijaté členění reálných investic.","tp":2},{"id":"19692.1","t":"s","q":"Systém vypořádání burzovních obchodů, ve kterém současně dochází k pohybu cenných papírů a peněžních prostředků, se nazývá:","o":["Global settlement.","Delivery versus payment (DVP).","Riskless payment (RLP).","Global delivery."],"c":[1],"p":46,"e":"Lze odvodit z § 88 Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb., jde o obvyklou praxi na světových trzích.","tp":0},{"id":"19693.1","t":"s","q":"Cennými papíry kolektivního investování jsou zejména:","o":["Akcie inv. fondu, podílové listy a ETF.","Dluhopisy a deriváty.","Opce a futures.","Akcie a termínové obchody."],"c":[0],"p":47,"e":"Ze své podstaty tyto fondy používají nízkorizikové investiční nástroje.","tp":2},{"id":"19694.1","t":"s","q":"Investičními nástroji nejsou:","o":["Akcie.","Platební nástroje.","Dluhopis.","Opce."],"c":[1],"p":47,"e":"Investiční a neinvestiční nástroje definuje ZPKT v § 3.","tp":2},{"id":"19695.1","t":"s","q":"Trh, na kterém dochází k prvotnímu prodeji (emisi) určitého nástroje, např. k prodeji nově emitovaných dluhopisů či akcií, se nazývá:","o":["Základní trh.","Primární trh.","Sekundární trh.","Terciální trh."],"c":[1],"p":47,"e":"Vychází z obvyklého členění trhů v odborné literatuře.","tp":2},{"id":"19696.2","t":"s","q":"Pokud lze uplatnit opci pouze v jeden přesně určený den splatnosti opce, jde o:","o":["Kanadskou opci.","Japonskou opci.","Evropskou opci.","Americkou opci."],"c":[2],"p":47,"e":"Historická zvyklost na trzích a odborná literatura.","tp":5},{"id":"19697.1","t":"s","q":"Schopnost přeměny investičního nástroje na disponibilní finanční prostředky s minimálními náklady se nazývá:","o":["Volatilita.","Bonita.","Solventnost.","Likvidita."],"c":[3],"p":47,"e":"Jde o historickou zvyklost na trzích, (tzv. notorieta, z lat. notorius, známý), skutečnost, která se pokládá za všeobecně známou a není třeba ji kodifikovat.","tp":2},{"id":"19702.1","t":"s","q":"Dluhopisy mohou mít podobu:","o":["Pouze zaknihovanou nebo listinnou.","Zaknihovanou, listinnou nebo majetkovou.","Zaknihovanou, listinnou nebo evidenční.","Zaknihovanou nebo majetkovou."],"c":[0],"p":48,"e":"Znění zákona.","tp":0},{"id":"19703.1","t":"s","q":"Pokud má dluhopis zaknihovanou podobu, pak se jedná o dluhopis, který:","o":["Má podobu elektronického záznamu v evidenci.","Musí být obchodovaný na regulovaném trhu.","Je neveřejně obchodovatelný.","Nemůže změnit majitele."],"c":[0],"p":48,"e":"Znění zákona.","tp":3},{"id":"19704.1","t":"s","q":"Pro dluhopis mající formu \"na řad\" může práva spojená s tímto CP vykonávat pouze osoba:","o":["Zapsaná jako majitel v seznamu vedeném emitentem.","Zapsaná jako majitel v evidenci dozorového orgánu (ČNB).","Která tento CP vlastní, přičemž převod rubopisem je možný pouze se souhlasem centrálního depozitáře.","Která tento CP vlastní, přičemž převod rubopisem není možný."],"c":[0],"p":48,"e":"Znění zákona.","tp":3},{"id":"19705.1","t":"s","q":"Pro listinný dluhopis \"na řad\" může práva spojená s tímto cenným papírem vykonávat osoba:","o":["Zapsaná jako vlastník v seznamu vlastníků vedeného oprávněnou osobou.","Nacházející se kdekoliv v seznamu na rubopisu.","Zapsaná jako majitel v evidenci dozorového orgánu (ČNB).","Která tento cenný papír získala v rámci primárního úpisu."],"c":[0],"p":48,"e":"Znění zákona.","tp":0},{"id":"19706.1","t":"s","q":"Dluhopis mající formu \"na řad\":","o":["Patří mezi dluhopisy, které obsahují jméno oprávněné osoby.","Patří mezi dluhopisy na jméno, přičemž převod rubopisem není možný.","Patří mezi dluhopisy na majitele, přičemž převod rubopisem je nutný.","Patří mezi dluhopisy na majitele, přičemž převod rubopisem není možný."],"c":[0],"p":48,"e":"Znění zákona.","tp":3},{"id":"19707.1","t":"s","q":"Komunální dluhopis může být vydán:","o":["Obcí po předchozím souhlasu Ministerstva financí ČR.","Obcí za účelem navýšení základního kapitálu.","Obcí, a to pouze v České republice.","Obcí nebo ministerstvem."],"c":[0],"p":49,"e":"Znění zákona.","tp":3},{"id":"19708.1","t":"s","q":"Hypoteční zástavní list je cenný papír:","o":["Jehož jmenovitá hodnota a výnosy jsou kryté pohledávkami z hypotečních úvěrů.","Který musí být vydávám jako listinný.","Jehož emitentem je banka nebo územně samosprávný celek.","Dluhopis sloužící jako doklad o hypotečním úvěru."],"c":[0],"p":49,"e":"Znění zákona.","tp":0},{"id":"19709.1","t":"s","q":"Prioritní dluhopis umožňuje jeho vlastníkovi přednostní právo při:","o":["Upisování akcií daného emitenta.","Nákupu dalších dluhopisů daného emitenta.","Výplatě dividendy.","Hlasování na valné hromadě emitenta."],"c":[0],"p":49,"e":"Znění zákona.","tp":3},{"id":"19710.1","t":"s","q":"U emise dluhopisů obecně platí, že splatnost je možná:","o":["Jednorázově k datu splatnosti nebo splátkami.","Pouze jednorázově k datu splatnosti.","Pouze splátkami nejpozději k datu splatnosti.","V období mezi 30 dny před datem splatnosti a datem splatnosti."],"c":[0],"p":49,"e":"Znění zákona.","tp":3},{"id":"19711.1","t":"s","q":"Pro emisi tzv. svolatelných (callable) dluhopisů je předčasné splacení možné:","o":["Pokud je tato možnost uvedena v emisních podmínkách.","Kdykoliv.","Pokud je dluhopis listinný.","V případě evidence dluhopisu v centrálním depozitáři."],"c":[0],"p":49,"e":"Znění zákona.","tp":3},{"id":"19713.1","t":"s","q":"Rozhodnutí valné hromady o vydání vyměnitelných (konvertibilních) dluhopisů musí obsahovat zejména:","o":["Jmenovitou hodnotu dluhopisů, počet dluhopisů, místo a lhůtu pro uplatnění práv, údaje o emisním kurzu a charakteristiku akcií, za které lze dluhopis vyměnit nebo upsat.","Emisní kurs, formu, podobu, výši dividendy, místo a lhůtu pro uplatnění práv a charakteristiku akcií, za které lze dluhopis vyměnit nebo upsat.","Lhůtu pro uplatnění práva výměny, rozhodný den, jmenovitou hodnotu, výnos a charakteristiku akcií, za které lze dluhopis vyměnit nebo upsat.","Počet dluhopisů, přednostní právo, rozhodnutí o zvýšení kapitálu, lhůtu pro uplatnění práva výměny a emisní kurz."],"c":[0],"p":50,"e":"Znění zákona.","tp":3},{"id":"19718.1","t":"s","q":"Sběrný dluhopis je listinný dluhopis:","o":["Který je upsaný v upisovací listině, ale jednotlivé podíly (dluhopisy) pak lze obchodovat jednotlivě.","U kterého dochází k cílenému sběru nákupních pokynů.","U kterého je nutný sběr určitého počtu kusů.","Kde je omezen počet vlastníků."],"c":[0],"p":50,"e":"Znění zákona.","tp":3},{"id":"19719.1","t":"s","q":"Z hlediska typu úročení je konkrétní výše výnosu předem známa u:","o":["Dluhopisů s pevným úrokem a dluhopisů s nulovým úrokem (zero).","Dluhopisů s pevným úrokem a variabilních dluhopisů.","Dluhopisů s pevným úrokem a majetkových dluhopisů.","Dluhopisů s pevným úrokem a indexovaných dluhopisů."],"c":[0],"p":50,"e":"Znění zákona.","tp":2},{"id":"19720.1","t":"s","q":"Právo účasti na schůzi vlastníků dluhopisu má osoba vedená v evidenci osoby oprávněné k vedení evidence jako vlastník dluhopisu:","o":["K tzv. rozhodnému dni.","Ke dni konání schůze vlastníků.","Nejméně 15 dnů před dnem konání schůze vlastníků.","Nejpozději do 15 dnů od oznámení konání schůze vlastníků."],"c":[0],"p":50,"e":"Znění zákona.","tp":3},{"id":"19721.1","t":"s","q":"Společný zástupce vlastníků dluhopisů:","o":["Je ustanoven na základě rozhodnutí schůze vlastníků.","Je ustanoven na základě rozhodnutí emitenta.","Pokud je ustanoven, nemůže být odvolán.","Se může schůze vlastníků technicky účastnit prostřednictvím dálkového přenosu, ale je považován za nepřítomného."],"c":[0],"p":50,"e":"Znění zákona.","tp":3},{"id":"19722.1","t":"s","q":"V případě, že emisní podmínky umožňují oddělení práva na výnos od dluhopisu, tak:","o":["Spolu s listinným dluhopisem musí být vydán kuponový arch, přičemž každý výnos musí mít svůj vlastní kupon.","Kuponový arch pro listinný dluhopis nemusí být vydán, ale každý výnos musí mít svůj vlastní kupon.","Pro listinný dluhopis platí, že obchodovat lze pouze jednotlivé oddělené kupony.","Pro zaknihovaný dluhopis platí, že obchodovat lze pouze jednotlivé oddělené kupony."],"c":[0],"p":51,"e":"Znění zákona.","tp":3},{"id":"19723.2","t":"s","q":"Při oddělení práva na výnos od dluhopisu:","o":["Je opětovné spojení jistiny a kuponů možné, pokud jsou k tomu splněny podmínky dané zákonem.","Je možné opětovné spojení jistiny a kuponů, které už byly splatné.","Je možné opětovné spojení jistiny a kuponů, a to na žádost osoby oprávněné k vedení evidence.","Není možné opětovné spojení jistiny a kuponů."],"c":[0],"p":51,"e":"Znění zákona.","tp":3},{"id":"19724.1","t":"s","q":"U některých dluhopisů lze (v souladu s emisními podmínkami) oddělit jistinu a výnosy. U takovýchto dluhopisů předčasné splacení:","o":["Je možné.","Je možné pouze v případě souhlasu ČNB.","Je možné pouze v případě listinných dluhopisů.","Není možné."],"c":[0],"p":51,"e":"Znění zákona.","tp":3},{"id":"19725.1","t":"s","q":"Pokud je dluhopis vydán jako svolatelný, pak:","o":["Je možné předčasné splacení emise, pokud to umožňují emisní podmínky.","Je možné oddělit kupóny od jistiny.","Má majitel dluhopisů právo svolat valnou hromadu.","Nesmí mít variabilní úrokovou sazbu."],"c":[0],"p":51,"e":"Pokud je dluhopis svolatelný (vypověditelný), pak je v emisních podmínkách zakotveno právo emitenta na předčasné splacení emise.","tp":3},{"id":"19726.1","t":"s","q":"Bezkuponový dluhopis nazývaný také \"zero bond\" je:","o":["Diskontovaný dluhopis, přičemž diskont je zohledněn v ceně nižší než nominální hodnota dluhopisu.","Anuitní dluhopis, kde anuitou je myšlena jistina.","Zajištěný dluhopis, přičemž zajištěny jsou závazky emitenta.","Dluhopis s odloženou platbou, kde je odložena platba výnosů z kupónů za první období."],"c":[0],"p":51,"e":"Zero dluhopisy jsou prodávány za nižší cenu, čímž se nahrazuje absence kupónových výnosů.","tp":3},{"id":"19727.1","t":"s","q":"Pro dluhopisový program platí, že:","o":["Přesný počet emisí spadajících pod tento program nemusí být předem určen.","Přesný počet emisí spadajících pod tento program musí být předem určen.","Musí být předem určen min. a max. počet emisí spadajících pod tento program.","Přesný počet emisí spadajících pod tento program musí být předem určen, ale lze ho změnit."],"c":[0],"p":52,"e":"Znění zákona.","tp":3},{"id":"19728.3","t":"s","q":"Ohledně osoby emitenta dluhopisů vydávaných v rámci dluhopisového programu:","o":["Není žádné omezení.","Omezení je, ale mohou být vydávány pouze státní nebo korporátní.","Omezení je, mohou být vydávány pouze státní nebo bankovní.","Omezení je, mohou být vydávány pouze státní nebo municipální."],"c":[0],"p":52,"e":"Zákonem č. 172/2012 Sb. byl upraven § 3 zákona č. 190/2004 Sb., o dluhopisech, ve znění pozdějších předpisů, kdy došlo ke zrušení výčtu osob, které mohou dluhopisy vydávat. Současně znění zákona neobsahuje žádné omezení. Pokud má dluhopis prospekt je možné ho dle Zákona č. 256/2004 Sb., o podnikání na kap. trhu, § 35 nabízet veřejně.","tp":3},{"id":"19729.1","t":"s","q":"V případě, že na veřejném trhu lze obchodovat práva na výnos odděleně od dluhopisu, tak:","o":["Musí mít svoje vlastní označení (ISIN) dluhopis s kupony, jistina a každý kupon.","Musí mít svoje vlastní označení (ISIN) dluhopis s kupony a jistina.","Musí mít svoje vlastní označení (ISIN) dluhopis s kupony a každý kupon.","Musí mít svoje vlastní označení (ISIN) jistina a každý kupon."],"c":[0],"p":52,"e":"Znění zákona.","tp":3},{"id":"19734.3","t":"s","q":"Podstatou opčního listu je přednostní právo na upsání:","o":["Akcií nebo dluhopisů daného emitenta.","Opcí daného emitenta.","Certifikátů daného emitenta.","Podílových listů daného emitenta."],"c":[0],"p":52,"e":"Opční list je derivátem, jehož podkladovým aktivem je akcie nebo dluhopis, jiné podkladové aktivum se v případě opčního listu nepoužívá.","tp":3},{"id":"19735.3","t":"s","q":"Opční list je vydáván jako cenný papír:","o":["Na doručitele.","Na majitele.","Na jméno.","Na řad."],"c":[0],"p":52,"e":"Podstatou opčního listu je právo na úpis akcie nebo dluhopisu, toto právo má subjekt, který toto právo využije - tedy doručitel.","tp":0},{"id":"19736.1","t":"s","q":"Emitent investičního certifikátu má obvykle povinnost:","o":["Odkoupit certifikát od investora zpět, což je dáno emisními podmínkami.","Prodat certifikát investorovi.","Umožnit investorovi výměnu certifikátu za podkladové aktivum.","Dodat investorovi podkladové aktivum."],"c":[0],"p":53,"e":"Svou podstatou se investiční certifikáty řadí mezi dluhové instrumenty, ze kterých vyplývá povinnost emitenta vůči majiteli. Tato povinnost bývá zakotvena v emisních podmínkách certifikátů.","tp":3},{"id":"19737.1","t":"s","q":"Na cenu investičního certifikátu má vliv:","o":["Vývoj ceny podkladového aktiva.","Doba do výplaty dividendy.","Doba do výplaty kupónu.","Termín vypořádání."],"c":[0],"p":53,"e":"Závislost na ceně PA je jednou ze základní vlastností investičních certifikátů.","tp":5},{"id":"19738.2","t":"s","q":"To, že je emise vydávána jako časově neohraničená (věčná) obligace:","o":["Musí být dáno emisními podmínkami.","Se investor dozví při výplatě kupónů.","Emitent nemusí oznamovat.","Znamená, že nemá ohraničenou výšku úroku."],"c":[0],"p":53,"e":"Jde o dluhopisy, jejichž základní vlastností je, že v emisních podmínkách není termín splatnosti.","tp":3},{"id":"19740.1","t":"s","q":"Opční listy jako zaknihovaný cenný papír vydány být:","o":["Mohou.","Nemohou.","Mohou, ale pouze se souhlasem regulovaného trhu, kde mají být obchodovány.","Mohou, pokud emitent požádá o výjimku ČNB."],"c":[0],"p":53,"e":"Opční listy jako zaknihovaný cenný papír vydány být mohou.","tp":0},{"id":"19742.3","t":"s","q":"S dluhovými cennými papíry lze na burze cenných papírů v České republice obchodovat:","o":["Pokud splňují podmínky pro přijetí investičního nástroje k obchodování na regulovaném trhu.","Pouze se souhlasem emitenta.","Pouze se souhlasem Ministerstva financí ČR.","Pokud mají schválený prospekt a úrokovou míru."],"c":[0],"p":53,"e":"Dluhové cenné papíry obchodované na burze cenných papírů musí splňovat podmínky pro jejich přijetí k obchodování na burze, tedy regulovaném trhu, přitom není nutný ani souhlas emitenta, ani souhlas Ministerstva financí ČR.","tp":0},{"id":"19743.1","t":"s","q":"Pokud bylo uplatněno právo vyplývající z daného opčního listu:","o":["Dojde ke zrušení tohoto opčního listu.","Musí být tato skutečnost zveřejněna.","Je vydán nový opční list.","Může dojít k zaevidování tohoto opčního listu."],"c":[0],"p":54,"e":"Pokud bylo uplatněno právo vyplývající z daného opčního listu, dojde ke zrušení tohoto opčního listu.","tp":10},{"id":"19744.1","t":"s","q":"Dluhové cenné papíry mohou být nahrazeny hromadnou listinou pouze v případě, že jsou:","o":["Zastupitelné.","Obchodovatelné.","Imobilizované.","S pevným úrokem."],"c":[0],"p":54,"e":"Dluhové cenné papíry mohou být nahrazeny hromadnou listinou pouze v případě, že jsou zastupitelné.","tp":0},{"id":"19745.1","t":"s","q":"Z vlastnictví hromadné listiny dluhopisů plyne vlastníkovi právo na:","o":["Její výměnu za jednotlivé dluhopisy.","Mimořádnou výplatu hromadného úroku.","Její výměnu za prioritní akcie.","Obchodování na regulovaném trhu."],"c":[0],"p":54,"e":"Z vlastnictví hromadné listiny dluhopisů plyne vlastníkovi právo na její výměnu za jednotlivé dluhopisy.","tp":3},{"id":"19751.1","t":"s","q":"V emisi je 1 000 ks akcií, je veřejně obchodovatelná. Jmenovitá hodnota akcie = 1 000 Kč, emisní kurz = 1 100 Kč, kurz akcie = 1 500 Kč. Z těchto hodnot lze určit, že:","o":["Emisní ážio = 100 Kč.","Emisní ážio = 200 Kč.","Emisní ážio = 300 Kč.","Emisní ážio = 500 Kč."],"c":[0],"p":54,"e":"Emisní ážio = emisní kurz - nominální hodnota 1 100-1 000=100.","tp":4},{"id":"19752.1","t":"s","q":"Technická analýza akcií vychází z:","o":["Dosavadního vývoje a výsledků trhu.","Tržních ukazatelů emitenta akcií.","Analýzy celkových aktiv emitenta.","Fundamentální analýzy."],"c":[0],"p":54,"e":"Technická analýza vychází z publikovaných tržních dat.","tp":4},{"id":"19753.1","t":"s","q":"O výplatě dividendy akcionářům rozhoduje:","o":["Valná hromada.","Dozorčí rada.","Dozorový orgán.","Osoba oprávněná k vedení evidence."],"c":[0],"p":55,"e":"Znění zákona o Obchodních korporacích.","tp":4},{"id":"19754.1","t":"s","q":"Podíl na zisku (tzv. dividendu) lze vyplatit:","o":["Pouze ve stanovené výši.","Pouze v hotovosti.","Pouze v sídle emitenta.","Pouze přes účet osoby oprávněné k vedení evidence."],"c":[0],"p":55,"e":"Znění zákona o Obchodních korporacích.","tp":4},{"id":"19755.1","t":"s","q":"Podíl na zisku (tzv. dividenda), přičemž společníci se podílejí na zisku v poměru svých podílů, může být vyplacen:","o":["U zaknihovaných i listinných akcií.","U zaknihovaných i listinných akcií, pokud byly řádně vyplaceny zálohy za zisk.","Pouze u zaknihovaných akcií.","Pouze u zaknihovaných akcií, ledaže by listinné akcie byly prioritní."],"c":[0],"p":55,"e":"Znění zákona o Obchodních korporacích.","tp":4},{"id":"19756.1","t":"s","q":"Pokud je \"P/E (Price to Earnings) ratio\" u akcie vysoké (např. když P/E = 60), pak:","o":["Je akcie nadhodnocena.","Je akcie podhodnocena.","Je akcie likvidní.","Je akcie volatilní."],"c":[0],"p":55,"e":"Pokud je P/E vysoké, tak je vysoký kurz vůči ziskovosti akcie (vysoká hodnota čitatele vůči jmenovateli).","tp":4},{"id":"19757.1","t":"s","q":"Pro parametr \"ukazatel čistého zisku na akcii\" se používá zkratka:","o":["EPS (earnings per share).","EPE (earnings per equity).","ROA (return on asset).","ROE (return on equity)."],"c":[0],"p":55,"e":"Ukazatel čistého zisku na akcii = EPS.","tp":4},{"id":"19762.1","t":"s","q":"Zatímní list je vydáván akciovou společností:","o":["Jako náhrada akcií - jsou s ním spojena práva a povinnosti nesplacených akcií.","Jako doklad o investici do dluhopisů vydaných tímto emitentem.","Namísto dlužního úpisu této akciové společnosti.","Jako doklad o uložení peněz do depozitu."],"c":[0],"p":56,"e":"Znění zákona.","tp":4},{"id":"19763.2","t":"s","q":"Vydání zatímních listů dané akciové společnosti musí umožňovat:","o":["Stanovy akciové společnosti.","Dozorový orgán.","Statut akciové společnosti.","Zákon o cenných papírech."],"c":[0],"p":56,"e":"Znění zákona.","tp":0},{"id":"19764.1","t":"s","q":"Zkratka GDR znamená.","o":["Global Depositary Receipt (globální depozitní certifikáty).","Government Depositary Receipt (státní depozitní certifikáty).","Gold Depositary Receipt (zlaté depozitní certifikáty).","Garanted Depositary Receipt (Garantované depozitní certifikáty)."],"c":[0],"p":56,"e":"GDR = Global Depositary Receipt.","tp":10},{"id":"19765.1","t":"s","q":"Global Depository Receipt (GDR) jsou vydávány za účelem:","o":["Obchodování akcií v zahraničí, přičemž původní akcie jsou uloženy v odpovídajícím depozitáři.","Obchodování akcií v zahraničí, přičemž původní akcie pozbývají platnosti.","Zpětného odkupu akcií ze zahraničního trhu, přičemž již odkoupené akcie jsou uloženy v odpovídajícím depozitáři.","Obchodování akcií v zahraničí, přičemž na zahraniční GDR se nevztahuje právo na úpis akcií."],"c":[0],"p":56,"e":"GDR slouží pro obchodování s akciemi na zahraničím trhu bez nutné administrativy související s jejich převodem do zahraničí.","tp":4},{"id":"19766.1","t":"s","q":"Pokud daný cenný papír představuje podíl na akciové společnosti, jedná se o:","o":["Majetkový cenný papír.","Podílový list.","Podílovou akcii.","Podílový certifikát."],"c":[0],"p":56,"e":"Za majetkové cenné papíry jsou považovány takové cenné papíry, kde investor majetkově vstupuje do a.s. (na rozdíl např. od dluhových cenných papírů) .","tp":0},{"id":"19767.1","t":"s","q":"Kmenový list je emitován:","o":["Společností s ručením omezeným.","Podílovým fondem.","Akciovou společností.","Bankou."],"c":[0],"p":57,"e":"Majetkový CP, který emituje s.r.o. za účelem převodu vlastnických podílů.","tp":1},{"id":"19768.1","t":"s","q":"Účelem vydání kmenových listů je:","o":["Možnost převodu vlastnických podílů.","Možnost změny podoby akcie, která patří ke kmenovému listu.","Uplatnění práva na úpis akcií.","Informace o seznamu podílníků."],"c":[0],"p":57,"e":"Majetkový CP, který emituje s.r.o. za účelem převodu vlastnických podílů.","tp":4},{"id":"19769.1","t":"s","q":"Kusová akcie je akcie, která:","o":["Nemá jmenovitou hodnotu.","Nemá stanovenou formu.","Nemá stanovenou podobu.","Nemůže být vydána obchodní společností."],"c":[0],"p":57,"e":"Znění zákona.","tp":4},{"id":"19770.2","t":"s","q":"Účetní hodnota pro kusové akcie se stanovuje jako:","o":["Podíl základního kapitálu a počtu vydaných kusových akcií.","Podíl základního kapitálu a počtu vydaných akcií se jmenovitou hodnotou.","Podíl tržní kapitalizace a kurzu akcie.","Podíl tržní kapitalizace a počtu vydaných akcií"],"c":[0],"p":57,"e":"Znění zákona.","tp":4},{"id":"19771.1","t":"s","q":"K jedné kusové akcii patří:","o":["Jeden hlas, pokud stanovy neuvádí jinak.","Výplata jedné dividendy.","Jeden hlas navíc oproti běžným akciím.","Jedna výměna za prioritní akcii."],"c":[0],"p":57,"e":"Znění zákona.","tp":4},{"id":"19772.2","t":"s","q":"Vlastnictví majetkového cenného papíru je automaticky spojeno:","o":["S majetkovým vstupem do dané akciové společnosti.","Se zápisem na majetkovém účtu v Centrálním depozitáři cenných papírů.","Se zápisem na majetkovém účtu v clearingové bance.","S majetkovým vstupem do podílových fondů emitenta."],"c":[0],"p":58,"e":"Vlastnictví majetkového cenného papíru znamená majetkový vstup investora do společnosti (emitenta cenného papíru) a nabytí akcionářských práv.","tp":0},{"id":"19773.1","t":"s","q":"Investiční list patří mezi:","o":["Cenné papíry, které představují podíl na majetku.","Investiční cenné papíry, které jsou obchodovatelné na veřejných trzích.","Cenné papíry, které nejsou převoditelné.","Majetkové CP, které mohou být vydávány pouze jako zaknihované."],"c":[0],"p":58,"e":"Znění zákona.","tp":0},{"id":"19790.1","t":"s","q":"Opce dávající právo uplatnění kdykoli do doby expirace se nazývá:","o":["Evropská opce.","Americká opce.","Asijská opce.","Binární opce."],"c":[1],"p":58,"e":"Americkou opci lze, na rozdíl od evropské, uplatnit kdykoli do data expirace, včetně tohoto data.","tp":5},{"id":"19791.1","t":"s","q":"Burzovní kontrakt závazný pro obě strany se nazývá:","o":["Swap.","Futures.","Credit default swap (CDS).","Opce."],"c":[1],"p":58,"e":"Kontrakt futures se od forwardového kontraktu liší právě svou standardizací, která spočívá mj. v tom, že kontrakt futures je obchodován na burze.","tp":5},{"id":"19792.1","t":"s","q":"Podkladovým aktivem kontraktu Forward rate agreement (FRA) je:","o":["Úroková míra.","Akcie.","Měna.","Komodita."],"c":[0],"p":58,"e":"FRA neboli \"forward rate agreement\" je \"dohoda o budoucích úrokových sazbách\", takže úroková sazba je podkladovým aktivem.","tp":5},{"id":"19793.1","t":"s","q":"Podkladovým aktivem kontraktu Credit default swap (CDS) je:","o":["Akcie.","Akciový index.","Dluhopis.","Měna."],"c":[2],"p":59,"e":"CDS (credit default swap) je vlastně \"pojištění dluhopisu\", ten je tedy podkladovým aktivem.","tp":5},{"id":"19794.1","t":"s","q":"Z následujících kontraktů je derivátem:","o":["Akcie.","Dluhopisy.","Pokladniční poukázka.","Swap."],"c":[3],"p":59,"e":"Pouze swap je z uvedených možností derivátem.","tp":5},{"id":"19795.1","t":"s","q":"Úrokový swap je nejčastěji uzavírán na několik:","o":["Dní.","Týdnů.","Měsíců.","Let."],"c":[3],"p":59,"e":"Pro úrokový swap je typická opakovaná výměna úrokových sazeb v delším časovém horizontu několika let.","tp":5},{"id":"19796.1","t":"s","q":"Kontrakt, jehož nákupem získá investor právo, nikoli povinnost plnit, se nazývá:","o":["Swap.","Forward.","Opce.","Futures."],"c":[2],"p":59,"e":"Nákupem opce nebo kontraktu CDS získává investor právo uplatnit opci nebo CDS, nemá však povinnost uplatnění - své právo využije nebo nevyužije podle vývoje podkladového aktiva.","tp":5},{"id":"19797.1","t":"s","q":"Derivátový kontrakt je definován jako:","o":["Promptní kontrakt spojený vždy s konkrétním podkladovým aktivem.","Promptní kontrakt, který nemusí být spojen s žádným podkladovým aktivem.","Termínový kontrakt spojený vždy s konkrétním podkladovým aktivem.","Termínový kontrakt, který nemusí být spojen s žádným podkladovým aktivem."],"c":[2],"p":59,"e":"Derivát je z definice termínový kontrakt, který je odvozen od podkladového aktiva - bez něho nemá smysl.","tp":5},{"id":"19798.1","t":"s","q":"Prodej put opce je spojen s budoucím:","o":["Právem koupit podkladové aktivum.","Právem prodat podkladové aktivum.","Závazkem koupit podkladové aktivum.","Závazkem prodat podkladové aktivum."],"c":[2],"p":60,"e":"Prodejce put opce poskytl protistraně právo mu prodat podkladové aktivum, v případě využití opce má tedy závazek toto aktivum koupit.","tp":5},{"id":"19799.1","t":"s","q":"Nákup call opce je spojen s budoucím:","o":["Právem koupit podkladové aktivum.","Závazkem koupit podkladové aktivum.","Právem prodat podkladové aktivum.","Závazkem prodat podkladové aktivum."],"c":[0],"p":60,"e":"Držitel call opce má právo koupit podkladové aktivum.","tp":5},{"id":"19800.1","t":"s","q":"Každá opce obchodovaná na trhu:","o":["Nemusí mít žádnou realizační cenu (strike price).","Má vždy právě jednu realizační cenu (strike price).","Má vždy právě dvě realizační ceny (strike prices), investor si může zvolit.","Může mít více než dvě realizační ceny (strike prices), investor má ještě větší možnost volby, která se projeví v ceně opce."],"c":[1],"p":60,"e":"Opce má vždy pouze jednu realizační cenu. Opce se ale mohou lišit různě stanovenou realizační cenou (strike price), podle výše těchto realizačních cen se liší i prémie zaplacené za tyto opce.","tp":5},{"id":"19801.3","t":"s","q":"Opční list opravňující k budoucímu nákupu podkladového aktiva se nazývá:","o":["Globální depozitní certifikát (GDR).","Investiční certifikát.","Warrant.","Akciový certifikát."],"c":[2],"p":60,"e":"Warrant je jiný název pro opční list, který dává právo na budoucí nákup podkladového aktiva.","tp":5},{"id":"19830.2","t":"s","q":"Pokud je realizační cena (strike price) u call opce vyšší než tržní cena podkladového aktiva, je call opce tzv.:","o":["Mimo peníze (out of the money).","Na penězích (at the money).","V penězích (in the money).","S penězi (with the money)."],"c":[0],"p":60,"e":"Pozice \"out of the money\" nastane v případě call opce, je-li aktuální tržní cena nižší než realizační cena (strike price). Pokud by totiž toto platilo v čase expirace, nebyla by opce uplatněna.","tp":5},{"id":"19831.2","t":"s","q":"Pokud je realizační cena (strike price) u put opce vyšší než tržní cena podkladového aktiva, je put opce tzv.:","o":["Mimo peníze (OTM, out of the money).","Na penězích (ATM, at the money).","V penězích (ITM, in the money).","S penězi (WTM, with the money)."],"c":[2],"p":61,"e":"Pozice \"in the money\" nastane v případě put opce, je-li aktuální tržní cena podkladového aktiva nižší než realizační cena (strike price) opce. Pokud by totiž toto platilo v čase expirace, byla by opce uplatněna.","tp":5},{"id":"19832.1","t":"s","q":"K zajištění proti úrokovému riziku se z nabízených možností použije:","o":["Komoditní futures.","Měnový swap.","Akciová opce.","Kontrakt forward rate agreement (FRA)."],"c":[3],"p":61,"e":"Kontrakt FRA je derivátovým kontraktem, kde podkladové aktivum je úroková míra, a používá se právě na zajištění proti úrokovému riziku.","tp":5},{"id":"19833.1","t":"s","q":"Podkladové aktivum se zajistí proti riziku poklesu jeho ceny z nabízených možností:","o":["Nákupem call opce.","Prodejem call opce.","Nákupem put opce.","Prodejem put opce."],"c":[2],"p":61,"e":"Nákupem put opce se investor zajišťuje proti poklesu podkladového aktiva, protože put opce při poklesu podkladového aktiva zvyšuje svoji hodnotu, čímž pokles podkladového aktiva kompenzuje.","tp":5},{"id":"19834.1","t":"s","q":"Forwardová cena nezávisí na:","o":["Volatilitě podkladového aktiva.","Ceně podkladového aktiva.","Úrokové sazbě.","Době trvání forwardového kontraktu."],"c":[0],"p":61,"e":"Forwardová cena je funkcí spotové ceny podkladového aktiva, úrokové míry a doby do vypršení kontraktu, nikoli volatility podkladového aktiva, jako je tomu u opcí.","tp":5},{"id":"19835.1","t":"s","q":"Investor koupí call opci s realizační cenou (strike price) X = 90 Kč za cenu c = 10 Kč. K datu expirace dosáhne investor celkového zisku ve výši 50 Kč při tržní ceně podkladového aktiva:","o":["S = 40 Kč.","S = 50 Kč.","S = 140 Kč.","S = 150 Kč."],"c":[3],"p":61,"e":"Investor má nákupem call opce náklad 10 Kč a dosáhne celkového zisku ve výši 50 Kč, pokud zisk z nakoupené call opce bude ve výši 60 Kč. To nastane, bude-li tržní cena podkladového aktiva při expiraci rovna 150 Kč.","tp":5},{"id":"19836.1","t":"s","q":"Investor prodá put opci s realizační cenou (strike price) X = 120 Kč za cenu p = 20 Kč. K datu expirace dosáhne investor celkového zisku ve výši 10 Kč při tržní ceně podkladového aktiva:","o":["S = 100 Kč.","S = 110 Kč.","S = 120 Kč.","S = 130 Kč."],"c":[1],"p":62,"e":"Investor získá prodejem put opce 20 Kč a dosáhne celkového zisku ve výši 10 Kč, pokud ztráta z prodané put opce bude ve výši 10 Kč. To nastane, bude-li tržní cena podkladového aktiva při expiraci rovna 110 Kč.","tp":5},{"id":"19837.1","t":"s","q":"Hodnota opce se skládá:","o":["Z vnitřní hodnoty a z vnější hodnoty.","Z vnitřní hodnoty a z marže.","Z časové hodnoty a z marže.","Z vnitřní hodnoty a z časové hodnoty."],"c":[3],"p":62,"e":"Hodnota opce je součtem její vnitřní hodnoty (nezáporné číslo odvozené ze vztahu mezi realizační cenou a tržní cenou opce) a časové hodnoty (nezáporné číslo blížící se limitně k nule, pokud se opce blíží ke své expiraci).","tp":5},{"id":"19838.1","t":"s","q":"Blíží-li se datum expirace opce, potom se její časová hodnota:","o":["Snižuje.","Zvyšuje.","Nemění.","Může se zvyšovat nebo snižovat."],"c":[0],"p":62,"e":"S blížícím se datem expirace se časová hodnota blíží k nule, tedy klesá.","tp":5},{"id":"19839.1","t":"s","q":"Vnitřní hodnota opce je:","o":["Vždy kladná .","Vždy záporná.","Vždy rovna nule.","Vždy nezáporná."],"c":[3],"p":62,"e":"Pro opce v penězích je vnitřní hodnota kladná, pro opce na penězích nebo mimo peníze je vnitřní hodnota nulová - je tedy vždy nezáporná.","tp":5},{"id":"19840.4","t":"s","q":"Při vypsání call opce je její realizační cena (strike price) v porovnání s aktuální tržní cenou podkladového aktiva:","o":["Vždy vyšší.","Vždy nižší.","Vždy stejná.","Vyšší, nižší nebo stejná."],"c":[3],"p":62,"e":"Realizační cena (strike price) call opce může být stanovena libovolně \"v blízkosti\" aktuální tržní ceny podkladového aktiva, může být tedy vyšší, nižší nebo stejná.","tp":5},{"id":"19937.1","t":"s","q":"Peněžní trh se, ve srovnání s kapitálovým trhem vyznačuje:","o":["Nižší výnosností a nižší rizikovostí.","Nižší výnosností a vyšší rizikovostí.","Vyšší výnosností a vyšší rizikovostí.","Vyšší výnosností a nižší rizikovostí."],"c":[0],"p":63,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku. Tyto nástroje vykazují vždy nižší výnos a nižší riziko než trh kapitálový.","tp":2},{"id":"19938.1","t":"s","q":"Pro peněžní trh, je ve srovnání s kapitálovým trhem charakteristické:","o":["Krátká doba splatnosti cenných papírů.","Dlouhá doba splatnosti cenných papírů.","Obchodovatelnost cenných papírů pouze na OTC trhu.","Obchodovatelnost cenných papírů pouze na burze."],"c":[0],"p":63,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku. Tyto nástroje vykazují vždy nižší výnos a nižší riziko než trh kapitálový.","tp":2},{"id":"19939.1","t":"s","q":"Typickým úvěrem, který je možné získat na peněžním trhu je:","o":["Kontokorentní úvěr.","Hypoteční úvěr evropského typu.","Hypoteční úvěr amerického typu.","5letý investiční úvěr."],"c":[0],"p":63,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku (např. kontokorentní úvěr, spotřebitelský úvěr se splatností 1 rok).","tp":3},{"id":"19940.1","t":"s","q":"Pro peněžní trh je charakteristické:","o":["Obchodování krátkodobých finančních investičních instrumentů.","Obchodování dlouhodobých finančních investičních instrumentů.","Obchodování dlouhodobých dluhových instrumentů.","Obchodování majetkových investičních cenných papírů."],"c":[0],"p":63,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku. Tyto nástroje vykazují nižší výnos a nižší riziko než trh kapitálový.","tp":2},{"id":"19941.1","t":"s","q":"Na peněžním trhu se obchodují instrumenty se splatností:","o":["Do jednoho roku.","1 - 5 let.","Více než pět let.","Instrumenty nemají stanovenu splatnost, jedná se perpetuitní cenné papíry."],"c":[0],"p":63,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku. Tyto nástroje vykazují vždy nižší výnos a nižší riziko než trh kapitálový.","tp":3},{"id":"19942.1","t":"s","q":"Peněžním trhem je:","o":["Trh krátkodobých cenných papírů.","Trh dlouhodobých cenných papírů.","Trh smluvních kontraktů CAP a FLOOR.","Trh smluvních kontraktů FRA a COLLAR."],"c":[0],"p":64,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku. Tyto nástroje vykazují vždy nižší výnos a nižší riziko než trh kapitálový.","tp":2},{"id":"19943.1","t":"s","q":"Nástroje obchodované na peněžním trhu:","o":["Se obchodují na burzovním i OTC trhu.","Se obchodují pouze na burze.","Se obchodují pouze na OTC trhu.","Jsou určeny pouze pro institucionální investory."],"c":[0],"p":64,"e":"Krátkodobé instrumenty se obchodují jak na OTC trhu (např. směnky), ale i na burzovním trhu (dluhopisy se splatností 1 roku).","tp":2},{"id":"19944.1","t":"s","q":"Úvěrem poskytnutým na peněžním trhu je:","o":["Spotřebitelský úvěr na 10 měsíců.","Investiční 5letý úvěr.","Překlenovací 3letý úvěr.","Hypoteční úvěr."],"c":[0],"p":64,"e":"Peněžní trh je trhem krátkodobým, tzn. obchodují se cenné papíry a úvěry se splatností do 1 roku (např. kontokorentní úvěr, spotřebitelský úvěr se splatností 1 rok).","tp":3},{"id":"19945.1","t":"s","q":"Odprodej směnky před její splatností novému majiteli se nazývá:","o":["Eskont směnky.","Diskont směnky.","Akceptace směnky.","Aval směnky."],"c":[0],"p":64,"e":"Nový majitel směnky poskytuje předchozímu majiteli směnky eskontní úvěr s regresí nebo bez regrese, od toho se potom odvíjí výše diskontní sazby, resp. zisk pro nového vlastníka.","tp":3},{"id":"19946.1","t":"s","q":"Depozitní certifikát na jméno:","o":["Je z hlediska svojí splatnosti, považován krátkodobý cenný papír, který podléhá případnému plnění z Garančního systému finančního trhu.","Je z hlediska svojí splatnosti považován za krátkodobý cenný papír, který nepodléhá případnému plnění z Garančního systému finančního trhu.","Je z hlediska svojí splatnosti považován za dlouhodobý cenný papír, který podléhá případnému plnění z Garančního systému finančního trhu.","Je z hlediska svojí splatnosti považován za dlouhodobý cenný papír, který nepodléhá případnému plnění z Garančního systému finančního trhu."],"c":[0],"p":64,"e":"Depozitní certifikát je krátkodobým cenným papírem, který podléhá případnému plnění z Garančního systému finančního trhu.","tp":2},{"id":"19947.2","t":"s","q":"Depozitní směnka:","o":["Je krátkodobým cenným papírem, který nepodléhá případnému plnění z Garančního systému finančního trhu.","Je krátkodobým cenným papírem, který podléhá případnému plnění z Garančního systému finančního trhu.","Je dlouhodobým cenným papírem, který podléhá případnému plnění z Garančního systému finančního trhu.","Je dlouhodobým cenným papírem, který nepodléhá případnému plnění z Garančního systému finančního trhu."],"c":[0],"p":65,"e":"Depozitní směnka je krátkodobým cenným papírem, který nepodléhá případnému plnění z Garančního systému finančního trhu.","tp":2},{"id":"19948.1","t":"s","q":"Typickým znakem směnky cizí je:","o":["Akcept.","Skonto.","Bianco.","Vinkulace."],"c":[0],"p":65,"e":"U cizí směnky, vystupuje vždy výstavce, věřitel a dlužník. Dlužník svým podpisem (akceptem) směnky akceptuje (přistupuje) k dluhu. V případě neuhrazení výstavce figuruje jako ručitel.","tp":3},{"id":"19953.1","t":"s","q":"Emisní cena diskontovaného dluhopisu je při kladném výnosovém procentu:","o":["Vždy nižší než její nominální hodnota (emituje se s diskontem).","Vždy vyšší než její nominální hodnota (emituje se s prémií).","Vždy rovna nominální hodnotě.","Závisí na velikosti emisního ážia, resp. disážia a dle toho může být vyšší či nižší než její nominální hodnota."],"c":[0],"p":65,"e":"Emisní cena diskontovaného dluhopisu (zero coupon bondu) je vždy nižší než nominální hodnota, během životnosti nenese investorovi žádný běžný výnos. Investor ve splatnosti inkasuje nominální hodnotu.Příp. Zákon č. 190/2004 o dluhopisech, §16, písmeno b).","tp":3},{"id":"19954.1","t":"s","q":"V případě, že tržní cena kuponového dluhopisu je vyšší než jeho nominální hodnota:","o":["Je výnos do splatnosti nižší než kupónová sazba.","Je výnos do splatnosti vyšší než kupónová sazba.","Durace je vždy vyšší než doba do splatnosti.","Durace je vždy rovna době do splatnosti."],"c":[0],"p":65,"e":"S rostoucí cenou obligace klesá její výnosnost. Pokud je cena obligace rovna nominální hodnotě, je výnos do splatnosti roven kupónové sazbě. Pokud je cena vyšší než nominální hodnota, výnos do splatnosti klesá pod kupónovou sazbu.","tp":3},{"id":"19955.1","t":"s","q":"Dluhopis s vyšší kuponovou sazbou bude mít ve srovnání s dluhopisem s nižší kuponovou sazbou za jinak naprosto stejných podmínek (doba do splatnosti, ratingové hodnocení, výnos do splatnosti).","o":["Vyšší vnitřní hodnotu (současnou hodnotu).","Nižší vnitřní hodnotu (současnou hodnotu).","Vyšší duraci.","Nižší běžné výnosy."],"c":[0],"p":65,"e":"Při růstu kuponu, např. u variabilně úročených obligací, při neměnném výnosu do splatnosti, roste její vnitřní hodnota, protože dochází k diskontování vyššího běžného výnosu požadovanou výnosovou mírou, resp. výnosem do splatnosti.","tp":3},{"id":"19956.2","t":"s","q":"Ratingovou tabulku hodnotící emitenty dluhopisů dle jejich kreditního rizika lze rozdělit na dva základní stupně:","o":["Investiční a spekulativní.","Dlouhodobý a krátkodobý.","Diskontovaný a kuponový.","High rate a junk rate."],"c":[0],"p":66,"e":"Ratingová tabulka hodnotí kreditní riziko emitenta, který vydává dluhopisy. Podle toho o jak rizikového emitenta se jedná, získává ratingové ohodnocení (např. od agentury S&P, Moodys či Fitch), které jej zařadí do investičního stupně (investment grade, např. dle S&P od AAA do BBB-), kdy jím vydané cenné papíry jsou \"bezpečné\" nebo spekulativního stupně (junk bonds, junk level, např. dle S&P od BB+ do D), kdy jsou jím vydané cenné papíry hodnoceny jako vysoce rizikové, s tím, že emitent nemusí dostát svým závazkům. Samozřejmě platí, že čím horší ratingové hodnocení, tím se emitentovi zvyšují úrokové náklady.","tp":3},{"id":"19957.3","t":"s","q":"Emisní cena kupónového dluhopisu:","o":["Je ve většině případů (zpravidla, typicky) rovna nominální hodnotě.","Je vždy nižší než její nominální hodnota (emituje se s diskontem).","Je vždy vyšší než její nominální hodnota (emituje se s prémií), maximálně však o 10 %.","Je vždy vyšší než její nominální hodnota (emituje se s prémií), minimálně však o 10 %."],"c":[0],"p":66,"e":"Kupónová obligace je emitována za nominální hodnotu, investor obdrží běžný výnos v podobě inkasovaných kuponů.","tp":3},{"id":"19958.1","t":"s","q":"V případě, že investor drží diskontovaný dluhopis (zero bond) až do splatnosti a dluhopis nakoupil při jeho emisi:","o":["Nominální výnos je odvozen z diskontu.","Nominální výnos je roven kuponové platbě.","Nominální výnos závisí na prodejní ceně emitentovi.","Nominální výnos bude nulový (koupil při emisi, drží do splatnosti)."],"c":[0],"p":66,"e":"Diskontovaná obligace se emituje, příp. prodává, na sekundárním trhu za cenu nižší než nominální hodnota. Ve splatnosti obdrží invest. nominál, tzn. jeho zisk je ve výši diskontu.","tp":3},{"id":"19959.1","t":"s","q":"Citlivost ceny dluhopisu na změnu úrokových sazeb lze odhadnout pomocí:","o":["Modifikované durace.","Výnosu do splatnosti.","Imunizace.","Alikvotního úrokového výnosu."],"c":[0],"p":66,"e":"Ukazatelem úrokového rizika u dluhopisů může být durace, která hodnotí citlivost změny ceny obligace na změnu úrokových sazeb.","tp":3},{"id":"19960.2","t":"s","q":"Ceny dlouhodobých dluhopisů s fixním kupónem budou na změnu úrokové sazby:","o":["Reagovat velmi citlivě, ve srovnání s krátkodobými fixními dluhopisy.","Reagovat mnohem méně citlivěji ve srovnání s krátkodobými fixními dluhopisy.","Nebudou na změnu úrokových sazeb reagovat vůbec, protože vyplácený kupon je fixní.","Nebudou na změnu úrokové sazby vůbec reagovat, protože reagují pouze na změnu inflace."],"c":[0],"p":67,"e":"Citlivost ceny dluhopisu na změnu úrokových sazeb zkoumá durace. Na duraci lze nahlížet i jako na průměrnou dobu do splatnosti či průměrnou dobu návratnosti, která indikuje, za jak dlouho se investorovi vrátí investované prostředky do obligace. S růstem splatnosti roste i durace obligace, protože čím je delší splatnost obligace, tím roste i pravděpodobnost, že dojde ke změně úrokových sazeb, které budou mít vliv na cenu obligace. V případě kuponové obligace ale durace neroste lineárně, ale růstem splatnosti obligace dochází k růstu durace, klesajícím tempem, protože se projevuje vliv kuponových plateb, které zkracují průměrnou dobu, za kterou se investorovi vrátí investované prostředky. Velmi citlivě (výrazněji) tak na změnu úrokových sazeb budou reagovat ceny dlouhodobých dluhopisů (vysoká durace) s fixním kuponem, zatímco méně výrazněji dluhopisy s variabilním kuponem. Navíc v případě variabilně úročených dluhopisů investor zná výši kuponu pouze k určitému okamžiku (pokud je např. kupon PRIBOR +1 %, investor neví, v jaké výši obdrží kupon např. za jeden či dva roky, zná pouze aktuální výši kuponu). Z tohoto důvodu lze na variabilní dluhopisy nahlížet jako na \"jednoleté fixní\", právě proto, že investor zná výši kuponu pouze na daný rok. Navíc změna ceny u variabilních dluhopisů nebude tak výrazná proto, že tyto dluhopisy absorbují změnu tržní úrokové sazby právě ve výši vyplácených kuponů.","tp":3},{"id":"19961.2","t":"s","q":"Durace diskontovaného dluhopisu (zero bondu):","o":["Je rovna době do splatnosti dluhopisu.","Je vždy nulová.","Je vždy vyšší, než doba do splatnosti dluhopisu.","Neexistuje."],"c":[0],"p":67,"e":"Durace takové obligace bude vždy rovna době do splatnosti, protože obligace nevyplácí žádný kupon, čímž se nezkracuje průměrná doba návratu vložených prostředků.","tp":3},{"id":"19963.1","t":"s","q":"Vztah mezi vývojem ceny dluhopisu (jeho současné vnitřní hodnoty) a úrokovými sazbami:","o":["Je konvexní.","Je přímo úměrný.","Žádný vztah neexistuje, vliv na cenu dluhopisu má pouze nabídka a poptávka.","Žádný vztah neexistuje, vliv na cenu má pouze kuponová sazba dluhopisu."],"c":[0],"p":67,"e":"S růstem úrokových sazeb dochází k poklesu ceny obligace, resp. vnitřní hodnoty obligace. Matematicky možno podložit diskontováním budoucích kuponových plateb vyšší diskontní mírou. Vztah ale není přímo úměrný, je konvexní.","tp":3},{"id":"19962.3","t":"s","q":"S růstem splatnosti fixně úročeného dluhopisu s kuponem vyšším než výnosové procento:","o":["Durace roste, klesajícím tempem.","Durace roste, rostoucím tempem.","Durace roste lineárně.","Splatnost dluhopisu nemá vliv na duraci."],"c":[0],"p":67,"e":"Durace představuje citlivost ceny dluhopisu na změnu úrokových sazeb. Na duraci lze nahlížet i jako na průměrnou dobu do splatnosti či průměrnou dobu návratnosti, která indikuje, za jak dlouho se investorovi vrátí investované prostředky do obligace. S růstem splatnosti roste i durace obligace, protože čím je delší splatnost obligace, roste i pravděpodobnost, že dojde ke změně úrokových sazeb, které budou mít vliv na cenu obligace. V případě kuponové obligace ale durace neroste lineárně, ale růstem splatnosti obligace dochází k růstu durace klesajícím tempem, protože se projevuje vliv kuponových plateb, které zkracují průměrnou dobu, za kterou se investorovi vrátí investované prostředky.","tp":3},{"id":"19964.1","t":"s","q":"Kladný alikvotní úrokový výnos:","o":["Náleží prodávajícímu.","Náleží kupujícímu.","Při obchodování dluhopisů nemůže vzniknout kladný alikvotní úrokový výnos.","Náleží zprostředkovateli obchodu, zpravidla obchodníkovi s cennými papíry."],"c":[0],"p":68,"e":"Alikvotní úrokový výnos hradí kupující prodávajícímu, pokud dojde k prodeji dluhopisu mezi kuponovými platbami, s tím, že je to pro prodávajícího určitá odměna za to, že držel po předchozí výplatě kuponu obligaci ještě po určitou dobu.","tp":2},{"id":"19981.1","t":"s","q":"Pojem \"časový test\" používáme v souvislosti s:","o":["Možným osvobozením úplatného převodu cenných papírů od daně z příjmu.","Dobou do splatnosti dluhopisu.","Testem přiměřenosti.","Testem vhodnosti."],"c":[0],"p":68,"e":"Upraveno Zákonem č. 586/1992 S., o daních z příjmu, ve znění pozdějších předpisů - v některých případech je zdanění výnosu z prodeje cenného papíru odvislé od doby, po kterou poplatník cenný papír vlastní. Tato doba je pak označována zažitým pojmem \"časový test\".","tp":9},{"id":"19982.1","t":"s","q":"Příjem z prodeje cenných papírů nezařazených do obchodního majetku u fyzické osoby:","o":["Pokud není osvobozen od daně z příjmu, pak se daní jako ostatní příjem podle § 10 Zákona č. 586/1992 Sb., o daních z příjmu, ve znění pozdějších předpisů..","Pokud není osvobozen od daně z příjmu, pak se daní jako součást příjmů ze závislé činnosti podle § 6 ZDP.","Nepodléhá nikdy dani z příjmu.","Podléhá vždy dani z příjmu."],"c":[0],"p":68,"e":"Příjmy z úplatného převodu cenných papírů tvoří samostatný základ daně, který je snížený o výdaje prokazatelně vynaložené na jeho pořízení, tzn. kupní cenu cenného papíru.","tp":0},{"id":"19983.1","t":"s","q":"Fyzická osoba odvede z hrubého zisku z prodeje cenných papírů nezařazených do obchodního majetku (pokud příjem není osvobozen od daně z příjmu):","o":["Pouze daň z příjmu.","Daň z příjmu a pojistné na sociální a zdravotní pojištění.","Daň z příjmu a pojistné na sociální pojištění.","Daň z příjmu a pojistné na zdravotní pojištění."],"c":[0],"p":68,"e":"Příjmy z úplatného převodu cenných papírů tvoří samostatný základ daně, který je snížený o výdaje prokazatelně vynaložené na jeho pořízení, tzn. kupní cenu cenného papíru.","tp":9},{"id":"19984.1","t":"s","q":"Aktuální pravidla pro danění příjmu z úplatného převodu cenných papírů upravuje:","o":["Zákon o dani z příjmu.","Zákon o cenných papírech.","Zákon o podnikání na kapitálovém trhu.","Občanský zákoník."],"c":[0],"p":68,"e":"Zákon o dani z příjmu stanovuje pravidla pro příjem z kapitálového majetku, resp. pro příjem plynoucí z držby cenných papírů. Zákon o cenných papírech je nově inkorporován v novém občanském zákoníku. Zákon o podnikání na kapitálovém trhu neřeší daňové povinnosti vyplývající z investic na něm.","tp":0},{"id":"19985.1","t":"s","q":"Pokud fyzická osoba prodá cenné papíry nezařazené do obchodního majetku se ztrátou, pak:","o":["Tuto ztrátu nemůže z hlediska daně z příjmu uplatnit proti zisku z jiných druhů příjmu, například z podnikání.","Tuto ztrátu může z hlediska daně z příjmu uplatnit proti zisku z jiných druhů příjmu, například z podnikání.","Tuto ztrátu může z hlediska daně z příjmu převést do dalších zdaňovacích období.","Tuto ztrátu nemůže uplatnit ani proti zisku z prodeje jiných cenných papírů ve stejném zdaňovacím období."],"c":[0],"p":69,"e":"Upraveno v ZDP, tvoří samostatný základ daně.","tp":2},{"id":"19986.1","t":"s","q":"Aktuální výše zdanění dividend pro fyzické osoby, které nemají akcie v obchodním majetku, činí:","o":["15 %.","19 %.","21 %.","Dividendy vůbec nepodléhají dani z příjmu."],"c":[0],"p":69,"e":"Dividenda se zdaňuje tzv. srážkovou daní 15 %, tzv. přímo u zdroje (daň tedy odvádí plátce dividendy) a akcionář obdrží již zdaněnou (čistou) dividendu.","tp":4},{"id":"19987.1","t":"s","q":"Právnická osoba nakoupí do obchodního majetku cenné papíry a bude je držet po celé zdaňovací období. Pořizovací cenu v tomto zdaňovacím období:","o":["Neuplatní jako výdaj snižující základ daně.","Uplatní jako výdaj snižující základ daně.","Může uplatnit jako výdaj snižující základ daní, pokud se tím nedostane do ztráty.","Může uplatnit jako výdaj snižující základ daně nebo se může rozhodnout, že ji uplatní až ve zdaňovacím období, kdy cenné papíry prodá."],"c":[0],"p":69,"e":"Upraveno v zákoně č. 586/1992 Sb., o daních z příjmu, ve znění pozdějších předpisů, kdy pořizovací cenu cenného papíru lze jako výdaj na dosažení zisku uplatnit až v okamžiku prodeje cenného papíru.","tp":9},{"id":"19988.3","t":"s","q":"Postup zdanění inkasovaných úroků (kuponů) fyzickou osobou u kuponových obligací emitenta s domicilem v ČR je následující:","o":["Úroky jsou zdaněny srážkovou daní 15 % plátcem, příjemce je v daňovém přiznání neuvádí.","Úroky jsou zdaněny srážkovou daní 19 % plátcem, příjemce je v daňovém přiznání neuvádí.","Příjemce inkasované úroky uvádí v daňovém přiznání a jsou zdaněny 15 %.","Příjemce inkasované úroky uvádí v daňovém přiznání a jsou zdaněny 21 %."],"c":[0],"p":69,"e":"Příjmy z úroků dluhopisů, stejně jako z dividend jsou zdaněné u zdroje srážkovou daní 15 %, kterou odvádí společnost vyplácející úroky, dividendy (emitent), případně ten kdo za ni dividendy vyplácí. Pokud se jedná o úroky, dividendy společností, které jsou daňovými rezidenty ČR, není investor povinen tento příjem zdaněný srážkovou daní uvádět v daňovém přiznání.","tp":3},{"id":"19989.1","t":"s","q":"Při prodeji cenných papírů je základem daně:","o":["Kladný rozdíl mezi prodejní a pořizovací cenou.","Prodejní cena.","Pořizovací cena.","Prodejní nebo pořizovací cena podle toho, co je vyšší."],"c":[0],"p":69,"e":"Základem daně je příjem snížený o výdaje prokazatelně vynaložené na jeho dosažení. U příjmů plynoucích z cenných papírů je výdajem cena, za kterou poplatník věc prokazatelně nabyl.","tp":0},{"id":"19990.1","t":"s","q":"Pro osvobození zisku z prodeje cenných papírů od daně z příjmu u fyzické osoby, která cenné papíry nemá zahrnuty do obchodního majetku, je rozhodující:","o":["Výše celkového příjmu z prodeje cenných papírů v daném zdaňovacím období.","Výše celkového zisku z prodeje cenných papírů v daném zdaňovacím období.","Výše celkového daňového základu poplatníka v daném zdaňovacím období.","Výše samostatného daňového základu poplatníka z prodeje cenných papírů v daném zdaňovacím období."],"c":[0],"p":70,"e":"Pro osvobození od daně z příjmu je rozhodující příjem z úplatného převodu cenných papírů a příjmy z podílů připadajících na podílové listy při zrušení podílového fondu, pokud jejich úhrn u poplatníka nepřesáhne ve zdaňovacím období částku 100 000 Kč.","tp":9},{"id":"19991.1","t":"s","q":"Fyzická osoba nemá cenné papíry zahrnuty do obchodního majetku. Zisk z prodeje cenných papírů, pokud prodej není osvobozen od daně z příjmu:","o":["Tvoří samostatný základ daně.","Zahrnuje se do základu daně z příjmu ze zaměstnání (vázané činnosti).","Zahrnuje se do základu daně z příjmu z podnikání (samostatné činnosti).","Zahrnuje se do základu daně z kapitálového majetku."],"c":[0],"p":70,"e":"Základem daně je příjem snížený o výdaje prokazatelně vynaložené na jeho dosažení. U příjmů plynoucích z cenných papírů je výdajem cena, za kterou poplatník věc prokazatelně nabyl.","tp":0},{"id":"19992.2","t":"s","q":"Pokud je příjem v souvislosti s prodejem cenných papírů realizován v cizí měně, pak se u cenných papírů nezahrnutých do obchodního majetku poplatníka použije pro účely stanovení daňového základu:","o":["Jednotný kurs stanovený pro celé zdaňovací období pokynem Generálního finančního ředitelství, kterým se přepočtou příjmy i výdaje.","Aktuální kurs k 1. dni v měsíci.","Aktuální kurs ke dni podání daňového přiznání, kterým se přepočtou příjmy i výdaje.","Aktuální kurs k 31. 12. příslušného zdaňovacího období, kterým se přepočtou příjmy i výdaje."],"c":[0],"p":70,"e":"Pro daňové účely se používají kurzy devizového trhu vyhlášené Českou národní bankou uplatňované v účetnictví poplatníků. Pokud poplatník nevede účetnictví, použije jednotný kurz, nevyužije-li kurzy devizového trhu uplatňované podle zvláštních právních předpisů o účetnictví. Tento kurz se stanoví jako průměr směnného kurzu stanoveného Českou národní bankou poslední den každého měsíce zdaňovacího období. V případě, že se daňové přiznání podává v průběhu zdaňovacího období, použije se směnný kurz k datu uskutečnění jednotlivých příjmů a výdajů nebo průměr směnného kurzu stanoveného Českou národní bankou poslední den každého měsíce části zdaňovacího období, za kterou se daňové přiznání podává.","tp":9},{"id":"20009.1","t":"s","q":"Pro primární kapitálový trh neplatí následující tvrzení:","o":["Slouží k zajištění likvidity pro investory do investičních nástrojů.","Protiplnění za nabízené investiční nástroje získává jejich emitent.","Dochází zde k prodeji investičních nástrojů jejich prvním nabyvatelům.","Slouží k získávání peněžních prostředku od investorů."],"c":[0],"p":70,"e":"Při prodeji akcií na primárním trhu získává peníze emitent, přičemž se jedná o prodej prvním nabyvatelům.","tp":2},{"id":"20010.1","t":"s","q":"Emisní ážio je:","o":["Rozdíl mezi nominální nebo účetní hodnotou akcie a jejím vyšším emisním kursem.","Rozdíl mezi jmenovitou hodnotnou a nižší prodejní cenou akcií.","Dividendový výnos plynoucí z nově emitovaných akcií.","Účetní hodnota nově emitovaných akcií."],"c":[0],"p":71,"e":"Viz. znění zákona.","tp":4},{"id":"20011.2","t":"s","q":"Proces, kdy společnost poprvé veřejně nabízí své akcie se označuje jako:","o":["IPO (initial public offer).","Private placement.","Tender.","Kontinuální aukce."],"c":[0],"p":71,"e":"IPO (initial public offering) je vžitý termín pro primární veřejnou nabídku akcií spojenou se vstupem na burzovní trh.","tp":4},{"id":"20012.1","t":"s","q":"Zkratka SPO v terminologii kapitálových trhů standardně označuje:","o":["Sekundární (druhotnou, sezónní) veřejnou nabídku cenných papírů.","Samostatně emitovanou opci.","Standardizovanou emisi obligací.","Vypořádací a platební operace."],"c":[0],"p":71,"e":"SPO (secondary public offering) je vžitý termín pro sekundární veřejnou nabídku akcií, tedy označením pro další veřejnou nabídku akcií, které jsou již přijaty na organizovaný veřejný trh.","tp":2},{"id":"20013.2","t":"s","q":"Neveřejné umístění cenných papírů emitentem omezenému okruhu předem stanovených osob se označuje jako:","o":["Private placement.","Primární aukce.","IPO.","SEO."],"c":[0],"p":71,"e":"Private placement je neveřejná nabídka nebo chcete-li umísťování soukromého kapitálu. Jde v podstatě o prodej cenných papírů, které se prodávají nikoliv prostřednictvím veřejné nabídky, ale spíše prostřednictvím nabídky soukromé.","tp":0},{"id":"20014.1","t":"s","q":"Datum emise cenného papíru je:","o":["Den, kdy může dojít k vydání cenného papíru prvnímu nabyvateli.","Den, kdy cenný papír nabyl první nabyvatel.","Den, kdy došlo k prodeji cenného papíru na veřejném trhu.","Den primární aukce."],"c":[0],"p":71,"e":"Datum emise cenného papíru označuje den, kdy může dojít k vydání cenného papíru prvnímu nabyvateli. Není-li stanoveno jinak, určí datum emise cenného papíru emitent.","tp":0},{"id":"20016.1","t":"s","q":"Pro sekundární trhy neplatí:","o":["Emitent nabízí něco, co ještě neexistuje a co vznikne pouze za předpokladu, že vydávaný cenný papír najde svého prvonabyvatele.","Jejich ekonomickou funkcí je změna struktury majitelů cenných papírů.","Cenné papíry se zde opakovaně obchodují.","Při změně majitele nepřechází hotovost mezi investory a emitenty, ale mezi investory navzájem."],"c":[0],"p":72,"e":"Na sekundárním trhu se prodávají již dříve do oběhu uvedené cenné papíry.","tp":0},{"id":"20017.1","t":"s","q":"Pokud na kapitálovém trhu ceny finančních aktiv klesají, mluvíme o tzv.:","o":["Medvědím trhu.","Jelením trhu.","Býčím trhu.","Tygřím trhu."],"c":[0],"p":72,"e":"Medvědí trh = klesající trh. Býčí trh = rostoucí trh.","tp":2},{"id":"20018.2","t":"s","q":"Počet akcií v emisi je 1 000 kusů s nominální hodnotou 100 Kč. Akcie jsou veřejně obchodovatelné a poslední kurz akcie je 500 Kč. Jaká je tržní kapitalizace emise?","o":["500 000 Kč.","100 000 Kč.","50 000 Kč.","550 000 Kč."],"c":[0],"p":72,"e":"Tržní kapitalizace je dána součinem počtu cenných papírů a jejich ceny, tedy 1 000 x 500 = 500 000 Kč. Nezajímá nás nominální hodnota emise (1 000 x 100 = 100 000 Kč).","tp":4},{"id":"20019.1","t":"s","q":"Stanovení emisního kurzu a alokace akcií při veřejné nabídce probíhá zpravidla formou:","o":["Bookbuildingu.","Road show.","Aukce.","Rozhodnutím dozorčí rady."],"c":[0],"p":72,"e":"Proces prodeje akcií, při kterém investiční banka sbírá cenové nabídky a teprve na základě poptávky stanoví emisní cenu.","tp":4},{"id":"20020.1","t":"s","q":"Duální listing znamená:","o":["Obchodování s emisí akcií na více trzích.","Obchodování s emisí akcií v různých měnách.","Vypořádání probíhá v různých měnách.","Prospekt cenného papíru je vytvořen ve dvou jazycích."],"c":[0],"p":72,"e":"Duální kotace - stav, kdy jsou akcie společnosti v jednom okamžiku přijaty k obchodování na více trzích současně.","tp":4},{"id":"20025.2","t":"s","q":"Prospekt využívaný pro veřejnou nabídku je platný po dobu:","o":["12 měsíců od jeho schválení ČNB.","18 měsíců od jeho schválení ČNB.","6 měsíců od jeho schválení ČNB.","24 měsíců od jeho schválení ČNB."],"c":[0],"p":73,"e":"Viz znění zákona.","tp":0},{"id":"20026.1","t":"s","q":"Za správnost a úplnost údajů uvedených v prospektu cenného papíru odpovídá:","o":["Osoba, která prospekt vyhotovila a ručitel, pokud je uveden v prospektu a zaručil se na správnost údajů.","Manažer emise.","Výhradně ručitel emise, který se zaručil za správnost údajů.","Auditor, který ověřil poslední účetní závěrku emitenta."],"c":[0],"p":73,"e":"Prospekt vyhotovuje emitent nebo osoba, která má v úmyslu veřejně nabízet cenné papíry. Za správnost údajů uvedených v prospektu potom odpovídá osoba, která prospekt vydala, příp. za tyto údaje může odpovídat ručitel, pokud je uveden v tomto prospektu a zaručil se za správnost údajů v něm.","tp":0},{"id":"20028.1","t":"s","q":"Prospekt cenného papíru, který je vydáván emitentem se sídlem v ČR, schvaluje až na případy, kdy zákon umožňuje jeho schválení zahraničním orgánem:","o":["Česká národní banka.","Ministerstvo financí České republiky.","Nejvyšší kontrolní úřad.","Specializovaný finanční úřad."],"c":[0],"p":73,"e":"Pokud má emitent sídlo v ČR, schvaluje na základě žádosti emitenta tento prospekt ČNB.","tp":0},{"id":"20029.1","t":"s","q":"Investor nakoupí diskontované dluhopisy s nominální hodnotou 12 000 Kč a se splatností za 2 roky. Emisní kurz je 10 000 Kč. Jaký bude kapitálový výnos investora, bude-li dluhopisy držet až do splatnosti:","o":["2 000 Kč.","12 000 Kč.","10 000 Kč.","22 000 Kč."],"c":[0],"p":73,"e":"Výnos za 2 roky u diskontovaného dluhopisu (zero bond) je rozdíl mezi jmenovitou hodnotou a emisním kurzem, tj.12 000-10 000 = 2 000 Kč.","tp":3},{"id":"20030.3","t":"s","q":"Není-li ke dni schvalování prospektu známa konečná cena a počet cenných papírů, které budou veřejně nabídnuty, může Česká národní banka schválit prospekt, pokud:","o":["Je v prospektu uvedena maximální cena, nebo kritéria nebo podmínky, za kterých budou konečná cena a počet cenných papírů určeny.","Je možné odvolat koupi nebo nabídku cenných papírů nejméně 2 pracovní dny po uveřejnění konečné ceny a počtu cenných papírů, které budou veřejně nabízeny.","Je v prospektu uvedena minimální cena, nebo kritéria nebo podmínky, za kterých bude cena určena.","Je možné odvolat koupi nebo upisování cenných papírů nejvíce 3 pracovní dny po uveřejnění konečné ceny a počtu cenných papírů, které budou veřejně nabízeny."],"c":[0],"p":74,"e":"Vychází ze Zákona o podnikání na kapitálovém trhu, kdy ČNB může schválit prospekt, pokud je v něm uvedena maximální cena, příp. jsou uvedeny podmínky, jak bude konečná cena stanovena, nebo je možné odvolat upsání cenných papírů 2 pracovní dny po uveřejnění konečné ceny.","tp":0},{"id":"20031.2","t":"s","q":"Prospekt cenného papíru určený pro účely veřejné nabídky cenných papírů výhradně v České republice (cenné papíry emitenta nejsou přijaty k obchodování na evropském regulovaném trhu) musí být vyhotoven vždy:","o":["V českém jazyce.","V českém nebo slovenském jazyce.","V českém nebo anglickém jazyce.","V českém i anglickém jazyce."],"c":[0],"p":74,"e":"Pokud ČNB schvaluje prospekt pro veřejnou nabídku realizovanou výhradně v České republice, musí být jazyk prospektu v češtině.","tp":0},{"id":"20032.2","t":"s","q":"Pokud emitent chce veřejně nabízet dluhopisy a na veřejnou nabídku či jejího emitenta nelze aplikovat některou ze zákonných výjimek, je emitent ve vztahu k takové veřejné nabídce povinen:","o":["Uveřejnit prospekt cenného papíru.","Vyhotovit shrnutí emise.","Vyhotovit analytickou zprávu.","Uveřejnit výroční zprávu."],"c":[0],"p":74,"e":"Osoba, která chce veřejně nabízet cenné papíry musí povinně uveřejnit prospekt cenného papíru schváleného ČNB.","tp":3},{"id":"20033.1","t":"s","q":"Ke změně emisních podmínek dluhopisů se vyžaduje:","o":["Předchozí souhlas schůze vlastníků.","Souhlas valné hromady.","Předchozí souhlas České národní banky.","Zaslání návrhu změn vlastníkům dluhopisů."],"c":[0],"p":74,"e":"Emitent může změnit emisní podmínky, ale pouze s předchozím souhlasem schůze vlastníků, s tím, že změněné emisní podmínky musí bez zbytečného odkladu zpřístupnit investorům.","tp":3},{"id":"20034.1","t":"s","q":"Který ISIN náleží českému cennému papíru:","o":["CZ0005112300.","BMG200452024.","LU0275164910.","AT0000908504."],"c":[0],"p":74,"e":"Mezinárodní systém číslování pro identifikaci cenných papírů - první 2 písmena označují kód země, v níž má emitent sídlo.","tp":0},{"id":"20035.1","t":"s","q":"Prospekt cenného papíru může být rozdělen na několik samostatných dokumentů, které z uvedených to jsou:","o":["Registrační dokument, doklad o cenném papíru a shrnutí prospektu.","Shrnutí prospektu, analýza rizik a prohlášení odpovědných osob.","Doklad o cenném papíru, právní due diligence, analýza rizik.","Shrnutí prospektu, veřejný příslib a finanční analýza emitenta."],"c":[0],"p":75,"e":"Prospekt cenného papíru musí obsahovat informace nezbytné pro investory. Prospekt může být vydán jako jeden celek, příp. jej může tvořit více samostatných dokumentů. Potom se takovýto prospekt dělí na registrační dokument, doklad o cenném papíru a shrnutí prospektu. Registrační dokument obsahuje údaje týkající se emitenta. Doklad o cenném papíru obsahuje údaje o cenném papíru, který je veřejně nabízen nebo má být přijat k obchodování na evropském regulovaném trhu.","tp":0},{"id":"20036.1","t":"s","q":"Do jakého okamžiku a jakým způsobem musí emitent dluhopisů zpřístupnit investorům emisní podmínky, aby mohl dluhopis vydat:","o":["Nejpozději do data emise a na nosiči informací, který umožňuje reprodukci v nezměněné podobě a uchování tak, aby mohly být využívány alespoň do data splatnosti těchto dluhopisů.","Nejpozději týden před datem emise, a to vždy alespoň v jednom celostátně distribuovaném tištěném deníku a dále jakýmkoliv jiným vhodným způsobem.","Nejpozději den před datem emise a vždy alespoň na internetových stránkách emitenta a na internetových stránkách České národní banky.","Emisní podmínky v případě emise dluhopisů nemusí být investorům zpřístupněny."],"c":[0],"p":75,"e":"Emisní podmínky musí být investorům zpřístupněny nejpozději k datu emise.","tp":3},{"id":"20041.1","t":"s","q":"Rozhodný den pro výplatu dividendy:","o":["Je možné stanovit odlišně, než rozhodný den pro účast na valné hromadě.","Je vždy jiný, než rozhodný den pro účast na valné hromadě.","Je vždy stejný jako rozhodný den pro účast na valné hromadě.","Je uveden v prospektu emitenta."],"c":[0],"p":75,"e":"Rozhodný den pro výplatu dividendy je rozhodný den pro účast na valné hromadě, není-li uvedeno ve stanovách společnosti jinak.","tp":4},{"id":"20042.1","t":"s","q":"Investor, který zakoupil akcie, které jsou přijaty k obchodování na regulovaném trhu v České republice, může očekávat, že jejich emitent bude (až na zákonné výjimky) uveřejňovat informace v jakých jazycích:","o":["V jazyce českém, v jazyce anglickém nebo v obou jazycích současně.","V jakémkoliv jazyce, který si emitent zvolí.","Vždy výlučně v jazyce českém.","V jakémkoliv úředním jazyce státu, který je členem EU."],"c":[0],"p":75,"e":"Informační povinnost emitenta je periodická a průběžná. Emitent, jehož investiční cenný papír je přijat k obchodování pouze na regulovaném trhu, uveřejní povinně uveřejňovanou informaci v jazyce českém nebo v jazyce anglickém.","tp":3},{"id":"20043.1","t":"s","q":"Emitent cenného papíru přijatého k obchodování na regulovaný trh v České republice je (až na zákonné výjimky) povinen uveřejnit způsobem umožňujícím dálkový přístup pololetní zprávu nejpozději do:","o":["3 měsíců po uplynutí prvních 6 měsíců účetního období.","4 měsíců po uplynutí prvních 6 měsíců účetního období nebo v lhůtě, kterou stanoví právní řád státu, ve kterém má emitent sídlo.","2 měsíců po uplynutí prvních 6 měsíců účetního období nebo v lhůtě, kterou stanoví právní řád státu, ve kterém má emitent sídlo.","12 měsíců po uplynutí prvních 6 měsíců účetního období."],"c":[0],"p":76,"e":"Emitent cenného papíru má informační povinnost jak vůči burze, tak vůči investorům. Tato povinnost je průběžná (povinnost zveřejňovat kurzotvorné informace) a periodická - uveřejnění pololetní a výroční zprávy, kdy pololetní zpráva musí být uveřejněna do 3 měsíců po uplynutí prvních 6 měsíců účetního období.","tp":0},{"id":"20044.2","t":"s","q":"Co znamená ukazatel P/E ratio:","o":["Poměr aktuální tržní ceny akcie a posledního zveřejněného čistého zisku připadajícího na jednu akcii.","Poměr vlastního kapitálu a celkových aktiv.","Poměr celkových oběžných aktiv a krátkodobých závazků.","Ukazatel dividendy na akcii."],"c":[0],"p":76,"e":"Price earning ratio je jedním z pravděpodobně nejvíce používaných indikátorů technické analýzy na její mikroekonomické úrovni. Jeho obliba je především v jednoduchosti konstrukce, která předsatvuje podíl trřního kurzu cenného papíru (akcie) vůči zisku připadajícímu na jednu akcii. P/E tak dává investorovi informaci o tom, kolik je ochoten zaplatit za jednu jednotku zisku. Např. P/E = 15 znamená, že investor je ochoten zaplatit 15 Kč (dolarů, Eur) za jednu korunu (dolar, Euro) zisku, resp. jeho investice se mu tak vrátí za 15 let.","tp":4},{"id":"20045.3","t":"s","q":"Pokud na kapitálovém trhu ceny finančních aktiv rostou, mluvíme o tzv.:","o":["Medvědím trhu.","Jelením trhu.","Býčím trhu.","Tygřím trhu."],"c":[2],"p":76,"e":"V případě pozitivního růstového trendu trhu se obecně hovoří o tzv. býčím trendu, který je spojen s kladnými a pozitivními očekáváními investorů a rostoucími nákupními pokyny. Naopak v případě klesajícího trendu, spojeného s pesimismem, krizí apod. se hovoří o tzv. medvědím trhu, kdy převládají prodejní pokyny.","tp":2},{"id":"20046.1","t":"s","q":"Emitent nebo účastník trhu s povolenkami uveřejnění vnitřní informace:","o":["Může odložit ze závažných důvodů a musí být schopen zajistit důvěrnost této informace","Nesmí nikdy odložit","Může odložit, rozhodlo-li o tom představenstvo","Může odložit kdykoli"],"c":[0],"p":76,"e":"Vnitřní informace (insider information) je taková informace, která nebyla uveřejněna, týká se přímo nebo nepřímo jednoho nebo několika emitentů nebo jednoho nebo několika finančních nástrojů a která, pokud by byla zveřejněna, by pravděpodobně měla významný dopad na ceny těchto finančních nástrojů. Emitent je povinen co nejdříve informovat veřejnost o vnitřních informacích, jež se tohoto emitenta přímo týkají. Emitent nebo účastník trhu s povolenkami na emise může na svou vlastní odpovědnost odložit zveřejnění vnitřních informací za předpokladu, že okamžité zveřejnění pravděpodobně ohrozí oprávněné zájmy emitenta nebo účastníka trhu s povolenkami na emise a současně odkladem zveřejnění pravděpodobně nedojde k uvedení veřejnosti v omyl a současně emitent nebo účastník trhu s povolenkami na emise je schopen zajistit věrnost těchto informací.","tp":3},{"id":"20047.2","t":"s","q":"Emitent dluhopisů přijatých k obchodování na regulovaném trhu v České republice je povinen zákonem stanoveným způsobem uveřejnit následující informaci:","o":["Informaci o konání schůze vlastníků dluhopisů.","Samostatnou zprávu o plnění parametru úrokového krytí ve vztahu k dluhopisům.","Čtvrtletní zprávu statutárního orgánu emitenta.","Informace o změnách ve vrcholovém managementu emitenta a jím ovládaných osob."],"c":[0],"p":77,"e":"Ze zákona je emitent povinen uveřejnit nebo zaslat oznámení o konání schůze vlastníků dluhopisů nebo obdobného shromáždění vlastníků cenných papírů představujících právo na splacení dlužné částky. Ostatní možnosti zákon neuvádí.","tp":3},{"id":"20048.1","t":"s","q":"Pokud tržní cena okamžitě reaguje na uveřejňované informace, jedná se o:","o":["Silnou formu informační efektivnosti.","Slabou formu informační otevřenosti.","Středně silnou formu právní efektivnosti.","Slabou formu operační efektivnosti."],"c":[0],"p":77,"e":"Kurz obsahuje všechny informace včetně neveřejných (teorie efektivních trhů).","tp":2},{"id":"20049.1","t":"s","q":"S přibližující se dobou výplaty kuponu:","o":["Cena dluhopisu narůstá.","Cena dluhopisu klesá.","Cena dluhopisu se nemění.","Dluhopis není možnost převádět."],"c":[0],"p":77,"e":"Cena dluhopisu závisí na výši úrokových sazeb v okamžiku nákupu a na časovém posunu data nákupu vzhledem k datu výplaty dalšího kuponu.","tp":3},{"id":"20050.1","t":"s","q":"Akcionář nemá právo na:","o":["Zajištění stálého růstu ceny akcie.","Podíl na likvidačním zůstatku při zániku společnosti.","Dividendu.","Podílet se na řízení společnosti prostřednictvím hlasování na valné hromadě."],"c":[0],"p":77,"e":"Základní práva akcionářů - právo účastnit se valné hromady, právo na dividendu a právo na likvidačním zůstatku.","tp":4},{"id":"20052.1","t":"s","q":"V případě, že má emitent sídlo v České republice a vydal akcie, jenž jsou přijaty k obchodování na evropský regulovaný trh, jsou investorům veřejně dostupné tyto informace z valné hromady:","o":["Informace o usneseních přijatých na valné hromadě a počtu hlasů odevzdaných pro návrh, proti němu a počtu hlasů, ohledně nichž se hlasující zdrželi hlasování.","Notářský zápis z valné hromady.","Zvukový záznam z valné hromady.","Jmenný seznam akcionářů, kteří se zúčastnili valné hromady."],"c":[0],"p":77,"e":"Informační povinností emitenta je i zveřejnění informací (\"zápisu\") z valné hromady a to do 15 dnů od jejího konání. Je povinen uveřejnit zejména údaje o počtu platných hlasů odevzdaných při hlasování o každém návrhu a celkovém počtu platných hlasů odevzdaných pro návrh, proti návrhu a počtu hlasů, ohledně nichž se hlasující zdrželi hlasování.","tp":4},{"id":"20051.1","t":"s","q":"Co je povinnou náležitostí výroční zprávy emitenta akcií se sídlem v České republice přijatých k obchodování na regulovaný trh v České republice:","o":["Souhrnné informace o odměnách členů statutárních a dozorčích orgánů emitenta.","Sektorovou analýzu emitenta.","Informace o výši a rozhodném dni dividendy za uplynulé účetní období.","Zápisy z jednání statutárního orgánu a kontrolního orgánu emitenta za dané účetní období."],"c":[0],"p":78,"e":"Výroční zpráva nebo konsolidovaná výroční zpráva musejí poskytovat investorům věrný a poctivý obraz o finanční situaci, podnikatelské činnosti a výsledcích hospodaření emitenta a jeho konsolidačního celku za uplynulé účetní období a o vyhlídkách budoucího vývoje finanční situace, podnikatelské činnosti a výsledků hospodaření emitenta. Výroční zpráva a konsolidovaná výroční zpráva musejí obsahovat číselné údaje a informace o finanční situaci, podnikatelské činnosti a výsledcích hospodaření emitenta a jeho konsolidačního celku za uplynulé účetní období v rozsahu číselných údajů a informací uváděných v prospektu, s uvedením důležitých faktorů, rizik a nejistot, které ovlivnily finanční situaci, podnikatelskou činnost nebo výsledky hospodaření emitenta, včetně např. informace o všech peněžitých a nepeněžitých příjmech, které přijaly za účetní období osoby s řídící pravomocí od emitenta a od osob ovládaných emitentem, a to souhrnně za všechny členy statutárního orgánu, souhrnně za všechny členy dozorčí rady a souhrnně za všechny ostatní osoby s řídící pravomocí.","tp":3},{"id":"20057.1","t":"s","q":"Co se rozumí prováděním pokynů zákazníka?","o":["Jednání vedoucí k uzavření smlouvy o koupi nebo prodeji investičního nástroje na účet zákazníka, včetně uzavření smlouvy o koupi nebo prodeji investičního nástroje za zákonem blíže specifikovaných podmínek.","Pouze uzavření smlouvy o prodeji investičního nástroje na účet obchodníka s cennými papíry za zákonem blíže specifikovaných podmínek.","Pouze uzavření smlouvy o koupi investičního nástroje na účet obchodníka s cennými papíry.","Pouze uzavření smlouvy o koupi nebo prodeji investičního nástroje na účet obchodníka s cennými papíry."],"c":[0],"p":78,"e":"Provádění pokynů je zásadně odlišné od obchodování na vlastní účet obchodníka s cennými papíry.","tp":0},{"id":"20058.1","t":"s","q":"Přijímání a předávání pokynů týkajících se investičních nástrojů:","o":["Patří mezi hlavní investiční služby.","Je jedinou hlavní investiční službou obchodníka s cennými papíry.","Patří mezi doplňkové investiční služby.","Není to investiční služba."],"c":[0],"p":78,"e":"Přijímání a předávání pokynů je hlavní investiční službou investičních zprostředkovatelů, u obchodníků s cennými papíry navíc spolu s prováděním pokynů zákazníka, k čemuž investiční zprostředkovatel není oprávněn.","tp":0},{"id":"20059.1","t":"s","q":"Jaké investiční služby může poskytovat investiční zprostředkovatel?","o":["Může poskytovat investiční poradenství, přijaté pokyny zákazníka předává osobám uvedeným v zákoně o podnikání na kapitálovém trhu (např. bance, obchodníkovi s cennými papíry).","Může provádět pokyny zákazníků.","Může provádět pokyny zákazníků, ale pouze za předpokladu, že je vlastnicky propojen s obchodníkem s cennými papíry.","Může provádět úschovu a správu cenných papírů pro zákazníky."],"c":[0],"p":78,"e":"Investiční zprostředkovatel má omezená oprávnění oproti obchodníkovi s cennými papíry a proto, přestože může poskytovat investiční poradenství týkající se investičních nástrojů, nemůže sám provádět pokyny a tyto musí předávat k provedení pouze v zákoně uvedeným osobám.","tp":0},{"id":"20060.1","t":"s","q":"Jak se nazývá projevení zájmu investora o nově emitované akcie?","o":["Upisování.","Opce.","Emise.","Investování na sekundárním trhu."],"c":[0],"p":79,"e":"Upisování je aktivní krok investora spočívající v závazku k zakoupení nové emise akcií.","tp":4},{"id":"20061.1","t":"s","q":"Upisování a umisťování investičních nástrojů:","o":["Patří mezi hlavní investiční služby.","Patří mezi vedlejší investiční služby.","Nepatří mezi investiční služby.","Spadá výlučně do oblasti fondů kolektivního investování."],"c":[0],"p":79,"e":"Upisování a umisťování je hlavní investiční službou uvedenou v zákoně č. 256/2004 Sb.","tp":4},{"id":"20062.1","t":"s","q":"Kdo získává peníze při upisování akcií?","o":["Emitent.","Investor.","Klient.","Komerční banka v podobě depozit."],"c":[0],"p":79,"e":"Peníze získá emitent, který akcie emitoval, je to jeho dlouhodobý zdroj financí.","tp":4},{"id":"20063.1","t":"s","q":"Kdo může být organizátorem regulovaného trhu?","o":["Je to právnická osoba, která má povolení ČNB organizovat regulovaný trh, např. Burza cenných papírů Praha.","Je to zásadně fyzická osoba oprávněná organizovat regulovaný trh, která získá příslušné povolení od ČNB.","Může to být právnická i fyzická osoba, která může organizovat kapitálový trh a má k tomu povolení od Evropské centrální banky.","Je to orgán EU pro kontrolu kapitálového trhu."],"c":[0],"p":79,"e":"Regulovaný trh je opakem trhu over-the-counter (OTC). Regulovaný trh má stanovena pravidla a jeho organizátor potřebuje ke své činnosti povolení ČNB (v ČR např. Burza cenných papírů Praha a RM-systém).","tp":0},{"id":"20064.1","t":"s","q":"Je pro investičního zprostředkovatele předepsán počáteční kapitál a jeho výše?","o":["Ano, počáteční kapitál je stanoven tak, že musí mít průhledný a nezávadný původ. Jeho výše stanovena není.","Ano, počáteční kapitál je stanoven, jeho výše a původ se v povolovacím řízení nezkoumá.","Počáteční kapitál je Českou národní bankou stanoven v rámci povolovacího řízení ve výši 50.000 EUR.","Počáteční kapitál investičního zprostředkovatele zákon o podnikání na kapitálovém trhu neřeší, to řeší u obchodníka s cennými papíry."],"c":[0],"p":79,"e":"Zákonem je pro investičního zprostředkovatele předepsán počáteční kapitál, který má průhledný a nezávadný původ, přičemž vlastní kapitál umožní řádný výkon jeho činnosti, což je požadavek i u ostatních osob podnikajících na kapitálovém trhu.","tp":0},{"id":"20065.1","t":"s","q":"Jaké informace musí obdržet zákazník, je-li mu nabízena investiční služba jako součást složeného produktu (popř. jako podmínku sjednání složeného produktu)?","o":["Musí mu být popsáno, jak se liší rizika složeného produktu od rizik vyplývajících ze součástí složeného produktu.","Musí mu být popsáno hlavní riziko složeného produktu.","Musí mu být popsáno riziko hlavní součásti složeného produktu.","Musí mu být popsána rizika vyskytující se na kapitálovém trhu a ta musí být porovnána s riziky složeného produktu."],"c":[0],"p":80,"e":"S ohledem na to, že se rizikovost jednotlivých produktů liší, musí zákazník obdržet informaci mj. jak o riziku složeného produktu, tak o rizicích jeho součástí, pokud nejsou rizika vyplývající ze složeného produktu zjevně odlišná od rizik vyplývajících ze součástí složeného produktu, jsou-li sjednány samostatně. Správná odpověď je zestručněna z důvodu přehlednosti.","tp":0},{"id":"20066.1","t":"s","q":"Jakou informaci musí zákazník obdržet, je-li mu nabízena hlavní investiční služba jako součást složeného produktu (nebo jako podmínka sjednání složeného produktu) před poskytnutím investiční služby?","o":["Musí být v dostatečném časovém předstihu informován, které součásti složeného produktu lze sjednat samostatně a jaká je za ně v tomto případě úplata.","Musí mu být vypočítána celá výše úplaty za tuto investiční službu.","Musí mu být sdělována úplata za tuto investiční službu v pravidelných výpisech po celou dobu trvání investice.","Musí mu být sdělována cena jednotlivých součástí složeného produktu ve výpisech po celou dobu trvání investice."],"c":[0],"p":80,"e":"U složených produktů se často liší úplaty v porovnání s úplatami za jednotlivé součásti složených produktů, pokud by byly sjednány samostatně. Informace o této úplatě patří mezi povinné informace, které musí zákazník v dostatečném časovém předstihu před poskytnutím investiční služby obdržet.","tp":0},{"id":"20067.1","t":"s","q":"Může organizátor regulovaného trhu na evropském regulovaném trhu provést pokyn účastníka s využitím svého vlastního majetku?","o":["Nesmí, je to zákonem zakázáno.","Nesmí, pokud mu to neumožňuje smlouva s klientem.","Může, pokud k tomu získá dodatečně souhlas klienta.","Může bez omezení."],"c":[0],"p":80,"e":"V zájmu ochrany zákazníků a transparentnosti je zakázáno využívat vlastní majetek organizátora regulovaného trhu k provádění pokynů účastníků trhu, a to i v případě, že by s tím účastník trhu souhlasil.","tp":0},{"id":"20068.2","t":"s","q":"Může organizátor regulovaného trhu provozovat mnohostranný obchodní systém?","o":["Ano, může, pak je povinen postupovat s odbornou péčí obdobně jako obchodník s cennými papíry.","Ano, může bez dalšího omezení.","Nemůže.","Nemůže, protože jinak by nesměl organizovat regulovaný trh."],"c":[0],"p":80,"e":"Zákon rozlišuje, že organizátor regulovaného trhu jednak organizuje regulovaný trh, jednak může provozovat mnohostranný obchodní systém, čímž ale poskytuje investiční služby, proto má povinnost jednat s odbornou péčí obdobně jako obchodník s cennými papíry.","tp":0},{"id":"20073.2","t":"s","q":"Může investiční zprostředkovatel poskytovat doplňkovou investiční službu úschovy a správy investičních nástrojů pro zákazníka?","o":["Nemůže, zákon o podnikání na kapitálovém trhu to neumožňuje.","Může, pokud při tom nepřijímá peněžní prostředky zákazníků.","Může, ale jen současně s hlavní investiční službou.","Může, ale jen na základě udělené plné moci od obchodníka s cennými papíry."],"c":[0],"p":81,"e":"Investiční zprostředkovatel není oprávněn poskytovat žádnou doplňkovou investiční službu na základě povolení od ČNB, avšak to nevylučuje poskytování doplňkových investičních služeb na základě jiného povolení nežli od ČNB (např. na základě živnostenského oprávnění. To ovšem neplatí pro doplňkovou investiční službu dle § 4 odst. 3 písm. a), která náleží pouze pro obchodníky s cennými papíry na základě povolení od ČNB.","tp":0},{"id":"20074.1","t":"s","q":"Může investiční zprostředkovatel poskytovat pro zákazníky službu úschovy investičních nástrojů?","o":["Ne, protože nesmí poskytovat žádné doplňkové investiční služby.","Může.","Může jen u fondů kolektivního investování.","Může, ale jen investiční nástroje spravované investiční společností."],"c":[0],"p":81,"e":"Investiční zprostředkovatel není oprávněn poskytovat žádnou doplňkovou investiční službu.","tp":0},{"id":"20075.1","t":"s","q":"Může investiční zprostředkovatel poskytovat zákazníkům úvěr na nákup investičních nástrojů?","o":["Nesmí, protože se jedná o doplňkovou investiční službu.","Může to činit u fondu kvalifikovaných investorů.","Může s ohledem na svůj počáteční kapitál.","Může, ale jen ve spolupráci s obchodníkem s cennými papíry."],"c":[0],"p":81,"e":"Investiční zprostředkovatel není oprávněn poskytovat žádnou doplňkovou investiční službu.","tp":0},{"id":"20076.1","t":"s","q":"Obchodník s cennými papíry jako svou doplňkovou službu poskytuje úschovu cenných papírů, přičemž:","o":["Drží cenné papíry zákazníka odděleně od vlastních cenných papírů, není-li sjednáno jinak.","Drží cenné papíry zákazníka vždy odděleně od vlastních cenných papírů.","Drží cenné papíry zákazníka společně s vlastními cennými papíry.","Zákon neupravuje oddělené držení cenných papírů zákazníka a obchodníka s cennými papíry."],"c":[0],"p":81,"e":"Odděleným držením cenných papírů (investičních nástrojů) zákazníka při jejich úschově je chráněn majetek zákazníka, tato oblast je upravena jak občanským zákoníkem, tak i zákonem č. 256/2004 Sb.","tp":0},{"id":"20077.1","t":"s","q":"Je poradenská činnost týkající se struktury kapitálu a přeměn společností investiční službou upravenou zákonem o podnikání na kapitálovém trhu?","o":["Ano, jedná se o doplňkovou investiční službu.","Ne.","Ne, jde o činnost podle zákona o advokacii.","Ano, jedná se o hlavní investiční službu obchodníka s cennými papíry."],"c":[0],"p":81,"e":"Zahrnutí poradenské činnosti týkající se struktury kapitálu, průmyslové strategie a poskytování poradenství ohledně přeměn společností nebo převodů obchodních závodů patří mezi doplňkové investiční služby.","tp":0},{"id":"20078.1","t":"s","q":"Doplňkovou investiční službou je mimo jiné:","o":["Provádění devizových služeb souvisejících s poskytováním investičních služeb.","Provádění pokynů na účet zákazníka.","Provádění pokynů na vlastní účet obchodníka s cennými papíry.","Provozování mnohostranného obchodního systému."],"c":[0],"p":82,"e":"Služby související s upisováním nebo umisťováním investičních nástrojů považuje zákon č. 256/2004 Sb. za doplňkovou investiční službu na rozdíl od vlastního upisování nebo umisťování investičních nástrojů.","tp":0},{"id":"20079.1","t":"s","q":"Která z následujících činností je doplňkovou investiční službou?","o":["Poskytování úvěru za účelem nákupu investičního nástroje, na němž se poskytovatel úvěru podílí.","Poskytování spotřebitelského úvěru.","Investiční poradenství týkající se investičních nástrojů.","Provádění pokynů týkajících se investičních nástrojů na účet zákazníka."],"c":[0],"p":82,"e":"Doplňkové investiční služby jsou v zákoně o podnikání na kapitálovém trhu taxativně vymezeny.","tp":0},{"id":"20080.1","t":"s","q":"Která z následujících činností je doplňková investiční služba poskytovaná obchodníkem s cennými papíry?","o":["Služby související s upisováním investičních nástrojů.","Provozování mnohostranného obchodního systému.","Obchodování s investičními nástroji na vlastní účet.","Přijímání a předávání pokynů týkajících se investičních nástrojů."],"c":[0],"p":82,"e":"Doplňkové investiční služby jsou v zákoně o podnikání na kapitálovém trhu taxativně vymezeny.","tp":0},{"id":"20081.1","t":"s","q":"Může zahraniční osoba ze státu mimo EU nabízet na území ČR doplňkové investiční služby?","o":["Ano, pokud je registrovaná evropským orgánem dohledu nebo má povolení České národní banky.","Ano, pokud jde o právnickou osobu se sídlem sice mimo členské státy EU, avšak se sídlem v jiném státě EHP.","Může, na základě oznámení České národní bance.","Může, na základě oznámení Evropské centrální bance."],"c":[0],"p":82,"e":"Režim pro poskytování hlavních a vedlejších investičních služeb je pro osoby se sídlem ve státě, který není členským státem EU stanoven v zákoně tak, že pro svoji činnost na území ČR potřebují buď registraci Evropského orgánu dohledu (Evropský orgán pro cenné papíry a trhy) nebo mohou poskytovat tyto služby pouze prostřednictvím pobočky na základě povolení od České národní banky.","tp":0},{"id":"20082.1","t":"s","q":"Která z následujících činností je doplňkovou investiční službou?","o":["Poradenská činnost týkající se nabytí účasti v obchodní korporaci.","Obchodování s investičními nástroji na vlastní účet.","Zprostředkování pojištění investičních nástrojů.","Provozování organizovaného obchodního systému."],"c":[0],"p":82,"e":"Doplňkové investiční služby jsou v zákoně o podnikání na kapitálovém trhu taxativně vymezeny.","tp":0},{"id":"20083.1","t":"s","q":"Která z následujících činností není doplňkovou investiční službou?","o":["Investiční poradenství týkající se investičních nástrojů.","Úschova a správa investičních nástrojů pro zákazníka.","Poskytování úvěru zákazníkovi na nákup investičního nástroje, na němž se poskytovatel úvěru podílí.","Služby související s upisováním investičních nástrojů."],"c":[0],"p":83,"e":"Doplňkové investiční služby jsou v zákoně o podnikání na kapitálovém trhu taxativně vymezeny.","tp":0},{"id":"20084.1","t":"s","q":"Kterou investiční službu nesmí poskytovat investiční zprostředkovatel?","o":["Úschovu a správu investičních nástrojů zákazníka.","Přijímání pokynů zákazníka týkajících se investičních nástrojů.","Předávání pokynů zákazníka týkajících se investičních nástrojů.","Poskytování investičního poradenství týkajícího se investičních nástrojů."],"c":[0],"p":83,"e":"Investiční zprostředkovatel může poskytovat pouze zákonem vyjmenované hlavní investiční služby.","tp":0},{"id":"20089.1","t":"s","q":"Jaké jsou stanoveny požadavky na evidenci smluv týkajících se investičních služeb poskytovaných investičním zprostředkovatelem?","o":["Musí umožnit nastavení a ověření přístupových práv, zabezpečení ochrany údajů a pravidelné zálohování dat.","Musí být zřízeno záložní pracoviště pro ukládání dat odlišné od sídla investičního zprostředkovatele.","Musí být umožněn dálkový přístup pro orgány dohledu České národní banky.","Musí být umožněn dálkový přístup pro externího auditora, aby mohl průběžně ověřovat správnost nastavení systému vedení evidence investičního zprostředkovatele."],"c":[0],"p":83,"e":"Prováděcí právní předpis konkretizuje požadavky na evidenci vedenou investičním zprostředkovatelem s ohledem na ochranu údajů v evidenci.","tp":0},{"id":"20090.1","t":"s","q":"Týká se řízení střetu zájmů i střetu zájmů mezi investičními zprostředkovateli působícími pro obchodníka s cennými papíry a jeho zákazníky?","o":["Ano.","Ne.","Ano, ale jen v oblasti vztahu jejich vázaných zástupců k zákazníkům.","Ano, ale jen ve vztahu k potenciálním zákazníkům."],"c":[0],"p":83,"e":"Vzhledem k tomu, že za určitých okolností obchodník s cennými papíry odpovídá za jednání investičních zprostředkovatelů se zákazníky, je v jeho zájmu i řízení střetu zájmů u těchto subjektů, což je mj. i zákonná povinnost.","tp":0},{"id":"20091.1","t":"s","q":"Jaká povinnost platí pro investičního zprostředkovatele při poskytování investiční služby investičního poradenství?","o":["Musí informovat zákazníka, že službu poskytuje závisle nebo nezávisle.","Nesmí poskytovat investiční poradenství týkající se investičních nástrojů vydaných nebo vytvořených obchodníkem s cennými papíry, na něhož je smluvně navázán.","Nesmí svým vázaným zástupcům povolit nabízení investičních nástrojů na základě omezené analýzy investičních nástrojů.","Nejsou stanoveny žádné konkrétní povinnosti, postačuje obecné ustanovení o povinnosti vykonávat činnost obezřetně."],"c":[0],"p":83,"e":"Účelem ochrany zákazníků jakožto příjemců investičního poradenství je poskytnout jim informace, ze kterých je zřejmá závislost investičního zprostředkovatele nebo jeho závislost na určitém tvůrci investičního nástroje.","tp":0},{"id":"20092.1","t":"s","q":"Může obchodník s cennými papíry použít investiční nástroje zákazníka k obchodům na vlastní účet?","o":["Ano, ale musí získat od zákazníka předem výslovný písemný souhlas s uvedením podmínek.","Ne, nesmí.","Ano, ale jen získá-li kladné vyjádření externího auditora.","Ano, ale musí o tom v dostatečném předstihu informovat Českou národní banku."],"c":[0],"p":84,"e":"Omezení použití investičních nástrojů zákazníků na vlastní účet obchodníka s cennými papíry má zabránit zneužití tohoto majetku zákazníků a zamezit ztrátám, se kterými nebyli zákazníci předem srozuměni. Umožňuje se rovněž stanovení podmínek pro takové obchody.","tp":0},{"id":"20093.1","t":"s","q":"Co je zdrojem majetku Garančního fondu obchodníků s cennými papíry?","o":["Především příspěvky od obchodníků s cennými papíry a pokuty.","Příspěvky od České národní banky.","Příspěvky od ministerstva financí.","Garanční fond nemá vlastní majetek, je pouze evidenčním místem pro zpracování náhrad zákazníkům."],"c":[0],"p":84,"e":"Zdrojem majetku Garančního fondu jsou příspěvky od obchodníků s cennými papíry, pokuty a výnosy z investování.","tp":0},{"id":"20094.2","t":"s","q":"Systém správy a řízení obchodníka s cennými papíry nemusí obsahovat:","o":["Oblast marketingu.","Oblast řízení rizik.","Systém vnitřní kontroly.","Zásady a postupy odměňování."],"c":[0],"p":84,"e":"K zajištění řádného a obezřetného výkonu činností musí obsahovat systém správy a řízení obchodníků s cennými papíry celou řadu oblastí zajišťujících stabilitu obchodníka s cennými papíry a ochranu zákazníka, které jsou v zákoně č. 256/2004 Sb. vyjmenovány. Mezi tyto oblasti nepatří tzv. nevýznamné provozní činnosti.","tp":0},{"id":"20095.2","t":"s","q":"Co rozumíme střetem zájmů obchodníka s cennými papíry s klientem?","o":["Skutečnost, která v konkrétním případě představuje nebezpečí poškození klienta (nebo více klientů).","Konflikt manažerů a podřízených zaměstnanců obchodníka s cennými papíry.","Nesouhlas zákazníků s poplatkovou politikou obchodníka s cennými papíry","Skutečnost, která v důsledku obchodů obchodníka s cennými papíry na vlastní účet pro něj zvyšuje riziko."],"c":[0],"p":84,"e":"Řízení střetu zájmů je jedním z předpokladů řádného a obezřetného výkonu činnosti, které má chránit zákazníky. Obchodník s cennými papíry je povinen oblast střetu zájmů rozpracovat ve svém řídicím a kontrolním systému, což bývá upraveno v různých vnitřních předpisech. Vázaní zástupci mají povinnost vznik střetu zájmů oznamovat, obchodník pak informuje zákazníka.","tp":0},{"id":"20096.2","t":"s","q":"Při zjišťování a posuzování střetu zájmů musí obchodník s cennými papíry posoudit, zda:","o":["Může získat finanční prospěch na úkor zákazníka.","Může získat jeho vedoucí osoba finanční prospěch na úkor vázaných zástupců.","Může získat finanční prospěch jeho vedoucí osoba na úkor jeho investičních zprostředkovatelů.","Může získat finanční prospěch jeho zaměstnanec na úkor externích vázaných zástupců."],"c":[0],"p":84,"e":"Zákon č. 256/2004 Sb., o podnikání na kapitálovém trhu, § 11a.","tp":0},{"id":"20097.3","t":"s","q":"Jakým způsobem může např. vzniknout střet zájmů mezi obchodníkem s cennými papíry a zákazníkem?","o":["Obchodník s cennými papíry má odlišný zájem na výsledku obchodu prováděného na účet zákazníka od tohoto zákazníka.","Obchodník s cennými papíry má totožný zájem jako zákazník při provádění obchodu na účet zákazníka.","Obchodník s cennými papíry má rozsáhlejší informace o konkrétním investičním nástroji než zákazník.","Obchodník s cennými papíry nemá dostatek informací o konkrétním investičním nástroji, o nějž má zákazník zájem."],"c":[0],"p":85,"e":"Podstatou řízení střetu zájmů je ochrana zákazníka před ztrátami v důsledku finančního prospěchu obchodníka s cennými papíry, jeho pracovníků a vázaných zástupců. Jde o konkretizaci § 11a ve světle dříve publikovaných metodických stanovisek ČNB.","tp":0},{"id":"20098.3","t":"s","q":"O střet zájmů se zákazníkem se také jedná v následujícím případě:","o":["Obchodník s cennými papíry se vyhne své finanční ztrátě na úkor zákazníka.","Obchodník s cennými papíry poruší povinnosti evidence obchodů na účet zákazníka.","Obchodník s cennými papíry se dělí o poplatky s investičním zprostředkovatelem.","Může získat finanční prospěch jeho zaměstnanec na úkor externích vázaných zástupců."],"c":[0],"p":85,"e":"Podstatou řízení střetu zájmů je ochrana zákazníka před ztrátami v důsledku finančního prospěchu obchodníka s cennými papíry, jeho pracovníků a vázaných zástupců. Jde o konkretizaci § 11a ve světle dříve publikovaných metodických stanovisek ČNB.","tp":0},{"id":"20099.3","t":"s","q":"O střet zájmů obchodníka s cennými papíry se zákazníkem se jedná také v následujícím případě:","o":["Obchodník s cennými papíry má zájem upřednostnit zájmy jiných zákazníků před zájmy zákazníka.","Obchodník s cennými papíry jedná s klientem jako s neprofesionálním zákazníkem.","Obchodník s cennými papíry nepožaduje od vázaných zástupců informace o stavu obchodu se zákazníkem.","Obchodník s cennými papíry umožní svému statutárnímu orgánu jednat se zákazníkem."],"c":[0],"p":85,"e":"Řízení střetu zájmů je jedním z předpokladů řádného a obezřetného výkonu činnosti, které má chránit zákazníky. Obchodník s cennými papíry je povinen oblast střetu zájmů rozpracovat ve svém řídicím a kontrolním systému, což bývá upraveno v různých vnitřních předpisech. Vázaní zástupci mají povinnost vznik střetu zájmů oznamovat, obchodník pak informuje zákazníka.","tp":0},{"id":"20105.1","t":"s","q":"Co musí obchodník s cennými papíry učinit za účelem ochrany vlastnického práva zákazníka?","o":["Při nakládání s investičními nástroji musí zavést opatření k vyloučení použití investičních nástrojů zákazníka k obchodům na vlastní účet nebo účet jiného zákazníka, pokud k tomu nemá výslovný souhlas zákazníka.","Musí vést evidenci majetku zákazníka v deníku obchodníka.","Při použití investičních nástrojů zákazníka k obchodům na vlastní účet k tomu musí získat dodatečný souhlas zákazníka.","K použití investičních nástrojů zákazníka k obchodům na vlastní účet nepotřebuje souhlas zákazníka, nesmí však zákazníka poškodit."],"c":[0],"p":85,"e":"Ochrana majetku zákazníka je v popředí zájmu právní úpravy, proto se nepřipouští jakékoli jiné použití investičních nástrojů zákazníka než k obchodům na jeho účet, pokud k tomu zákazník nedá výslovný souhlas předem.","tp":0},{"id":"20106.1","t":"s","q":"Co musí obchodník s cennými papíry splňovat při nakládání s peněžními prostředky zákazníka?","o":["Obchodník s cennými papíry musí mít opatření k vyloučení použití peněžních prostředků zákazníka k obchodům na svůj vlastní účet nebo účet jiného zákazníka.","Obchodník s cennými papíry musí vést peněžní prostředky zákazníka na podúčtu v bance v rámci svého platebního účtu.","Obchodník s cennými papíry musí vést peněžní prostředky zákazníků na jejich vlastních platebních účtech u banky.","Obchodník s cennými papíry musí vést peněžní prostředky zákazníka jen na účtu u České národní banky."],"c":[0],"p":86,"e":"Peněžním prostředkům zákazníka je poskytována maximální ochrana, aby nedošlo k jejich zneužití. Obchodník s cennými papíry nesmí s těmito prostředky nakládat jinak než k obchodům na jejich účet a k jinému použití peněžních prostředků nemůže dojít ani po případném souhlasu zákazníka, zákon takový souhlas nepředpokládá. Výjimkou je použití takových peněžních prostředků obchodníky s cennými papíry, které jsou bankou.","tp":0},{"id":"20107.1","t":"s","q":"Musí obchodník s cennými papíry informovat o opatřeních na ochranu majetku zákazníků Českou národní banku?","o":["Ano, obchodník s cennými papíry musí zajistit, aby jeho externí auditor nejméně jednou ročně podal zprávu České národní bance.","Ano, obchodník s cennými papíry musí průběžně informovat Českou národní banku.","Obchodník s cennými papíry musí informovat Českou národní banku o opatřeních na ochranu majetku zákazníků jen na vyžádání.","Ne, nemusí."],"c":[0],"p":86,"e":"Česká národní banka v rámci výkonu dohledu na dálku vyžaduje informace, aby mohla průběžně sledovat plnění povinností souvisejících s ochranou majetku zákazníků. Pro objektivnost informací je formulována povinnost zajistit zpracování zprávy externím auditorem (auditorskou společností), nikoli interním auditorem obchodníka s cennými papíry.","tp":0},{"id":"20108.1","t":"s","q":"Jaký je základní požadavek na evidenci majetku zákazníka v systému vnitřní evidence obchodníka s cennými papíry?","o":["Musí zajistit soustavnou a jednoznačnou identifikaci investičních nástrojů a peněžních prostředků každého zákazníka.","Musí zajistit jednou ročně uvedení evidence majetku zákazníků do souladu se skutečným stavem.","Musí v předepsaných lhůtách informovat o majetku zákazníků Českou národní banku.","Nemá stanoveny žádné povinnosti, ty má stanoveny externí auditor."],"c":[0],"p":86,"e":"Požadavek na ochranu majetku zákazníků u obchodníků s cennými papíry spočívá především v řádné evidenci majetku a peněžních prostředků zákazníků, aby nedošlo k jejich použití obchodníkem s cennými papíry nebo na účet jiných zákazníků bez jejich souhlasu. Vzhledem k tomu, že u řady investičních nástrojů má zákazník právo na odkup kdykoli, musí být evidence obchodníka umožňující identifikaci tohoto majetku vedena soustavně.","tp":0},{"id":"20109.1","t":"s","q":"Jakou povinnost má obchodník s cennými papíry ve vztahu k investičním nástrojům zákazníka drženým třetí osobou?","o":["Musí zajistit shodu dat ve své evidenci se skutečným stavem investičních nástrojů zákazníka u této třetí osoby.","Nesmí umožnit držení investičních nástrojů zákazníka třetí osobou.","Může umožnit držení investičních nástrojů zákazníků třetí osobou maximálně po dobu jednoho roku.","Musí informovat externího auditora, aby provedl kontrolu u této třetí osoby."],"c":[0],"p":86,"e":"Ochrana majetku zákazníka se vztahuje i na jeho majetek, který je v držení třetí osoby. S ohledem na povinnost mít neustále jednoznačnou identifikaci majetku zákazníka musí obchodník s cennými papíry uvádět do souladu svoji vnitřní evidenci se skutečným stavem i u třetí osoby.","tp":0},{"id":"20110.1","t":"s","q":"Co je to rekonciliace?","o":["Proces zajišťující kontrolu shody dat ve vnitřní evidenci obchodníka s cennými papíry se skutečným stavem peněžních prostředků a investičních nástrojů zákazníka držených třetí osobou.","Je to systém interní evidence obchodníka s cennými papíry.","Objem investičních nástrojů zákazníka v držení třetí osoby.","Výstup auditu investičních nástrojů zákazníka u třetí osoby."],"c":[0],"p":87,"e":"Rekonciliace je obecně z účetního hlediska shoda nebo uvedení do souladu. V oblasti kapitálového trhu je to definice zajišťující shodu dat se skutečným stavem.","tp":0},{"id":"20111.1","t":"s","q":"Jakým způsobem musí obchodník s cennými papíry ve své vnitřní evidenci zajistit identifikaci investičních nástrojů zákazníků?","o":["Musí být zajištěna jednoznačná identifikace investičních nástrojů každého zákazníka, aby byl majetek držený pro jednoho zákazníka kdykoli odlišen od majetku ostatních zákazníků a majetku obchodníka s cennými papíry.","Musí být zajištěna identifikace investičních nástrojů všech zákazníků podle jednotlivých tříd investičních nástrojů spravovaných obchodníkem s cennými papíry.","Musí být zajištěno pouze odlišení majetku obchodníka s cennými papíry od investičních nástrojů zákazníků; přiřazení investičních nástrojů ke konkrétnímu zákazníkovi se provádí při jejich odprodeji.","Musí být zajištěna evidence pro usnadnění kontroly ze strany ministerstva financí."],"c":[0],"p":87,"e":"Prováděcí právní předpis požaduje, aby byl v každém okamžiku identifikován majetek jednotlivých zákazníků a odepsán od majetku ostatních zákazníků i obchodníka s cennými papíry.","tp":0},{"id":"20112.1","t":"s","q":"Jakým způsobem zajistí obchodník s cennými papíry systém správy ochrany majetku zákazníků?","o":["Určí alespoň jednoho odpovědného pracovníka kontrolujícího dodržování povinností v oblasti ochrany majetku zákazníků.","Smluvně zajistí u subjektu provádějícího externí audit u obchodníka s cennými papíry kontrolu dodržování povinností v oblasti ochrany majetku zákazníků.","Zajistí formulací příslušných ustanovení ve smlouvách s vázanými zástupci dodržování povinností v oblasti ochrany majetku zákazníků.","Oblast ochrany majetku zákazníků zahrnuje do zpráv předkládaných ministerstvu financí."],"c":[0],"p":87,"e":"Prováděcí právní předpis požaduje zavedení systému správy a řízení v oblasti ochrany majetku zákazníků určením alespoň jednoho odpovědného pracovníka kontrolujícího dodržování povinností v oblasti ochrany majetku zákazníků.","tp":0},{"id":"20113.1","t":"s","q":"Musí evidence obchodníka s cennými papíry obsahovat nějaké údaje o vedení účtů u třetích osob?","o":["Vnitřní evidence obchodníka s cennými papíry musí obsahovat informace, na jakém účtu u třetí osoby jsou vedeny investiční nástroje a peněžní prostředky každého zákazníka.","Evidence obchodníka s cennými papíry musí obsahovat pouze seznam bank, které používá pro obchody svých zákazníků.","Evidence obchodníka s cennými papíry musí obsahovat informace o souhrnných účtech vedených u třetích osob.","Vnitřní evidence obchodníka s cennými papíry tyto informace obsahovat nemusí."],"c":[0],"p":87,"e":"Prováděcí právní předpis požaduje, aby obchodník měl vnitřní evidenci o takových účtech.","tp":0},{"id":"20114.1","t":"s","q":"Musí obchodník s cennými papíry chránit majetek zákazníků proti podvodům?","o":["Ano, musí zavést účinná organizační opatření, která povedou k minimalizaci rizika podvodu.","Ano, musí o tomto riziku zákazníka poučit.","Ano, musí umožnit zákazníkům pojištění jejich majetku, který jim spravuje.","Ne, je to součást rizika, které nese zákazník na kapitálovém trhu."],"c":[0],"p":88,"e":"Prováděcí právní předpis stanovuje obchodníkovi s cennými papíry povinnost přijmout účinná organizační opatření k minimalizaci rizika podvodu, konkretizaci těchto opatření nechává na obchodníkovi s cennými papíry, avšak riziko podvodu nelze přenášet na zákazníky.","tp":0},{"id":"20115.1","t":"s","q":"U jakých osob může obchodník s cennými papíry uložit peněžní prostředky zákazníků?","o":["Může je uložit u centrální banky, úvěrové instituce s povolením k činnosti v členském státě EU, zahraniční banky.","Může uložit peněžní prostředky pouze u centrální banky a bank na území ČR. Výjimečně může tyto peněžní prostředky uložit u družstevních záložen.","Může je uložit u jakéhokoliv subjektu finančních služeb, avšak jen na území EU.","Může je uložit pouze u bank a spořitelních a úvěrních družstev (v zahraničí u obdobných subjektů)."],"c":[0],"p":88,"e":"Prováděcí právní předpis omezuje ukládání peněžních prostředků zákazníků taxativním výčtem okruhu subjektů, u nichž lze tyto prostředky uložit.","tp":0},{"id":"20116.1","t":"s","q":"Může obchodník s cennými papíry uložit investiční nástroje zákazníků u třetích osob a pokud ano, za jakých podmínek?","o":["Ano, může je uložit, pokud vezme v úvahu zkušenosti této osoby, její pověst na finančním trhu a právní požadavky pro nakládání s investičními nástroji zákazníků a pokud toto uložení ve třetím státě podléhá regulaci a dohledu (s určitými výjimkami).","Ano, může je uložit, avšak pouze u právnických osob na území ČR majících rating od renomované ratingové agentury AA a vyšší.","Může je uložit u třetích osob bez dalšího omezení, musí posoudit pouze operační riziko.","Ne, investiční nástroje zákazníků nesmí u třetích osob ukládat s výjimkou bank a spořitelních a úvěrních družstev."],"c":[0],"p":88,"e":"Právní předpis stanoví, že při ukládání investičních nástrojů zákazníků u třetích osob musí obchodník s cennými papíry jednat s odbornou péčí, kterou dále konkretizuje.","tp":0},{"id":"20121.1","t":"s","q":"Jaká je stanovena povinnost ochrany zákazníků při vytváření investičního nástroje obchodníkem s cennými papíry?","o":["Musí zajistit, aby návrh investičního nástroje nepoškozoval koncové zákazníky tím, že by obchodníkovi s cennými papíry umožňoval snížit svá vlastní rizika.","Musí zajistit, aby bylo zákazníkovi vysvětleno snížení vlastních rizik obchodníka s cennými papíry.","Musí zajistit snížení vlastní expozice spojené s investičním nástrojem.","Musí informovat zákazníka o držení investičního nástroje na svůj vlastní účet."],"c":[0],"p":88,"e":"Ve vyhlášce č. 308/2017 Sb. jsou rozpracovány povinnosti obchodníků s cennými papíry, kteří vytvářejí investiční nástroje nabízené zákazníkům. Základní povinnosti se týkají opatření k zajištění řízení střetu zájmů a zhodnocení rizik špatných výsledků pro investora.","tp":0},{"id":"20122.2","t":"s","q":"Jaké informace si musí zajistit obchodník s cennými papíry nabízející investiční nástroj, který sám nevytvářel?","o":["Musí si zajistit od tvůrce investičního nástroje informace potřebné pro porozumění jeho vlastnostem, aby tento investiční nástroj byl vhodný pro cílový trh (konečné zákazníky). K tomu může použít i veřejné informace.","Musí si zajistit školení u tvůrce investičního nástroje pro své zaměstnance a vázané zástupce.","Musí si zpracovat vlastní analýzu investičního nástroje, aby uměl řídit svoje rizika.","Nemusí od tvůrce investičního nástroje požadovat informace, jako osoba mající registraci pro podnikání na kapitálovém trhu musí umět pracovat s veřejně dostupnými informacemi."],"c":[0],"p":89,"e":"Prováděcí vyhláška č. 308/2017 Sb. ukládá distributorům investičních nástrojů zajistit, že investiční nástroje a služby, které mají v úmyslu nabízet, jsou v souladu s vlastnostmi, potřebami a cíli určeného cílového trhu.","tp":0},{"id":"20123.1","t":"s","q":"Jaké má obchodník s cennými papíry povinnosti ohledně hodnocení investičního nástroje, který nabízí?","o":["Musí pravidelně hodnotit investiční nástroj, který nabízí nebo doporučuje, přitom musí vzít v úvahu všechny události, které by mohly podstatně ovlivnit potenciální riziko pro cílový trh.","Musí průběžně zkoumat plnění obchodních cílů a rizika obchodníka s cennými papíry.","Musí hodnotit investiční nástroj jen ve vztahu ke konkrétnímu zákazníkovi, rizika, ani cíle určeného cílového trhu nehodnotí.","Musí investiční nástroj ohodnotit z hlediska rizika pro konkrétního zákazníka na začátku jeho nabízení nebo doporučování, tedy definuje jeho rizikovost pro jednotlivého zákazníka nebo homogenní skupinu zákazníků."],"c":[0],"p":89,"e":"Obchodník s cennými papíry pravidelně přezkoumává soulad nabízených investičních nástrojů (a služeb) z hlediska souladu s vlastnostmi, potřebami a cíli určeného cílového trhu; bere přitom v úvahu všechny události, které by mohly podstatně ovlivnit potenciální riziko pro určený cílový trh.","tp":0},{"id":"20124.1","t":"s","q":"Posuzuje obchodník s cennými papíry potenciální střety zájmů při vytváření investičního nástroje?","o":["Ano, vždy.","Ano, ale jen při vytváření s využitím třetí strany.","Ne.","Ne, je to úloha externího auditora."],"c":[0],"p":89,"e":"Řídit střet zájmů se požaduje při každé činnosti obchodníka s cennými papíry.","tp":0},{"id":"20125.1","t":"s","q":"Co musí obchodník s cennými papíry při vytváření investičního nástroje učinit?","o":["Musí určit cílový trh pro každý investiční nástroj a upřesnit typ zákazníků, s jejichž potřebami, charakteristikami a cíli je nebo není investiční nástroj slučitelný.","Musí určit pro každý investiční nástroj alespoň dva cílové trhy s jejichž potřebami, charakteristikami a cíli je investiční nástroj slučitelný.","Musí určit cílové zákazníky pro vybrané jím vytvářené investiční nástroje.","Musí určit cílové zákazníky pro svůj stěžejní investiční nástroj, u něj musí upřesnit okruh zákazníků, s jejichž potřebami a cíli je tento investiční nástroj slučitelný."],"c":[0],"p":89,"e":"Pravidla ochrany zákazníků zahrnují i povinnosti při vytváření investičních nástrojů, kdy každý investiční nástroj je určen pro jiný cílový trh a jiný typ zákazníků.","tp":2},{"id":"20126.2","t":"s","q":"Musí obchodník s cennými papíry před uvedením investičního nástroje na trh posoudit, zda neohrožuje stabilitu a fungování finančního trhu?","o":["Ano, musí to učinit ještě před takovým rozhodnutím.","Ne, musí to učinit až ve lhůtě 30 dnů od uvedení investičního nástroje na trh.","Musí toto riziko projednat s externím auditorem s dostatečným předstihem před uvedením investičního nástroje na trh, aby auditor mohl vytvořit zprávu pro ČNB.","Ne, toto není jeho povinnost, posuzuje to Česká národní banka."],"c":[0],"p":90,"e":"Stabilita finančního trhu je základním předpokladem jeho efektivního fungování. Proto je stanovena povinnost pro účastníky tohoto trhu neohrožovat svým jednáním jeho stabilitu.","tp":2},{"id":"20127.1","t":"s","q":"Co musí učinit obchodník s cennými papíry vytvářející investiční nástroj vůči obchodníkovi s cennými papíry nabízejícímu tento investiční nástroj?","o":["Musí stanovit, s jakými potřebami a charakteristikami zákazníků je investiční nástroj slučitelný.","Musí mu poskytnout prospekt tohoto investičního nástroje.","Musí mu poskytnout emisní podmínky k tomuto investičnímu nástroji.","Musí mu umožnit, aby se podílel na schvalování tohoto investičního nástroje."],"c":[0],"p":90,"e":"Zákon o podnikání na kapitálovém trhu stanovuje taxativně povinnosti obchodníka s cennými papíry, který vytváří investiční nástroj a dále je konkretizuje v prováděcím právním předpise.","tp":0},{"id":"20129.1","t":"s","q":"Obchodník s cennými papíry vytvářející investiční nástroj jej musí posuzovat za nepříznivých podmínek?","o":["Ano, musí, zejména z hlediska zhoršení tržního prostředí nebo situace, kdy se tvůrce investičního nástroje dostane do úpadku.","Ne, nemusí, investiční nástroj nese vždy riziko pro koncové zákazníky.","Ano, musí zohlednit riziko úpadku zákazníka.","Musí tento nový investiční nástroj porovnat před zahájením nabízení s konkurenčními investičními nástroji."],"c":[0],"p":90,"e":"Prováděcí právní předpis stanovuje obchodníkovi s cennými papíry povinnosti ohledně analýzy scénářů a posouzení rizik pro koncové zákazníky.","tp":0},{"id":"20130.1","t":"s","q":"Má investiční zprostředkovatel nějaké povinnosti týkající se jím nabízeného investičního nástroje?","o":["Musí od osoby vytvářející investiční nástroj získat informace o investičním nástroji a cílovém trhu.","Musí získat informace o subjektech, které se podílely na vytváření tohoto investičního nástroje.","Musí od České národní banky získat informace o schválení tohoto investičního nástroje.","Musí sám na základě prospektu investičního nástroje definovat cílovou skupinu zákazníků."],"c":[0],"p":90,"e":"Investiční zprostředkovatel má obdobné povinnosti jako obchodník s cennými papíry ohledně získávání informací o investičním nástroji, který chce nabízet nebo doporučovat.","tp":0},{"id":"20131.1","t":"s","q":"Má investiční zprostředkovatel právo na informace o investičních nástrojích od obchodníka s cennými papíry, který investiční nástroje vytváří?","o":["Ano, má právo na veškeré potřebné informace o těchto investičních nástrojích a informace o cílovém trhu, pro který jsou určeny.","Ano, má právo na emisní podmínky.","Ano, má právo na emisní podmínky a investiční kalkulačky.","Ne, musí si zajistit dostatečné informace z veřejně dostupných zdrojů, ale musí proškolit své vázané zástupce."],"c":[0],"p":90,"e":"Zákon o podnikání na kapitálovém trhu stanovuje taxativně povinnosti obchodníka s cennými papíry, který vytváří investiční nástroj a dále je konkretizuje v prováděcím právním předpise.","tp":0},{"id":"20132.1","t":"s","q":"Musí obchodník s cennými papíry nabízející investiční nástroj, který sám nevytvářel, zavést nějaký systém nabízení investičních nástrojů?","o":["Ano, tento systém musí zajišťovat, že nabízený nebo doporučovaný investiční nástroj je slučitelný s potřebami a cíli cílového trhu a že nebudou ohroženy zájmy zákazníků.","Ano, tento systém musí odpovídat jeho obchodní strategii, za slučitelnost s potřebami zákazníků odpovídá distribuční síť.","Ano, musí spolupracovat na systému nabízení s obchodníkem s cennými papíry, který investiční nástroj vytvářel.","Ne, tento systém musí mít zaveden pouze obchodník s cennými papíry vytvářející investiční nástroj."],"c":[0],"p":91,"e":"Prováděcí právní předpis stanovuje obchodníkovi s cennými papíry, který nabízí investiční nástroj, povinnosti ohledně systému nabízení investičních nástrojů. Tuto povinnost má obchodník s cennými papíry, který investiční nástroj vytvářel, i ten, který jej pouze nabízí nebo doporučuje.","tp":0},{"id":"20137.3","t":"s","q":"Jaké informace může při jednání se zákazníky obchodník s cennými papíry používat?","o":["Informace jasné, pravdivé, nezavádějící.","Pravdivé informace, bez ohledu na to, zda na jejich základě zákazník může správně posoudit vhodnost investičního nástroje.","Informace, které se má k investičnímu nástroji dispozici, přitom není důležité, zda zákazník je schopen pochopit rizika investičního nástroje.","Informace, které jsou ohledem na znalosti zákazníka za smysluplné, přitom není důležité, že zákazník není schopen učinit sám investiční rozhodnutí."],"c":[0],"p":91,"e":"Zákon zakazuje používat informace, které by mohly uvést zákazníka v omyl a vést ho k výběru nevhodného investičního nástroje, stejně tak jako informace, z nichž by zákazník pro jejich nejasnost nemohl správně posoudit vhodnost investičního nástroje.","tp":0},{"id":"20138.2","t":"s","q":"Jaké je omezení pro odměňování pracovníků a vázaných zástupců obchodníka s cennými papíry?","o":["Obchodník s cennými papíry nesmí odměňovat pracovníky a vázané zástupce tak, aby to vedlo k porušení povinností jednat v nejlepším zájmů zákazníků (součást odborné péče).","Obchodník s cennými papíry nesmí odměňováním motivovat k porušení povinnosti jednat v nejlepším zájmu zákazníků pouze své pracovníky.","Obchodník s cennými papíry nesmí své vázané zástupce odměňovat způsobem motivujícím je k porušení povinnosti jednat v nejlepším zájmu zákazníků, to se však nevztahuje na jeho pracovníky, protože ti nemají samostatnou odpovědnost.","Pro odměňování jeho pracovníků a vázaných zástupců nejsou žádná omezení."],"c":[0],"p":91,"e":"MiFID II požaduje, aby odměňování a hodnocení výkonnosti pracovníků a vázaných zástupců obchodníků s cennými papíry nevedlo k obchodním jednáním těchto osob, které by bylo v rozporu s povinností jednat v nejlepším zájmů zákazníků, jak ukládá § 15c odst. 3 zákona č. 256/2004 Sb.","tp":0},{"id":"20139.1","t":"s","q":"Je obchodník s cennými papíry povinen upozornit zákazníka, že jejich telefonické hovory budou zaznamenávány?","o":["Ano, alespoň jednou před telefonickým poskytnutím investiční služby, která zahrnuje přijetí, předání nebo provedení pokynu zákazníka.","Ne, je to pouze na jeho uvážení.","Tuto povinnost má pouze při poskytování služby investičního poradenství.","Ano, ale jen ve vztahu k potenciálním zákazníkům."],"c":[0],"p":91,"e":"Je v zájmu ochrany zákazníků i osob jednajících za obchodníka s cennými papíry zaznamenávat telefonické hovory, což je stanoveno navíc jako povinnost v § 17 zákona č. 256/2004 Sb.","tp":0},{"id":"20140.3","t":"s","q":"V jakém rozsahu musí obchodník s cennými papíry při poskytování investičního poradenství získat od zákazníka informace v oblasti jeho odborných znalostí a zkušeností v oblasti investic?","o":["Získané informace mu musí umožnit vyhodnotit, zda rozsah poskytnutí rady ohledně investičního nástroje odpovídá odborným znalostem a zkušenostem zákazníka pro pochopení charakteru investičního nástroje.","Musí se spolehnout na informace, které má o úrovni vzdělání zákazníka.","Musí vycházet z informací poskytnutých mu útvarem kontrolujícím dodržování právních předpisů (compliance).","Musí vycházet z informací, které získá o zákazníkem dosud využívaných finančních produktech."],"c":[0],"p":92,"e":"Pochopení charakteru investičního nástroje je klíčové pro rozhodnutí zákazníka o investici. Vysvětlení jeho parametrů se odvíjí od míry znalostí a zkušeností zákazníka s investičními nástroji.","tp":0},{"id":"20141.1","t":"s","q":"Ve které situaci není obchodník s cennými papíry povinen při přijímání a předávání pokynů a provádění pokynů týkajících se investičních nástrojů na účet zákazníka požádat zákazníka o informace týkající se jeho odborných znalostí a zkušeností z oblasti investic?","o":["Je-li provádění pokynů týkajících se investičních nástrojů na účet zákazníka poskytováno z podnětu zákazníka a týká se pouze jednoduchého investičního nástroje.","Jde-li o investiční poradenství v oblasti derivátů.","Obdržel-li k tomu souhlas České národní banky.","Obdržel-li k tomu souhlas útvar zajišťující kontrolu dodržování právních předpisů (compliance)."],"c":[0],"p":92,"e":"Jedná se o výjimečnou situaci, kdy zákon nevyžaduje, aby obchodník s cennými papíry při provádění pokynů týkajících se jednoduchého investičního nástroje na účet zákazníka zjišťoval informace od zákazníka.","tp":0},{"id":"20142.2","t":"s","q":"Jak často je povinen obchodník s cennými papíry poskytovat zákazníkovi informace o službách, které mu poskytl?","o":["Po celou dobu trvání investice, alespoň jednou ročně.","Po ukončení investice (prodeji investičních nástrojů).","Frekvence není zákonem předepsána.","Každý měsíc."],"c":[0],"p":92,"e":"Jedná se o informační povinnost pravidelného charakteru, pro kterou novela zákona č. 256/2004 Sb. stanovuje povinnost poskytnout informace na nosiči dat, a to nejméně jednou ročně.","tp":0},{"id":"20143.1","t":"s","q":"Jaké informace musí obchodník s cennými papíry vytvářející investiční nástroj poskytnout distributorům?","o":["Informace dostatečné k tomu, aby distributoři porozuměli vlastnostem investičního nástroje a správně jej nabízeli.","Informace o sobě jako tvůrci investičního nástroje, další informace musí distributoři získat v rámci průběžného vzdělávání.","Informace o České národní bance jako orgánu schvalujícího investiční nástroje.","Informace o způsobu distribuce a o zakázaných obchodních praktikách."],"c":[0],"p":92,"e":"V prováděcím právním předpise jsou stanoveny minimální informace, které musí být poskytnuty distributorům investičních nástrojů.","tp":0},{"id":"20144.1","t":"s","q":"Co se rozumí poskytováním investičních služeb s odbornou péčí?","o":["Znamená to, že obchodník s cennými papíry jedná kvalifikovaně, čestně a spravedlivě a v nejlepším zájmu zákazníků.","Znamená to, že obchodník s cennými papíry jedná v souladu se zájmem na splnění plánovaných cílů.","Znamená to, že obchodník s cennými papíry dosahuje u investičních nástrojů, které vytváří, očekávané zhodnocení.","Znamená to, že obchodník s cennými papíry jedná čestně a spravedlivě ve vztahu ke svým distribučním sítím."],"c":[0],"p":92,"e":"Jednání s odbornou péčí je stanoveno napříč finančním trhem, jeho cílem je chránit zájmy zákazníků jako slabší osoby ve vztazích s profesionálními subjekty působícími na finančním trhu.","tp":0},{"id":"20145.3","t":"s","q":"Co musí zejména učinit obchodník s cennými papíry, pokud se změní solventnost některých emitentů jež může vést ke změně výkonnosti investičního nástroje?","o":["Musí přijmout vhodná opatření např. v oblasti poskytnutí podstatných informací zákazníkovi nebo distributorovi.","Musí informovat Českou národní banku a poskytnout jí všechny potřebné informace o události.","Musí soustředit a vyhodnotit všechny informace od útvaru vykonávající průběžnou kontrolu dodržování právních povinnosti (compliance).","Musí uložit internímu auditorovi prověřit procesy schvalování a distribuce investičního nástroje."],"c":[0],"p":93,"e":"Jedná se o jednu ze situací, které by mohly ovlivnit potenciální riziko nebo očekávaný výnos investičního instrumentu a jednu ze základních povinností pro obchodníka s cennými papíry stanoveného prováděcím právním předpisem.","tp":0},{"id":"20147.1","t":"s","q":"Jaké platí omezení pro přípustnost pobídky?","o":["Pobídka nesmí vést k porušení povinnosti obchodníka s cennými papíry poskytovat investiční služby s odbornou péčí.","Pobídka nesmí být přijata jako úplata od zákazníka.","Pobídka nesmí být přijata od osoby jednající na účet zákazníka.","Omezení pro nepřípustnost pobídky nejsou stanovena, musí být dodržena pravidla pro střet zájmů."],"c":[0],"p":93,"e":"Omezení pro poskytnutí nebo přijetí pobídek je upraveno tak, aby nebyla porušena zásada jednat v co nejlepším zájmu zákazníka.","tp":6},{"id":"20148.1","t":"s","q":"Jaké jsou požadavky na způsob vedení evidence investičního zprostředkovatele?","o":["Musí být vedena v elektronickém informačním systému se zadáváním údajů neprodleně po jejich vzniku nebo získání.","Musí být vedena v listinné podobě s tím, že se údaje musí zaznamenat s časem vložení ihned po přijetí pokynu zákazníka.","Musí být vedena v elektronické podobě s povinností aktualizace údajů jednou týdně.","Musí být vedena v listinné podobě s aktualizací a kontrolou údajů ke konci každého kalendářního měsíce."],"c":[0],"p":93,"e":"Požadavek na elektronické vedení evidence investičního zprostředkovatele je konkretizován v prováděcím právním předpisu, včetně dalšího upřesnění.","tp":0},{"id":"20153.3","t":"s","q":"Zákazník se může u Finančního arbitra domáhat náhrady škody způsobené vázaným zástupcem investičního zprostředkovatele při poskytování investiční služby:","o":["Výhradně po investičním zprostředkovateli.","Výhradně po vázaném zástupci.","Po investičním zprostředkovateli nebo po vázaném zástupci dle svého uvážení.","Vždy současně po investičním zprostředkovateli i po vázaném zástupci."],"c":[0],"p":93,"e":"Za škodu způsobenou vázaným zástupcem odpovídá investiční zprostředkovatel.","tp":0},{"id":"20154.2","t":"s","q":"Podání finančnímu arbitrovi:","o":["Není spojeno s žádným poplatkem.","Podléhá fixnímu poplatku ve výši 1.000 Kč.","Podléhá poplatku ve výši 4 % z výše požadované náhrady škody.","V případě úspěchu zákazníka ve sporu je bezplatné, jinak podléhá poplatku 1.000 Kč."],"c":[0],"p":93,"e":"Řízení před finančním arbitrem se zahajuje na návrh navrhovatele. Řízení před finančním arbitrem je bezplatné. Neplatí se žádný poplatek za podání návrhu na zahájení řízení. Neplatí se žádné náklady řízení podle toho, jak spor dopadne.","tp":6},{"id":"20155.1","t":"s","q":"Domáhat se rozhodnutí o povinnosti investičního zprostředkovatele uhradit způsobenou škodu v souvislosti s kolektivním investováním může zákazník:","o":["U finančního arbitra, pokud před tím neuspěl přímo u investičního zprostředkovatele.","U České národní banky.","U Ministerstva financí.","U České obchodní inspekce."],"c":[0],"p":94,"e":"Pouze finanční arbitr (z vyjmenovaných institucí) je nadán kompetencí rozhodování o povinnosti nahradit škodu.","tp":0},{"id":"20156.2","t":"s","q":"Pokud finanční arbitr vyhoví třeba jen z části návrhu zákazníka ve sporu s investičním zprostředkovatelem, pak:","o":["Vždy uloží investičnímu zprostředkovateli sankci ve výši 10 % z částky, kterou je zprostředkovatel podle nálezu povinen zaplatit zákazníkovi, nejméně však 15 000 Kč.","Může dle svého uvážení uložit investičnímu zprostředkovateli sankci ve výši 10 % z částky, kterou je zprostředkovatel podle nálezu povinen zaplatit zákazníkovi, nejméně však 15 000 Kč.","Nesmí investičnímu zprostředkovateli uložit žádnou sankci.","Může vázanému zástupci investičního zprostředkovatele, který svým jednáním spor vyvolal, uložit sankci ve výši 10 % z částky, kterou je zprostředkovatel podle nálezu povinen zaplatit zákazníkovi, nejméně však 15 000 Kč."],"c":[0],"p":94,"e":"Sankci nelze prominout, není tedy na uvážení finančního arbitra, zda sankci uloží.. V nálezu, jímž arbitr vyhovuje, byť i jen zčásti, návrhu navrhovatele, uloží současně instituci povinnost zaplatit sankci ve výši 10 % z částky, kterou je instituce podle nálezu povinna zaplatit navrhovateli, nejméně však 15 000 Kč.","tp":0},{"id":"20157.1","t":"s","q":"Česká národní banka může na základě stížnosti zákazníka:","o":["Uložit sankci investičnímu zprostředkovateli nebo obchodníkovi s cennými papíry.","Rozhodnout o povinnosti investičního zprostředkovatele nebo obchodníka s cennými papíry nahradit zákazníkovi způsobenou škodu.","Rozhodnout o neplatnosti realizovaného obchodu.","Uložit garančnímu fondu uhradit zákazníkovi škodu, kterou mu způsobil investiční zprostředkovatel nebo obchodník s cennými papíry."],"c":[0],"p":94,"e":"ČNB nemá kompetenci řešit soukromoprávní spory ani nijak zasahovat do vztahu zákazník - poskytovatel investiční služby.","tp":0},{"id":"20158.3","t":"s","q":"Pokud investiční zprostředkovatel způsobí zákazníkovi škodu porušením zákonných povinností:","o":["Kryje škodu povinné pojištění investičního zprostředkovatele.","Kryje škodu Garanční fond obchodníků s cennými papíry.","Není tato škoda kryta žádným pojištěním.","Kryje škodu povinné pojištění investiční společnosti nebo obchodníka s cennými papíry, se kterými je investiční zprostředkovatel ve smluvním vztahu."],"c":[0],"p":94,"e":"Povinné pojištění investičního zprostředkovatele je definováno zákonem o podnikání na kapitálovém trhu, s tím, že ČNB udělí povolení k činnosti investičního zprostředkovatele na základě žádosti obchodní společnosti, pokud mimo jiné bude mít tato společnost nejpozději ke dni zahájení činnosti sjednáno povinné pojištění. Limit povinného pojištění je alespoň 13 500 000 Kč na jednu pojistnou událost.","tp":0},{"id":"20159.1","t":"s","q":"Pro případ povinnosti nahradit zákazníkovi škodu způsobenou porušením některé z povinností investičního zprostředkovatele stanovených zákonem, investiční zprostředkovatel:","o":["Musí být po celou dobu své činnosti pojištěn.","Může být pojištěn dle svého uvážení.","Nemusí být pojištěn, pokud nabízí jen nástroje kolektivního investování.","Nemusí být pojištěn, pokud nenabízí investiční službu Investiční poradenství."],"c":[0],"p":95,"e":"Investiční zprostředkovatel musí disponovat po celou dobu provádění svojí činnosti povinným pojištěním s limitem alespoň 13 500 000 Kč na každou pojistnou událost.","tp":0},{"id":"20160.1","t":"s","q":"Investiční zprostředkovatel způsobí zákazníkovi škodu porušením povinnosti uložené mu zákonem č. 256/2004 Sb. Zákazníkovi tuto škodu kryje:","o":["Povinné pojištění investičního zprostředkovatele.","Garanční fond obchodníků s cennými papíry.","Rezervní fond investičního zprostředkovatele.","Emitent cenného papíru, pro kterého investiční zprostředkovatel působí."],"c":[0],"p":95,"e":"Povinné pojištění investičního zprostředkovatele je definováno zákonem o podnikání na kapitálovém trhu, s tím, že ČNB udělí povolení k činnosti investičního zprostředkovatele na základě žádosti obchodní společnosti, pokud mimo jiné bude mít tato společnost nejpozději ke dni zahájení činnosti sjednáno povinné pojištění. Limit povinného pojištění je nejméně 13 500 000 Kč na jednu pojistnou událost.","tp":0},{"id":"20161.2","t":"s","q":"Pokud investiční zprostředkovatel neposkytne Finančnímu arbitrovi vyžádané informace v rámci řízení:","o":["Může mu Finanční arbitr uložit pořádkovou pokutu.","Finanční arbitr to oznámí České národní bance.","Finanční arbitr zastaví řízení.","Finanční arbitr to oznámí ministerstvu financí."],"c":[0],"p":95,"e":"Arbitr vyzve po podání návrhu instituci, aby se do 15 dnů k návrhu vyjádřila. V průběhu řízení je arbitr oprávněn vyžadovat od účastníků řízení předložení veškerých důkazů na podporu jejich tvrzení, a to včetně podání ústního vysvětlení. Instituce je povinna do 15 dnů na výzvu předložit arbitrovi požadované doklady a účastnit se jednání, vyhovět žádosti arbitra o poskytnutí vysvětlení a žádosti o předložení dokumentace vztahující se k předmětu sporu a umožnit arbitrovi nahlédnout do svých spisů a elektronických záznamů, které se týkají vedeného sporu. Arbitr může rozhodnutím uložit pořádkovou pokutu až do výše 100 000 Kč instituci, jestliže v řízení ztěžuje jeho postup tím, že na výzvu nepředloží arbitrovi požadované doklady a účastnit se jednání, nevyhoví žádosti arbitra o poskytnutí vysvětlení a žádosti o předložení dokumentace vztahující se k předmětu sporu či neumožní arbitrovi nahlédnout do svých spisů a elektronických záznamů, které se týkají vedeného sporu.","tp":6},{"id":"20162.1","t":"s","q":"Vázaný zástupce investičního zprostředkovatele způsobí zákazníkovi škodu porušením povinnosti uložené mu zákonem č. 256/2004 Sb. Zákazníkovi tuto škodu kryje:","o":["Povinné pojištění investičního zprostředkovatele.","Povinné pojištění vázaného zástupce investičního zprostředkovatele.","Garanční fond obchodníků s cennými papíry.","Rezervní fond vázaného zástupce."],"c":[0],"p":95,"e":"Protože je zastoupeným investičním zprostředkovatel dle § 32a odst. 3, zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, je investiční zprostředkovatel mít ze zákona uzavřené povinné pojištěné, ze kterého by se hradila škoda způsobená vázaným zástupce, do výše nejméně 13 500 000 Kč na jednu pojistnou událost (§ 31 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu).","tp":0},{"id":"20163.2","t":"s","q":"Základní parametry pojištění (tj. minimální limity pojistného plnění a maximální limity na spoluúčast) investičního zprostředkovatele pro případ povinnosti nahradit zákazníkovi škodu způsobenou porušením některé z povinností investičního zprostředkovatele stanovených zákonem:","o":["Jsou dány zákonem o podnikání na kapitálovém trhu.","Určuje investiční zprostředkovatel dle svého uvážení.","Určuje Česká národní banka svojí vyhláškou.","Určuje ministerstvo financí svojí vyhláškou."],"c":[0],"p":96,"e":"Základní parametry povinného pojištění investičního zprostředkovatele jsou nastaveny přímo zákonem.","tp":0},{"id":"20164.1","t":"s","q":"O námitkách proti nálezu finančního arbitra rozhoduje:","o":["Finanční arbitr.","Soud.","Česká národní banka.","Ministerstvo financí."],"c":[0],"p":96,"e":"Arbitr rozhoduje ve věci samé bez zbytečného odkladu nálezem. Písemné vyhotovení nálezu se doručuje účastníkům řízení bez zbytečného odkladu do vlastních rukou. Nález obsahuje výrok, odůvodnění a poučení o námitkách. Do 15 dnů ode dne doručení písemného vyhotovení nálezu nebo usnesení mohou účastníci řízení podat proti nálezu nebo usnesení odůvodněné námitky. Arbitr rozhodnutím o námitkách nález potvrdí nebo změní, nebo usnesení potvrdí, změní nebo zruší. Rozhodnutí o námitkách je konečné.","tp":6},{"id":"20168.1","t":"s","q":"Výše náhrady z Garančního fondu obchodníků s cennými papíry:","o":["Je omezena na 90 % aktuálního závazku, nejvýše se však vyplatí částka v korunách českých odpovídající 20 000 EUR pro jednoho zákazníka u jednoho obchodníka s cennými papíry.","Je omezena na 90 % aktuálního závazku, horní hranice vyplácené částky není omezena.","Činí 100 % aktuálního závazku, nejvýše se však vyplatí částka v korunách českých odpovídající 20 000 EUR pro jednoho zákazníka u jednoho obchodníka s cennými papíry.","Není nijak omezena."],"c":[0],"p":96,"e":"Výše náhrady je 90 % vypočteného nároku, je to rozdíl např. oproti pojištění vklad u bank.","tp":0},{"id":"20169.1","t":"s","q":"Tržní ztrátu, tedy rozdíl nákupní a prodejní ceny cenných papírů v majetku zákazníka:","o":["Nese vždy zákazník, není zajištěna žádným garančním systémem.","Vyplatí zákazníkovi Garanční fond obchodníků s cennými papíry v plné výši.","Vyplatí zákazníkovi Garanční fond obchodníků s cennými papíry do výše 90 % prokázané ztráty.","Nese obchodník s cennými papíry."],"c":[0],"p":96,"e":"Garanční fond obchodníků s cennými papíry nehradí tržní ztrátu investice zákazníka.","tp":0},{"id":"20170.1","t":"s","q":"Investice do standardního fondu realizovaná přímým nákupem podílových listů od investiční společnosti:","o":["Není kryta Garančním fondem obchodníků s cennými papíry.","Je kryta Garančním fondem obchodníků s cennými papíry do výše 90 % aktuálního nároku.","Je kryta Garančním fondem obchodníků s cennými papíry do výše 100 % aktuálního nároku.","Je pojištěna povinným pojištěním správce fondu."],"c":[0],"p":96,"e":"Pokud podílové listy nejsou zahrnuty do majetku obhospodařovaného obchodníkem s cennými papíry, pak se na ně krytí Garančního fondu obchodníků s cennými papíry nevztahuje.","tp":1},{"id":"20171.2","t":"s","q":"Garanční fond obchodníků s cennými papíry:","o":["Nekryje investice do standardních podílových fondů, pokud nejsou součástí majetku zákazníka obhospodařovaného OCP.","Kryje i investice do standardních podílových fondů i pokud nejsou součástí majetku zákazníka obhospodařovaného OCP.","Kryje veškeré investice na kapitálovém trhu.","Nekryje investice do státních dluhopisů realizované prostřednictvím obchodníka s cennými papíry."],"c":[0],"p":97,"e":"Garanční fond kryje pouze neschopnost obchodníků s cennými papíry dostát svým závazkům. Pokud zákazník nevyužívá v souvislosti s investicí do podílových fondů služeb obchodníka s cennými papíry, není investice kryta Garančním fondem obchodníků s cennými papíry.","tp":1},{"id":"20172.3","t":"s","q":"Příspěvek do Garančního fondu obchodníků s cennými papíry:","o":["Platí obchodník s cennými papíry z objemu výnosů z poplatků a provizí za poskytnuté investiční služby za poslední kalendářní rok","Platí zákazník z objemu uskutečněných investic za poslední kalendářní rok.","Platí burza cenných papírů z objemu realizovaných obchodů za poslední kalendářní rok.","Platí obchodník s cennými papíry z celkového objemu majetku zákazníků za poslední kalendářní rok."],"c":[0],"p":97,"e":"Obchodník s cennými papíry odvádí do Garančního fondu 2 % z objemu z poplatků a provizí za poskytnuté investiční služby, nejméně však 10 000 Kč.","tp":0},{"id":"20173.2","t":"s","q":"Náhrada z Garančního fondu musí být vyplacena:","o":["Do 3 měsíců ode dne ověření přihlášeného nároku a vypočtení výše náhrady.","Do 6 měsíců ode dne ověření přihlášeného nároku a vypočtení výše náhrady.","Do 12 měsíců ode dne ověření přihlášeného nároku a vypočtení výše náhrady.","Lhůta pro výplatu není zákonem stanovena."],"c":[0],"p":97,"e":"Garanční fond obchodníků s cennými papíry poskytuje náhradu ve výši 90 % klientovi pohledávky, maximálně však do výše 20 000 EUR, s tím, že náhrada musí být ze zákona vyplacena do 3 měsíců ode dne ověření přihlášeného nároku a vypočtení výše náhrady.","tp":1},{"id":"20174.2","t":"s","q":"Zákazník - fyzická osoba má za obchodníkem s cennými papíry, který není schopen dostát svým závazkům, pohledávku ve výši 100 000 Kč. Kolik mu vyplatí Garanční fond obchodníků s cennými papíry?","o":["90 000 Kč.","100 000 Kč.","85 000 Kč.","0 Kč."],"c":[0],"p":97,"e":"V případě, že obchodník s cennými papíry není schopen dluhy a závazky vůči svým zákazníkům, vyplácí náhrady Garanční fond obchodníků s cennými papíry, který vyplácí částku odpovídající 90 % pohledávky klienta, maximálně však částku odpovídající 20 000 EUR pro jednoho zákazníka u jednoho obchodníka s cennými papíry.","tp":0},{"id":"20175.1","t":"s","q":"Zákazník - obec má za obchodníkem s cennými papíry, který není schopen dostát svým závazkům, pohledávku ve výši 1 000 000,- Kč. Kolik obci vyplatí Garanční fond obchodníků s cennými papíry?","o":["900 000 Kč.","1 000 000 Kč.","850 000 Kč.","0 Kč."],"c":[3],"p":98,"e":"Obec patří mezi subjekty, kterým se ze zákona náhrada neposkytuje. Na náhradu z Garančního fondu nemá nárok (mimo jiné) Česká konsolidační agentura, územní samosprávný celek.","tp":0},{"id":"20176.1","t":"s","q":"Investiční zprostředkovatel do Garančního fondu obchodníků s cennými papíry:","o":["Neplatí za žádných okolností.","Platí pouze v případě, kdy spolupracuje s jedním nebo více obchodníky s cennými papíry.","Platí pouze v případě, když poskytuje hlavní investiční službu investiční poradenství.","Platí pouze v případě, když není pojištěn pro případ škody způsobené zákazníkům."],"c":[0],"p":98,"e":"Do Garančního fondu hradí příspěvky pouze obchodník s cennými papíry, nikoli investiční zprostředkovatel.","tp":0},{"id":"20177.2","t":"s","q":"Příspěvky do Garančního fondu obchodníků s cennými papíry:","o":["Jsou ze zákona povinné.","Jsou dobrovolné.","Jsou ze zákona povinné až od určitého objemu realizovaných obchodů.","Jsou ze zákona povinné až od určitého počtu zákazníků."],"c":[0],"p":98,"e":"Každý obchodník s cennými papíry je povinen hradit ročně do Garančního fondu roční příspěvek ve výši 2 % z objemu výnosů z poplatků a provizí, nejméně však 10 000 Kč ročně.","tp":0},{"id":"20178.3","t":"s","q":"Výši příspěvků do Garančního fondu obchodníků s cennými papíry:","o":["Stanoví zákon.","Stanoví Garanční fond obchodníků s cennými papíry.","Stanoví Česká národní banka.","Stanoví ministerstvo financí."],"c":[0],"p":98,"e":"Roční výši příspěvku obchodníka s cennými papíry 2 % z objemu výnosů z poplatků a provizí (min. však 10 000 Kč) do Garančního fondu definuje § 129 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu a je povinný.","tp":0},{"id":"20179.2","t":"s","q":"Kontrolu správné výše placení příspěvků do Garančního fondu obchodníků s cennými papíry provádí vždy jednou ročně:","o":["Česká národní banka.","Ministerstvo financí.","Každý plátce příspěvku.","Garanční fond obchodníků s cennými papíry."],"c":[0],"p":98,"e":"Garanční fond obchodníků s cennými papíry informuje neprodleně po uplynutí lhůty pro úhradu příspěvků obchodníky s cennými papíry ČNB o výši jejich příspěvků, které jednotliví obchodníci s cennými papíry zaplatili Garančnímu fondu za příslušný kalendářní rok, kdy příspěvky obchodníků jsou splatné do 31. 3. ČNB porovná výši skutečně zaplacených příspěvků s objemem výnosů z poplatků a provizí za poskytnuté investiční služby za poslední rok zjištěným na základě údajů ověřených auditorem obdržených od obchodníka s cennými papíry.","tp":0},{"id":"20184.2","t":"s","q":"Investiční strategie buy and hold znamená:","o":["V době poklesu cen aktiv investor kupuje, při růstu cen aktiva prodává.","V době koupě aktiva již má investor uzavřenu smlouvu o budoucím prodeji.","Investor nakupuje aktivum k dlouhodobému držení.","Jde o jednu ze spekulativních strategií."],"c":[2],"p":99,"e":"Strategie buy and hold znamená, že investor aktivum koupí a dlouhodobě drží. Nespekuluje na budoucí vývoj, v době koupě aktiva nemá ani uzavřenou smlouvu o budoucím prodeji.","tp":7},{"id":"20185.1","t":"s","q":"Růstová investiční strategie (growth strategy) je zaměřena na:","o":["Vyhledávání podhodnocených akcií proti jejich vnitřní hodnotě (fair value).","Vyhledávání nadhodnocených akcií proti jejich vnitřní hodnotě (fair value).","Vyhledávání akcií s vysokým ukazatelem P/E (vyšším než 35).","Vyhledávání akcií s vysokým potenciálem růstu v dalších letech vzhledem například k růstu ostatních akcií ve stejném odvětví."],"c":[3],"p":99,"e":"Růstová strategie vyhledává akcie (aktiva), která mají dle názoru analytika vysoký potenciál růstu v dalších letech vzhledem například k růstu ostatních akcií ve stejném odvětví.","tp":4},{"id":"20186.1","t":"s","q":"Pro investiční horizont 20 let je obvykle nejvhodnější využít:","o":["Akciový fond.","Dluhopisový fond.","Fond peněžního trhu.","Stavební spoření se státním příspěvkem."],"c":[0],"p":99,"e":"Pro dlouhodobý investiční horizont jsou obvykle nejvhodnější akciové fondy. Stavební spoření je nejvýhodnější pro dobu 6 let, dluhopisové fondy a fondy peněžního trhu na dobu ještě kratší.","tp":1},{"id":"20187.2","t":"s","q":"Pro dosažení dlouhodobých cílů klienta je nejdůležitější:","o":["Výběr dlouhodobě nejvýnosnějších podílových fondů.","Správné načasování nákupů a prodejů.","Správná alokace aktiv.","Využití strategie dollar-cost averaging (průměrování nákladů)."],"c":[2],"p":99,"e":"Pro dlouhodobé investování je nejdůležitější správná alokace mezi jednotlivé třídy aktiv.","tp":7},{"id":"20188.3","t":"s","q":"Pro spíše kratší investiční horizont (3 roky) je pro konzervativního klienta vhodné využít:","o":["Akciový fond.","Dluhopisový fond.","Běžný účet","Stavební spoření se státním příspěvkem."],"c":[1],"p":99,"e":"Pro krátkodobější horizont 3 roky jsou vhodné dluhopisové investice. Akciové investice jsou pro investice na 3 roky příliš volatilní (a proto nevhodné), běžný účet nelze považovat za investici. Stavební spoření je vhodné pro investici s časovým horizontem 6 a více let kvůli přiznání státního příspěvku.","tp":7},{"id":"20189.2","t":"s","q":"Pro investiční horizont 5 let je obvykle pro konzervativního klienta nejvhodnější využít:","o":["Akciový fond.","Nově založené stavební spoření se státním příspěvkem.","Dluhopisový fond.","Běžný účet."],"c":[2],"p":100,"e":"Pro horizont 5 let je nejvhodnější dluhopisový fond. Na 5 let bychom již mohli malou část investovat do akciových fondů (ale nejsou \"nejvhodnější\"), běžný účet nelze považovat za investici. Stavební spoření je vhodné pro investici s časovým horizontem 6 a více let kvůli přiznání státního příspěvku.","tp":7},{"id":"20190.1","t":"s","q":"Hodnotová strategie (value) fondů je zaměřena na:","o":["Vyhledávání podhodnocených akcií proti jejich vnitřní hodnotě (fair value).","Vyhledávání nadhodnocených akcií proti jejich vnitřní hodnotě (fair value).","Vyhledávání akcií s rostoucím ukazatelem P/E.","Vyhledávání akcií s vysokým potenciálem růstu v dalších letech."],"c":[0],"p":100,"e":"Hodnotová strategie je zaměřená na vyhledávání podhodnocených akcií vůči jejich vnitřní hodnotě, většinou jde o akcie s nízkým P/E. Akcie s vysokým P/E kupuje jen investor toužící po ztrátě. Vysoký potenciál růstu ocení strategie růstová.","tp":4},{"id":"20191.1","t":"s","q":"Pro financování vzdělání dítěte za 15 let je obvykle nejvhodnější využít:","o":["Akciový fond.","Dluhopisový fond.","Fond peněžního trhu.","Nově založené stavební spoření se státním příspěvkem."],"c":[0],"p":100,"e":"Pro investici na 15 let je obvykle nejvhodnější akciový fond. Dluhopisový fond a fond PT jsou nejvhodnější pro kratší investiční horizonty. Stavební spoření se st. příspěvkem má na 15 let velmi nízkou výnosnost.","tp":1},{"id":"20192.1","t":"s","q":"P/E akciového trhu je 40. Ve svém portfoliu bychom měli:","o":["Změnit taktickou alokaci a akcie podvážit.","Změnit taktickou alokaci a akcie převážit.","Změnit strategickou alokaci a akcie podvážit.","Změnit strategickou alokaci a akcie převážit."],"c":[0],"p":100,"e":"P/E 40 znamená, že akcie jsou nadhodnocené. Proto bychom je měli takticky podvážit (= snížit jejich podíl v portfoliu). Strategická alokace se určuje na základě časového horizontu cílů a rizikového profilu investora.","tp":7},{"id":"20193.1","t":"s","q":"Investor uplatňující globální investiční strategii bude mít nejvyšší podíl akciové složky portfolia v akciích:","o":["České republiky (bez měnového rizika).","Zemí V4.","USA.","Nejlidnatějších rozvíjejících se zemích světa (Čína, Indie atd.)."],"c":[2],"p":100,"e":"Globální investiční strategie musí ctít podíl tržní kapitalizace aktiv ve světě. Největší podíl (přes 50 %) má akciový trh v USA.","tp":7},{"id":"20194.1","t":"s","q":"Výhodou akciových ETF proti akciovým podílovým fondům je:","o":["Stabilně překonávaný benchmark.","Nižší TER (ongoing charge).","Nižší volatilita.","Nižší kreditní riziko."],"c":[1],"p":101,"e":"ETF mají nižší nákladovost (TER neboli ongoing charge). ETF stabilně nepřekonávají benchmark, indexové ETF se ho snaží držet. Volatilitu mají podobnou jako akciové fondy, kreditní riziko je také podobné, ne-li vyšší (ve srovnání s OPF).","tp":1},{"id":"20195.1","t":"s","q":"P/E akciového trhu je 8. Tento ukazatel naznačuje, že ve svém portfoliu bychom měli:","o":["Změnit taktickou alokaci a akcie podvážit.","Změnit taktickou alokaci a akcie převážit.","Změnit strategickou alokaci a akcie podvážit.","Změnit strategickou alokaci a akcie převážit."],"c":[1],"p":101,"e":"P/E 8 znamená, že akcie jsou podhodnocené. Proto bychom je měli takticky převážit (= zvýšit jejich podíl v portfoliu). Strategická alokace se určuje na základě časového horizontu cílů a rizikového profilu investora.","tp":7},{"id":"20196.1","t":"s","q":"Pro investiční horizont 30 let je obvykle nejvhodnější využít:","o":["Globální akciový fond.","Dluhopisový fond investující do českých státních dluhopisů.","Investiční životní pojištění.","Kapitálové životní pojištění."],"c":[0],"p":101,"e":"Pro dlouhodobý investiční horizont jsou obvykle nejvhodnější akciové fondy. Dluhopisové fondy mají dlouhodobě nižší výnosy a inflační riziko. Investiční a kapitálové životní pojištění je nevhodné pro vysokou nákladovost.","tp":7},{"id":"20197.1","t":"s","q":"Akciový trh poklesl o 30 % a váš klient se obává dalšího vývoje. Doporučíte mu:","o":["Prodat všechny akciové fondy a počkat na další pokles, poté nakoupit za nižší ceny.","Prodat část akciových fondů a počkat na další pokles, poté nakoupit za nižší ceny.","Řídit se strategií buy and hold.","Řídit se strategií sell and go away."],"c":[2],"p":101,"e":"Při výrazném poklesu trhu by investoři měli pokračovat v pravidelných investicích a podílové listy držet (buy and hold). Investoři často dělají chybu, že při hlubokých poklesech podílové listy prodávají (částečně nebo úplně). Strategii sell and go away jsem si vymyslel, inspirován heslem \"Sell in May and go away\".","tp":1},{"id":"20198.1","t":"s","q":"Která odpověď nejlépe charakterizuje strategii investování podle zpětného zrcátka:","o":["Kupovat aktiva s nadprůměrnými výnosy v uplynulých letech.","Kupovat aktiva, která v uplynulých letech dosahovala podprůměrné výnosy (a jsou proto pravděpodobně podhodnocená).","Jde o strategii, která v minulosti vždy vedla k nadprůměrným výsledkům.","Koncentrovat investice do 1 aktiva, po dosažení investičního cíle aktivum prodat."],"c":[0],"p":101,"e":"Investování podle zpětného zrcátka je jednou z častých chyb investorů. Charakterizuje ji koupě aktiv, která v uplynulých letech zaznamenala nadprůměrné výnosy a tím se o ni začali investoři zajímat.","tp":7},{"id":"20199.1","t":"s","q":"Strategická alokace portfolia znamená:","o":["Výběr konkrétních podílových fondů pro dlouhodobý investiční horizont.","Stanovení podílu aktiv na základě investičního horizontu cílů a rizikového profilu investora.","Analýza konkrétních investičních příležitostí.","Přizpůsobování podílu aktiv na základě aktuální situace na trzích."],"c":[1],"p":102,"e":"Strategická alokace vychází z cílů a rizikového profilu investora (klienta). Na základě strategické alokace dochází k výběru konkrétních investičních nástrojů (podílových fondů). Přizpůsobování podílu aktiv aktuální situaci je předmětem taktické alokace.","tp":7},{"id":"20222.2","t":"s","q":"Důvodem pro diverzifikaci portfolia je obvykle:","o":["Zvýšení výnosu portfolia.","Zvýšení rizika portfolia.","Snížení výnosu portfolia.","Snížení rizika portfolia."],"c":[3],"p":102,"e":"Důvodem, proč diverzifikujeme portfolio, je snížení rizika portfolia. Výnos se může snížit nebo zvýšit v závislosti na konkrétním aktivu, které do portfolia přidáváme.","tp":7},{"id":"20223.1","t":"s","q":"Největším rizikem investic do akciových podílových fondů je:","o":["Riziko kreditní.","Riziko volatility.","Riziko měnové.","Riziko inflace."],"c":[1],"p":102,"e":"Největším rizikem investic do akciových fondů je kolísání. Kreditní riziko ve fondu je nižší než při koupi jedné akcie. Riziko měnové ovlivňuje volatilitu, ale je možné ho zajistit. Inflační riziko jsou akcie většinou schopné pokrýt.","tp":1},{"id":"20224.1","t":"s","q":"S rostoucím investičním horizontem:","o":["Průměrný výnos investic do podílových fondů roste.","Roste pravděpodobnost ztráty investic do podílových fondů.","Průměrný výnos investic do podílových fondů klesá.","Klesá pravděpodobnost ztráty investic do podílových fondů."],"c":[3],"p":102,"e":"Čím déle investujeme, tím klesá pravděpodobnost ztráty investice do podílových fondů. Ztrátové roky jsou kompenzovány roky ziskovými. Průměrný výnos se s rostoucím časovým horizontem nemění.","tp":1},{"id":"20225.1","t":"s","q":"Směrodatná odchylka fondu je 17 % p. a. Pravděpodobně se jedná o:","o":["Akciový fond.","Dluhopisový fond státních dluhopisů.","Fond peněžního trhu.","Smíšený (balancovaný) fond."],"c":[0],"p":102,"e":"Směrodatná odchylka 17 % je vysoká, odpovídá akciovým fondům.","tp":1},{"id":"20226.1","t":"s","q":"Fond má Syntetický ukazatel rizika a výnosu (SRRI) ve výši 2. Jde pravděpodobně o fond:","o":["Akciový fond.","Dluhopisový fond korporátních dluhopisů.","Fond peněžního trhu.","Smíšený (balancovaný) fond."],"c":[2],"p":103,"e":"Ukazatel SRRI nabývá hodnoty od 1 (velmi konzervativní fondy peněžního trhu) do 7 (akciové fondy exotičtějších trhů nebo sektorů). SRRI 2 tak odpovídá fondům peněžního trhu.","tp":1},{"id":"20227.1","t":"s","q":"Fond má Syntetický ukazatel rizika a výnosu (SRRI) ve výši 6. Jde pravděpodobně o fond:","o":["Akciový fond.","Dluhopisový fond.","Fond peněžního trhu.","Smíšený (balancovaný) fond."],"c":[0],"p":103,"e":"Ukazatel SRRI nabývá hodnoty od 1 (velmi konzervativní fondy peněžního trhu) do 7 (akciové fondy exotičtějších trhů nebo sektorů). SRRI 6 tak odpovídá standardním akciovým fondům.","tp":1},{"id":"20228.1","t":"s","q":"Směrodatná odchylka fondu je 1 % p. a. Pravděpodobně se jedná o:","o":["Akciový fond.","Dluhopisový fond.","Fond peněžního trhu.","Smíšený (balancovaný) fond."],"c":[2],"p":103,"e":"Směrodatná odchylka (volatilita) 1 % je nízká, odpovídá krátkodobým fondům = fondům peněžního trhu. Nižší riziko mají velmi konzervativní fondy peněžního trhu, vyšší riziko (nad 2 %) konzervativní dluhopisové fondy.","tp":1},{"id":"20229.1","t":"s","q":"Směrodatná odchylka fondu je 3,5 % p. a. Pravděpodobně se jedná o:","o":["Akciový fond.","Dluhopisový fond státních dluhopisů.","Fond peněžního trhu.","Smíšený (balancovaný) fond."],"c":[1],"p":103,"e":"Směrodatná odchylka dluhopisových fondů bývá v rozmezí od 2 do 10 %.","tp":1},{"id":"20230.1","t":"s","q":"Riziko portfolia se nesníží, když kombinujeme investice:","o":["Se zápornou korelací.","S nulovou korelací.","S korelací 1.","S korelací vyšší než 1."],"c":[2],"p":103,"e":"Pro snížení rizika portfolia je nejlepší vybírat aktiva se zápornou korelací. Nekorelovaná aktiva i aktiva s nízkou kladnou korelací také snižují riziko. Riziko nesníží aktiva s korelací 1. Korelace vyšší než 1 neexistuje (proto nejde o správnou odpověď).","tp":7},{"id":"20231.1","t":"s","q":"Vhodnou diverzifikací snížíme riziko:","o":["Tržní riziko.","Systematické riziko.","Jedinečné riziko.","Žádné riziko diverzifikace nesnižuje."],"c":[2],"p":104,"e":"Vhodná diverzifikace snižuje jedinečné riziko. Tržní riziko = systematické riziko nelze snížit.","tp":7},{"id":"20232.1","t":"s","q":"Který z uvedených akciových fondů v době ekonomické krize pravděpodobně poklesne nejméně?","o":["Zaměřený na země BRICS.","Globální fond s ukazatelem ß > 1.","S benchmarkem Eurostoxx 50.","S benchmarkem MSCI World."],"c":[3],"p":104,"e":"Z důvodu maximální diverzifikace pravděpodobně nejméně poklesne globální fond (benchmark MSCI World). Země BRICS reprezentují emerging markets, Eurostoxx 50 evropský trh. Ukazatel beta větší než 1 znamená, že fond roste a klesá rychleji než benchmark.","tp":1},{"id":"20233.2","t":"s","q":"Globální indexový fond bude mít pravděpodobně ukazatel ß:","o":["Větší než 1.","Blížící se 1.","Blížící se 0.","Záporný."],"c":[1],"p":104,"e":"Globální indexový fond má ukazatel beta velmi blízko 1. Indexový fond se snaží kopírovat index, proto jeho beta bude blízká 1. Čím více je zvolené portfolio tržní, tím více se jeho systematické riziko blíží betě trhu, tzn. jedné.","tp":4},{"id":"20235.3","t":"s","q":"Největším rizikem dlouhodobých investic do českých dluhopisových podílových fondů (investujících především do státních dluhopisů) je:","o":["Riziko kreditní.","Riziko volatility.","Riziko měnové.","Riziko inflace."],"c":[3],"p":104,"e":"Největším rizikem investic do dluhopisových fondů je inflace. Kreditní riziko ve fondu je nižší než při koupi jednoho dluhopisu. Riziko měnové u fondu investujícího do českých dluhopisů není. Volatilita v dlouhodobém horizontu nehraje podstatnou roli, mnohem vyšším rizikem je postupné znehodnocení investice dlouhodobou inflací.","tp":3},{"id":"20236.1","t":"s","q":"Pro dlouhodobého investora (s investičním horizontem 30 let) do akciových fondů je důležité využívat fondy, které měnové riziko:","o":["Zajišťují v plném rozsahu, snižují tak riziko.","Zajišťují proti devalvaci domácí měny.","Zajišťují proti oslabení měnového kurzu.","Nezajišťují, ušetří na poplatcích za zajištění měnového rizika."],"c":[3],"p":104,"e":"Pro investory s dlouhými časovými horizonty není zajištění měnového rizika na zahraničních akciových trzích důležité. V dlouhém období může měnové zajištění dokonce zvýšit volatilitu výnosů.","tp":1},{"id":"20259.1","t":"s","q":"Jak lze v důchodovém systému charakterizovat transformovaný fond?","o":["Transformovaný fond je součástí třetího pilíře důchodového systému a vznikl transformací penzijního fondu, který fungoval do konce roku 2012.","Představuje finanční prostředky sloužící k investování do velmi rychle rostoucích inovativních projektů - do transformace malých a středních firem.","Je jedním ze tří strukturálních fondů Evropské unie a jeho cílem je ochrana před diskriminací a nerovnostmi.","Manažer fondu nepřihlédne k době účasti na důchodovém spoření a výše důchodu se transformuje."],"c":[0],"p":105,"e":"Charakteristika vyplývá ze zákona o doplňkovém penzijním spoření, tedy ze zákona 427/2011 Sb., o doplňkovém penzijním spoření, zejména § 171-§196), který stanoví nároky účastníků v transformovaném fondu.","tp":1},{"id":"20260.2","t":"s","q":"Uvádí zákon případy, nebo situace, kdy celkový limit výplaty z Garančního systému finančního trhu může být ve výši až 200 000 EUR?","o":["Ano, pokud jde např. o vklady plynoucí z dědictví, ale k vkladu musí dojít během tří měsíců před rozhodným dnem.","Ano, pokud jde o pohledávky ze směnek a jiných cenných papírů, včetně podílových listů otevřených podílových fondů.","V případě, že celková suma náhrady činí nejvýše 90 % nevydaného zákaznického majetku.","Zákon vyšší úhradu v žádném případě nepřipouští."],"c":[0],"p":105,"e":"Pro drobné investory je podstatné, aby jejich vklady v bankách byly pojištěné. V situaci, kdy si uvědomí, že pojištěná část vkladů je menší, než celková hodnota vkladu v bance, je to motiv pro investování.","tp":2},{"id":"20261.2","t":"s","q":"Pokud účastník splňoval všechny podmínky stanovené zákonem o doplňkovém penzijním spoření a zaplatil měsíční příspěvek ve výši 300 Kč, náleží mu měsíčně státní příspěvek ve výši:","o":["0 Kč.","90 Kč.","180 Kč.","340 Kč."],"c":[0],"p":105,"e":"Výše příspěvku je definována zákonem č. 427/2011 Sb., o doplňkovém penzijním spoření, v §14. Je-li výše měsíčního příspěvku účastníka 500 až 1699 Kč, činí výše měsíčního státního příspěvku 20 % z částky měsíčního příspěvku účastníka; je-li výše příspěvku účastníka 1700 Kč a více, činí výše státního příspěvku 340 Kč.","tp":8},{"id":"20262.1","t":"s","q":"Doplňkové penzijní spoření má zákonem stanovené některé specifické vlastnosti:","o":["V současnosti se lze (jako nový zájemce) přihlásit do takzvaných transformovaných fondů a následně v nich spořit.","Noví zájemci mohou vstupovat jen do takzvaných účastnických fondů.","O platbu do fondu ve výši 3 % se snižuje odvod do státního důchodu (tzv. prvního pilíře).","Platby účastníka do fondu nejsou v žádném případě spojeny se státním příspěvkem."],"c":[1],"p":105,"e":"Většina účastníků třetího pilíře zůstává v transformovaných fondech penzijního připojištění (noví nepřibývají, fondy jsou od prosince 2012 uzamčené).","tp":1},{"id":"20264.2","t":"s","q":"Jak jsou shromažďovány zdroje Garančního fondu obchodníků s cennými papíry?","o":["Investor se může pojistit proti svým ztrátám při obchodování placením ročního příspěvku do garančního fondu ve výši 3 % ze svého majetku.","Každý z obchodníků s cennými papíry platí roční příspěvek ve výši 2 % z objemu výnosů z poplatků a provizí za poskytnuté investiční služby za poslední rok, nejméně 10 000 Kč.","Garanční fond získává prostředky ze státního rozpočtu prostřednictvím zvláštního účtu Ministerstva financí ČR.","Garanční fond získává prostředky ze státního rozpočtu prostřednictvím zvláštního účtu Ministerstva průmyslu a obchodu ČR.."],"c":[1],"p":106,"e":"Placení příspěvků do Fondu kontroluje ČNB. Porovná výši skutečně zaplacených příspěvků s objemem výnosů z poplatků a provizí za poskytnuté investiční služby za poslední rok zjištěným na základě údajů ověřených auditorem obdržených od obchodníků s cennými papíry.","tp":0},{"id":"20265.1","t":"s","q":"V čem může spočívat další podnikatelská činnost organizátora regulovaného trhu?","o":["Především v činnostech nesouvisejících s operacemi na finančních trzích.","Například v činnosti komoditní burzy.","V jakékoliv činnosti, ke které se nemusí vyjadřovat regulátor.","Může podnikat v čemkoliv, nesmí se ale věnovat správě vlastního majetku."],"c":[1],"p":106,"e":"Vyplývá ze znění zákona.","tp":0},{"id":"20266.2","t":"s","q":"Může penzijní fond nakupovat movité a nemovité věci?","o":["Ano, ale celková hodnota movitých a nemovitých věcí nesmí tvořit více než 5 % majetku penzijního fondu.","Ano, ale celková hodnota movitých a nemovitých věcí nesmí tvořit více než 50 % majetku penzijního fondu.","Ano, ale celková hodnota movitých a nemovitých věcí nesmí tvořit více než 75 % majetku penzijního fondu.","Ano, ale celková hodnota movitých a nemovitých věcí nesmí tvořit více než 10 % majetku penzijního fondu."],"c":[3],"p":106,"e":"Vyplývá ze znění zákona.","tp":1},{"id":"20267.2","t":"s","q":"Může organizátor regulovaného trhu zrušit obchod uzavřený podle pravidel tohoto trhu?","o":["Může v případě, když jedna ze stran obchodu prokáže nefunkčnost technologie používané k obchodování.","Může, například z důvodu omylu v pokynu při uzavření obchodu.","Může v případě, když jedna ze stran obchodu prokáže omyl v pokynu při zadávání pokynu.","Organizátor regulovaného trhu nemůže obchod zrušit."],"c":[3],"p":106,"e":"Vyplývá ze znění zákona.","tp":0},{"id":"20268.1","t":"s","q":"Může být cenný papír vydaný fondem kolektivního investování, který není přijatý k obchodování na evropském regulovaném trhu za účelem uveřejňování jeho hodnoty, registrován na regulovaném trhu?","o":["Ano, podmínky pro registraci cenného papíru vydaného fondem kolektivního investování a způsob stanovení jeho hodnoty stanoví organizátor regulovaného trhu.","Ne registrace by odporovala zásadám EU pro operace s cennými papíry.","Jen v případě, že Banka pro mezinárodní platby udělí s registrací souhlas.","Možnost registrace závisí na rozhodnutí Evropské komise"],"c":[0],"p":106,"e":"Vyplývá ze znění zákona.","tp":0},{"id":"20269.1","t":"s","q":"Lze vyřadit cenný papír z obchodování na regulovaném trhu?","o":["Z obchodování na regulovaném trhu nelze cenný papír vyřadit v žádném případě.","V podmínkách právního řádu v ČR nelze a není to obvyklé ani v zahraničí.","Lze, pokud emitent svůj záměr oznámí ČNB a zveřejní tuto informaci na svém webu.","V podmínkách právního řádu v ČR nelze, ale v zahraničí je to obvyklé."],"c":[2],"p":107,"e":"Vyplývá ze znění zákona.","tp":0},{"id":"20270.1","t":"s","q":"Povinnost zachovávat mlčenlivost o informaci, která může mít význam pro posouzení vývoje na kapitálovém trhu nebo může významně poškodit osobu využívající služby poskytované na kapitálovém trhu, a která nebyla uveřejněna platí pro osoby charakterizované v zákoně:","o":["Trvá i po ukončení jejich činnosti po dobu pěti let.","Trvá i po ukončení jejich činnosti po dobu šesti měsíců.","Trvá i po ukončení jejich činnosti po dobu jednoho roku.","Trvá i po ukončení jejich činnosti."],"c":[3],"p":107,"e":"Vyplývá ze znění zákona.","tp":2},{"id":"20349.5","t":"s","q":"Investiční služby dělíme na hlavní a doplňkové. Mezi hlavní služby mino jiné patří:","o":["Přijímání a předávání pokynů týkajících se investičních nástrojů.","Úschova a správa investičních nástrojů pro zákazníka, včetně opatrování a souvisejících služeb, s výjimkou vedení účtů centrálním depozitářem nebo zahraničním centrálním depozitářem.","Poradenská činnost týkající se struktury kapitálu, průmyslové strategie a s tím souvisejících otázek, jakož i poskytování porad a služeb týkajících se přeměn společností, převodů obchodních závodů nebo nabytí účasti v obchodní korporaci.","Devizové služby související s poskytováním investičních služeb."],"c":[0],"p":107,"e":"Podrobné členění investičních služeb uvádí § 4. Zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"20351.2","t":"s","q":"V emisi je 1 000 ks akcií, je veřejně obchodovatelná. Jmenovitá hodnota akcie = 1 000 Kč, emisní kurz = 1 100 Kč, kurz akcie = 1 500 Kč. Z těchto hodnot lze určit, že:","o":["Základní kapitál při vydání emise byl 1 000 000 Kč.","Základní kapitál při vydání emise byl 1 100 000 Kč.","Základní kapitál při vydání emise byl 1 200 000 Kč.","Základní kapitál při vydání emise byl 1 500 000 Kč."],"c":[0],"p":107,"e":"Základní kapitál je součinem počtu akcií a jmenovité hodnoty akcie.","tp":4},{"id":"20352.1","t":"s","q":"V emisi je 1 000 ks akcií, je veřejně obchodovatelná. Jmenovitá hodnota akcie = 1 000 Kč, emisní kurz = 1 100 Kč, kurz akcie = 1 500 Kč. Z těchto hodnot lze určit, že:","o":["Po štěpení emise 2 : 1 bude v emisi 2 000 ks akcií se jmenovitou hodnotou 500 Kč.","Po štěpení emise 2 : 1 bude v emisi 2000 ks akcií se jmenovitou hodnotou 1 000 Kč.","Po štěpení emise 2 : 1 bude v emisi 2000 ks akcií se jmenovitou hodnotou 750 Kč.","Po štěpení emise 2 : 1 bude v emisi 2000 ks akcií se jmenovitou hodnotou 550 Kč."],"c":[0],"p":107,"e":"Zvýším-li počet akcií dvakrát, měla by se pouze dvakrát snížit jejich jmenovitá hodnota.","tp":4},{"id":"20353.2","t":"s","q":"V emisi je 1 000 ks akcií. Celá emise je veřejně obchodovatelná. Jmenovitá hodnota jedné akcie = 1 000 Kč, emisní kurz = 1 100 Kč, aktuální kurz akcie = 1 500 Kč. Z těchto hodnot lze určit, že:","o":["Tržní kapitalizace = 1 500 000 Kč.","Tržní kapitalizace = 1 000 000 Kč.","Tržní kapitalizace = 1 100 000 Kč.","Tržní kapitalizace = 1 200 000 Kč."],"c":[0],"p":108,"e":"Tržní kapitalizace = počet akcií × tržní cena (kurz) 1 000x1 500=1 500 000.","tp":4},{"id":"20354.1","t":"s","q":"V emisi je 1 000 ks akcií, je veřejně obchodovatelná. Nominální hodnota akcie = 1 000 Kč, účetní hodnota akcie = 1 200 Kč, kurz akcie = 1 500 Kč. Z těchto hodnot lze určit, že:","o":["Nelze usuzovat nic ohledně dividendy.","By měla být vyplacena dividenda ve výši 200 Kč (účetní hodnota ? nominální hodnota).","By neměla být vyplacena dividenda, protože kurz je vyšší než účetní hodnota.","By měla být vyplacena dividenda ve výši 300 Kč (kurz ? účetní hodnota)."],"c":[0],"p":108,"e":"Z daných veličin nejde usoudit nic o zisku ani o výplatním poměru, který je v gesci orgánů společnosti.","tp":4},{"id":"20355.3","t":"s","q":"Je-li tržní cena podkladového aktiva S = 90 Kč, realizační cena (strike price) call opce na toto podkladové aktivum X = 100 Kč, realizační cena (strike price) put opce na toto podkladové aktivum X = 80 Kč, potom:","o":["Call opce je v penězích (in the money), put opce je mimo peníze (out of the money).","Call opce je mimo peníze (out of the money), put opce je v penězích (in the money).","Call opce i put opce jsou v penězích (in the money).","Call opce i put opce jsou mimo peníze (out of the money)."],"c":[3],"p":108,"e":"Call opce je \"mimo peníze\" (out of the money), je-li tržní cena podkladového aktiva nižší než realizační cena (strike price), put opce je \"mimo peníze\" (out of the money), je-li tržní cena podkladového aktiva vyšší než realizační cena (strike price).","tp":5},{"id":"20837.2","t":"s","q":"Termín splatnosti u perpetuitních dluhových cenných papírů:","o":["Není stanovený.","Je stanovený, ale může být po dobu splatnosti dluhopisu změněn oznámením emitenta (call able bond).","Musí být maximálně do 30 let od data jejich emise.","Musí být maximálně do 50 let od data jejich emise."],"c":[0],"p":108,"e":"Jde o dluhopisy, u kterých v emisních podmínkách není termín splatnosti, nejsou časově ohraničené.","tp":3},{"id":"20907.4","t":"s","q":"Které tvrzení týkající se organizátora regulovaného trhu je pravdivé?","o":["Jako jediný se subjektů finančního trhu v ČR může organizovat regulovaný trh.","Nesmí mít formu společnosti s ručením omezeným.","Nemusí mít sídlo i skutečné sídlo na území České republiky.","K provozování své činnosti potřebuje zvláštní povolení Ministerstva financí jako regulátora trhu."],"c":[0],"p":108,"e":"Organizátor regulovaného trhu musí minimálně naplňovat zákonné předpoklady stanovené v §37 a 38 ZPKT.","tp":0},{"id":"22166.2","t":"s","q":"K burzovnímu obchodování, tzn. k obchodování na regulovaném trhu lze přijmout pouze:","o":["Listinné cenné papíry.","Cenné papíry na doručitele.","Zaknihované cenné papíry.","Cenné papíry těch emisí, kterým byl přidělen \"ISIN\"."],"c":[3],"p":109,"e":"\"ISIN\", neboli \"International Security Identification Number\" představuje mezinárodně uznávanou identifikaci těch emisí zastupitelných cenných papírů, které splňují všechny mezinárodně stanovené podmínky pro povolení jejich obchodovatelnosti na tuzemských i zahraničních burzách cenných papírů, jakožto regulovaných veřejných trhů. Ze zákona může být k obchodování na regulovaném trhu přijat jen takový investiční nástroj, kterému bylo přiděleno identifikační označení podle mezinárodního systému číslování pro identifikaci cenných papírů (ISIN).","tp":0},{"id":"22168.2","t":"s","q":"Do působnosti investičních společností nepatří:","o":["Obhospodařování majetku investičních fondů a jejich administrace.","Obhospodařování majetku zákazníků na základě s nimi individuálně uzavřených smluv.","Úschova a správa investičních nástrojů v obhospodařovaných investičních fondech.","Penzijní (důchodové) spoření."],"c":[3],"p":109,"e":"Investiční společnosti jsou licencovanými právnickými osobami, jež mohou na základě udělené licence obhospodařovat a administrovat investiční fondy včetně vykonávání dalších s tím souvisejících činností, jakož i provádět portfolio management dalších zákazníků na základě s nimi uzavřených individuálních smluv. Do jejich kompetence ovšem nespadá obhospodařování penzijních fondů, které musí zajišťovat výhradně penzijní společnost.","tp":1},{"id":"22169.2","t":"s","q":"Šeky se vyznačují tím, že:","o":["Investorům přinášejí běžný výnos.","Jde o platební instrumenty.","Investorům přinášejí kapitálový výnos.","Jde o investiční instrumenty."],"c":[1],"p":109,"e":"Šeky představují platební instrumenty.","tp":2},{"id":"22170.2","t":"s","q":"Subjekt, který eviduje majetek investičního fondu, kontroluje, zda je s majetkem fondu nakládáno dle jeho statutu či provádí příkazy v souladu se statutem fondu se nazývá:","o":["Obhospodařovatel.","Hlavní podpůrce.","Administrátor.","Depozitář."],"c":[3],"p":109,"e":"Depozitářem investičního fondu nebo zahraničního investičního fondu je právnická osoba, která je na základě depozitářské smlouvy oprávněna: a) mít v opatrování majetek investičního fondu nebo zahraničního investičního fondu, umožňuje-li to jeho povaha, b) zřídit a vést peněžní účty a evidovat pohyb veškerých peněžních prostředků náležících do majetku investičního fondu nebo zahraničního investičního fondu, c) evidovat, umožňuje-li to jeho povaha, nebo kontrolovat stav jiného majetku investičního fondu nebo zahraničního investičního fondu než majetku uvedeného v písmenech a) a b).","tp":1},{"id":"22173.4","t":"s","q":"Hotovostní peníze se vyznačují tím, že svým majitelům:","o":["Přinášejí pouze běžný výnos.","Přinášejí pouze kapitálový výnos.","Nepřinášejí ani běžný, ani kapitálový výnos.","Přinášejí běžný i kapitálový výnos."],"c":[2],"p":110,"e":"Hotovostní peníze nenesou výnos a tudíž se nejedná o investiční instrument.","tp":2},{"id":"22174.2","t":"s","q":"Povinné sjednání účasti depozitáře je specifickým regulačním opatřením určeným pro regulaci:","o":["Investičních a penzijních fondů.","Burz cenných papírů.","Obchodních bank.","Pojišťoven."],"c":[0],"p":110,"e":"Depozitář eviduje majetek fondu a kontroluje, zda je s ním nakládáno ve smyslu platných ustanovení a pravidel.","tp":0},{"id":"22175.2","t":"s","q":"Mezi funkce, jež zabezpečují obchodní banky, nepatří:","o":["Emitování bezhotovostních peněz.","Provádění bezhotovostního platebního styku.","Měnová (monetární) politika.","Finanční zprostředkování."],"c":[2],"p":110,"e":"Základním posláním obchodních bank je zabezpečování tří významných funkcí, a to finančního zprostředkování, emitování bezhotovostních peněz a provádění bezhotovostního platebního styku. Pokud jde o měnovou politiku, tak tu může provádět pouze centrální banka.","tp":2},{"id":"22177.1","t":"s","q":"Funkce věřitele poslední instance (kterou vykonávají centrální banky) byla vytvořena za účelem omezení systémového rizika:","o":["V sektoru investičních služeb.","V sektoru pojišťovnictví.","V sektoru finančních konglomerátů.","V sektoru bankovnictví."],"c":[3],"p":110,"e":"Funkce věřitele poslední instance má zajistit, aby případný úpadek některé (významné) banky nevyvolal úpadky dalších bank a neohrozil funkčnost celého bankovního systému.","tp":2},{"id":"22181.3","t":"s","q":"V České republice je zákonné pojištění vkladů zajišťováno:","o":["Ministerstvem financí.","Garančním systémem finančního trhu.","Českou národní bankou.","Českou bankovní asociací."],"c":[1],"p":110,"e":"V České republice je zákonné pojištění bankovních vkladů zajišťováno Garančním systémem finančního trhu.","tp":2},{"id":"22182.5","t":"s","q":"LIBOR představuje:","o":["Bezrizikovou tržní úrokovou míru ve Spojeném království Velké Británie a Severního Irska (London Interest Banking rate Out of Risk).","Mezibankovní referenční úrokovou sazbu vyhlašovanou bankovní asociací v Londýně na základě nabídek tzv. referenčních bank.","Mezibankovní úrokovou sazbu, za níž ve Velké Británii poptávají obchodní banky úvěry.","Diskontní sazbu centrální banky Velké Británie."],"c":[1],"p":111,"e":"LIBOR , neboli \"London Inter Bank Offered Rate\" představuje světově nejvýznamnější mezibankovní referenční úrokovou sazbu vyhlašovanou bankovní asociací v Londýně na základě hlášení referenčních bank, od které se odvozuje variabilní úročení mnohých úvěrů a dluhopisů denominovaných v nejvýznamnějších světových měnách.","tp":2},{"id":"22183.2","t":"s","q":"Státní pokladniční poukázky patří mezi dluhové cenné papíry, které:","o":["Vydává Ministerstvo financí ČR a díky své krátké době splatnosti nejsou obchodovány na kapitálových trzích.","Vydává Česká národní banka a patří mezi střednědobé dluhopisy.","Vydává stát prostřednictvím České národní banky a patří mezi investiční nástroje s variabilním úrokem.","Vydává stát prostřednictvím Ministerstva financí ČR jako záruku vydané hypoteční listy."],"c":[0],"p":111,"e":"Státní pokladniční poukázky vydává stát prostřednictvím Ministerstva financí ČR, splatnost je do 1 roku (proto se řadí na finanční trh).","tp":3},{"id":"22208.3","t":"s","q":"Jakým způsobem zaznamenává investiční zprostředkovatel údaje o přijatých a předaných pokynech týkajících se investičních nástrojů?","o":["Vede Evidenci smluv a přijatých a předaných pokynů.","Údaje zaznamenává pouze obchodník s cennými papíry, a to po jejich předání.","Vede Deník obchodníka s cennými papíry.","Vede Evidenci zákazníků a potenciálních zákazníků."],"c":[0],"p":111,"e":"Evidence investičního zprostředkovatele se skládá ze dvou částí, přičemž první z nich je Evidence smluv a přijatých a předaných pokynů. Druhou částí je Evidence osob, která obsahuje údaje o osobách jejichž identifikace se vyskytuje v Evidenci smluv a přijatých a předaných pokynů.","tp":0},{"id":"22209.3","t":"s","q":"Je obchodník s cennými papíry povinen při poskytování investičních služeb \"obhospodařování majetku zákazníka, je-li jeho součástí investiční nástroj, na základě volné úvahy v rámci smluvního ujednání\" a \"investičního poradenství týkajícího se investičních nástrojů\" požadovat od zákazníka (mimo jiné) informaci o jeho hospodářské situaci?","o":["Ano, a to podle druhu a rozsahu zákazníkem požadovaných investičních služeb.","Ne, jedná se o dobrovolně poskytované údaje.","Ano, avšak pouze u zákazníka, který nedisponuje zkušenostmi v oblasti investic.","Ne, obchodník s cennými papíry je oprávněn vyžadovat pouze informace o zkušenostech v oblasti investic."],"c":[0],"p":111,"e":"Pravidla jednání obchodníka s cennými papíry se zákazníky upravují rozsah informací, které je obchodník s cennými papíry povinen vyžádat, a to včetně informace ohledně hospodářské situace zákazníka.","tp":0},{"id":"22230.2","t":"s","q":"Volatilitu investic měříme:","o":["Směrodatnou odchylkou.","Koeficientem determinace.","Korelačním koeficientem.","Schillerovým koeficientem."],"c":[0],"p":112,"e":"Volatilitu měříme směrodatnou odchylkou. Korelace měří vztah mezi 2 veličinami, koeficient determinace je druhou mocninou korelačního koeficientu. Schillerův koeficient neexistuje, Schillerovo P/E vyjadřuje poměr ceny akcií k průměru zisků za posledních 10 let.","tp":7},{"id":"22415.1","t":"s","q":"Maximální výše výstupního poplatku:","o":["Nesmí překročit 10 %.","Je stanovena věstníkem Evropské centrální banky.","Musí být uvedena ve statutu fondu kolektivního investování.","Závisí na aktuální výši základní úrokové sazby ČNB."],"c":[2],"p":112,"e":"Údaje o poplatcích účtovaných investorům a nákladech hrazených z majetku fondu kolektivního investování musí být dle zákona o investičních společnostech a fondech uvedeny ve statutu fondu kolektivního investování.","tp":1},{"id":"22416.1","t":"s","q":"Administrátor fondu:","o":["Zajišťuje zejména komplexní řízení investic a rizik.","Opatruje majetek fondu a provádí související kontrolní činnosti, v rámci kterých zejména kontroluje finanční pohyby a vydávání a odkupování cenných papírů.","Provádí činnosti spojené s vydáváním a odkupem cenných papírů, vedením účetnictví, oceňováním a dalšími službami nezbytnými pro řádný provoz fondu.","Ověřuje účetní závěrky a výroční zprávy fondu a toto reportuje na roční bázi České národní bance."],"c":[2],"p":112,"e":"Je stanoveno v Zákoně č. 240/2013 Sb., o investičních společnostech a investičních fondech, § 38 ZISIF.","tp":1},{"id":"22419.2","t":"s","q":"Anualizovaná výkonnost:","o":["Je vyjádřením průměrné roční výkonnosti.","Je vyjádřením výkonnosti za poslední kalendářní rok.","Je vyjádřením výkonnosti od začátku aktuálního kalendářního roku.","Je vyjádřením průměrného rozdílu výkonnosti fondu a benchmarku."],"c":[0],"p":112,"e":"Anualizovaná výkonnost neboli průměrná roční výkonnost vyjadřuje historickou průměrnou výkonnost za jeden rok.","tp":1},{"id":"23642.2","t":"s","q":"Vyberte nesprávné tvrzení - Shrnutí prospektu obsahuje:","o":["Auditovanou účetní závěrku emitenta.","Stručný popis podstatných rizik emitenta cenného papíru.","Stručnou charakteristiku emitenta cenného papíru a případného ručitele.","Upozornění na to, že shrnutí představuje úvod k prospektu."],"c":[0],"p":113,"e":"Shrnutí prospektu je stručný a strukturovaný dokument, který investorovi přináší srozumitelnou formou upozornění na to, že shrnutí prospektu je úvodem k prospektu a že rozhodnutí investovat do cenných papírů by mělo být založeno na tom, že investor zváží prospekt jako celek. Strukturovaný prospekt přináší investorovi strukturovaný přehled informací nezbytných k posouzení povahy cenného papíru a rizik s ním spojených tak, aby na jejich základě a při zvážení prospektu jako celku mohl adresát nabídky usoudit, zda je cenný papír pro něj vhodný. Tento přehled obsahuje alespoň stručnou charakteristiku emitenta cenného papíru a případného ručitele, včetně rizik spojených s majetkem, závazky a finanční situací těchto osob, stručný popis podstatných rizik emitenta cenného papíru a případného ručitele a stručný popis podstatných rizik souvisejících s investicí do daného cenného papíru, základní charakteristiku investice do tohoto cenného papíru a popis práv spojených s tímto cenným papírem.","tp":0},{"id":"23643.2","t":"s","q":"Emitent může vydat dluhopisy jen tehdy:","o":["Pokud byly nejpozději k datu emise investorům zpřístupněny emisní podmínky.","Pokud Česká národní banka schválila emisní podmínky.","Pokud byly emisní podmínky ověřeny auditorem.","Pokud emitent zaslal České národní bance emisní podmínky."],"c":[0],"p":113,"e":"Dluhopisy mohou být dle zákona o dluhopisech vydány pouze tehdy, pokud měli investoři nejpozději k datu emise zpřístupněny emisní podmínky.","tp":3},{"id":"23701.2","t":"s","q":"Předčasné splacení dluhopisu:","o":["Nemůže nikdy nastat.","Může nastat pouze na základě výzvy emitenta.","Může nastat pouze na základě výzvy držitele dluhopisu.","Může nastat buď na základě výzvy emitenta nebo držitele dluhopisu."],"c":[3],"p":113,"e":"Dluhopis umožňuje předčasné splacení buď na základě výzvy emitenta (callable bond) nebo na základě výzvy držitele dluhopisu (puttable bond), přičemž toto musí být uvedeno v emisních podmínkách dluhopisu.","tp":3},{"id":"23738.1","t":"s","q":"Kolik může mít jeden dlouhodobý investiční produkt poskytovatelů?","o":["více","jen jednoho","maximálně tři poskytovatele","neomezený počet"],"c":[1],"p":113,"e":"V souladu s § 134g odst. 5 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, ve znění pozdějších předpisů může mít každý DIP jen jednoho poskytovatele, to však nebrání tomu, aby poskytovatel využíval při poskytování dlouhodobého investičního produktu služeb jiné osoby.","tp":2},{"id":"23740.1","t":"s","q":"Příspěvek uhrazený zaměstnavatelem na zaměstnancův dlouhodobý investiční produkt je daňově podporovaný:","o":["vždy, bez jakéhokoliv omezení","až do výše 48 000 Kč ročně","pouze v případě, že příspěvek zaměstnavatele činí alespoň 1 000 Kč měsíčně","až do výše 50 000 Kč ročně"],"c":[3],"p":114,"e":"Podle § 6 odst. 9 písm. m) zákona č. 586/1992 Sb., o daních z příjmů, ve znění pozdějších předpisů, jsou od daně z příjmu osvobozeny příspěvky uhrazené zaměstnavatelem na daňově podporované produkty spoření na stáří jeho zaměstnance nebo na daňově podporované pojištění dlouhodobé péče, jehož pojistníkem je jeho zaměstnanec, do úhrnné výše 50000 Kč ročně.","tp":9},{"id":"23742.1","t":"s","q":"Finanční poradci, kteří jsou povinni zveřejňovat určité informace související s udržitelností dle nařízení (EU) 2019/2088, o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR), jsou tímto nařízením taxativně vymezeni. Informační povinnosti pro finanční poradce vyplývající ze SFDR se:","o":["použijí výhradně jen na ty finanční poradce, kteří poskytují pojišťovací poradenství v oblasti pojistných produktů s investiční složkou","použijí na všechny obchodníky s cennými papíry, kteří poskytují investiční poradenství týkající se investičních nástrojů (tj. bez ohledu na jejich počet zaměstnanců)","použijí na obchodníky s cennými papíry, kteří poskytují investiční poradenství týkající se investičních nástrojů, a zároveň mají alespoň 3 zaměstnance","nepoužijí na žádné finanční poradce, neboť informační povinnosti vyplývající ze SFDR se použijí pouze na účastníky finančního trhu"],"c":[2],"p":114,"e":"Příslušné nařízení vymezuje finanční poradce, na které se vztahují některé z informačních povinností předepsaných SFDR, taxativním výčtem v čl. 2 bodě 11. Mezi finanční poradce dle tohoto ustanovení patří mj. právě investiční podniky, které poskytují investiční poradenství. Z adaptace SFDR do zákona č. 256/2004 Sb. o podnikání na kapitálových trzích vyplývá, že jde mj. o ty obchodníky s cennými papíry, kteří poskytují investiční poradenství týkající se investičních nástrojů, a zároveň mají alespoň 3 zaměstnance. Na obchodníky s cennými papíry zaměstnávající méně než 3 zaměstnance se SFDR nepoužije, neboť se na ně použije výjimka podle čl. 17 daného nařízení, která je promítnuta do adaptace SFDR do ZPKT. Odpověď v tom smyslu, že SFDR se použije pouze na finanční poradce poskytující pojišťovací poradenství k pojistným produktům s investiční složkou, není správná, neboť taxativní výčet finančních poradců je širší (mj. zahrnuje např. úvěrové instituce či správcovské společnosti subjektů kolektivního investování do převoditelných cenných papírů, které poskytují investiční poradenství, a další finanční poradce.","tp":6},{"id":"23745.1","t":"s","q":"Na který z níže uvedených produktů či nástrojů se použijí informační povinnosti dle nařízení (EU) 2019/2088, o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR)?","o":["neživotní pojištění, např. pojištění proti přírodním živlům, které snižuje expozici vůči tzv. rizikům udržitelnosti","spravované portfolio v souladu s pověřeními od zákazníků s možností vlastního uvážení ve vztahu k jednotlivým zákazníkům, pokud tato portfolia zahrnují jeden nebo více finančních nástrojů","veřejně obchodovatelná akcie na regulovaném trhu v některém z členských států EU","korporátní dluhopis obchodovatelný na regulovaném trhu v některém z členských států EU"],"c":[1],"p":114,"e":"Příslušné nařízení vymezuje finanční produkty taxativním výčtem v čl. 2 v bodě 12. Mezi finanční produkty dle tohoto ustanovení patří mj. také právě spravované portfolio ve smyslu čl. 4 odst. 1 bodu 8 směrnice 2014/65/EU (MiFID II), tj. produkt s návazností na hlavní investiční službu obhospodařování majetku zákazníka, je-li jeho součástí investiční nástroj, na základě volné úvahy v rámci smluvního ujednání (podle § 4, bodu 2, písm. d) zákona č. 256/2004 Sb. o podnikání na kapitálových trzích). Z uvedených možností jde o jediný finanční produkt, který je v SFDR taxativně vymezen. Pokud jde o ostatní možnosti, pod tento pojem nespadají, neboť jsou mimo výčet finančních produktů podle SFDR (v případě korporátního dluhopisu a akcie jde o investiční nástroj, nikoliv o produkt ve smyslu SFDR; v případě neživotního pojištění jde o jiný typ neinvestičního produktu, které leží taktéž mimo působnost SFDR).","tp":6},{"id":"23749.1","t":"s","q":"V případě investičního fondu, který zveřejňuje informace o environmentálních cílech produktu ve výroční zprávě dle čl. 11 nařízení o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR), zahrnuje tato povinnost také kvantitativní informaci o míře sladěnosti investic daného produktu s taxonomií EU pro environmentálně udržitelné ekonomické činnosti. Pokud účastník finančního trhu (spravující fond) neshromáždí přes veškeré své úsilí použitelné podkladové informace pro plnění této povinnosti, postupuje takto:","o":["část mandatorních šablon pravidelných zpráv týkající se informací o sladěnosti s taxonomií nevyplňuje, existuje však povinnost tuto část i nadále povinně zveřejňovat, byť nevyplněnou","v relevantní části šablon uvede 0% sladěnost","v relevantní části šablon uvede kvantitativní odhad, který účastník finančního trhu subjektivně považuje za realistický","část mandatorních šablon pravidelných zpráv týkající se informací o sladěnosti s taxonomií v daném případě vůbec neuvede (šablonu zveřejní bez části s vazbou na sladěnost produktu s taxonomií)"],"c":[1],"p":115,"e":"Konsolidované otázky a odpovědi Komise k použití rámce SFDR uvádějí, že pokud účastník finančního trhu v daném případě neshromáždí údaje o tom, do jaké míry jsou investice, na nichž je finanční produkt založen, směřovány do ekonomických činností, které se kvalifikují jako environmentálně udržitelné podle čl. 3 nařízení o taxonomii, musí v předsmluvní dokumentaci a pravidelných produktových zprávách uvádět nulu, resp. 0% sladěnost investic produktu s taxonomií EU pro udržitelné ekonomické činnosti.","tp":6},{"id":"23754.1","t":"s","q":"Za environmentálně udržitelnou investici podle nařízení (EU) 2020/852 o zřízení rámce pro usnadnění udržitelných investic (tzv. nařízení o taxonomii) lze považovat investici do:","o":["zeleného dluhopisu, jehož výnosy jsou použity výhradně na financování činností, které jsou environmentálně udržitelnými činnostmi dle nařízení o taxonomii","svrchovaného dluhopisu, který byl emitován vládou (či jinou svrchovanou entitou), jež je signatářem Pařížské dohody o klimatu","zeleného dluhopisu, jehož výnosy jsou použity na financování činností, které plní všechna kritéria taxonomie pro environmentální oblast, byť nejsou naplněny minimální záruky pro sociální oblast","zeleného dluhopisu, jehož výnosy jsou použity na financování činností, které plní kritéria taxonomie pro příspěvek k plnění environmentálních cílů, naplňují minimální sociální záruky, ale neplní kritéria pro uplatňování principu významně nepoškozovat plnění ostatních environmentálních cílů"],"c":[0],"p":115,"e":"Environmentálně udržitelnou investicí je dle čl. 2 bodu 1 nařízení (EU) 2020/852 (tzv. nařízení o taxonomii) investice do jedné nebo více hospodářských činností, které se podle nařízení o taxonomii kvalifikují jako environmentálně udržitelné. Čl. 3 téhož nařízení stanoví, že: Pro účely stanovení míry, do jaké je investice environmentálně udržitelná, se hospodářská činnost kvalifikuje jako environmentálně udržitelná, pokud tato hospodářská činnost:\na) významně přispívá k jednomu nebo více environmentálním cílům stanoveným v čl. 9 v souladu s články 10 až 16; b) významně nepoškozuje žádný z environmentálních cílů stanovených v článku 9 v souladu s článkem 17;\nc) je vykonávána v souladu s minimálními zárukami stanovenými v čl. 18; a d) splňuje technická screeningová kritéria, která Komise stanovila v souladu s čl. 10 odst. 3, čl. 11 odst. 3, čl. 12 odst. 2, čl. 13 odst. 2, čl. 14 odst. 2 nebo čl. 15 odst. 2.\nPouze u jedné možnosti jsou všechny tyto podmínky naplněny.","tp":3},{"id":"23755.1","t":"s","q":"Musí mít obchodník s cennými papíry ve své nabídce finančních nástrojů také nástroj (potažmo produkt), který vyhovuje regulatorní definici preferencí týkajících se udržitelnosti?","o":["ano, musí mít minimálně jednu investiční možnost (nástroj nebo produkt) orientovanou na plnění cíle v environmentální oblasti","ano, musí mít alespoň jeden nástroj či produkt, který určitým (jakýmkoliv) způsobem zohledňuje negativní dopad na životní prostředí","ne, nicméně je povinen tuto skutečnost ohlásit České národní bance","ne, není jeho povinností takovýto nástroj či produkt nabízet"],"c":[3],"p":115,"e":"Žádná současná regulace nestanoví povinnost mít v nabídce nástroj (či produkt) vyhovující definici preferencí týkajících se udržitelnosti. Prováděcí nařízení (EU) 2017/565 stanoví mj. povinnost zjišťovat a zohledňovat preference týkající se udržitelnosti v rámci posuzování vhodnosti. Prováděcí směrnice (EU) 2017/593 zase mj. začleňuje faktory udržitelnosti do povinností při řízení produktů. Nicméně žádná z těchto (ani jiných) právních norem nezakládá povinnost poskytovatelům upravit svou nabídku tak, aby měli v nabídce nástroje (či produkty) zohledňující udržitelnost (ve smyslu zohledňování ESG aspektů). Rovněž neexistuje ani žádná regulace, která by předepisovala ohlašovací povinnost obchodníka s cennými papíry vůči ČNB, jak je uvedeno v jedné z nabízených odpovědí.","tp":0},{"id":"23756.1","t":"s","q":"Pokud finanční poradce poskytující službu investiční poradenství nemá v nabídce finanční nástroj, který by byl v souladu s preferencemi zákazníka, které se týkají udržitelnosti a které byly zjištěny v rámci posouzení vhodnosti, může:","o":["doporučit produkt či investiční strategii, která by nebyla v souladu s klientovými preferencemi týkajícími se udržitelnosti identifikovanými při poskytování rady","doporučit jiný produkt či investiční možnost z nabídky, pokud klient upraví své preference týkající se udržitelnosti tak, že upravené preference budou v souladu s touto nabídkou; o této změně preference je třeba uchovat záznam","doporučit jiný produkt nebo nástroj, pokud klient upraví své preference; o změně preferencí není nutné provést záznam","nabídnout produkt či nástroj bez jakýchkoliv dalších podmínek (preference týkající se udržitelnosti klienta se považují za doplňkové aspekty v tom ohledu, že neexistuje povinnost je bezpodmínečně zohledňovat)"],"c":[1],"p":116,"e":"Uvedený postup vyplývá z čl. 54 odst. 10 prováděcího nařízení (EU) 2017/565, ve znění nařízení (EU) 2021/1253, kde je uvedeno:\nPokud žádná služba ani nástroj není pro zákazníka vhodný, investiční podnik je v rámci poskytování investiční služby v podobě investičního poradenství či správy portfolií nedoporučí ani nerozhodne o obchodování s nimi.\nInvestiční podnik nedoporučí ani se nerozhodne obchodovat s finančními nástroji jako s nástroji, které splňují preference zákazníka nebo potenciálního zákazníka týkající se udržitelnosti, pokud tyto finanční nástroje předmětné preference nesplňují. Investiční podniky svým zákazníkům nebo potenciálním zákazníkům vysvětlí důvody, proč tak neučinily, a vedou o těchto důvodech záznamy.\nPokud žádný finanční nástroj nesplňuje preference zákazníka nebo potenciálního zákazníka týkající se udržitelnosti a zákazník se rozhodne upravit své preference týkající se udržitelnosti, investiční podniky vedou záznamy o rozhodnutí zákazníka, včetně důvodů tohoto rozhodnutí.\nStejný princip rozvíjí Obecné pokyny ESMA v bodě 6. (s. 28).","tp":6},{"id":"23757.1","t":"s","q":"Pokud finanční poradce poskytující službu investiční poradenství nemá v nabídce finanční nástroj, který by byl v souladu s preferencemi zákazníka, které se týkají udržitelnosti a které byly zjištěny v rámci posouzení vhodnosti:","o":["pokusí se zákazníka přesvědčit, aby změnil svou preferenci tak, aby bylo možné nějaký nástroj doporučit","může jej informovat o vlastní nabídce nástrojů s určitými prvky udržitelnosti, které má ve své nabídce, avšak pouze v případě, pokud se zákazník sám rozhodne změnit své preference týkající se udržitelnosti","může mu doporučit, aby upravil některý ze svých jiných investičních cílů (např. připustil vyšší rizikovost) tak, aby mohl připadnout v úvahu některý z nástrojů, které má v nabídce","upozorní zákazníka, že doporučovaný nástroj neodpovídá jeho preferencím udržitelnosti, nicméně může mu bezprostředně doporučit jiný nástroj, který je v souladu s vyhodnocením ostatních povinných aspektů testování vhodnosti"],"c":[1],"p":116,"e":"Pokud poskytovatel investičního poradenství nemá v nabídce nástroj, který by zohledňoval preference udržitelnosti, které zákazník vyjádřil, není možné takový nástroj doporučit. Nicméně je možné poté, co zákazníkovi byl sdělen výsledek posouzení vhodnosti pro něj, zákazníka upozornit na možnost změny preferencí (nikoli ho ovšem k tomuto kroku nutit, přesvědčovat či jinak přimět). Pouze pokud zákazník sám dobrovolně vyjádří úmysl své preference změnit, lze mu poskytnout informaci o tom, jaké produkty či nástroje s prvky udržitelnosti jsou v nabídce poskytovatele. Návrat k posuzování ostatních investičních cílů není možný, neboť posuzování preferencí týkajících se udržitelnosti má nastat až po posouzení vhodnosti vzhledem k ostatním investičním cílům zákazníka. Uvedené postupy se odvíjejí od nařízení (EU) 2021/1253 a jsou upřesněny Obecnými pokyny ESMA k některým aspektům požadavků směrnice MiFID II ohledně vhodnosti (body 81 až 83).","tp":6},{"id":"19371.1","t":"m","q":"Finanční systém zajišťuje v ekonomice:","o":["Funkce depozitní a kreditní.","Funkci politickou (regulační).","Funkci uchování hodnoty (bohatství).","Funkci ochrany proti riziku."],"c":[0,1,2,3],"p":116,"e":"Finanční systém zajišťuje v rámci ekonomického systému tyto funkce: depozitní, kreditní, uchování hodnoty (bohatství), likvidity, platební, ochrany proti riziku a politickou (regulační).","tp":0},{"id":"19373.2","t":"m","q":"Ve smyslu ekonomické teorie plní peníze následující jedinečné funkce:","o":["Jsou prostředkem směny.","Jsou trvalou hodnotou, která nepodléhá změnám.","Jsou uchovatelem hodnoty (i když je všeobecně známo, že podléhají inflaci).","Jsou mírou hodnoty, neboli zúčtovací jednotkou, resp. měřítkem cen."],"c":[0,2,3],"p":117,"e":"Peníze jsou prostředkem směny, mírou hodnoty (zúčtovací jednotkou, resp. měřítkem cen) a uchovatelem hodnoty.","tp":2},{"id":"19387.1","t":"m","q":"Jaká jsou základní individuální investiční kritéria?","o":["Rizikovost.","Likvidita.","Nadproporcionálnost.","Výnosnost."],"c":[0,1,3],"p":117,"e":"Výnosnost, rizikovost a likvidita jsou základními faktory individuální investiční strategie, přičemž platí, že neexistuje investice, která by dosahovala optima ve všech těchto kritériích. Existuje pouze varianta jejich optimálního vzájemného poměru.","tp":2},{"id":"19388.1","t":"m","q":"Za dílčí faktory rizikovosti lze při investování do cenných papírů považovat:","o":["Riziko změn tržní úrokové míry.","Riziko vlastností (resp. smluvních ustanovení) jednotlivých investičních instrumentů.","Riziko měnové.","Riziko insolvence či úpadku emitenta (tzv. kreditní riziko)."],"c":[0,1,2,3],"p":117,"e":"Rizikovost je nutno uvažovat jako množinu jednotlivých dílčích rizik spojených s určitým investičním nástrojem.","tp":0},{"id":"19389.3","t":"m","q":"V souvislosti s tvorbou investičního portfolia platí tyto zásady:","o":["Vhodně provedená diverzifikace snižuje nesystematické riziko portfolia.","Čím bude menší vzájemná závislost mezi změnami výnosnosti jednotlivých investičních nástrojů, tím větší omezení rizikovosti diverzifikace přinese.","Rizikovost portfolia klesá s počtem do něj zařazených druhů investičních instrumentů, a to bez ohledu na to, o jak rizikové nástroje se jedná.","Rizikovost portfolia lze snížit buď zařazením méně rizikových investičních nástrojů, nebo vyšší vahou, jež jim bude v portfoliu přidělena."],"c":[0,1,3],"p":117,"e":"Základ prospěšnosti diverzifikace je obsažen v úsloví \"nesázet vše na jednu kartu\". Z toho vyplývá, že držba více druhů investičních aktiv snižuje rizikovost jejich držby, ovšem za předpokladu, že do portfolia nezařadíme rizikovější investiční instrumenty, než tam byly předtím.","tp":7},{"id":"19390.1","t":"m","q":"Za často používané dynamické metody hodnocení finančních investic se všeobecně považují:","o":["Metoda hrubé současné hodnoty.","Metoda vnitřní míry výnosu (resp. vnitřního výnosového procenta).","Metoda čisté současné hodnoty.","Black-Scholesův model rentability."],"c":[1,2],"p":117,"e":"Mezi nejvýznamnější dynamické metody hodnocení výnosnosti finančních investic, založené na vztazích mezi současnou a budoucí hodnotou, patří metody čisté současné hodnoty a vnitřní míry výnosu.","tp":2},{"id":"19403.1","t":"m","q":"Anuitní splácení je typické pro:","o":["Kuponový státní dluhopis s variabilním kuponem.","Leasing.","Státní pokladniční poukázku.","Hypotéku."],"c":[1,3],"p":118,"e":"Hypotéka i leasing (po odečtení případné akontace) jsou spláceny ve formě anuity, kdy se nominální hodnota půjčky rozpouští do jednotlivých splátek. Kuponový státní dluhopis i státní pokladniční poukázka mají nenulovou nominální hodnotu, nejedná se tedy o anuitu.","tp":3},{"id":"19404.1","t":"m","q":"Systém pravidelných splátek ve stejné výši se nazývá:","o":["Anuita.","Perpetuita.","Dluhopis s nulovým kuponem.","Kredit."],"c":[0,1],"p":118,"e":"Je-li systém pravidelných splátek ve stejné výši omezen na konečný počet let, jedná se o anuitu, je-li počet splátek neomezený (jdoucí \"do nekonečna\"), jedná se o perpetuitu.","tp":3},{"id":"19405.1","t":"m","q":"Se kterými typy z uvedených leasingů se můžete setkat na trhu?","o":["Operativní leasing.","Faktorový leasing.","Reciproční leasing.","Finanční leasing."],"c":[0,3],"p":118,"e":"Finanční a operativní leasing jsou dvě obecně známé a používané formy leasingu.","tp":2},{"id":"19406.2","t":"m","q":"Mezi typy úročení z níže uvedených možností patří:","o":["Jednoduché úročení.","Podvojné úročení.","Složené úročení.","Komplexní úročení."],"c":[0,2],"p":118,"e":"Jednoduché a složené úročení jsou obecně známé a používané formy úročení.","tp":2},{"id":"19420.1","t":"m","q":"Podle kritéria, jedná-li se o nové emise či obchoduje-li se s již dříve vydanými a již obchodovanými cennými papíry se trh cenných papírů dělí na:","o":["Primární trh cenných papírů.","Sekundární trh cenných papírů.","Terciální trh cenných papírů.","Regulovaný trh cenných papírů."],"c":[0,1],"p":118,"e":"Podle toho, jedná-li se o nové emise poprvé uváděné na finanční trh, či se obchoduje s již dříve vydanými a již opakovaně obchodovanými cennými papíry, se trh cenných papírů dělí na trh primární a sekundární.","tp":0},{"id":"19421.1","t":"m","q":"Finanční trh obsahuje následující základní segmenty:","o":["Trh peněžní.","Trh kapitálový.","Trh komoditní.","Trh OTC."],"c":[0,1,2],"p":119,"e":"Finanční trh obsahuje 4 základní segmenty - trh peněžní (krátkodobý), trh kapitálový (dlouhodobý), trh s cizími měnami a trh komoditní. OTC trh je pouze místo vypořádání, tzv. over the counter, přes přepážku, nejtypičtěji v bance.","tp":2},{"id":"19422.1","t":"m","q":"Mezi termínové (derivátové) burzy řadíme:","o":["Komoditní OTC-burzy.","Burzy futures.","Burzy opční.","Komoditní burzy promptní (spotové)."],"c":[1,2],"p":119,"e":"Mezi termínové derivátové burzy patří burzy futures a burzy opční.","tp":4},{"id":"19435.2","t":"m","q":"Složené úročení se typicky používá:","o":["Pokud je počet úrokových období vyšší než jedna.","Pokud je počet úrokových období nižší než jedna.","Při dlouhodobém investičním horizontu (resp. uložení prostředků).","Pro dosažení vyššího zhodnocení na delších horizontech než při užití jednoduchého úročení."],"c":[0,2,3],"p":119,"e":"Složené úročení, při kterém dochází k úročení připsaných úroků se zpravidla používá v okamžiku, kdy počet úrokových období je větší než jedno.","tp":2},{"id":"19436.1","t":"m","q":"Za pojišťovací instituce lze považovat:","o":["Zajišťovny.","Pojišťovací makléře.","Likvidátory pojistných událostí.","Pojišťovny"],"c":[0,3],"p":119,"e":"Pojišťovacími institucemi se rozumí pojišťovny a zajišťovny (neboli pojišťovny pojišťoven).","tp":10},{"id":"19437.2","t":"m","q":"Promptní (či spotové) burzy, resp. regulované trhy, se vyznačují tím, že:","o":["Střetává se na nich agregovaná nabídka s agregovanou poptávkou.","Způsob obchodování je založen na principu oboustranné aukce.","Musí stanovit nejnižší přípustná obchodovatelná množství.","Vypořádání obchodů probíhá brzy po jejich uzavření."],"c":[0,1,2,3],"p":119,"e":"Burzy jsou licencovanými finančními institucemi, jejichž podnikatelskou činností je organizování trhu s určitými obchodovatelnými investičními instrumenty.","tp":4},{"id":"19438.1","t":"m","q":"Mezi licencované, resp. registrované, profese fyzických osob patří:","o":["Investiční zprostředkovatelé.","Pojistní statistici.","Pojišťovací zprostředkovatelé.","Samostatní likvidátoři pojistných událostí."],"c":[0,2,3],"p":120,"e":"Jde o celou řadu odborných profesí, jejichž výkon podléhá zpřísněným kvalifikačním a personálním předpokladům, jakož i registraci (neboli zařazení do veřejných seznamů vedených regulatorními orgány).","tp":0},{"id":"19451.1","t":"m","q":"Základními sektory vymezenými v rámci finančního systému pro účely regulace a dohledu bývají:","o":["Sektor bankovnictví.","Sektor investičních služeb.","Sektor pojišťovnictví.","Sektor vzájemné výpomoci finančních institucí."],"c":[0,1,2],"p":120,"e":"Podle příbuznosti nabízených produktů a služeb rozlišují systémy regulace a dohledu nejčastěji sektor bankovnictví, sektor investičních služeb a sektor pojišťovnictví.","tp":0},{"id":"19452.1","t":"m","q":"Základními typy možného tržního selhání ve finančním systému může být:","o":["Informační asymetrie.","Zneužívání dominantního postavení na trhu.","Zneužití trhu.","Systémové riziko (riziko možného selhání celého finančního systému)."],"c":[0,1,2,3],"p":120,"e":"V rámci finančního systému existují čtyři základní faktory možného selhání trhu: informační asymetrie, zneužívání dominantního postavení na trhu, zneužití trhu a systémové riziko.","tp":2},{"id":"19453.2","t":"m","q":"Mezi cíle soudobých systémů regulace a dohledu patří:","o":["Finanční stabilita jednotlivých finančních institucí.","Posilování důvěry investorů a emitentů investičních nástrojů v kapitálový trh.","Podpora zdravého rozvoje a transparentnosti kapitálového trhu.","Zabránit selhání každého jednotlivého poskytovatele služeb na kapitálovém trhu nebo jednotlivého emitenta."],"c":[0,1,2],"p":120,"e":"Společnými cíli soudobých systémů regulace a dohledu jsou: finanční stabilita jednotlivých finančních institucí, ochrana drobných investorů a ostatních klientů finančních institucí, ochrana tržní konkurence a finanční stabilita ve finančním systému.","tp":0},{"id":"19454.2","t":"m","q":"Systémy bankovní regulace a dohledu bývají založeny na těchto základních nástrojích:","o":["Udělování bankovních licencí.","Obezřetnostní dohled a ochranu zákazníků bank.","Povinné pojištění bankovních vkladů.","Výkon funkce věřitele poslední instance."],"c":[0,1,2,3],"p":120,"e":"Systémy bankovní regulace jsou založeny na těchto nástrojích: na udělování bankovních licencí, na obezřetnostním dohledu a ochraně bankovních komitentů, na povinném pojištění bankovních vkladů a na výkonu funkce věřitele poslední instance.","tp":0},{"id":"19470.2","t":"m","q":"Fond kvalifikovaných investorů:","o":["Shromažďuje prostředky nebo jiná aktiva pouze od fyzických osob.","Shromažďuje prostředky nebo jiná aktiva od omezeného počtu tzv. kvalifikovaných investorů.","Může investovat pouze do akcií a dluhopisů.","Podléhá výrazně volnější regulaci než fondy kolektivního investování."],"c":[1,3],"p":121,"e":"Jedná se fondy s vyšším potenciálem výnosů, avšak obvykle s velkým rizikem. Je upraveno v zákonu č. 240/2013 Sb., o investičních společnostech a investičních fondech.","tp":1},{"id":"19471.1","t":"m","q":"Investiční společnosti jsou oprávněny v souladu se svou licencí vykonávat obvykle následující funkce:","o":["Funkce obhospodařovatele majetku investičních či podílových fondů včetně investování a řízení souvisejících rizik.","Funkce administrátora, což obnáší např. výpočet aktuální hodnoty akcií či podílových listů fondu.","Funkci centrálního depozitáře pro jimi organizované obchody na finančním trhu.","Funkci úschovy a správy investičních nástrojů obhospodařovaných investičních a podílových fondů."],"c":[0,1,3],"p":121,"e":"Jedná se o základní obecné členění funkcí, zejména s přihlédnutím k zákonu č. 240/2013, Sb. o investičních společnostech a investičních fondech.","tp":1},{"id":"19472.5","t":"m","q":"Obchodník s cennými papíry je:","o":["Subjekt, kterému ČNB vydala příslušné povolení.","Každý subjekt, který to uvede ve svém obchodním názvu.","Subjekt, kterému umožní přístup k obchodování burza cenných papírů a má současně potřebné povolení.","Každý subjekt, který k obchodování pověří burza cenných papírů."],"c":[0,2],"p":121,"e":"Ustanovuje § 5, § 6 a další Zákona o podnikání na kapitálovém trhu (ZPKT), č. 256/2004 Sb., dále Oldřich Rejnuš, Finanční trhy 4. rozšířené vydání, GRADA Publishing, Praha, 2014, ISBN 978-80-247-3671-6, str. 117.","tp":0},{"id":"19473.3","t":"m","q":"Pokud vázaný zástupce investičního zprostředkovatele obdrží od zákazníka stížnost na svoji činnost:","o":["Je povinen ji postoupit investičnímu zprostředkovateli a zákazníka o tom informovat.","Je povinen na ni odpovědět zákazníkovi do 30 dnů.","Je povinen ji postoupit ČNB a zákazníka o tom informovat.","Může ji dle svého uvážení se zákazníkem také prodiskutovat, ale hlavně ji neprodleně postoupí investičnímu zprostředkovateli."],"c":[0,3],"p":121,"e":"Uvedeno v § 29, § 33 zákona o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb.","tp":0},{"id":"19474.2","t":"m","q":"Vázaný zástupce investičního zprostředkovatele:","o":["Musí mít s investičním zprostředkovatelem uzavřenu písemnou smlouvu.","Nemůže nakládat s finančními prostředky nebo investičními nástroji v majetku zákazníka, i kdyby jej k tomu zákazník písemně zmocnil.","Nemůže nakládat s finančními prostředky nebo investičními nástroji v majetku zákazníka, i kdyby s tím souhlasil zastupovaný investiční zprostředkovatel.","Může nakládat s finančními prostředky nebo investičními nástroji v majetku zákazníka, pokud zastupovaný investiční zprostředkovatel splňuje zákonem stanovenou kapitálovou přiměřenost."],"c":[0,1,2],"p":121,"e":"Vztah a povinnosti vázaného zástupce investičního zprostředkovatele upravuje zákon č. 256/2004 Sb., o podnikání na kapitálovém trhu.","tp":0},{"id":"19490.4","t":"m","q":"Trhy s cennými papíry podle různých hledisek nejčastěji dělíme na:","o":["Trhy primární a trhy sekundární.","Trhy regulované a trhy neregulované.","Trhy se státními aktivy a trhy s privátními aktivy.","Trhy s osobními aktivy a trhy korporátní."],"c":[0,1],"p":122,"e":"Trhy standardně rozdělujeme na primární nebo sekundární podle toho, jedná-li se o nové emise poprvé uváděné na finanční trh, nebo se obchoduje s cennýmim papíry již dříve vydanými. Z pohledu intenzity regulace a dohledu pak trhy dělíme dle aktuální legislativy na trhy regulované a trhy neregulované.","tp":2},{"id":"19491.8","t":"m","q":"Trhy známé pod zkratkou OTC (Over The Counter) mají následující vlastnosti:","o":["Obchodování veřejně obchodovatelných cenných papírů nepřijatých na trh burzy cenných papírů","Obchodování v případě, kdy na burzách se obchoduje v předem určeném časovém rozsahu, avšak obchod je třeba uskutečnit až v době po ukončení seance na burze.","Obchodování pouze registrovaných (kotovaných) cenných papírů.","Obchodování je založeno na členském principu."],"c":[0,1],"p":122,"e":"Jedná se o běžně zavedenou formu trhů s cennými papíry. OTC trhy bývají vstřícnější z časového hlediska a mají obvykle nižší obchodní poplatky.","tp":0},{"id":"19492.5","t":"m","q":"Prostředky Garančního fondu obchodníků s cennými papíry lze použít na:","o":["Náhrady plynoucí z neschopnosti obchodníka s cennými papíry splnit své závazky spočívající ve vydání majetku zákazníků zákazníkům, z důvodu přímo souvisejícího s jeho finanční situací.","Derivátové a pákové spekulace s cílem překonat benchmark a dosáhnout výnosu z kapitálového majetku.","Pouze na podporu obchodování státních strukturálních fondů.","Úhradu nákladů na činnost Garančního fondu."],"c":[0,3],"p":122,"e":"Fungování Garančního fondu obchodníků s cennými papíry je upraveno zákonem č. 256/2004 Sb., o podnikání na kapitálovém trhu. Dle § 128, odst. 13 mohou být peněžní prostředky Garančního fondu investovány pouze bezpečným způsobem, což rizikové napákované spekulace či spekulování s deriváty rozhodně nejsou.","tp":0},{"id":"19493.8","t":"m","q":"Na Burze cenných papírů Praha se obchodují:","o":["Akcie nebo obdobné cenné papíry představující podíl na společnosti nebo jiné právnické osobě.","Platební nástroje.","Strukturované produkty.","Dluhopisy nebo obdobné cenné papíry představující právo na splacení dlužné částky."],"c":[0,2,3],"p":122,"e":"Na Burze Cenných Papírů Praha se obchodují akcie, dluhopisy, investiční fondy, strukturované produkty a warranty. Platební nástroje se na burze neobchodují. Obchodované instrumenty jsou uvedeny na stránkách BCPP.","tp":0},{"id":"19494.3","t":"m","q":"Na Burze Cenných Papírů Praha jsou mj. tyto tržní segmenty:","o":["PCE market - pro termínované kontrakty na komodity.","Prime Market - pro akciové emise.","Standard Market - pro akciové emise.","SWAP Market - trh pro měnové a úrokové swapy."],"c":[1,2],"p":122,"e":"Na BCPP jsou tyto trhy: Prime Marekt, Standard Market a START Market a Free Market pro akcie, trhy dluhopisů a strukturovaných produktů. Termínované kontrakty na komodity, ani swapy se na BCPP neobchodují.","tp":4},{"id":"19495.5","t":"m","q":"Centrální depozitář cenných papírů (CDCP) je právnická osoba, která:","o":["Neprovádí vypořádání, ale je oprávněna vést centrální evidenci investičních nástrojů.","Provádí vypořádání, ale nevede centrální evidenci cenných papírů v České republice.","Je společností působící v oboru vypořádání obchodů s cennými papíry.","Vede centrální evidenci cenných papírů v České republice."],"c":[2,3],"p":123,"e":"V červenci 2010 CDCP převzal evidenci cenných papírů do té doby vedenou Střediskem cenných papírů. Investiční nástroje jsou v CD vedeny na účtech vlastníků nebo účtech zákazníků, kteří dále sami ve své evidenci vedou majetkové účty svých klientů. Činnost CD je regulována ČNB. Od 5.12.2017 se Centrální depozitář cenných papírů stal přímým účastníkem Euroclear Bank SA/NV a k 1. prosinci 2017 otevřel příslušné linky pro vypořádání.","tp":0},{"id":"19511.2","t":"m","q":"Posouzení (test) přiměřenosti pro účely poskytnutí hlavní investiční služby přijímaní a předávání pokynů týkající se investičních nástrojů:","o":["Slouží k posouzení, zda zákazník disponuje potřebnými zkušenostmi a znalostmi k tomu, aby porozuměl rizikům souvisejícím s nabízeným nebo poptávaným produktem či investiční službou.","Na základě jeho vyhodnocení je osoba poskytující inv. službu (OCP, IZ) povinna klientovi doporučit vhodný produkt.","Je předpokladem k řádnému poskytnutí investiční služby přijímání a předávání pokynů týkající se investičních nástrojů.","Jeho obsahem jsou dotazy na znalosti a zkušenosti v oblasti investic, finanční zázemí a investiční cíle klienta."],"c":[0,2],"p":123,"e":"Při poskytování hlavní inv. služby přijímání a předávání pokynů týkajících se investičních nástrojů (zprostředkování), je osoba poskytující inv. službu povinna požádat zákazníka o informace o jeho odborných znalostech v oblasti investic a zkušenostech v oblasti investic. Toto posouzení se označuje jako test přiměřenosti.","tp":0},{"id":"19512.1","t":"m","q":"Klient musí být v dostatečném předstihu před poskytnutím inv. služby informován:","o":["O investičních službách, které mu jsou poskytovány.","O investičních nástrojích, kterých se má poskytovaná služba týkat.","O tom, zda je inv. služba investiční poradenství poskytována nezávisle či nikoli.","O existenci, povaze a výši pobídky, případně způsobu jejího výpočtu, nelze-li její výši určit."],"c":[0,1,2,3],"p":123,"e":"Klient musí být v dostatečném časovém předstihu před poskytnutím inv. služby informován o údajích o osobě, která mu inv. služby poskytuje, o investičních službách, které tato osoba poskytuje, inv. nástrojích, kterých se má inv. služba týkat a veškerých nákladech a souvisejících úplatách. Osoba jednající se zákazníky je povinna informovat zákazníka v dostatečném časovém předstihu před poskytnutím inv. služby jasně, podrobně, přesně a srozumitelně o existenci, povaze a výši pobídky podle § 15 odst. 4, případně o způsobu jejího výpočtu, nelze-li její výši určit. Dále musí být mj. informován, zda osoba jednající se zákazníky tuto inv. službu poskytuje nezávisle nebo nikoli.","tp":6},{"id":"19513.1","t":"m","q":"V rámci kontroly (nikoliv identifikace) klienta (fyzické osoby) ve smyslu zákona č. 253/2008 Sb. povinná osoba:","o":["Ověří a zaznamená identifikační údaje z průkazu totožnosti.","Ověří shodu podoby s vyobrazením v průkazu totožnosti.","Přezkoumá zdroje peněžních prostředků nebo jiného majetku, kterého se daný obchod týká.","Zjistí informace o účelu a zamýšlené povaze obchodu."],"c":[2,3],"p":123,"e":"Kontrola klienta zahrnuje mj. získání informací o účelu a zamýšlené povaze obchodu nebo obchodního vztahu a přezkoumávání zdrojů peněžních prostředků nebo jiného majetku, kterého se obchod nebo obchodní vztah týká. První dvě odpovědi se vztahují k povinnosti identifikace klienta, nikoliv kontroly.","tp":8},{"id":"19514.2","t":"m","q":"Při poskytování investiční služby profesionálnímu zákazníkovi:","o":["se předpokládá, že profesionální zákazník má odborné znalosti a zkušenosti v oblasti investic k tomu, aby činil vlastní investiční rozhodnutí a vyhodnocoval rizika, která podstupuje v souvislosti s investiční službou","se předpokládá, že profesionální zákazník má finanční zázemí k tomu, aby podstupoval související investiční rizika, odpovídající jeho investičním cílům","se předpokládá, že profesionální zákazník má odborné znalosti a zkušenosti v oblasti investic k tomu, aby činil vlastní investiční rozhodnutí a vyhodnocoval rizika s tím spojená, jeho finanční zázemí a investční cíle se však musí posuzovat vždy","se předpokládá, že i profesionálnímu zákazníkovi je nutné poskytnout poučení o rizicích spojených s jeho investičním rozhodnutím"],"c":[0,1],"p":124,"e":"Má se za to, že profesionální zákazník uvedený v § 2a má odborné znalosti a zkušenosti v oblasti investic k tomu, aby činil vlastní investiční rozhodnutí a vyhodnocoval rizika, která podstupuje, a finanční zázemí k tomu, aby podstupoval související investiční rizika, odpovídající jeho investičním cílům.","tp":6},{"id":"19515.1","t":"m","q":"Vázaný zástupce může při poskytování investičních služeb zastupovat:","o":["Obchodníka s cennými papíry.","Investiční společnost.","Investiční fond.","Investičního zprostředkovatele."],"c":[0,1,3],"p":124,"e":"Vázaný zástupce může zastupovat obchodníka s cennými papíry, investičního zprostředkovatele, nebo investiční společnost, která má povolení k výkonu některé z činností uvedených v § 11 odst. 1 písm. c) až f) zákona č. 240/2013 Sb.","tp":0},{"id":"19516.1","t":"m","q":"V rámci identifikace klienta (fyzické osoby) ve smyslu zákona č. 253/2008 Sb. povinná osoba:","o":["Ověří a zaznamená identifikační údaje z průkazu totožnosti.","Ověří shodu podoby s vyobrazením v průkazu totožnosti.","Zaznamená druh a číslo průkazu totožnosti, stát, popřípadě orgán, který jej vydal, a dobu jeho platnosti.","Zjistí a zaznamená, zda klient není politicky exponovanou osobou."],"c":[0,1,2,3],"p":124,"e":"Při identifikaci klienta, který je fyzickou osobou, povinná osoba identifikační údaje zaznamená a ověří z průkazu totožnosti, jsou- li v něm uvedeny, a dále zaznamená druh a číslo průkazu totožnosti, stát, popřípadě orgán, který jej vydal, a dobu jeho platnosti; současně ověří shodu podoby s vyobrazením v průkazu totožnosti. Dále zjistí a zaznamená, zda klient není politicky exponovanou osobou.","tp":8},{"id":"19532.1","t":"m","q":"Výnos dluhopisu může být vyjádřen:","o":["Pevnou úrokovou sazbou.","Pohyblivou úrokovou sazbou odvozenou například z jiných úrokových sazeb nebo pohybu měnových kurzů.","Rozdílem mezi jmenovitou hodnotou a nižším emisním kurzem.","Rozdílem mezi jmenovitou hodnotou a vyšším emisním kurzem (uvažujeme-li pouze kladný výnos)."],"c":[0,1,2],"p":124,"e":"Výnos dluhopisu lze určit zejména: pevnou úrokovou sazbou, rozdílem mezi jmenovitou hodnotou dluhopisu a jeho nižším emisním kurzem, pohyblivou úrokovou sazbou odvozenou například z jiných úrokových sazeb či úrokových výnosů, pohybu měnových kurzů, finančních indexů či cen komodit.","tp":2},{"id":"19533.1","t":"m","q":"Česká národní banka v rámci výkonu dohledu nad kapitálovým trhem:","o":["Rozhoduje o žádostech o udělení licencí, povolení a registrací subjektů kapitálového trhu.","Kontroluje dodržování zákonů a vyhlášek v oblasti kapitálového trhu.","Rozhoduje spory mezi subjekty kapitálového trhu a spotřebiteli.","Vede řízení o přestupcích v oblasti kapitálového trhu a ukládá opatření k nápravě."],"c":[0,1,3],"p":125,"e":"Dohled mj. zahrnuje: rozhodování o žádostech o udělení licencí, povolení, registrací a souhlasů podle jiných právních předpisů, kontrolu dodržování zákonů a přímo použitelných předpisů Evropské unie, jestliže je k této kontrole Česká národní banka tímto zákonem nebo jinými právními předpisy zmocněna, a kontrolu dodržování vyhlášek vydaných Českou národní bankou, ukládání opatření k nápravě a správních trestů podle tohoto zákona nebo jiných právních předpisů, řízení o přestupcích.","tp":0},{"id":"19534.1","t":"m","q":"Emitentem dluhopisu může být za předpokladu splnění všech zákonných podmínek:","o":["Jakákoliv právnická nebo fyzická osoba.","Pouze obchodní společnost.","Územní samosprávný celek (kraj, obec).","V případě hypotečních zástavních listů banka."],"c":[0,2,3],"p":125,"e":"Zákon o dluhopisech nikde neomezuje, kdo může být emitentem dluhopisu.","tp":3},{"id":"19535.1","t":"m","q":"Kupon:","o":["Je cenný papír.","Je označení pro dluhopis používané v americkém právu.","Představuje právo na výnos z dluhopisu.","Slouží k převodu dluhopisu na nového majitele."],"c":[0,2],"p":125,"e":"Právo na výnos dluhopisu může být od dluhopisu odděleno a spojeno s kuponem jako cenným papírem nebo zaknihovaným cenným papírem vydaným k uplatnění tohoto práva.","tp":3},{"id":"19536.1","t":"m","q":"O hypotečním zástavním listu platí:","o":["Jedná se o cenný papír.","Jedná se o dluhopis.","Jeho emitentem může být pouze banka.","Jeho jmenovitá hodnota a poměrný výnos jsou kryty pohledávkami z hypotečních úvěrů."],"c":[0,1,2,3],"p":125,"e":"Hypoteční zástavní listy jsou dluhopisy, jejichž jmenovitá hodnota a poměrný výnos jsou plně nebo částečně kryty pohledávkami z hypotečních úvěrů. Hypoteční zástavní listy může vydávat pouze banka.","tp":3},{"id":"19537.1","t":"m","q":"Dohled nad kapitálovým trhem vykonávaný ze strany České národní banky zahrnuje:","o":["Vydávání zákonů a podzákonných právních předpisů (např. vyhlášek).","Provádění kontrol subjektů dohledu na dálku a na místě.","Ukládání opatření k nápravě a správních trestů subjektům dohledu v oblasti podnikání na kapitálovém trhu.","Vydávání bankovek a mincí."],"c":[1,2],"p":125,"e":"Dohled České národní banky v oblasti kapitálového trhu zahrnuje mj. kontrolu dodržování podmínek stanovených udělenými licencemi a povolením (vč. provádění kontrol subjektů dohledu na dálku a na místě), vedení řízení o přestupcích a ukládání opatření k nápravě a správních trestů. Vydávání zákonů a vyhlášek je předmětem regulace. Vydávání bankovek a mincí patří do působnosti ČNB, netýká se však oblasti dohledu nad kapitálovým trhem.","tp":0},{"id":"19553.1","t":"m","q":"Odstoupit od smlouvy lze (předpokládejme, že se nejedná o žádný specifický smluvní typ upravený zákonem, není-li v odpovědích uvedeno jinak):","o":["Vždy do 14 dnů od podpisu smlouvy.","Do 7 dnů v případě spotřebitelských smluv uzavíraných mimo obchodní prostory.","V případech, kdy si to smluvní strany ve smlouvě ujednají.","V případě podstatného porušení smlouvy jednou ze smluvních stran."],"c":[2,3],"p":126,"e":"Od smlouvy lze odstoupit, ujednají-li si to strany, nebo stanoví-li tak zákon. Poruší-li strana smlouvu podstatným způsobem, může druhá strana bez zbytečného odkladu od smlouvy odstoupit. Jedná-li se o spotřebitelské smlouvy uzavírané mimo obchodní prostory, má spotřebitel právo odstoupit od smlouvy ve lhůtě čtrnácti dnů.","tp":8},{"id":"19554.1","t":"m","q":"Neplatné je takové právní jednání (např. smlouva), které:","o":["Je v rozporu se zákonem.","Se příčí dobrým mravům.","Nebylo učiněno písemně.","Neobsahuje jednoznačnou identifikaci některé ze smluvních stran."],"c":[0,1],"p":126,"e":"Neplatné je právní jednání, které se příčí dobrým mravům, jakož i právní jednání, které odporuje zákonu, pokud to smysl a účel zákona vyžaduje.","tp":8},{"id":"19555.1","t":"m","q":"Škoda způsobená informací nebo radou dle § 2950 Občanského zákoníku:","o":["Může být způsobena pouze někým, kdo vystupuje jako příslušník určitého stavu či povolání nebo vystupuje jako odborník.","Může být způsobena odborníkem, který danou informaci nebo radu poskytuje za odměnu.","Může být způsobena neúplnou nebo nesprávnou informací nebo škodlivou radou.","Může být způsobena pouze nesprávnou informací nebo škodlivou radou."],"c":[0,1,2],"p":126,"e":"Kdo se hlásí jako příslušník určitého stavu nebo povolání k odbornému výkonu nebo jinak vystupuje jako odborník, nahradí škodu, způsobí-li ji neúplnou nebo nesprávnou informací nebo škodlivou radou danou za odměnu v záležitosti svého vědění nebo dovednosti. Jinak se hradí jen škoda, kterou někdo informací nebo radou způsobil vědomě.","tp":8},{"id":"19556.1","t":"m","q":"Právnická osoba:","o":["Je od svého vzniku do svého zániku způsobilá mít práva a povinnosti.","Nemůže být založena za jiným účelem nežli podnikání.","Vzniká dnem zápisu do veřejného rejstříku, pokud zákon nestanoví jinak.","Je organizovaným útvarem osob a/nebo majetku."],"c":[0,2,3],"p":126,"e":"Právnická osoba je organizovaný útvar osob nebo majetku, o kterém zákon stanoví, že má právní osobnost. Právnická osoba má právní osobnost od svého vzniku do svého zániku. Právnickou osobu lze ustavit ve veřejném nebo v soukromém zájmu. Právnická osoba vzniká dnem zápisu do veřejného rejstříku.","tp":8},{"id":"19557.1","t":"m","q":"Povinnost nahradit škodu:","o":["Nemůže vzniknout v důsledku porušení povinností ze smlouvy.","Nedopadá na toho, kdo při své činnosti použije zmocněnce či zaměstnance.","Spočívá v povinnosti škůdce uhradit poškozenému skutečnou škodu a dále to, co poškozenému ušlo.","Spočívá rovněž v povinnosti škůdce zprostit poškozeného dluhu, pokud skutečná škoda záležela ve vzniku dluhu poškozeného."],"c":[2,3],"p":127,"e":"Poruší-li strana povinnost ze smlouvy, nahradí škodu z toho vzniklou druhé straně nebo i osobě, jejímuž zájmu mělo splnění ujednané povinnosti zjevně sloužit. Kdo při své činnosti použije zmocněnce, zaměstnance nebo jiného pomocníka, nahradí škodu jím způsobenou stejně, jako by ji způsobil sám. Hradí se skutečná škoda a to, co poškozenému ušlo (ušlý zisk). Záleží-li skutečná škoda ve vzniku dluhu, má poškozený právo, aby ho škůdce dluhu zprostil nebo mu poskytl náhradu.","tp":8},{"id":"19558.1","t":"m","q":"Oprávněným zástupcem obchodní korporace (společnosti) je:","o":["Člen, případně členové statutárního orgánu.","Fyzická nebo právnická osoba na základě plné moci udělené ze strany obchodní korporace (společnosti).","Prokurista zapsaný v obchodním rejstříku.","Člen, případně členové kontrolního orgánu."],"c":[0,1,2],"p":127,"e":"Právnickou osobu zastupuje člen, případně členové statutárního orgánu, a to způsobem zapsaným do veřejného rejstříku. Právnická osoba může ke svému zastupování rovněž zmocnit fyzickou či právnickou osobu, přičemž rozsah zástupčího oprávnění uvede v plné moci. Udělením prokury pak právnická osoba zmocňuje prokuristu k právním jednáním, ke kterým dochází při provozu obchodního závodu.","tp":0},{"id":"19571.1","t":"m","q":"Fondem kvalifikovaných investorů může být:","o":["Podílový fond","Akciová společnost","Veřejná obchodní společnost","Komanditní společnost"],"c":[0,1,3],"p":127,"e":"ZISIF definuje přípustné formy fondu kvalifikovaných investorů. Veřejná obchodní společnost mezi nimi není.","tp":1},{"id":"19572.1","t":"m","q":"Uzavřený podílový fond:","o":["Musí být vždy označen slovy \"uzavřený podílový fond\".","Nesmí být na území Evropské unie nabízen.","Smí investovat pouze do vysoce likvidních aktiv.","Zpravidla vydává pouze omezený počet podílových listů."],"c":[0,3],"p":127,"e":"U otevřeného podílového fondu podílové listy odkoupením zanikají a noví vlastníci nabývají podílové listy zásadně originálně, tedy novými podílovými listy. U uzavřených podílových fondů, kde je omezeno právo na odkup podílových listů k tomu zpravidla nemůže dojít.","tp":1},{"id":"19573.1","t":"m","q":"Investičním fondem je:","o":["Standardní fond kolektivního investování.","Speciální fond kolektivního investování.","Fond kvalifikovaných investorů.","Účastnický penzijní fond."],"c":[0,1,2],"p":127,"e":"Účastnický fond je zřízen penzijní společností dle zákona č. 427/2011 o DPS, nespadá mezi investiční fondy kolektivního nebo kvalifikovaného investování.","tp":1},{"id":"19574.1","t":"m","q":"Exchange Traded Fund:","o":["Je akciový fond kolektivního investování, jehož podkladovým aktivem je burzovní akciový index.","Je možné koupit na sekundárním trhu burzy cenných papírů.","Je investiční nástroj sloužící výhradně pro kvalifikované investory.","Zpravidla nevyužívá aktivní investiční strategii spočívající v analýze a výběru konkrétních investičních nástrojů do portfolia."],"c":[1,3],"p":128,"e":"ETF je obchodován na burze cenných papírů (např. AMEX). Zpravidla se jedná o strategii pasivního kopírování vybraného indexu (akciového či jiného).","tp":4},{"id":"19587.1","t":"m","q":"Obhospodařovatelem investičního fondu může být:","o":["Investiční společnost.","Samosprávný investiční fond.","Obchodník s cennými papíry.","Ministerstvo financí ČR."],"c":[0,1],"p":128,"e":"Osobu obhospodařovatele definuje ZISIF.","tp":1},{"id":"19588.1","t":"m","q":"Předmětem podnikání investiční společnosti není:","o":["Obhospodařování investičních fondů.","Administrace investičních fondů.","Přijímání a předávání pokynů týkající se investičních nástrojů.","Poskytování lombardních úvěrů."],"c":[3],"p":128,"e":"Investiční společnost neposkytuje zákazníkům úvěry.","tp":1},{"id":"19589.1","t":"m","q":"Administrace investičního fondu zpravidla zahrnuje:","o":["Vedení účetnictví fondu.","Rozdělování a vyplácení výnosů z majetku tohoto fondu.","Compliance a vnitřní audit.","Vyhotovení a aktualizace výroční zprávy a pololetní zprávy tohoto fondu."],"c":[0,1,2,3],"p":128,"e":"Všechny tyto činnosti jsou definovány zákonem jako činnosti administrace fondu.","tp":1},{"id":"19590.1","t":"m","q":"Obhospodařovatel investičního fondu:","o":["Je regulován Zákonem o investičních společnostech a investičních fondech.","Spravuje majetek investičního fondu.","Provádí investování na účet fondu.","Řídí rizika spojená s investováním."],"c":[0,1,2,3],"p":128,"e":"Všechny tyto činnosti splňují definici obhospodařovatel fondu.","tp":1},{"id":"19603.2","t":"m","q":"Rizikový profil fondu:","o":["Vyjadřuje např. ukazatel SRRI (synthetic risk and reward indicator).","Ovlivňuje skladba investičních instrumentů v majetku fondu.","Je vždy přímo úměrný jeho nákladovosti.","Je uveden ve statutu fondu a nemusí tak být uveden ve Sdělení klíčových informacích."],"c":[0,1],"p":129,"e":"SRRI vyjadřuje rizikovost fondu na stupnici 1 - 7. Různé třídy aktiv mají různou rizikovost, vyjádřené svou volatilitou. Typicky akcie vyšší, nástroje peněžního trhu nižší. Nákladovost fondu nemusí mít nutně přímou souvislost s rizikovým profilem. Rizikový profil je nedílnou součástí Sdělení klíčových informací.","tp":1},{"id":"19604.1","t":"m","q":"Fond s volatilitou menší než 2,0 % může mít na stupnici SRRI hodnotu:","o":["1.","2.","3.","4."],"c":[0,1],"p":129,"e":"Stupnice SRRI je rozdělena podle historické volatility fondu. Horní hranice pro stupeň 1 je 0,5 %, pro stupeň 2 je hranice 2,0 %.","tp":1},{"id":"19605.1","t":"m","q":"Ukazatel SRRI:","o":["Je prezentován na rizikové stupnici s hodnotami 1 - 7.","Může být použit pro vyhodnocení vhodnosti fondu pro konkrétního investora.","Je pro každý fond vypočten na základě stejné metodiky a může sloužit pro porovnání rizikovosti dvou libovolných fondů.","Je povinnou součástí Sdělení klíčových informací."],"c":[0,1,2,3],"p":129,"e":"SRRI je ukazatel rizikovosti, součást KIID, je zobrazen na stupnici 1 - 7 a je pro každý fond vypočten na základě stejné metodiky.","tp":1},{"id":"19606.1","t":"m","q":"Mezi vyspělé akciové trhy jsou zpravidla zařazovány tyto země:","o":["USA.","Francie.","Japonsko.","Rusko."],"c":[0,1,2],"p":129,"e":"Vyspělými trhy jsou zpravidla chápány země západní Evropy, USA a Japonsko.","tp":2},{"id":"19620.1","t":"m","q":"Mezi ukazatele, jež vyjadřují rizikovost fondu patří:","o":["Volatilita.","Alfa.","Sharpe Ratio.","Beta."],"c":[0,2,3],"p":129,"e":"Alfa vyjadřuje výnos fondu dosažený v porovnání s referenčním trhem, Sharpe Ratio i Beta vychází z volatility, která představuje tržní riziko.","tp":7},{"id":"19621.1","t":"m","q":"Kreditní riziko:","o":["Je zpravidla spojováno s investicí do akcií.","Vyjadřuje riziko neschopnosti emitenta cenného papíru dostát svým závazkům.","Je vyšší u cenných papírů emitovaných v jiné měně než české koruně.","Neexistuje u emitentů, jako je stát nebo obec."],"c":[1],"p":130,"e":"Kreditní riziko spočívá v nesplacení jistiny cenného papíru.","tp":0},{"id":"19634.1","t":"m","q":"Statut fondu kolektivního investování nemusí obvykle obsahovat:","o":["Investiční strategii včetně investičních limitů.","Údaje nutné k identifikaci obhospodařovatele, administrátora a depozitáře fondu kolektivního investování.","Odhadovanou výkonnost fondu v tříletém, pětiletém a desetiletém horizontu.","Rizikový profil fondu."],"c":[2],"p":130,"e":"Statut fondu kolektivního investování je dokument, který obsahuje investiční strategii fondu kolektivního investování, popis rizik spojených s investováním tohoto fondu a další údaje nezbytné pro investory k zasvěcenému posouzení investice, zpracované formou srozumitelnou běžnému investorovi. Rozsah statutu je definován zákonem č. 240/2013 Sb..","tp":1},{"id":"19635.1","t":"m","q":"Fond kolektivního investování povinně vydává:","o":["Výroční zprávu.","Pololetní zprávu.","Sdělení klíčových informací.","Statut."],"c":[0,1,2,3],"p":130,"e":"Všechny tyto dokumenty má fond kolektivního investování za povinnost vydávat.","tp":1},{"id":"19636.1","t":"m","q":"Sdělení klíčových informací obsahuje:","o":["Informace o poplatcích fondu.","Informace o cíli a investiční politice fondu.","Informace o poměru rizika a výnosu fondu.","Informace o dosavadní výkonnosti."],"c":[0,1,2,3],"p":130,"e":"Všechny náležitosti Sdělení klíčových informací jsou definovány Nařízením komise.","tp":1},{"id":"19637.1","t":"m","q":"Sdělení klíčových informací obsahuje informaci o:","o":["Maximální výši vstupního poplatku.","Maximální výši výstupního poplatku.","Minimální výši vstupního poplatku.","Minimální výši výstupního poplatku."],"c":[0,1],"p":130,"e":"Nařízení komise definuje prezentaci poplatků jako nejvyšší možné procento, které může být investorovi strženo.","tp":1},{"id":"19650.1","t":"m","q":"Mezi cenné papíry kolektivního investování patří:","o":["Podílový list.","Dluhopis.","Investiční akcie.","Komanditní list."],"c":[0,2],"p":131,"e":"Podílový list a investiční akcie jsou cenné papíry, které vydávají fondy kolektivního investování (podílové fondy a akciové společnosti). Dluhopis ani komanditní list neslouží ke kolektivnímu investování.Cennými papíry kolektivního investování jsou cenné papíry představující podíl na investičních fondech nebo zahraničních investičních fondech.","tp":2},{"id":"19651.2","t":"m","q":"Pozastavit vydávání nebo odkupování může obhospodařovatel otevřeného podílového fondu:","o":["Maximálně po dobu tří měsíců (nejedná-li se o fond investující do nemovitostí).","Z důvodu ochrany práv podílníků či z provozních důvodů, zejména ve vztahu k činnostem souvisejícím s účetní závěrkou.","Kdykoliv bez udání důvodu.","Pouze na příkaz administrátora fondu."],"c":[0,1],"p":131,"e":"Dle zákona o investičních společnostech a investičních fondech může obhospodařovatel rozhodnout o pozastavení vydávání nebo odkupování podílových listů otevřeného podílového fondu jen, je-li to nezbytné z důvodu ochrany práv nebo právem chráněných zájmů podílníků nebo též z provozních důvodů, zejména ve vztahu k činnostem souvisejícím s účetní závěrkou.","tp":1},{"id":"19652.1","t":"m","q":"S podílovými listy je spojeno právo na:","o":["Podíl na zisku investičního fondu.","Podíl na zisku obhospodařovatele investičního fondu.","Podíl na likvidačním zůstatku investičního fondu.","Podíl na likvidačním zůstatku obhospodařovatele investičního fondu."],"c":[0,2],"p":131,"e":"Práva spojená s držbou podílového listu jsou definována zákonem. Základním právem je podíl na zisku, popř. likvidačního zůstatku fondu.","tp":1},{"id":"19653.1","t":"m","q":"Podílový list:","o":["Může mít zaknihovanou podobu.","Lze vždy nakoupit na burze cenných papírů.","Představuje podíl podílníka na podílovém fondu.","Je cenným papírem."],"c":[0,2,3],"p":131,"e":"Podílový list je cenný papír nebo zaknihovaný cenný papír, který představuje podíl podílníka na podílovém fondu a se kterým jsou spojena práva podílníka plynoucí z tohoto zákona nebo ze statutu podílového fondu.","tp":1},{"id":"19656.2","t":"m","q":"Mezi základní součásti řídicího a kontrolního systému obhospodařovatele investičního fondu patří:","o":["Strategické a operativní řízení.","Systém řízení rizik.","Systém vnitřní kontroly.","Vytváření marketingových kampaní pro podporu prodeje."],"c":[0,1,2],"p":131,"e":"Marketingové kampaně nejsou definovány jako součást řídicích a kontrolních systémů zákonem.","tp":1},{"id":"19668.2","t":"m","q":"Depozitář investičního fondu je povinen zejména:","o":["Opatrovat majetek investičního fondu.","Evidovat pohyb peněžních prostředků fondu.","Vyhotovovat a aktualizovat výroční zprávy a pololetní zprávy fondu.","Vyřizovat stížnosti a reklamace investorů."],"c":[0,1],"p":132,"e":"Činnosti depozitáře jsou definovány zákonem o investičních společnostech a investičních fondech.","tp":1},{"id":"19682.1","t":"m","q":"S investováním do investičních fondů může být spojen:","o":["Vstupní poplatek.","Poplatek za správu.","Výkonnostní poplatek.","Výstupní poplatek."],"c":[0,1,2,3],"p":132,"e":"Všechny tyto typy poplatků jsou běžnou součástí investování do fondů. Vstupní a výstupní poplatek při nákupu či prodeji a poplatek za správu a výkonnostní poplatek jako průběžná odměna obhospodařovateli.","tp":1},{"id":"19683.1","t":"m","q":"Do nákladů fondu kolektivního investování lze zahrnout:","o":["Náklady na audit účetní závěrky fondu.","Mzdové náklady portfolio manažera fondu.","Náklady na nabízení investic do tohoto fondu.","Úplatu za obhospodařování fondu."],"c":[0,1,3],"p":132,"e":"Náklady na propagaci a nabízení investic jsou zákonem definovány jako Nezahrnované náklady.","tp":1},{"id":"19684.3","t":"m","q":"Poplatek z dosažené výkonnosti fondu nad referenční hodnotu:","o":["Je označován jako výkonnostní poplatek (success fee či performance fee).","Je účtován při prodeji akcií či podílových listů fondu.","Je určen jako podíl z poplatku za správu.","Může být účtován u fondů kolektivního investování i u fondů kvalifikovaných investorů."],"c":[0,3],"p":132,"e":"Poplatek z nadvýkonnosti, neboli performance / success fee, je možno účtovat u všech druhů investičních fondů.","tp":1},{"id":"19685.1","t":"m","q":"Vstupní poplatek:","o":["Je hrazen investorem nakupujícím podílové listy či akcie fondu.","Nesmí být účtován distributorem fondu vyšší než připouští statut fondu.","Může být účtován při nákupu podílových listů či akcií fondu v různé výši v závislosti na ceníku různých distributorů.","Nesmí být účtován v případě, že fond aplikuje též výstupní poplatek."],"c":[0,1,2],"p":132,"e":"Maximální výše vstupního poplatku je stanovena Statutem fondu a zveřejněna v KIID. Hradí jej investor při nákupu fondu. Přesná výše se řídí ceníkem konkrétních distributora.","tp":1},{"id":"19699.3","t":"m","q":"Investiční cenné papíry obchodovatelné na kapitálovém trhu jsou zejména:","o":["Akcie nebo obdobné cenné papíry představující podíl na společnosti nebo jiné právnické osobě.","Dlouhodobé dluhopisy nebo obdobné cenné papíry představující právo na splacení dlužné částky.","Cenné papíry nahrazující cenné papíry definované jako akcie nebo obdobné cenné papíry představující podíl na společnosti nebo jiné právnické osobě.","Cenné papíry opravňující k nabytí nebo zcizení investičních cenných papírů definované jako akcie nebo obdobné cenné papíry představující podíl na společnosti nebo jiné právnické osobě."],"c":[0,1,2,3],"p":133,"e":"Ustanovuje tak zákon o podnikání na kapitálovém trhu (ZPKT) č. 256/2004 Sb, § 3, odst. 2 .","tp":0},{"id":"19700.1","t":"m","q":"Mezi finanční aktiva patří dle zavedené klasifikace:","o":["Hotovost.","Majetkové finanční nástroje.","Dluhové nástroje.","Výrobní faktory."],"c":[0,1,2],"p":133,"e":"Historická zvyklost na trzích, obsahuje odborná literatura.","tp":2},{"id":"19714.1","t":"m","q":"Pro státní dluhopis platí, že ho vydává:","o":["Česká republika, a to v České republice i v zahraničí.","Česká republika prostřednictvím ministerstva financí.","Česká republika na základě zákona o dluhopisech.","Česká republika prostřednictvím regulovaného trhu."],"c":[0,1,2],"p":133,"e":"Znění zákona.","tp":3},{"id":"19715.1","t":"m","q":"Pro podnikové (korporátní) dluhopisy platí, že:","o":["Výplata výnosů závisí na solventnosti emitenta.","Se mezi ně nepočítají dluhopisy vydané městy.","Nemusí mít zveřejněný prospekt.","Musí být splatné do 15 let."],"c":[0,1],"p":133,"e":"Dluhopisy vydané bankami se nazývají finanční dluhopisy, v případě insolvence se výnosy nevyplácejí.","tp":3},{"id":"19716.1","t":"m","q":"Dluhopis je označen jako vyměnitelný (konvertibilní), pokud je s ním spojeno právo na jeho výměnu za:","o":["Jiný dluhopis téhož emitenta.","Akcie téhož emitenta.","Derivát, jehož podkladovým aktivem je akcie téhož emitenta.","Dividendu, vyplácenou majitelům akcií téhož emitenta."],"c":[0,1],"p":133,"e":"Znění zákona.","tp":3},{"id":"19717.1","t":"m","q":"Pokud je dluhopis vydán jako podřízený:","o":["Musí být tato skutečnost vyznačena na listině nebo v evidenci.","Tato vlastnost se zohlední při vstupu emitenta do likvidace.","V případě úpadku emitenta mají přednost pohledávky majitelů dluhopisů, které nejsou podřízené.","Musí být tato skutečnost známa již při emisi tohoto dluhopisu."],"c":[0,1,2,3],"p":134,"e":"Znění zákona.","tp":3},{"id":"19730.1","t":"m","q":"Sběrný dluhopis je:","o":["Listinný dluhopis, kde podíl jednotlivých vlastníků je dán počtem upsaných dluhopisů.","Společným vlastnictvím podílníků na tomto sběrném dluhopisu.","Považován za samostatnou emisi.","Listinný dluhopis, kde není možné vlastnictví převést na jinou osobu."],"c":[0,1,2],"p":134,"e":"Znění zákona.","tp":3},{"id":"19731.1","t":"m","q":"Schůze vlastníků dluhopisů musí být svolána, pokud se emitent rozhodne pro:","o":["Změnu emisních podmínek.","Stažení dluhopisů z obchodování na regulovaném trhu.","Změnu, která ovlivní schopnost splácet.","Změnu, která je jako důvod pro svolání uvedena v emisních podmínkách."],"c":[0,1,2,3],"p":134,"e":"Znění zákona.","tp":3},{"id":"19732.1","t":"m","q":"Schůzi vlastníků dluhopisů může svolat:","o":["Vlastník dluhopisu.","Emitent dluhopisu.","Dozorový orgán.","Provozovatel regulovaného trhu, kde je dluhopis obchodován."],"c":[0,1],"p":134,"e":"Znění zákona.","tp":3},{"id":"19733.4","t":"m","q":"Jako dluhopisový program označujeme dluhopisy mající:","o":["Společné emisní podmínky.","Společného emitenta.","Společný ISIN.","Společné výnosy."],"c":[0,1],"p":134,"e":"Znění zákona.","tp":3},{"id":"19746.1","t":"m","q":"Investiční certifikát typově patří mezi:","o":["Dluhové cenné papíry.","Investiční cenné papíry.","Zastupitelné cenné papíry.","Kapitálové cenné papíry."],"c":[0,1,2],"p":135,"e":"IC je investiční nástroj dle §3 ZPKT, jsou obchodovány na burzách (lze pouze zastupitelné CP).","tp":0},{"id":"19747.2","t":"m","q":"Perpetuitní dluhové cenné papíry:","o":["Zpravidla přinášejí investorovi výnos v podobě výplaty úroků.","Nemají v emisních podmínkách určen termín splatnosti.","Nepatří mezi krátkodobé dluhopisy.","Patří mezi dluhové investiční nástroje."],"c":[0,1,2,3],"p":135,"e":"Jde o dluhopisy (tj. přinášejí pravidelný výnos), jejichž základní vlastností je, že v emisních podmínkách není termín splatnosti, nejsou časově ohraničené, tudíž nemohou patřit mezi krátkodobé dluhopisy.","tp":2},{"id":"19748.3","t":"m","q":"Mezi dluhové cenné papíry patří:","o":["Směnky.","Obligace.","Indosamenty.","Swapy."],"c":[0,1],"p":135,"e":"Indosament a swap nepatří mezi dluhové cenné papíry.","tp":0},{"id":"19749.1","t":"m","q":"Právo vyplývající z prioritního dluhopisu je možné uplatnit:","o":["Ve lhůtě stanovené emitentem.","Na místě stanoveném emitentem.","V Centrálním depozitáři cenných papírů.","Kdykoliv po dobu existence tohoto dluhopisu."],"c":[0,1],"p":135,"e":"Právo vyplývající z prioritního dluhopisu je možné uplatnit ve lhůtě stanovené emitentem a na místě stanoveném emitentem.","tp":3},{"id":"19758.1","t":"m","q":"Akcie se řadí mezi:","o":["Investiční cenné papíry.","Investiční nástroje.","Nástroje peněžního trhu.","Nástroje, jejichž hodnota se vztahuje k hodnotě jiného nástroje."],"c":[0,1],"p":135,"e":"Znění zákona.","tp":2},{"id":"19759.1","t":"m","q":"Akcie jsou obchodovatelné:","o":["Na kapitálovém trhu.","Na českém trhu i zahraničním trhu.","Na regulovaných i neregulovaných trzích.","Pouze na veřejném trhu."],"c":[0,1,2],"p":136,"e":"Znění zákona.","tp":2},{"id":"19760.1","t":"m","q":"Rozhodný den pro výplatu podílu na zisku (tzv. dividendy):","o":["Je den stanovený valnou hromadou za dodržení zákonných podmínek.","Může být rozhodný den pro účast na valné hromadě, která o dividendě rozhoduje.","Musí předcházet dni výplaty dividendy.","Je první pracovní den, který bezprostředně následuje po dni konání valné hromady."],"c":[0,1,2],"p":136,"e":"Znění zákona.","tp":4},{"id":"19761.3","t":"m","q":"Akcie zaručuje svému majiteli právo na:","o":["Účast na valné hromadě.","Výplatu dividendy.","Zpětné odkoupení ze strany emitenta.","Obchodování na regulovaném trhu."],"c":[0,1],"p":136,"e":"Znění zákona.","tp":4},{"id":"19774.1","t":"m","q":"Pokud se týká převoditelnosti, tak zatímní listy:","o":["Jsou převoditelné.","Jsou převoditelné rubopisem.","Jsou převoditelné, může však být nutný souhlas orgánu společnosti.","Jsou převoditelné, ale pouze se souhlasem Centrálního depozitáře cenných papírů, který vede evidenci."],"c":[0,1,2],"p":136,"e":"Znění zákona.","tp":4},{"id":"19775.1","t":"m","q":"Zatímní list se řadí mezi:","o":["Investiční cenné papíry.","Investiční nástroje.","Cenné papíry na řad.","Cenné papíry představující podíl na společnosti."],"c":[0,1,2,3],"p":136,"e":"Znění zákona.","tp":4},{"id":"19776.1","t":"m","q":"Majitel daných Global Depositary Receipt (GDR) má právo na:","o":["Výplatu dividendy, úpis nových akcií.","Obchodování s GDR, výplatu dividendy.","Výplatu dividendy, účast na valné hromadě.","Úpis nových akcií, účast na valné hromadě."],"c":[0,1],"p":137,"e":"GDR jsou ekvivalentem vlastnictví akcií, s výjimkou práva účasti na valné hromadě.","tp":4},{"id":"19777.4","t":"m","q":"S Global Depository Receipt (GDR) lze obchodovat na trzích:","o":["Sekundárních.","Veřejných.","Primárních.","Komoditních."],"c":[0,1],"p":137,"e":"Global Depository Receipts (GDR) nejsou předmětem primárního úpisu, jde o obchodovatelné CP.","tp":10},{"id":"19802.1","t":"m","q":"Z následujících kontraktů je existujícím druhem swapu:","o":["Úrokový swap.","Regulární swap.","Americký swap.","Měnový swap."],"c":[0,3],"p":137,"e":"Úrokový a měnový swap jsou standardní swapy.","tp":5},{"id":"19803.1","t":"m","q":"Pro který z následujících instrumentů je charakteristická platba prémie:","o":["Opce.","Swapu.","Forwardu.","Credit default swapu (CDS)."],"c":[0,3],"p":137,"e":"Opce a CDS dávají investorovi při jejich nákupu právo nikoli povinnost plnění, za toto právo zaplatí investor příslušnou prémii.","tp":5},{"id":"19804.1","t":"m","q":"Mezi podkladová aktiva opcí patří z níže uvedených:","o":["Akcie.","Úrokové sazby .","Komodity.","Měny."],"c":[0,1,2,3],"p":137,"e":"Všechna uvedená aktiva jsou standardními podkladovými aktivy opcí.","tp":5},{"id":"19805.1","t":"m","q":"Z následujících možností je existujícím druhem opce:","o":["Africká opce.","Americká opce.","Asijská opce.","Evropská opce."],"c":[1,2,3],"p":138,"e":"Americká, evropská i asijská opce existují na rozdíl od africké opce.","tp":5},{"id":"19841.1","t":"m","q":"Ke spekulaci na vzrůst ceny podkladového aktiva lze využít z nabízených kontraktů:","o":["Nákup call opce.","Nákup put opce.","Long forward.","Short forward."],"c":[0,2],"p":138,"e":"V případě nákupu call opce nebo pozice long forward dojde v budoucnu k nákupu za předem stanovenou cenu, tedy vzrůst ceny podkladového aktiva vede k zisku z těchto pozic.","tp":5},{"id":"19842.1","t":"m","q":"Nákup call opce s sebou nese následující výnosy a rizika:","o":["Neomezené riziko ztráty.","Omezené riziko ztráty.","Dosažení zisku při vzrůstu ceny podkladového aktiva.","Dosažení zisku při poklesu ceny podkladového aktiva."],"c":[1,2],"p":138,"e":"Nákupem call opce spekuluje investor na vzrůst ceny podkladového aktiva, přičemž nese omezené riziko ztráty ve výši prémie, kterou za opci zaplatil.","tp":5},{"id":"19843.1","t":"m","q":"Hodnota opce závisí z nabízených možností na:","o":["Volatilitě podkladového aktiva.","Ceně podkladového aktiva.","Realizační ceně (strike price).","Očekávaném výnosu podkladového aktiva."],"c":[0,1,2],"p":138,"e":"Hodnota opce závisí ceně podkladového aktiva, realizační ceně, volatilitě, době do splatnosti a úrokové míře.","tp":5},{"id":"19844.1","t":"m","q":"Nákup put opce s sebou nese následující výnosy a rizika:","o":["Omezené riziko ztráty.","Neomezené riziko ztráty.","Zisk při vzrůstu ceny podkladového aktiva.","Zisk při poklesu ceny podkladového aktiva."],"c":[0,3],"p":138,"e":"Put opce poskytuje výnos při poklesu tržní ceny podkladového aktiva, výše ztráty je maximálně ve výši zaplacené prémie.","tp":5},{"id":"19949.2","t":"m","q":"Státní pokladniční poukázka:","o":["Je typickým instrumentem obchodovaným na peněžním trhu.","Je určena neomezenému okruhu investorů.","Je určena pouze omezenému okruhu investorů.","Emituje se prostřednictvím aukce."],"c":[0,2,3],"p":139,"e":"Státní pokladniční poukázky emituje ministerstvo financí prostřednictvím centrální banky pouze tzv. přímým účastníkům aukce, formou aukce (ČNB využívá holandskou aukci). Jedná se o cenné papíry se splatností do jednoho roku.","tp":3},{"id":"19950.1","t":"m","q":"Nástrojem obchodovaným na peněžním trhu je z níže uvedených:","o":["Směnka vlastní.","Směnka cizí.","Akcie.","Opce."],"c":[0,1],"p":139,"e":"Obecně se obchodují krátkodobé cenné papíry, nejčastěji směnky, šeky, státní pokladniční poukázky.","tp":3},{"id":"19951.2","t":"m","q":"Charakteristické pro české státní pokladniční poukázky je:","o":["Obchodování na diskontním principu.","Emise prostřednictvím aukce.","Emise pomocí SEO.","Emise pomocí IPO."],"c":[0,1],"p":139,"e":"Státní pokladniční poukázky se za standardních podmínek emitují za cenu nižší než je jejich nominální hodnota. Výše diskontu potom představuje pro investora zisk. SPP se emitují přímým účastníkům formou aukce.","tp":3},{"id":"19965.1","t":"m","q":"Perpetuitní dluhopis (konzola):","o":["Patří mezi kuponové dluhopisy.","Patří mezi diskontované dluhopisy.","Má časově omezenou splatnost.","Nemá časově omezenou splatnost."],"c":[0,3],"p":139,"e":"Konzola představuje časově neohraničený kuponový dluhopis. Tzn. jedná se o dluhopis, který \"do nekonečně\" vyplácí kuponové platby.","tp":3},{"id":"19968.1","t":"m","q":"Ratingové hodnocení:","o":["Hodnotí schopnost dlužníka dostát svým závazkům.","Hodnotí míru kreditního rizika emitenta či emise.","Hodnotí pravděpodobnost dosažení daného výnosu.","Hodnotí směrodatnou odchylku investice."],"c":[0,1],"p":139,"e":"Ratingové hodnocení udává schopnost dlužníka (emitenta) splácet své závazky. Se zhoršujícím se ratingem roste kreditní riziko, resp. pravděpodobnost toho, že dlužník (emitent) nebude schopen dostát svým závazkům, např. hradit dle stanoveného harmonogramu kuponové platby a ve splatnosti vyplatit nominální hodnotu.","tp":3},{"id":"19996.1","t":"m","q":"Zdanění podléhá příjem v podobě:","o":["Dividendy vyplacené v souvislosti s vlastnictvím akcií.","Úroků vyplacených v souvislosti s vlastnictvím dluhopisů.","Podílu na zisku vyplaceného v souvislosti s vlastnictvím obchodního podílu ve společnosti s ručením omezeným.","Zisku z prodeje cenných papírů zahrnutých do obchodního majetku poplatníka."],"c":[0,1,2,3],"p":140,"e":"Zdanění podléhají příjmy plynoucí z kapitálového majetku, jedná se jak o běžné příjmy (dividendy, úroky z dluhopisů), tak i příjmy plynoucí z kapitálového výnosu (bez ohledu na dobu držby), pokud jsou či byly zařazeny do obchodního majetku.","tp":2},{"id":"19995.2","t":"m","q":"Zisk z prodeje cenných papírů není osvobozen od daně z příjmu:","o":["Pokud má poplatník, fyzická osoba, cenné papíry zahrnuty do obchodního majetku.","Pokud poplatník je fyzická osoba, nemá cenné papíry zahrnuty do obchodního majetku, ale mezi nákupem a prodejem uplynula doba kratší než 3 roky a příjem z prodeje přesáhne ve zdaňovacím období 100 000 Kč.","Pokud poplatník je fyzická osoba, nemá cenné papíry zahrnuty do obchodního majetku, ale jedná se o cenné papíry kolektivního investování.","Pokud se jedná o dluhopisy, které nemají zpracován a ČNB schválen prospekt."],"c":[0,1],"p":140,"e":"Od daně z příjmu je osvobozen příjem z úplatného převodu cenných papírů a příjmy z podílů připadajících na podílové listy při zrušení podílového fondu, pokud jejich úhrn u poplatníka nepřesáhne ve zdaňovacím období částku 100000 Kč. Osvobození se nevztahuje na příjmy z kapitálového majetku a na příjmy z úplatného převodu cenných papírů nebo z podílů připadajících na podílové listy při zrušení podílového fondu, které jsou nebo byly zahrnuty do obchodního majetku. Osvobození se vztahuje na příjem z úplatného převodu cenného papíru, přesáhne-li doba mezi nabytím a úplatným převodem tohoto cenného papíru při jeho úplatném převodu dobu 3 let. Osvobození se nevztahuje na příjem z úplatného převodu cenného papíru, který je nebo byl zahrnut do obchodního majetku, a to do 3 let od ukončení činnosti, ze které plyne příjem ze samostatné činnosti, a na příjem z kapitálového majetku.","tp":0},{"id":"20021.1","t":"m","q":"Které z uvedených atributů představují základní definiční znaky veřejné nabídky investičních cenných papírů:","o":["Nabídka obsahuje informace o nabízených investičních cenných papírech a podmínkách jejich nabytí.","Nabídka obsahuje dodatečné informace k tomu, aby investor učinil rozhodnutí koupit nebo upsat dané investiční cenné papíry.","Nabídka je činěna s využitím jak tištěných, tak i internetových médií.","Nabídka je oznámena České národní bance ve lhůtě 10 pracovních dnů od jejího zahájení."],"c":[0,1],"p":140,"e":"Hlavním znakem veřejné nabídky investičních cenných papírů je, že se jedná o jakékoli sdělení širšímu okruhu osob obsahující informace o nabízených investičních cenných papírech a podmínkách pro jejich nabytí, které jsou dostatečné k tomu, aby investor učinil rozhodnutí koupit nebo upsat tyto investiční cenné papíry. Není povinnost informovat o veřejné nabídce ČNB.","tp":0},{"id":"20022.2","t":"m","q":"Funkcí sekundárního trhu cenných papírů je především zajištění:","o":["Omezení přístupu třetích osob k investičním nástrojům.","Ochrany emitentů před zneužitím práv menšinových akcionářů.","Likvidity investičních nástrojů.","Vzniku transparentních cen investičních nástrojů."],"c":[2,3],"p":140,"e":"Na rozdíl od primárního trhu, který propojuje emitenty a invstory, kdy cenný papír na primárním trhu nalezne svého prvonabyvatele a peněžní toky od investorů plynou přímo k emitentům \"výměnou\" za cenné papíry, je základním úkolem a smyslem existence sekundárního trhu, především umožnit obchodování, resp. likviditu. V okamžiku, kdy se cenný ppaír obchoduje nas ekundárním trhu vzniká nabídka a poptávka a díky tomu se formuje cena. navíc na hlavním segmentu sekundárního trhu (prime market) fungují tzv. market makeři, díky kterým je zajištěna likvidita investičního nástroje v době, kdy by neexistovala protistrana obchdu, resp. pokud by nikdo z invesorů nechtěl kupovat či prodávat.","tp":2},{"id":"20023.1","t":"m","q":"Podle toho, zda se obchoduje s novými, či s již dříve vydanými cennými papíry rozlišujeme","o":["Primární trhy cenných papírů.","Sekundární trhy cenných papírů.","Zahraniční trhy cenných papírů.","OTC-trhy cenných papírů."],"c":[0,1],"p":141,"e":"Rozdělení trhů podle toho, zda se na nich obchoduje s nově vydávanými nebo s již vydanými cennými papíry.","tp":0},{"id":"20024.1","t":"m","q":"Které z uvedených organizovaných veřejných trhů pro obchodování s investičními nástroji jsou vymezeny v příslušných právních předpisech:","o":["Regulovaný trh.","Mnohostranný obchodní systém.","Alternativní trh.","Volný trh."],"c":[0,1],"p":141,"e":"Veřejným trhem je trh organizovaný burzou cenných papírů nebo jinou právnickou osobou, která k tomu má povolení. Podle zákona o podnikání na kapitálovém trhu mezi tyto trhy patří regulovaný trh a mnohostranný obchodní systém.","tp":2},{"id":"20037.2","t":"m","q":"Emisní podmínky musí obsahovat (přímo či ve formě odkazu na prospekt) následující informace:","o":["Mezinárodní identifikátor investičního nástroje ISIN, pokud je dané emisi přidělen.","Emisní kurz dluhopisů či způsob, jakým bude emisní kurz určen.","Datum nebo jiný okamžik splacení emise dluhopisů.","Místo a čas konání pravidelných schůzí vlastníků dluhopisů."],"c":[0,1,2],"p":141,"e":"Emisní podmínky musejí obsahovat označení emitenta, údaje o dluhopisech, nominální hodnotu dluhopisu, datum splacení, datum emise, lhůtu pro upisování, zda se jedná o listinný či zaknihovaný dluhopis, informace, jak bude dluhopis splacen, jaký bude emisní kurz, identifikační označení dluhopisů a další.","tp":3},{"id":"20038.3","t":"m","q":"Dluhové cenné papíry:","o":["Představují nárok na navrácení zapůjčených peněžních prostředků a na dohodnutý úrok.","Představují doklad o zapůjčení peněžních prostředků.","Dělí na krátkodobé, střednědobé a dlouhodobé.","Jejich majitelé jsou společníky, resp. (spolu)vlastníky příslušné společnosti."],"c":[0,1,2],"p":141,"e":"Dluhové cenné papíry v sobě ztělesňují dluh (závazek) emitenta vyplatit v době splatnosti dluhového nástroje jeho nominální hodnotu a případně pod dobu životnosti vyplácet věřiteli (investorovi) úrokové platby, např. v podobě kuponů (pokud se jedná o kuponový dluhopis). Dluhové nástroje mohou být krátkodobé (směnky, státní pokladniční poukázky) a obchodované na peněžním trhu nebo se může jednat o střednědobé či dlouhodobé dluhopisy (kuponové či diskontované), obchodované na kapitálovém trhu. Investor do dluhového nástroje se stává pouze věřitelem emitenta, nikoli spoluvlastníkem společnosti, jako je tomu v případě majetkových cenných papírů.","tp":0},{"id":"20039.1","t":"m","q":"Ve smyslu ekonomického rozlišení investic mezi finanční investice patří:","o":["Poskytnutí půjčky/úvěru.","Nákup akcie.","Nákup dluhopisů.","Nákup nemovitostí."],"c":[0,1,2],"p":141,"e":"Finanční investice jsou charakteristické tím, že se u nich jedná o kombinaci vlastností peněz, majetkových aktiv a dluhových instrumentů.","tp":2},{"id":"20040.1","t":"m","q":"Jaké informace můžete standardně nalézt v prospektu vyhotoveném pro veřejné nabízení akcií:","o":["Rizikové faktory a informace o rizikových faktorech.","Informace o podnikatelské či jiné činnosti emitenta a jeho hlavních trzích.","Údaje o akciích a jejich nabídce.","Predikce finančních výkazů emitenta pro období nadcházejících 3 let."],"c":[0,1,2],"p":142,"e":"Mezi informace, které lze nalézt v prospektu lze zařadit především informace o emitentovi, finanční údaje a ukazatele, rizikové faktory, trendy v odvětví či údaje o cenných papírech (např. práva na dividendy).","tp":4},{"id":"20053.2","t":"m","q":"Emitent investičního nástroje přijatého k obchodování na regulovaný trh v rámci plnění svých zákonných informačních povinností uveřejňuje:","o":["Výroční zprávu.","Informace o konání valné hromady či schůze vlastníků daného investičního nástroje.","Daňové přiznání.","Investiční doporučení."],"c":[0,1],"p":142,"e":"Emitent cenného papíru má informační povinnost jak vůči burze, tak vůči investorům. Tato povinnost je průběžná (povinnost zveřejňovat kurzotvorné informace) a periodická - uveřejnění pololetní a výroční zprávy, kdy výroční zprávu uveřejňuje do 4 měsíců po skončení svého účetního období.","tp":2},{"id":"20054.1","t":"m","q":"Vyberte co neplatí o zasvěcené osobě:","o":["Může na svůj účet nebo na účet třetí osoby nabýt nebo zcizit finanční nástroj, jehož se vnitřní informace týká.","Nemusí zachovávat mlčenlivost o vnitřní informaci.","Může učinit jiné osobě doporučení k nabytí nebo zcizení finančního nástroje, kterého se vnitřní informace týká.","Musí zachovávat mlčenlivost o vnitřní informace a zamezit jiné osobě přístup k této informaci."],"c":[0,1,2],"p":142,"e":"Viz. znění zákona.","tp":6},{"id":"20055.1","t":"m","q":"Jakou informaci mimo jiných vždy naleznete ve výroční zprávě emitenta akcií se sídlem v České republice přijatých k obchodování na regulovaný trh v České republice:","o":["Účetní závěrku nebo konsolidovanou účetní závěrku.","Zprávu auditora v plném znění.","Investiční analýzu předmětných akcií vypracovanou nezávislým analytikem.","Seznam akcionářů."],"c":[0,1],"p":142,"e":"Výroční zpráva musí kromě informací nezbytných pro naplnění účelu výroční zprávy dále obsahovat nejméně finanční a nefinanční informace o skutečnostech, které nastaly až po rozvahovém dni a jsou významné pro naplnění účelu výroční zprávy, o předpokládaném vývoji činnosti účetní jednotky, o aktivitách v oblasti výzkumu a vývoje, o nabytí vlastních akcií nebo vlastních podílů, o aktivitách v oblasti ochrany životního prostředí a pracovněprávních vztazích, o tom, zda účetní jednotka má pobočku nebo jinou část obchodního závodu v zahraničí či informace požadované podle zvláštních právních předpisů. Výroční zpráva obsahuje vždy účetní závěrku, příp. konsolidovanou účetní závěrku.","tp":4},{"id":"20056.1","t":"m","q":"Jaké jsou definiční znaky tzv. vnitřní informace týkající se emitenta veřejně obchodovatelného investičního cenného papíru?","o":["Jedná se o neuveřejněnou informaci.","Jedná se o informaci, která pokud bude uveřejněna, může mít významný dopad na cenu daného investičního cenného papíru.","Jedná se o informaci přesné povahy.","Jedná se o informaci, jejíž uveřejnění je zakázáno na základě rozhodnutí orgánu veřejné správy."],"c":[0,1,2],"p":143,"e":"Vnitřní informace (insider information) je taková informace, která nebyla uveřejněna, týká se přímo nebo nepřímo jednoho nebo několika emitentů nebo jednoho nebo několika finančních nástrojů a která, pokud by byla zveřejněna, by pravděpodobně měla významný dopad na ceny těchto finančních nástrojů.","tp":0},{"id":"20069.1","t":"m","q":"Investičním poradenstvím se rozumí:","o":["Poskytnutí individualizovaného doporučení zákazníkovi ohledně obchodu s konkrétním investičním nástrojem.","Poskytnutí individualizovaného doporučení obchodu s investičním nástrojem bez ohledu na to, zda je poskytováno z podnětu zákazníka nebo obchodníka s cennými papíry nebo investičního zprostředkovatele.","Jen obecné doporučení týkající se investičních nástrojů poskytnuté obchodníkem s cennými papíry.","Jen obecné doporučení zákazníkovi investičním zprostředkovatelem, neboť ten nemůže podle zákona poskytovat doporučení týkající se konkrétního investičního nástroje."],"c":[0,1],"p":143,"e":"Investiční doporučení může poskytovat obchodník s cennými papíry i investiční zprostředkovatel, vždy se však musí jednat o individualizované doporučení vztahující se k obchodu s konkrétním investičním nástrojem, jinak by se jednalo o informování o kapitálovém trhu a ne o poradenství.","tp":0},{"id":"20070.1","t":"m","q":"Povinnost obchodníka s cennými papíry provádět pokyny zákazníka za nejlepších podmínek znamená zohlednit:","o":["Cenu investičního nástroje.","Celkový objem poplatků.","Rychlost provedení pokynu.","Objem obchodu."],"c":[0,1,2,3],"p":143,"e":"Provedení pokynu za nejlepších podmínek pro zákazníka zohledňuje zejména výhodnou cenu investičního nástroje, celkové náklady pro zákazníka, s ohledem na měnící se cenu investičních nástrojů v čase i dobu provedení pokynu a další faktory, které nelze v zákoně vyčerpávajícím způsobem vyjmenovat.","tp":0},{"id":"20071.1","t":"m","q":"Co znamená termín \"kotace\"?","o":["Závazky k nákupu a prodeji akcií uvádějící cenu, za nichž jsou tvůrci trhu připraveni je koupit.","Závazky k určitému objemu nákupu a prodeje akcií.","Závazek klienta k nákupu akcií.","Přijetí cenného papíru k obchodování na trhu."],"c":[0,1],"p":143,"e":"Jedná se o jeden ze základních pojmů používaný v oblasti obchodních systémů, je uváděný v dokumentech ČNB i Burzy cenných papírů Praha a jedná se o závazek tvůrců trhu k nákupu nebo prodeji akcií co do ceny i objemu.","tp":4},{"id":"20072.1","t":"m","q":"Regulovaný trh musí splňovat následující podmínky:","o":["Je to trh s investičními nástroji organizovaný organizátorem regulovaného trhu na základě povolení ČNB.","Na tomto trhu se obchoduje pravidelně.","Tento trh má stanovena pravidla pro přijímání investičních nástrojů a pravidla přístupu na regulovaný trh.","Na tento trh musí mít zajištěn přístup retailoví klienti."],"c":[0,1,2],"p":144,"e":"Požadavky na regulovaný trh jsou stanoveny zákonem, a to jak v oblasti požadavku na registraci ČNB pro organizátora, tak v oblasti pravidelného obchodování a stanovení pravidel (přijímání investičních nástrojů, pravidla obchodování, pravidla přístupu na tento trh). Odpověď d) je chybná, protože zákon neukládá zajistit přístup retailových klientů.","tp":0},{"id":"20085.1","t":"m","q":"Mezi doplňkové investiční služby lze zahrnout:","o":["Poradenská činnost týkající se struktury kapitálu.","Investiční výzkum.","Devizové služby související s poskytováním investičních služeb.","Provozování mnohostranného obchodního systému."],"c":[0,1,2],"p":144,"e":"Doplňkové investiční služby jsou činnosti povolované obchodníkům s cennými papíry vedle některé hlavní investiční služby, kdy obchodník s cennými papíry musí mít povolení alespoň k jedné hlavní investiční službě.","tp":0},{"id":"20086.1","t":"m","q":"Doplňkovou investiční službou není:","o":["Přijímání a předávání pokynů zákazníka.","Provádění pokynů na účet zákazníka.","Obchodování s investičními nástroji na vlastní účet.","Investiční poradenství týkající se investičních nástrojů."],"c":[0,1,2,3],"p":144,"e":"Jedná se o hlavní investiční služby.","tp":0},{"id":"20087.1","t":"m","q":"Mezi doplňkové investiční služby patří poradenská činnost:","o":["Týkající se struktury kapitálu.","Průmyslové strategie.","Poskytování porad týkajících se přeměn společností.","Poskytování porad týkajících se nabytí účasti v obchodní korporaci."],"c":[0,1,2,3],"p":144,"e":"Mezi doplňkové investiční služby byly zahrnuty všechny uvedené činnosti.","tp":0},{"id":"20088.1","t":"m","q":"Mezi doplňkové investiční služby nepatří:","o":["Obchodování s investičními nástroji na vlastní účet.","Provozování organizovaného obchodního systému.","Úschova a správa investičních nástrojů.","Finanční analýza nebo jiné formy obecných doporučení týkajících se obchodování s investičními nástroji."],"c":[0,1],"p":144,"e":"Hlavní i doplňkové investiční služby jsou v zákoně o podnikání na kapitálovém trhu taxativně vymezeny.","tp":0},{"id":"20101.3","t":"m","q":"Postupy a metodiku pro zjišťování a řízení střetu zájmů musí vytvářet:","o":["Obchodník s cennými papíry.","Investiční zprostředkovatel.","Organizátor regulovaného trhu.","Vázaný zástupce."],"c":[0,1,2],"p":145,"e":"V zákoně č. 256/2004 Sb. je uvedena povinnost mít postupy pro zjišťování a řízení střetu zájmů u obchodníka s cennými papíry, investičního zprostředkovatele a organizátora regulovaného trhu. Vázaný zástupce může být fyzická nebo právnická osoba, za jehož činnost odpovídá obchodník s cennými papíry nebo investiční zprostředkovatel jako hlavní druhy zastoupených osob, kdy vázaný zástupce se musí řídit jejich postupy a pokyny.","tp":0},{"id":"20102.2","t":"m","q":"Jakými způsoby může vzniknout střet zájmů u obchodníka s cennými papíry?","o":["Obchodník s cennými papíry dosáhne zisku na úkor zákazníka.","Obchodník s cennými papíry upřednostní svoje zájmy před zájmy zákazníka nebo skupiny zákazníků.","Obchodník s cennými papíry má zájem na výsledku stejného obchodu jako zákazník, přičemž se jejich zájmy liší.","Obchodník s cennými papíry předejde svým ztrátám na úkor zákazníků."],"c":[0,1,2,3],"p":145,"e":"Obchodník s cennými papíry musí konkretizovat postupy pro zjišťování a řízení střetu zájmů, odpovědi jsou typickými příklady střetu zájmů představující konkretizaci ve vnitřních předpisech obchodníků s cennými papíry.","tp":0},{"id":"20103.2","t":"m","q":"Jaké jsou možné projevy střetu zájmů u investičního zprostředkovatele?","o":["Může získat finanční prospěch na úkor zákazníka.","Může se vyhnout finanční ztrátě na úkor zákazníka.","Má odlišný zájem na výsledku obchodu zprostředkovaného pro zákazníka od zájmu tohoto zákazníka.","Upřednostňuje z nějakého důvodu zájem jednoho zákazníka před zájmem jiného zákazníka."],"c":[0,1,2,3],"p":145,"e":"Podstatou řízení střetu zájmů je ochrana zákazníka před ztrátami v důsledku finančního prospěchu obchodníka s cennými papíry, jeho pracovníků a vázaných zástupců. Jde o konkretizaci § 11a ve světle dříve publikovaných metodických stanovisek ČNB. Investiční zprostředkovatel musí konkretizovat postupy pro řízení střetu zájmů, odpovědi jsou typickými příklady střetu zájmů.","tp":0},{"id":"20104.2","t":"m","q":"Co zahrnuje řízení střetu zájmů obchodníka s cennými papíry?","o":["Postupy pro zjišťování a zamezování střetu zájmů a jejich oznamování zákazníkům.","Postupy pro řízení střetu zájmů mezi obchodníkem s cennými papíry, jeho vázanými zástupci, pracovníky a zákazníky obchodníka s cennými papíry.","Postupy pro řízení střetu zájmů mezi obchodníkem s cennými papíry, jeho vázanými zástupci, pracovníky a potenciálními zákazníky obchodníka s cennými papíry.","Postupy pro řízení střetu zájmů mezi zákazníky obchodníka s cennými papíry."],"c":[0,1,2,3],"p":145,"e":"Obchodník s cennými papíry musí konkretizovat postupy pro zjišťování a řízení střetu zájmů, odpovědi jsou typickými příklady střetu zájmů představující konkretizaci ve vnitřních předpisech obchodníků s cennými papíry.","tp":0},{"id":"20117.1","t":"m","q":"Jaké povinnosti má investiční zprostředkovatel v oblasti evidence majetku zákazníků za účelem ochrany majetku zákazníka?","o":["Vést elektronickou evidenci přijatých a předaných pokynů týkajících se investičních nástrojů.","Vést elektronickou evidenci smluv týkajících se poskytovaných investičních služeb.","Uchovávat záznamy a dokumenty týkající se investičních služeb a obchodů pro účely kontroly Českou národní bankou.","Informovat Českou národní banku zasíláním evidence o převodech na platebních účtech zákazníků."],"c":[0,1,2],"p":146,"e":"Ochraně majetku zákazníků je věnována pozornost zejména z pohledu případného zneužití investičních nástrojů nebo peněžních prostředků zákazníků, popř. i nesprávného použití těchto investičních nástrojů. Proto jsou na něj mj. v oblasti evidence kladeny obdobné požadavky jako na obchodníka s cennými papíry.","tp":0},{"id":"20118.2","t":"m","q":"Pro osoby zastupující investičního zprostředkovatele při jednání se zákazníkem při poskytování investičních služeb platí:","o":["Může jít o pracovníka investičního zprostředkovatele splňujícího požadavky na odbornou způsobilost.","Může jít o vázaného zástupce splňujícího požadavky na odbornou způsobilost.","Může jít o člena správní rady investičního zprostředkovatele.","Musí jít o pracovníka, který složil maturitní zkoušku."],"c":[0,1,2,3],"p":146,"e":"Investiční zprostředkovatel může být v rámci poskytování investičních služeb zastoupen pouze svým pracovníkem nebo vázaným zástupcem. Tito musí mít všeobecné a odborné znalosti a dovednosti. Všeobecné znalosti se prokazují vysvědčením o maturitní zkoušce nebo dokladem o dosažení vyššího vzdělání, odborné znalosti a dovednosti se prokazují osvědčením o úspěšném vykonání odborné zkoušky.","tp":0},{"id":"20119.1","t":"m","q":"Základní zásady pro evidenci majetku zákazníků jsou:","o":["Zajištění soustavné a jednoznačné identifikace investičních nástrojů zákazníků.","Zajištění soustavné a jednoznačné identifikace peněžních prostředků zákazníků.","Odlišení majetku drženého pro jednoho zákazníka od majetku ostatních zákazníků.","Odlišení majetku drženého pro zákazníky od vlastního majetku obchodníka s cennými papíry."],"c":[0,1,2,3],"p":146,"e":"Ochrana majetku zákazníků spočívá v přesné evidenci a odlišení majetku jednotlivých zákazníků i jejich odlišení od majetku obchodníka s cennými papíry.","tp":0},{"id":"20120.1","t":"m","q":"Jaká je činnost Garančního fondu obchodníků s cennými papíry?","o":["Zajišťuje výplatu náhrad zákazníkům obchodníků s cennými papíry, kteří nejsou schopni plnit své dluhy vůči svým zákazníkům.","Přijímá příspěvky od obchodníků s cennými papíry.","Zajišťuje ověřování nároků na vyplacení náhrad z Garančního fondu.","Postupuje při své činnosti podle předpisů o pojišťovnictví."],"c":[0,1,2],"p":146,"e":"Garanční fond je právnická osoba zabezpečující záruční systém, ze kterého se vyplácejí náhrady zákazníkům obchodníka s cennými papíry, který není vůči nim schopen platit své dluhy, přijímá příspěvky od obchodníků s cennými papíry a zajišťuje agendu výplat, přitom se neřídí právními předpisy upravujícími pojišťovnictví.","tp":0},{"id":"20133.1","t":"m","q":"V souvislosti s nabízeným investičním nástrojem a investiční službou musí obchodník s cennými papíry zajistit:","o":["Dodržování požadavků týkajících se vhodnosti investičního nástroje nebo služby pro určený cílový trh.","Kontrolu systému nabízení investičního nástroje osobou vykonávající kontrolu dodržování právních předpisů (compliance).","Kontrolu systému nabízení investičního nástroje vedoucím orgánem obchodníka s cennými papíry.","Dostatečnou odbornou znalost jeho pracovníků týkající se vlastnosti nabízených investičních nástrojů, rizik s nimi spojených a určeného cílového trhu."],"c":[0,1,2,3],"p":147,"e":"Konkretizace povinností obchodníka s cennými papíry při jednání se zákazníky stanoví kromě věcných povinností i organizační povinnosti týkající se kontroly ze strany compliance a zapojení vedoucího orgánu do kontroly a dále povinnost zajistit odborné znalosti pracovníků dostatečné pro nabízení a doporučování investičních nástrojů a poskytování služeb.","tp":0},{"id":"20134.1","t":"m","q":"Jaké opatření zavede obchodník s cennými papíry vytvářející investiční nástroj nabízený zákazníkům?","o":["Zajistí, aby jeho vedoucí orgán měl kontrolu nad systémem vytváření a nabízení investičních nástrojů.","Zajistí, aby zprávy o dodržování právních povinností určených pro vedoucí orgán měly dostatek informací o vytvářených investičních nástrojích.","Zajistí informování dozorčí rady o konkrétních investičních obchodech.","Zajistí informování externího auditora před provedením obchodů s vytvořenými investičními nástroji."],"c":[0,1],"p":147,"e":"Systém obezřetného poskytování investičních služeb se vztahuje i na vytváření investičních nástrojů, přičemž je stanovena odpovědnost vedoucího orgánu obchodníka s cennými papíry mít informace a kontrolu nad procesem vytváření a nabízení investičních nástrojů.","tp":0},{"id":"20135.1","t":"m","q":"K jakým investičním nástrojům je oprávněn investiční zprostředkovatel poskytovat investiční služby?","o":["Cenné papíry kolektivního investování vydávané fondy kolektivního investování nebo fondy kvalifikovaných investorů, popř. srovnatelnými zahraničními investičními fondy.","Dluhopisy vydané Českou republikou.","Hypoteční zástavní listy.","Dluhopisy, ke kterým byl vydán prospekt."],"c":[0,1,2,3],"p":147,"e":"V zákoně o podnikání na kapitálovém trhu jsou taxativně vyjmenovány investiční nástroje, k jejichž zprostředkování je investiční zprostředkovatel oprávněn.","tp":0},{"id":"20136.1","t":"m","q":"Za jakých podmínek lze veřejně nabízet investice do investičního fondu v ČR?","o":["Lze je nabízet za podmínek stanovených zákonem o investičních společnostech a investičních fondech a jen tehdy, je-li fond zapsán v seznamu vedeném Českou národní bankou.","Lze je nabízet jen občanům ČR.","Lze je nabízet jen kvalifikovaným investorům za podmínek stanovených zákonem o podnikání na kapitálovém trhu.","Lze je nabízet za podmínek stanovených zákonem o investičních společnostech a investičních fondech, přitom se nepožaduje, aby byl fond zapsán v seznamu vedeném Českou národní bankou, to platí jen pro zahraniční investiční fondy."],"c":[0],"p":147,"e":"Veřejné nabízení investic do investičních fondů je umožněno za podmínek stanovených zákonem o investičních společnostech a investičních fondech za podmínky zapsání investičního fondu do příslušného seznamu vedeného Českou národní bankou.","tp":1},{"id":"20149.1","t":"m","q":"Obchodník s cennými papíry musí v dostatečném předstihu před poskytnutím investiční služby informovat zákazníka o","o":["Údajích o své osobě.","Poskytovaných investičních službách.","Investičních nástrojích, kterých se má investiční služba týkat a navrhovaných strategiích.","Veškerých nákladech a souvisejících úplatách."],"c":[0,1,2,3],"p":148,"e":"Zákon ukládá povinnosti o základních informacích pro zákazníky ex anté, aby zákazník získal na úvod informaci o obchodníkovi a předmětu obchodu.","tp":0},{"id":"20150.1","t":"m","q":"Jaké informace je třeba získat o zákazníkovi při poskytování obhospodařování jeho majetku a investičním poradenství ohledně investičních nástrojů?","o":["Odborné znalosti zákazníka v oblasti investic.","Zkušenosti zákazníka v oblasti investic.","Finanční zázemí zákazníka.","Investiční cíle zákazníka."],"c":[0,1,2,3],"p":148,"e":"Distributor investičních nástrojů musí zjišťovat, zda investiční produkt odpovídá potřebám zákazníka, včetně jeho investičních cílů, přitom sleduje zájmy zákazníka.","tp":1},{"id":"20151.1","t":"m","q":"Při posuzování úplaty a nákladů za investiční nástroj obchodník s cennými papíry zejména bere v úvahu","o":["Zda je úplata slučitelná s potřebami a cíli cílového trhu.","Zda úplata nezhoršuje očekávanou výnosnost investičního nástroje.","Zda je struktura úplaty přiměřeně transparentní a srozumitelná pro cílový trh.","Zda úplata nezahrnuje žádnou skrytou složku."],"c":[0,1,2,3],"p":148,"e":"Prováděcí právní předpis stanovuje demonstrativně požadavky na charakter a strukturu úplat za investiční nástroj.","tp":0},{"id":"20152.1","t":"m","q":"V jakých případech je přípustná pobídka?","o":["Jestliže má přispět ke zlepšení kvality poskytované investiční služby.","Jestliže umožňuje poskytování investiční služby nebo je pro tento účel nutná.","Jestliže přijetí nebo poskytnutí pobídky není v rozporu s povinností poskytovat investiční služby s odbornou péčí.","Jestliže si zákazník platí individuální přístup ze strany obchodníka s cennými papíry."],"c":[0,1,2],"p":148,"e":"Zákon o podnikání na kapitálovém trhu taxativně určuje podmínky, za nichž je pobídka přípustná s další konkretizací v prováděcím právním předpisu.","tp":0},{"id":"20165.1","t":"m","q":"Zákazník může právo na náhradu škody způsobené vázaným zástupcem investičního zprostředkovatele v souvislosti s kolektivním investováním uplatnit:","o":["U investičního zprostředkovatele.","Podáním finančnímu arbitrovi, pokud před tím neuspěl u investičního zprostředkovatele a věc současně nepodal k soudu.","U soudu.","U České národní banky."],"c":[0,1,2],"p":148,"e":"Za škodu zodpovídá IZ, náhrady se lze domáhat u něho, ale i u finančního arbitra či u soudu. ČNB nemůže zákazníkovi přiznat náhradu škody.","tp":0},{"id":"20166.1","t":"m","q":"Návrh zákazníka podaný finančnímu arbitrovi obsahuje mimo jiné:","o":["Označení účastníků řízení.","Doklad o tom, že instituce byla neúspěšně vyzvána k nápravě.","Označení, čeho se navrhovatel domáhá.","Doklad o zaplacení poplatku za podání návrhu."],"c":[0,1,2],"p":149,"e":"Upraveno zákonem 229/2002 Sb. , řízení je bezplatné. Podání musí předcházet neúspěšné oslovení instituce, v návrhu je třeba označit instituci a zákazníka jako účastníky řízení a musí být specifikováno, čeho se zákazník domáhá.","tp":6},{"id":"20167.1","t":"m","q":"Finanční arbitr odmítne podání:","o":["Od zákazníka, který je právnickou osobou.","Od zákazníka - fyzické osoby, který využil investiční službu v rámci své podnikatelské činnosti.","Směřující proti investičnímu zprostředkovateli.","Směřující proti obchodníkovi s cennými papíry."],"c":[0,1],"p":149,"e":"Finanční arbitr může rozhodovat pouze spory instituce se spotřebitelem, právnická osoba ani fyzická osoba jednající v rámci svého podnikání nejsou spotřebitelem.","tp":0},{"id":"20180.1","t":"m","q":"Na náhradu z Garančního fondu obchodníků s cennými papíry nemá mimo další subjekty nárok:","o":["Územní samosprávný celek.","Právnická osoba.","Osoba, která v souvislosti s legalizací výnosů z trestné činnosti svěřila obchodníkovi s cennými papíry, jehož zákazníkům se vyplácí náhrada z Garančního fondu, prostředky získané trestným činem.","Osoba, která trestným činem způsobila neschopnost obchodníka s cennými papíry, jehož zákazníkům se vyplácí náhrada z Garančního fondu, splnit své závazky vůči zákazníkům."],"c":[0,2,3],"p":149,"e":"Na náhradu z Garančního fondu nemá nárok Česká konsolidační agentura, územní samosprávný celek, resp. Garanční fond pozastaví výplatu náhrad zákazníkovi, který je podezřelý ze spáchání trestného činu, který způsobil neschopnost obchodníka s cennými papíry splnit své závazky vůči zákazníkům, a to po dobu trestního řízení vedeného proti této osobě či zákazníkovi, jehož majetek může souviset s legalizací výnosů z trestné činnosti.","tp":0},{"id":"20181.2","t":"m","q":"Riziko, že obhospodařovatel standardního podílového fondu nedostojí svým závazkům vůči zákazníkům, snižuje:","o":["Dohled nezávislého depozitáře","Oddělení majetku obhospodařovatele od majetku zákazníků.","Povinné pojištění obhospodařovatele.","Garanční fond obhospodařovatelů fondů."],"c":[0,1],"p":149,"e":"Majetek je chráněn systémovými opatřeními, nikoliv však garančním systémem.","tp":1},{"id":"20182.1","t":"m","q":"Garanční fond obchodníků s cennými papíry:","o":["Zajišťuje ověřování nároků na výplatu náhrad.","Zajišťuje výplatu náhrad.","Informuje ČNB o výši příspěvků, které obchodníci s cennými papíry zaplatili za kalendářní rok.","Přijímá příspěvky od obchodníků s cennými papíry."],"c":[0,1,2,3],"p":150,"e":"Garanční fond obchodníků s cennými papíry slouží především pro ochranu retailového klienta a pomáhá stabilizovat trh v oblasti poskytování záruk klientům. Garanční fond totiž zabezpečuje záruční systém, ze kterého se vyplácejí náhrady zákazníkům obchodníka s cennými papíry, který není schopen plnit své dluhy vůči svým zákazníkům. Garanční fond přijímá příspěvky od obchodníků s cennými papíry, zajišťuje ověřování nároků klientů na vyplácení náhrad a zajišťuje i vlastní vyplácení náhrad. Rovněž ale má informační povinnost vůči ČNB, kterou informuje o výši příspěvků, které jednotliví obchodníci s cennými papíry zaplatili za příslušný kalendářní rok.","tp":0},{"id":"20183.1","t":"m","q":"Pro Garanční fond obchodníků s cennými papíry platí:","o":["Není státním fondem.","Nevztahují se na něho právní předpisy upravující pojišťovnictví.","Je právnickou osobou.","Za jeho závazky ručí Česká národní banka."],"c":[0,1,2],"p":150,"e":"Garanční fond je právnickou osobu, která zabezpečuje záruční systém, ze kterého se vyplácejí náhrady zákazníkům obchodníka s cennými papíry, který není schopen plnit své dluhy vůči svým zákazníkům. Garanční fond se zapisuje do obchodního rejstříku. Garanční fond není státním fondem. Na Garanční fond se nevztahují právní předpisy upravující pojišťovnictví.","tp":0},{"id":"20200.1","t":"m","q":"Co je typické pro strategii průměrování nákladů (dollar cost averaging):","o":["Investor pravidelně investuje stejnou částku.","V době poklesu cen investor kupuje větší množství cenných papírů.","V době poklesu cen investor investuje větší částky než v době růstu cen.","V době poklesů cen roste celkový zisk investora."],"c":[0,1],"p":150,"e":"Dollar-cost averaging je známá i jako strategie pravidelného investování. Investor při ní investuje stále stejnou částku a díky tomu kupuje více levných podílových listů v době poklesu a méně drahých podílových listů v době růstu cen. V době poklesu cen zisk investora klesá (klesá tržní hodnota jeho investice).","tp":7},{"id":"20201.1","t":"m","q":"Klientovi je 35 let a chce si naspořit peníze na zajištění příjmů poté, co odejde do důchodu. Vhodnými investičními nástroji jsou:","o":["Fondy peněžního trhu.","Fondy životního cyklu.","Akciové fondy.","Doplňkové penzijní spoření."],"c":[1,2,3],"p":150,"e":"Jde o dlouhodobý investiční horizont. Vhodnými nástroji jsou fondy životního cyklu, akciové fondy i doplňkové penzijní spoření. Nevýhodou fondů peněžního trhu je jejich velmi nízká výnosnost v dlouhodobém horizontu.","tp":1},{"id":"20202.3","t":"m","q":"Pro financování menší havárie v koupelně (např. rozbitý bojler) je vhodné využít:","o":["Prostředky z akciového fondu investované do něj před 2 lety.","Prostředky ze stavebního spoření, založeného před 4 lety.","Prostředky, které má klient na spořicím účtu.","Prostředky z krátkodobé rezervy."],"c":[2,3],"p":151,"e":"Jedná se o menší havárii, kterou lze hradit z krátkodobé rezervy či prostředku na spořicím účtu klienta. Rozhodně není vhodné vypovídat stavební spoření, kde by klient musel vracet zálohy na státní příspěvek či nedávno založený akciový fond, který má dlouhodobý investiční horizont.","tp":7},{"id":"20203.1","t":"m","q":"Fond DELTA je nabízen ve 2 třídách: dividendové a růstové. Vyberte správné odpovědi:","o":["Kurz růstové třídy fondu poroste rychleji než dividendová třída fondu.","Kurz dividendové třídy fondu poroste rychleji než kurz růstové třídy fondu.","Volatilita dividendové třídy fondu bude vyšší než volatilita růstové třídy fondu.","Volatilita růstové třídy fondu bude vyšší než volatilita dividendové třídy fondu."],"c":[0,3],"p":151,"e":"Dividendový fond vyplácí dividendy investorům, růstový je reinvestuje. Proto kurz růstového fondu roste rychleji než kurz dividendového. Vyplácené dividendy přispívají k nižší volatilitě (část výnosu investor obdrží již nyní).","tp":1},{"id":"20204.2","t":"m","q":"Podílové fondy by měl investor do svého portfolia vybírat podle následujících kritérií:","o":["Vysoká obrátkovost portfolia fondu.","Nízká nákladovost (TER, ongoing charge) fondu.","Vysoká výnosnost za předchozí jeden rok.","Dostupné a relevantní informace o fondu a jeho správci."],"c":[1,3],"p":151,"e":"Při výběru fondů by měl investor mj. sledovat nákladovost fondu a zda jsou dostupné relevantní informace. Vysoká obrátkovost je nevýhodou, podle vysoké historické výnosnosti by se neměl investor rozhodovat, loňští vítězové často končí v dalších letech v poli poražených.","tp":1},{"id":"20205.2","t":"m","q":"Které fondy jsou vhodné pro konzervativní složku portfolia?","o":["Akciový fond s měnovým zajištěním.","Akciový fond bez měnového zajištění.","Fondy peněžních trhů.","Dluhopisový fond investující do českých státních dluhopisů."],"c":[2,3],"p":151,"e":"Do konzervativní složky portfolia patří fondy peněžních trhů a dluhopisové fondy, ne akciové.","tp":1},{"id":"20237.2","t":"m","q":"Která z následujících možností označuje investiční ratingový stupeň (investment grade) dle agentury S&P:","o":["A","BBB+","BBB","BB"],"c":[0,1,2],"p":151,"e":"Ratingy vyjadřují názor ratingové agentury ohledně úvěrového rizika daného subjektu (např. emitenta, státu...) nebo názor ohledně kvality daného dluhopisu). Jako investiční stupeň (investment grade) se označují dluhopisy s ratingem S&P od stupně BBB- a vyšší.","tp":3},{"id":"20238.1","t":"m","q":"Očekáváme, že v příštím roce nastane růst úrokových sazeb. Jakým dluhopisům se vyhneme, pokud chceme omezit úrokové riziko?","o":["Diskontní firemní dluhopis se splatností 1 rok.","Firemní dluhopis s fixním kupónem a splatností 5 let","Státní dluhopis s variabilním kupónem a splatností 5 let.","Státní dluhopis s fixním kupónem a splatnosti 10 let."],"c":[1,3],"p":152,"e":"Pokud očekáváme růst sazeb v příštím roce, nechceme dluhopisy s fixním kupónem a durací delší než 1 rok. Diskontní dluhopis do jednoho roku je maturuje před růstem sazeb a variabilní dluhopis se růstu sazeb přizpůsobí.","tp":3},{"id":"20239.1","t":"m","q":"Mezi časté chyby investorů do akciových fondů patří:","o":["Nakupují, když P/E akciového trhu je 30.","Nakupují, když P/E akciového trhu je 5.","Prodávají, když P/E akciového trhu je 30.","Prodávají, když P/E akciového trhu je 5."],"c":[0,3],"p":152,"e":"Je-li P/E akciového trhu 5, jsou akcie levné. Tehdy by měl investor kupovat, ne prodávat. Při P/E 30 jsou akcie drahé, tehdy by měl investor prodávat, ne kupovat.","tp":4},{"id":"20241.1","t":"m","q":"Kreditní riziko vyjadřuje:","o":["Riziko úpadku emitenta akcií.","Riziko nesplnění závazků ze strany emitenta dluhopisů.","Riziko zastavení výplaty dividend emitentem akcií.","Riziko ztráty časové hodnoty peněz."],"c":[0,1],"p":152,"e":"Kreditní riziko vyjadřuje riziko ztráty investované částky do akcií nebo dluhopisů.","tp":3},{"id":"20242.1","t":"m","q":"Vhodnými třídami aktiv schopnými dlouhodobě eliminovat riziko inflace jsou:","o":["Nemovitosti.","Peněžní trh.","Dluhopisy.","Akcie."],"c":[0,3],"p":152,"e":"Riziko inflace s vysokou pravděpodobností jsou schopny eliminovat akcie, nemovitosti a komodity (zde neuvedené). Pevně úročené cenné papíry (dluhopisy a pen. trh) v inflačním prostředí ztrácejí hodnotu.","tp":2},{"id":"20271.2","t":"m","q":"Vyberte všechny správné dílčí informace týkající se pojištění vkladů u bank v ČR.","o":["V ČR jsou pojištěny všechny neanonymní vklady fyzických a právnických osob vedené v českých korunách. Nejsou ale pojištěny např. pohledávky z vkladů bank a dalších finančních institucí.","V ČR jsou pojištěny všechny neanonymní vklady fyzických a právnických osob včetně vkladů vedených v cizí měně. Nejsou ale pojištěny např. pohledávky z vkladů bank a dalších finančních institucí.","Výše náhrady se vypočítá z celkového objemu pojištěných pohledávek z vkladů jednotlivého vkladatele u dotčené banky nebo družstevní záložny a poskytuje se ve výši 100 % tohoto objemu, maximálně však do výše ekvivalentu 100 000 EUR pro jednoho vkladatele u jedné banky nebo družstevní záložny.","Vklady u zahraničních bank z členských států Evropské unie, resp. Evropského hospodářského prostoru, jsou pojištěny stejným způsobem jako vklady v ČR, ale vždy u příslušného fondu ve státě sídla zahraniční banky."],"c":[0,1,2,3],"p":153,"e":"V možnostech bankovní regulace a dohledu v tržních podmínkách není a nemůže zabránit krachu každé banky nebo družstevní záložny (\"úvěrová instituce\"). K zajištění, aby případné ukončení činnosti úvěrové instituce mělo minimální dopady především na drobné klienty bank, slouží pojištění pohledávek z vkladů, které je upraveno zákonem o bankách.","tp":2},{"id":"20272.1","t":"m","q":"Vyberte všechny správné informace k tématu poskytování náhrad z Garančního fondu obchodníků s cennými papíry:","o":["Fond vyplatí nejvýše částku v korunách českých odpovídající 20 000 EUR pro jednoho zákazníka u jednoho obchodníka s cennými papíry.","Fond vyplatí nejvýše částku v korunách českých odpovídající 100 000 EUR pro jednoho zákazníka u jednoho obchodníka s cennými papíry.","Náhrada z Garančního fondu musí být podle zákona vyplacena do 3 měsíců ode dne ověření přihlášeného nároku a vypočtení výše náhrady.","Náhrada z Garančního fondu musí být podle zákona vyplacena po ověření přihlášeného nároku bez zbytečného odkladu."],"c":[0,2],"p":153,"e":"Fond poskytuje za podmínek stanovených zákonem náhradu zákazníkovi obchodníka s cennými papíry, který z důvodů přímo souvisejících s jeho finanční situací není schopen plnit závazky vůči svým zákazníkům za zákonných a smluvních podmínek. Limit je definován ZPKT.","tp":0},{"id":"20273.1","t":"m","q":"Do jakých nástrojů mohou penzijní fondy umisťovat shromážděné peněžní prostředky?","o":["Mohou být umístěny zejména do dluhopisů, jejichž emitentem je členský stát OECD.","Mohou být umístěny zejména do dluhopisů vydaných Evropskou investiční bankou nebo jinou mezinárodní finanční institucí, které je ČR členem.","Mohou být umístěny zejména do cenných papírů přijatých k obchodování na evropském regulovaném trhu.","Z důvodu ochrany před měnovým rizikem mohou být umístěny výhradně do státních, příp. korporátních dluhopisů země, ve které na penzijní fond domicil."],"c":[0,1,2],"p":153,"e":"Pravidla jsou definována zákonem.","tp":3},{"id":"20274.1","t":"m","q":"Kdy jsou osoby, od nichž zákon vyžaduje mlčenlivost, zproštěny této povinnosti?","o":["Například pro účely občanského soudního řízení.","Například pro účely soudního řízení správního.","Například pro účely trestního řízení.","Například pro účely správy daní a poplatků."],"c":[0,1,2,3],"p":153,"e":"Situace, kdy lze osoby, od nichž zákon vyžaduje mlčenlivost, mlčenlivosti zprostit definuje zákon Zákon č. 256/2004 Sb., o podnikání na kapitálovém trhu, v § 117.","tp":8},{"id":"20356.1","t":"m","q":"Finanční arbitr odmítne podání:","o":["Pokud ve věci samé již rozhodl soud nebo v téže věci probíhá řízení před soudem.","Pokud ve věci samé již bylo rozhodnuto v rozhodčím řízení, nebo v téže věci probíhá rozhodčí řízení.","Pokud spotřebitel není právně zastoupen.","Pokud spotřebitel neuhradí poplatek spojený s řízením před Finančním arbitrem."],"c":[0,1],"p":154,"e":"Upraveno zákonem 229/2002 Sb., právní zastoupení se nevyžaduje, řízení je bezplatné. Náklady řízení si nese každá strana sporu sama, finanční arbitr tedy nemůže nikomu přiznat ani náklady právního zastoupení.","tp":6},{"id":"22162.2","t":"m","q":"Očekávaný výnos dluhopisového investora:","o":["Roste s délkou splatnosti dluhopisu.","Roste se zhoršujícím se ratingem emise dluhopisů.","Klesá se zhoršujícím se ratingem emise dluhopisů.","Klesá s délkou splatnosti dluhopisu."],"c":[0,1],"p":154,"e":"Z teorie výnosových křivek vyplývá, že s prodlužující se délkou splatnosti obligace roste její výnos do splatnosti. Investoři rovněž budou požadovat vyšší rizikovou prémii při investici do dluhopisů s horším ratingem, čímž se emitentovi zvyšují náklady na obsluhu dluhu.","tp":3},{"id":"22171.2","t":"m","q":"Mezi základní makroekonomické funkce centrálních bank patří:","o":["Měnová (monetární) politika.","Emise hotovostních peněz.","Fiskální politika.","Devizová činnost."],"c":[0,1,3],"p":154,"e":"Cílem centrální banky je udržovat stabilní cenovou hladinu. Každá CB má dvě základní funkce - funkci makroekonomickou (provádění monetární politiky, např. pomocí přímých či nepřímých nástrojů, emisní monopol a provádění devizové činnosti). Mikroekonomické funkce souvisejí především s regulací odvětví.","tp":2},{"id":"22172.2","t":"m","q":"Z teoretického pohledu patří mezi dílčí segmenty kapitálového trhu:","o":["Akciový trh.","Trh dlouhodobých dluhopisů (obligací).","Trh dlouhodobých pojistných smluv.","Trh dlouhodobých úvěrů."],"c":[0,1,3],"p":154,"e":"Na kapitálovém trhu se obchodují investiční nástroje, jež mají povahu dlouhodobých finančních investic.","tp":2},{"id":"22176.2","t":"m","q":"Obezřetnostní dohled a ochrana klientů obchodníků s cennými papíry se zaměřuje na praktiky zneužívání trhu, jimiž jsou např.:","o":["Zneužívání neveřejných informací.","Manipulace s tržními cenami.","Vydávání účelových investičních doporučení.","Parazitování na obchodních příkazech klientů."],"c":[0,1,2,3],"p":154,"e":"Ve všech uvedených případech jde o nezákonné a neetické způsoby zneužívání trhu, kterých se ovšem v praxi vyskytuje mnohem více.","tp":0},{"id":"22178.2","t":"m","q":"V rámci regulace a dohledu byly jako součást ochrany finančního systému v České republice na základě vydaných zákonů zřízeny tyto garanční fondy:","o":["Garanční fond pojišťoven a zajišťoven.","Garanční systém finančního trhu.","Garanční fond finančních konglomerátů.","Garanční fond obchodníků s cennými papíry."],"c":[1,3],"p":155,"e":"V České republice existuje zákonné pojištění bankovních vkladů spadající do kompetence Garančního systému finančního trhu (dříve Fond pojištění vkladů) a zákonné pojištění obchodníků s cennými papíry prostřednictvím jejich příspěvků do Garančního fondu obchodníků s cennými papíry.","tp":0},{"id":"22180.2","t":"m","q":"Význam úrokových sazeb ve finančním a ekonomickém systému spočívá v tom, že:","o":["Uvádějí do rovnováhy nabídku a poptávku po penězích.","Napomáhají garantovat tok běžných úspor do investic, čímž podporují ekonomický růst.","Zaručují rozdělování disponibilních peněžních zdrojů tak, že je všeobecně směrují do investic s nejvyšší očekávanou mírou návratnosti.","Vzhledem ke svému vlivu na objem úspor a investic představují důležitý regulační nástroj."],"c":[0,1,2,3],"p":155,"e":"Podle ekonomické teorie spočívá význam úrokových sazeb v zabezpečování následujících čtyř funkcí. Úrokové sazby pomáhají směrovat tok běžných úspor do investic, čímž podporují ekonomický růst. Dále zaručují rozdělování disponibilních peněžních zdrojů tak, že je všeobecně směrují do investic s nejvyšší očekávanou mírou návratnosti. Za třetí uvádějí do rovnováhy nabídku a poptávku po penězích. A za čtvrté, vzhledem ke svému vlivu na objem úspor a investic představují důležitý regulační nástroj (jejž používají především centrální banky).","tp":2},{"id":"22417.2","t":"m","q":"Depozitář fondu kolektivního investování, který obhospodařovateli tohoto fondu, tomuto fondu, podílníkovi nebo akcionáři tohoto fondu způsobí újmu porušením své povinnosti stanovené nebo sjednané pro výkon jeho činnosti jako depozitáře:","o":["Je povinen nahradit újmu, avšak pouze do maximální výše 100 000 EUR či ekvivalentu v národní měně.","Není povinen ji nahradit.","Je povinen ji nahradit.","Zprostí se náhrady újmy, pouze prokáže-li, že újmu nezavinil ani z nedbalosti."],"c":[2,3],"p":155,"e":"Je stanoveno v § 80 ZISIF.","tp":1},{"id":"22418.1","t":"m","q":"Fondem kvalifikovaných investorů může být:","o":["Podílový fond.","Svěřenský fond.","Nadace.","Akciová společnost."],"c":[0,1,3],"p":155,"e":"Dle zákona o investičních společnostech a investičních fondech mohou být fondem kvalifikovaných investorů pouze subjekty jmenovitě uvedeny v příslušném odstavci, nadace mezi ně nepatří.","tp":1},{"id":"22421.4","t":"m","q":"V případě, že výkonnost fondu přibližně odpovídá jeho benchmarku, kdy portfolio manažer tedy dosahuje srovnatelných výnosů s benchmarkem, lze předpokládat, že faktor \"alfa\" fondu:","o":["Je kladný.","Je rovný hodnotě jedna.","Je záporný.","Je blízký nule."],"c":[3],"p":156,"e":"Ukazatel alfa u fondu měří přidanou hodnotu portfolio manažera, zda se mu podařilo překonat benchmark či nikoliv. V případě kladné alfy dosahuje fond vyššího výnosu oproti benchmarku, při záporné alfě, dosáhnul fond nižšího výnosu. Pokud je hodnota alfa rovna přesně nule či velmi blízká nule dosahuje fond srovnatelného výnosu jako benchmark. Samozřejmě, že investoři preferují co nejvyšší (kladnou) alfu.","tp":1},{"id":"22422.1","t":"m","q":"Modifikovaná durace je důležitý parametr při hodnocení a porovnávání:","o":["Dluhopisových fondů.","Akciových fondů.","Fondů peněžního trhu.","Nemovitostních fondů."],"c":[0,2],"p":156,"e":"Modifikovaná durace udává citlivost na změnu úrokových sazeb, měří tedy úrokové riziko, což je klíčový parametr sledovaný u fondů peněžního trhu a dluhopisových fondů.","tp":3},{"id":"23737.1","t":"m","q":"Kdo může poskytovat dlouhodobý investiční produkt (DIP):","o":["banka, spořitelní a úvěrní družstvo, obchodník s cennými papíry","zprostředkovatelé pojištění, kteří poskytují pojišťovací poradenství výhradně v oblasti neživotního pojištění","investiční společnost, samosprávný investiční fond","zahraniční osoba s obdobnou činností jako jsou banky, obchodníci s cennými papíry či investiční společnosti, která je oprávněná poskytovat své služby v České republice"],"c":[0,2,3],"p":156,"e":"Příslušný zákon vymezuje poskytovatele dlouhodobého investičního produktu v části 12, konkrétně v § 134g odst. 2 Poskytovat dlouhodobý investiční produkt může jen a) banka, b) spořitelní a úvěrní družstvo, c) obchodník s cennými papíry, d) investiční společnost, e) samosprávný investiční fond, f) zahraniční osoba s obdobnou činností jako některá z osob podle písmen a) až e) oprávněná poskytovat své služby v České republice.","tp":0},{"id":"23739.1","t":"m","q":"Dlouhodobý investiční produkt (DIP) je daňově zvýhodněný, je-li sjednáno, že majetek z DIP lze odepsat ve prospěch:","o":["poplatníka, který produkt sjednal nejdříve po uplynutí 120 kalendářních měsíců a po dosažení 60 let věku poplatníka","poplatníka, který produkt sjednal nejdříve po uplynutí 120 kalendářních měsíců bez omezení minimálního věku poplatníka","jiného poplatníka, v případě smrti poplatníka, který produkt sjednal","jiného poplatníka, v případě úplaty poskytovateli tohoto produktu za jeho vedení nebo služby s ním související"],"c":[0,2,3],"p":156,"e":"Zákon č. 586/1992 Sb., o daních z příjmů, ve znění pozdějších předpisů, § 15b odst. 1 říká, že produkt spoření na stáří je daňově podporovaný, pokud je sjednáno nebo jinak určeno, že výplata peněžních prostředků nebo plnění z tohoto produktu nebo odepsání majetku z DIP jsou ve prospěch poplatníka, který produkt sjednal, a to pouze po 120 kalendářních měsících od vzniku produktu, nejdříve však v kalendářním roce, ve kterém poplatník dosáhne 60 let věku, nebo jiného poplatníka, a to pouze v případě odepsání majetku z dlouhodobého investičního produktu za protiplnění poskytnuté ve prospěch tohoto produktu, ledaže se jedná o odepsání za protiplnění, jehož obvyklá cena je podstatně nižší než obvyklá cena odepisovaného majetku, nebo plnění povinnosti stanovené jiným právním předpisem.","tp":9},{"id":"23741.1","t":"m","q":"Co může tvořit majetek v dlouhodobém investičním produktu?","o":["cenné papíry kolektivního investování","ani jedna z variant není správná","dluhopisy nebo obdobné cenné papíry přijaté k obchodování na evropském regulovaném trhu","peněžní prostředky"],"c":[0,2,3],"p":157,"e":"V souladu s § 134i odst. zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, ve znění pozdějších předpisů, poskytovatel dlouhodobého investičního produktu zajistí, aby majetek v rámci dlouhodobého investičního produktu tvořily pouze: a) peněžní prostředky, b) investiční cenné papíry nebo nástroje peněžního trhu, které jsou přijaty k obchodování na evropském regulovaném trhu nebo v mnohostranném obchodním systému provozovatele se sídlem v členském státě Evropské unie, nebo na trhu obdobném regulovanému trhu se sídlem ve státě, který není členským státem Evropské unie, nebo se s nimi obchoduje na trhu obdobném regulovanému trhu se sídlem ve státě, který není členským státem Evropské unie, jestliže tyto trhy jsou uvedeny v seznamu zahraničních trhů obdobných regulovanému trhu se sídlem ve státě, který není členským státem Evropské unie, vedeném Českou národní bankou podle § 13 odst. 1 písm. k) zákona o dohledu v oblasti kapitálového trhu, c) dluhopisy nebo obdobné cenné papíry představující právo na splacení dlužné částky, jejichž emitentem je členský stát Evropské unie nebo centrální banka takového státu, d) kryté dluhopisy nebo obdobné cenné papíry představující právo na splacení dlužné částky, jejichž emitentem je zahraniční banka se sídlem v členském státě Evropské unie, e) cenné papíry kolektivního investování a f) deriváty, které nejsou investičním cenným papírem a které jsou sjednány výhradně za účelem zajištění majetku v rámci dlouhodobého investičního produktu, je-li hodnotou, ke které se vztahuje hodnota tohoto nástroje, úroková míra, měnový kurz nebo měna","tp":0},{"id":"23743.1","t":"m","q":"Nařízení (EU) 2019/2088, o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR), mj. stanoví určité povinnosti zveřejňovat informace související s udržitelností pro nařízením vymezené finanční poradce. Mezi tyto povinnosti patří zveřejnit na webových stránkách:","o":["informace o ESG vlastnostech či cílech těch jimi nabízených produktů, které lze považovat za produkty zohledňující faktory udržitelnosti","informace o svých politikách začleňování rizik týkajících se udržitelnosti do svého investičního nebo pojišťovacího poradenství","prohlášení o tom, jak ve svém investičním nebo pojišťovacím poradenství zohledňují hlavní nepříznivé dopady na faktory udržitelnosti (nebo vysvětlit důvody pro nezveřejnění takového prohlášení)","v rámci informací zveřejňovaných před uzavřením smlouvy popis způsobu, jakým jsou rizika týkající se udržitelnosti začleňována do jejich investičního nebo pojišťovacího poradenství (popř. vysvětlit důvody, proč tato rizika nepovažují za relevantní)"],"c":[1,2,3],"p":157,"e":"Povinnost pro finanční poradce zveřejňovat na svých webových stránkách informace o svých politikách začleňování rizik týkajících se udržitelnosti do svého investičního nebo pojišťovacího poradenství stanoví čl. 3 odst. 2 SFDR. Povinnost pro finanční poradce zveřejňovat na webu informace o zohledňování hlavních nepříznivých dopadů na udržitelnost při investičním nebo pojišťovacím poradenství stanoví čl. 4 odst. 5 SFDR. Tato povinnost je dále upravena prováděcím nařízením (EU) 2022/1288 (RTS k SFDR). Finanční poradci mají také zahrnout do informací zveřejňovaných před uzavřením smlouvy popis způsobu integrace rizik týkajících se udržitelnosti do svého investičního nebo pojišťovacího poradenství dle čl. 6 odst. 2 SFDR (popř. zveřejnit důvody, proč tato rizika nepovažují za relevantní). Povinnost zveřejňovat informace o ESG vlastnostech a cílech prosazovaných produkty se použije pro účastníky finančního trhu vymezené v SFDR, tedy nikoliv pro finanční poradce, kteří tuto informační povinnost nemají.","tp":6},{"id":"23744.1","t":"m","q":"Na který z níže uvedených finančních produktů se použije informační povinnost dle nařízení (EU) 2019/2088, o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR)?","o":["pojistný produkt s investiční složkou","subjekt kolektivního investování do převoditelných cenných papírů (tj. např. standardní fond kolektivního investování)","korporátní dluhopis obchodovatelný na regulovaném trhu v některém z členských států EU","spotřebitelský úvěr poskytnutý bankou na nákup produktu prokazatelně šetrného k životnímu prostředí"],"c":[0,1],"p":157,"e":"Příslušné nařízení vymezuje finanční produkty taxativním výčtem v čl. 2 v bodě 12. Mezi finanční produkty dle tohoto ustanovení patří mj. subjekt kolektivního investování do převoditelných cenných papírů a pojistný produkt s investiční složkou. Pokud jde o ostatní možnosti, pod tento pojem nespadají (tj. taxativní výčet finančních produktů nezahrnuje ani spotřebitelský úvěr ani korporátní dluhopis, který je sice investičním nástrojem, avšak nikoliv produktem ve smyslu SFDR).","tp":6},{"id":"23746.1","t":"m","q":"Účastníci finančního trhu mají podle nařízení (EU) 2019/2088 o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR) zveřejnit před uzavřením smlouvy informace o tom, zda a popř. jak začleňují rizika týkající se udržitelnosti do jejich investičních rozhodnutí. Tato rizika v zásadě představují potenciální významné negativní dopady na:","o":["(investiční) činnosti účastníka finančního trhu na environmentální oblast","(investiční) činnosti účastníka finančního trhu na sociální oblast","hodnotu investic, které by nastaly v důsledku události nebo situace v sociální oblasti","hodnotu investic, které by nastaly v důsledku události nebo situace v environmentální oblasti"],"c":[2,3],"p":158,"e":"Definice rizika týkajícího se udržitelnosti je uvedena v čl. 2, bodu 22 nařízení o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR). Jedná se o událost nebo situaci v environmentální nebo sociální oblasti nebo v oblasti správy a řízení, která by v případě, že by nastala, mohla mít skutečný nebo možný významný nepříznivý dopad na hodnotu investice. Riziko související s udržitelností se tak vztahuje k potenciálnímu finančnímu dopadu ESG aspektů na hodnotu investic, tj. nikoliv k dopadům investiční činnosti na životní prostředí a ostatní aspekty udržitelnosti, včetně dopadů na sociální oblast.","tp":6},{"id":"23747.1","t":"m","q":"Podle nařízení (EU) 2019/2088 o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR) musí standardní fond ve svém statutu zveřejnit informace o tom:","o":["zda a popř. jakým způsobem zohledňuje tzv. hlavní nepříznivý dopad na faktory udržitelnosti","zda a popř. jakým způsobem jsou rizika týkající se udržitelnosti začleňována do investičních rozhodnutí","jak jsou zásady odměňování správce fondu konzistentní se začleňováním rizik týkajících se udržitelnosti","kde na webu nalezne standardizované prohlášení o hlavních nepříznivých dopadech investičních rozhodnutí správce fondu na faktory udržitelnosti"],"c":[0,1],"p":158,"e":"Povinnost zveřejňovat informace o případném zohledňování tzv. hlavního nepříznivého dopadu produktu (zde standardního fondu) na faktory udržitelnosti v předsmluvní dokumentaci produktu (u standardního fondu ve v jeho statutu) zakládá čl. 7 SFDR. Povinnost zveřejňovat informace o případném začleňování rizik udržitelnosti do investičních rozhodnutí účastníků finančního trhu (zde správce fondu) stanoví čl. 6 SFDR. Informace o tom, jak účastníci finančního trhu zahrnují začleňování rizik udržitelnosti do svých zásad odměňování, se zveřejňuje na webových stránkách účastníka, nikoliv v předsmluvní dokumentaci (podle čl. 5 SFDR). Povinnosti uvádět standardizované prohlášení o hlavních nepříznivých dopadech investičních rozhodnutí účastníka finančního trhu (správce fondu) na faktory udržitelnosti je samostatnou informační povinností (podle čl. 4 SFDR), která se použije na účastníka finančního produktu, nikoliv na finanční produkt (podílový fond). Regulace přitom nezavádí žádnou povinnost uvádět odkaz na toto prohlášení ve statutu fondu.","tp":6},{"id":"23748.1","t":"m","q":"Podle nařízení (EU) 2019/2088 o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR) musí standardní fond, který prosazuje environmentální nebo sociální vlastnosti, zveřejnit informace o:","o":["dodržování těchto vlastností v příloze statutu fondu ve formě standardizované šablony","míře naplnění těchto vlastností v příloze výroční zprávy fondu ve formě standardizované šablony","dodržování těchto vlastností ve statutu fondu v libovolné formě, avšak za předpokladu, že tyto informace jsou jasné a nezavádějící","míře naplnění těchto vlastností ve výroční zprávě fondu v libovolné formě, avšak za předpokladu, že tyto informace jsou jasné a nezavádějící"],"c":[0,1],"p":158,"e":"Povinnost zveřejňovat informace o environmentálních nebo sociálních vlastnostech finančního produktu (zde standardního fondu) stanoví nařízení (EU) 2019/2088 o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR). Konkrétně zveřejňování informací o dodržování těchto environmentálních nebo sociálních vlastností v předsmluvní fázi upravuje čl. 8 SFDR. Tato povinnost je dále upravena prováděcím nařízením (EU) 2022/1288 (RTS k SFDR), které požaduje tyto informace zveřejňovat ve formě standardizované šablony (v příloze II tohoto nařízení), která je mandatorní přílohou předsmluvní dokumentace produktu (zde statutu fondu). Analogicky informace o míře naplnění environmentálních nebo sociálních vlastností produktu v pravidelných zprávách se zveřejňují podle čl. 11 SFDR. I tato informační povinnost je upravena výše uvedeným prováděcím nařízením, které i v tomto případě vyžaduje uvádění informací ve formě standardizované šablony (v příloze IV tohoto nařízení), která je mandatorní přílohou pravidelných produktových zpráv (zde výroční zprávy fondu). Informace o environmentálních nebo sociálních vlastnostech produktu tak nelze uvádět bez použití standardizovaných šablon.","tp":1},{"id":"23750.1","t":"m","q":"Které z těchto podmínek musí investice naplňovat, aby ji bylo možné považovat za udržitelnou investici dle nařízení o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb (SFDR)?","o":["je investováno do hospodářské činnosti, která přispívá k plnění environmentálního nebo sociálního cíle","investice významně nepoškozuje plnění žádného z cílů pro environmentální nebo sociální oblast","je investováno výhradně do hospodářských činností, které vyhovují taxonomii EU pro environmentálně udržitelné činnosti dle nařízení (EU) 2020/852, o zřízení rámce pro usnadnění udržitelných investic (tzv. nařízení o taxonomii)","společnosti, do nichž je investováno, musí dodržovat postupy řádné správy a řízení"],"c":[0,1,3],"p":159,"e":"V čl. 2 bodě 17 nařízení (EU) 2019/2088 (SFDR) je udržitelná investice definována jako investice do hospodářské činnosti, která přispívá k environmentálnímu nebo sociálnímu cíli, nebo investice do lidského kapitálu nebo hospodářsky či sociálně znevýhodněných komunit, za předpokladu, že tyto investice významně nepoškozují žádný z uvedených cílů a společnosti, do nichž je investováno, dodržují postupy řádné správy a řízení.\nUdržitelná investice nicméně nemusí nutně investovat do činností, které vyhovují taxonomii EU. Preambule v bodě 19 k tomu uvádí: V nařízení (EU) 2019/2088 se udržitelnou investicí rozumí investice do hospodářských činností, které přispívají k environmentálním cílům, což by mimo jiné mělo zahrnovat investice do environmentálně udržitelných hospodářských činností ve smyslu tohoto nařízení...","tp":6},{"id":"23751.1","t":"m","q":"Aby bylo možné považovat investici za environmentálně udržitelnou investici ve smyslu o nařízení o zřízení rámce pro usnadnění udržitelných investic (tzv. nařízení o taxonomii), musí být investováno do činností, které:","o":["naplňují technická screeningová kritéria unijní taxonomie environmentálně udržitelných činností","významně přispívají k jednomu nebo více environmentálním cílům vymezených v nařízení o taxonomii","významně nepoškozují žádný z environmentálních cílů vymezených v nařízení o taxonomii","jsou vykonávány v souladu s minimálními zárukami stanovenými v nařízení o taxonomii"],"c":[0,1,2,3],"p":159,"e":"Environmentálně udržitelnou investicí je dle čl. 2 bodu 1 nařízení o taxonomii investice do jedné nebo více hospodářských činností, které se podle nařízení o taxonomii kvalifikují jako environmentálně udržitelné. Čl. 3 téhož nařízení stanoví, že: Pro účely stanovení míry, do jaké je investice environmentálně udržitelná, se hospodářská činnost kvalifikuje jako environmentálně udržitelná, pokud tato hospodářská činnost:\na) významně přispívá k jednomu nebo více environmentálním cílům stanoveným v čl. 9 v souladu s články 10 až 16; b) významně nepoškozuje žádný z environmentálních cílů stanovených v článku 9 v souladu s článkem 17;\nc) je vykonávána v souladu s minimálními zárukami stanovenými v čl. 18; a d) splňuje technická screeningová kritéria, která Komise stanovila v souladu s čl. 10 odst. 3, čl. 11 odst. 3, čl. 12 odst. 2, čl. 13 odst. 2, čl. 14 odst. 2 nebo čl. 15 odst. 2.","tp":10},{"id":"23752.1","t":"m","q":"Pro vyjádření sladěnosti investičních fondů s taxonomií EU (klasifikačním systémem) pro environmentálně udržitelné činnosti se používají specifické KPI (klíčové ukazatele výkonnosti). Pro výpočet těchto ukazatelů mohou jako podkladová data či informace sloužit:","o":["veřejně dostupné informace zveřejňované emitenty","neveřejné informace poskytnuté emitenty","relevantní informace poskytnuté externími specializovanými poskytovateli dat","odůvodnitelné odhady, avšak pouze při naplnění specifických předpokladů"],"c":[0,1,2,3],"p":159,"e":"Bod 35 preambule nařízení (EU) 2022/1288 (RTS k SFDR) ke zdrojům dat a informací k vyjádření sladěnosti s taxonomií uvádí: Účastníci finančního trhu by měli mít možnost využívat poskytovatele údajů z řad třetích stran, pokud podniky dosud nesplnily povinnost stanovenou v článku 8 nařízení (EU) 2020/852 zveřejnit informace o tom, jakým způsobem a do jaké míry jejich činnosti souvisejí s hospodářskými činnostmi, které se podle článků 3 a 9 uvedeného nařízení kvalifikují jako environmentálně udržitelné. Při posuzování investic do společností, do nichž je investováno a které nepodléhají zveřejňování informací podle článku 8 nařízení (EU) 2020/852, by účastníci finančního trhu měli posoudit a využít veřejně oznamované údaje. Pouze v případě, že takové údaje nejsou k dispozici, by účastníci finančního trhu měli mít možnost využít údaje, které byly získány buď přímo od společností, do nichž je investováno, nebo od třetích stran, a to za předpokladu, že údaje zpřístupněné tímto postupem jsou rovnocenné údajům zpřístupněným na základě zveřejňování informací v souladu s uvedeným článkem 8. Možné použití odůvodnitelných odhadů při naplnění specifických podmínek lze dovodit z bodu 21 preambule nařízení (EU) 2020/852: Pokud jde o hospodářské činnosti prováděné podniky, které nejsou povinny zveřejňovat informace podle tohoto nařízení, mohly by výjimečně nastat případy, kdy by účastníci finančního trhu nemohli rozumně získat relevantní informace, jež jim umožňují spolehlivě určit soulad s technickými screeningovými kritérii stanovenými podle tohoto nařízení. V těchto výjimečných případech a pouze u těch hospodářských činností, o nichž nebylo možné získat úplné, spolehlivé a včasné informace, by mohli být účastníci finančního trhu oprávněni provádět doplňková posouzení a odhady na základě informací z jiných zdrojů. Tato posouzení a odhady by měly kompenzovat pouze omezené a specifické části požadovaných prvků údajů a vést k obezřetně formulovanému výsledku.\nNa dané ustanovení rovněž odkazují konsolidované otázky a odpovědi Komise a ESA k rámci SFDR (část VII Taxonomy-aligned investment disclosures, otázka 1, část Data use, dostupné zde: https://www.esma.europa.eu/sites/default/files/2023- 05/JC_2023_18_-_Consolidated_JC_SFDR_QAs.pdf).","tp":5},{"id":"23753.1","t":"m","q":"Pro účely zjišťování preferencí ohledně udržitelnosti u klientů se rozlišuje mezi finančními nástroji, které mají různé ambice v oblasti udržitelnosti. Prováděcí nařízení ke směrnici EU o trzích finančních nástrojů (MiFID II) pro tyto účely vymezuje termín - preference týkající se udržitelnosti - s ohledem na nástroje, které:","o":["se jakýmkoliv způsobem sebeprezentují jako udržitelné ve smyslu prosazování pozitivních environmentálních či sociálních vlastností","zohledňují hlavní nepříznivé dopady na faktory udržitelnosti (v zásadě na životní prostředí a sociální oblast)","investují do tzv. udržitelných investic ve smyslu nařízení (EU) 2019/2088 (nařízení o zveřejňování informací souvisejících s udržitelností v odvětví finančních služeb SFDR)","investují do tzv. environmentálně udržitelných investic ve smyslu nařízení (EU) 2020/852 (nařízení o zřízení rámce pro usnadnění udržitelných investic, tzv. nařízení o taxonomii)"],"c":[1,2,3],"p":160,"e":"Regulatorní vymezení - preferencí týkajících se udržitelnosti - je obsaženo v čl. 2 bodě 7 prováděcího nařízení (EU) 2017/565, ve znění nařízení (EU) 2021/1253, kde je uvedeno:\nPreferencemi týkajícími se udržitelnosti se rozumí volba zákazníka nebo potenciálního zákazníka, pokud jde o to, zda, a pokud ano, do jaké míry, by do jeho investic měl být začleněn jeden nebo několik z těchto finančních nástrojů: a) finanční nástroj, u něhož zákazník nebo potenciální zákazník určí, že se minimální podíl investuje do environmentálně udržitelných investic ve smyslu čl. 2 bodu 1 nařízení Evropského parlamentu a Rady (EU) 2020/852;\nb) finanční nástroj, u něhož zákazník nebo potenciální zákazník určí, že se minimální podíl investuje do udržitelných investic ve smyslu čl. 2 bodu 17 nařízení Evropského parlamentu a Rady (EU) 2019/2088;\nc) finanční nástroj, který zohledňuje hlavní nepříznivé dopady na faktory udržitelnosti, přičemž kvalitativní nebo kvantitativní prvky prokazující předmětné zohlednění určuje zákazník nebo potenciální zákazník.","tp":6},{"id":"23758.1","t":"m","q":"Poskytovatel služby investičního poradenství má následující povinnosti při zjišťování a zohledňování preferencí, které se týkají se udržitelnosti:","o":["vysvětlit rozdíly mezi jednotlivými prvky definice preferencí týkajících se udržitelnosti","vždy upřednostňovat nástroje, které mají vyšší míru ambicí v oblasti udržitelnosti","posuzovat preference udržitelnosti zákazníka až poté, kdy provedl posouzení ostatních mandatorních aspektů posuzování vhodnosti (finanční situace zákazníka, jiné investiční cíle a další)","v případě, že zákazník projeví nějaké preference týkající se udržitelnosti, je nutné dotazovat se na jejich specifikaci, primárně s ohledem na jejich regulatorní definici"],"c":[0,2,3],"p":160,"e":"Obecné pokyny ESMA k některým aspektům požadavků směrnice MiFID II ohledně vhodnosti mj. uvádějí, že je nutné vysvětlit rozdíly mezi jednotlivými prvky definice preferencí týkajících se udržitelnosti podle nařízení (EU) 2021/565 (bod 16). Dle obecných pokynů (bod 26) dále platí, že v případě, kdy zákazník projeví, že má nějakou (jakoukoliv) preferenci týkající se udržitelnosti, je nutné v dotazování pokračovat s cílem upřesnit takovou preferenci, a to hlavně s ohledem na tři typy těchto preferencí, které jsou vymezeny v čl. 2 v bodě 7 prováděcího nařízení (EU) 2017/565, ve znění nařízení (EU) 2021/1253. Obecné pokyny také explicitně uvádějí: Preference týkající se udržitelnosti by měly být posouzeny až po posouzení vhodnosti v souladu s kritérii týkajícími se znalostí a zkušeností, finanční situace a jiných investičních cílů. (bod 81). Na druhé straně neexistuje žádná regulace, která by zakládala upřednostňování nástrojů či produktů s vyšší mírou ambice v oblasti udržitelnosti při poskytování investičního poradenství (naopak základním principem pro zohledňování preferencí týkajících se udržitelnosti je dosažení jejich souladu s ESG atributy doporučovaným nástrojů).","tp":6},{"id":"21902.1","t":"c","q":"Jaké informace, dokumenty či prohlášení z nabízených možností si příslušný pracovník obchodníka s cennými papíry musí od zákazníka vyžádat?","o":["Informace o jeho odborných znalostech a zkušenostech v oblasti investic.","Potvrzení o založení majetkového účtu u Centrálního depozitáře cenných papírů.","Výpis z trestního rejstříku zákazníka, ne starší 3 měsíců.","Rodný list zákazníka"],"c":[0],"p":161,"e":"Obchodník s cennými papíry si vždy musí od zákazníka vyžádat informace o jeho odborných znalostech a zkušenostech v oblasti investic.","k":0},{"id":"21903.1","t":"c","q":"Obchodník s cennými papíry má mimo jiné povinnost zjišťování a řízení střetu zájmů. Ve vztahu k zákazníkovi to znamená, že:","o":["Nesmí získat finanční prospěch nebo se vyhnout finanční ztrátě na úkor zákazníka.","Nesmí poskytovat investiční služby konkurentům zákazníka.","Je v souladu s péčí řádného hospodáře vždy povinen realizovat zisk, i pokud je tomuto dojde na úkor zákazníka.","Nikdy nesmí zároveň obchodovat s investičním nástrojem na vlastní účet a na účet zákazníka."],"c":[0],"p":161,"e":"Obchodník s cennými papíry má povinnost zjišťovat, předcházet a řídit střet zájmů ve vztahu k zákazníkům, což mimo jiné znamená povinnost předcházet situacím, kdy by se vyhnul finanční ztrátě či získal prospěch na úkor zákazníka.","k":0},{"id":"21904.1","t":"c","q":"Zákazník zvažuje, že by část svých peněžních prostředků alokoval do investice nabízející vyšší výnos, byť za cenu vyššího rizika. Chtěl by mít nicméně možnost flexibilně rozložit investici a v případě potřeby část investice rychle odprodat. V takovém případě mu můžete doporučit:","o":["Investici do akcií kotovaných na burzovním trhu.","Investici do neveřejně obchodované emise akcií.","Investici do private equity fondu.","Investici do podílu ve startupu prostřednictvím zahraniční \"crowdfundingové\" platformy."],"c":[0],"p":161,"e":"Investici s vyšší mírou rizika při zachování likvidity nabízejí akcie obchodované na burze či obdobném veřejném trhu. V zadání případové studie je uvedeno, že zákazník preferuje investice s vyšší mírou rizika, jež zároveň nabízejí vyšší možnost zhodnocení investice. Zároveň ale hledá likvidní investici. Požadavkům zákazníka by vyhověly i jiné investiční nástroje, např. ETF či otevřený podílový fond investující do akcií, tyto však nejsou mezi nabízenými variantami. Ostatní varianty (tj. investice do private equity fondu, do podílu ve startupu či do neveřejně obchodovatelných akcií) nenabízejí zákazníkem požadovanou likviditu, protože např. private equity fondy jsou zpravidla zakládány v uzavřené podobě, obdobně při investici do start-upů neveřejně obchodovaných společností kapitál vázán na delší dobu, aby např. pokrýval ztráty v zárodečné a rané fázi podnikání.","k":0},{"id":"21905.1","t":"c","q":"Zákazník se v tisku dočetl, že u akcií energetické společnosti XYZ, a.s., došlo ke štěpení akcií a při návštěvě internetových stránek společnosti zjistil, že se cena akcií společnosti dramaticky snížila. Chtěl by proto poskytnout výklad toho, co označuje spojení \"štěpení akcií\":","o":["Jde o proces, kdy za jednu akcii o určité nominální hodnotě dostane jejich majitel odpovídající počet akcií o nižší nominálně hodnotě.","Emisi nových akcií v důsledku rozdělení společnosti, která vydala původní akcie.","Vydání nových akcií z dané emise o stejné jmenovité hodnotě, čímž dojde k přetlaku nabídky na trhu a poklesu ceny.","Jde o proces, kdy budou akcie akciové společnosti nahrazeny dluhopisy a investoři, kteří nestojí o dluhové cenné papíry, začali rychle prodávat, čímž klesla na trhu jejich cena."],"c":[0],"p":161,"e":"Jako štěpení akcií je označena transakce, při níž jsou akcie o určité jmenovité hodnotě z jedné emise v určitém poměru rozděleny na více akcií o nižší jmenovité hodnotě.","k":0},{"id":"21906.1","t":"c","q":"Zákazník zvažuje investici do akcií energetické společnosti XYZ, a.s. Společnost dlouhodobě vyplácí dividendu ve výši 35 Kč, nominální hodnota akcie je 650 Kč. Pokud by zákazník nakupoval akcie za cenu 775 Kč za akcií, jaké by dosáhl dividendové výnosnosti, pokud by společnost i v budoucnu vyplácela dividendu ve stejné výši?","o":["Přibližně 4,5 %.","Přibližně 5,3 %.","Přibližně 4 %.","Přibližně 5,5 %."],"c":[0],"p":162,"e":"Dividendový výnos představuje podíl dividendy vůči tržní ceně cenného papíru, resp. to, jaký je běžný výnos z investované částky.","k":0},{"id":"22235.2","t":"c","q":"Pokud by investiční zprostředkovatel vyřizoval zákazníkům takovýto zpětný odkup dluhopisů, o jakou investiční službu se jedná?","o":["Přijímání a předávání pokynů týkajících se investičních nástrojů.","Obchodování s investičním nástrojem na vlastní účet.","Umisťování investičních nástrojů bez závazku jejich upsání.","Investiční poradenství týkající se investičních nástrojů."],"c":[0],"p":163,"e":"Popsané jednání naplňuje vymezení investiční služby vymezené v § 4 odst. 2 písm. a) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, tedy investiční služby přijímání a předávání pokynů. Tato investiční služba zahrnuje rozmanité činnosti a úkony související s právním jednáním vztahujícím se k nakládáním s investičním nástrojem.","k":1},{"id":"22236.2","t":"c","q":"Je investiční zprostředkovatel oprávněn zákazníkům nabízet takovouto službu a tedy jim zprostředkovat popsanou záležitost?","o":["Ano, pokud byl k dané emisi dluhopisů vydán prospekt nebo srovnatelný dokument.","Ano, a to bez jakýchkoliv omezení.","Ano, ale objem transakce nesmí překročit 1 000 000 Kč.","Ne, investiční zprostředkovatel je oprávněn poskytovat pouze služby investičního poradenství."],"c":[0],"p":163,"e":"Investiční zprostředkovatel je oprávněn poskytovat investiční službu přijímání a předávání pokynů i ve vztahu k dluhopisům, ke kterým byl vydán prospekt nebo srovnatelný dokument.","k":1},{"id":"22237.2","t":"c","q":"Manželé chtějí investičnímu zprostředkovateli dluhopisy rovnou předat s tím, aby listinné dluhopisy donesl do sídla emitenta a vyřídil související administrativní záležitosti. Může investiční poradce postupovat takovýmto způsobem?","o":["Ne, investiční zprostředkovatel nesmí přijímat peněžní prostředky nebo investiční nástroje zákazníků.","Ano, investiční zprostředkovatel nesmí přijímat peněžní prostředky zákazníků, není ale oprávněn přijímat investiční nástroje.","Ne, investiční zprostředkovatel smí přijímat peněžní prostředky zákazníků, nesmí ale přijímat investiční nástroje.","Ano, investiční zprostředkovatel smí přijímat peněžní prostředky i investiční nástroje zákazníků."],"c":[0],"p":163,"e":"Investiční zprostředkovatel není oprávněn přijímat ani peněžní prostředky, ani investiční nástroje zákazníků.","k":1},{"id":"22238.2","t":"c","q":"V nabídce na odkup je uvedeno, že emitent v případě odkupu investorům uhradí i alikvotní úrokový výnos ke dni jejich odkoupení. Manželé se zalekli, že jim tak vyplatí pouze část jejich hodnoty. Poradce jim vysvětlí, že se jedná o:","o":["Poměrný úrokový výnos ode výplaty posledního kupónu do dne prodeje dluhopisu, tzn. obdrží ještě poměrnou část poslední kuponové platby.","Procentní úrokový výnos dluhopisu, který není stanoven jako fixní.","Bonusovou platbu poskytnutou vedle stanoveného úrokového výnosu dluhopisu, která náleží prodávajícímu za předčasný odprodej.","Částku představující transakční náklady Centrálního depozitáře cenných papírů za předčasný odprodej."],"c":[0],"p":163,"e":"Alikvotní úrokový výnos je částka, která držiteli připadá za období od poslední výplaty kuponu (úrokového výnosu) do dne jeho prodeje. Jedná se tedy o poměrnou část kuponové platby, která ještě celá nenaběhla, protože do data její výplaty zbývá určitá doba. AÚV tak představuje \"odměnu\", resp. uvedenou poměrnou část kuponové platby, která náleží prodávajícímu za to, že danou obligaci držel ještě po určitou dobu a neprodává dluhopis přímo k datu výplaty kuponu.","k":1},{"id":"22239.2","t":"c","q":"Emitent dluhopisů zatím manželům třikrát uhradil roční platby představující plný výnos z dluhopisů. Pokud byl úrokový výnos z dluhopisů ve všech třech případech 5 %, výnosy byly zdaněny 15 % sazbou daně a manželé do dluhopisů investovali částku 1 000 000 Kč, jakou peněžní částku zatím od emitenta inkasovali jakožto výnos z dluhopisů?","o":["127 500 Kč.","125 000 Kč.","123 500 Kč.","132 500 Kč."],"c":[0],"p":164,"e":"Čistá úroková sazba očištěná o sazbu daně 15 % činí 4,25 %. Při investici 1 000 000 Kč činí tedy roční čisté úrokové výnosy 42 500 Kč (0,0425 x 1000000 = 42 500 Kč). Manželé obdrželi platbu třikrát, jejich tříletý úrokový výnos tak bude trojnásobný (3 x 42 500 = 127 500 Kč).","k":1},{"id":"22366.5","t":"c","q":"Jaký krok by měl investiční zprostředkovatel vůči novému zákazníkovi nejprve učinit před samotným poskytováním investičních služeb?","o":["Předložit mu k vyplnění tzv. investiční dotazník.","Vyžádat si bankovní výpis ověřující skutečnost, že disponuje peněžními prostředky pro provedení investice.","Předložit mu k podpisu komisionářskou smlouvu.","Požádat o úhradu zálohy na poskytované investiční služby."],"c":[0],"p":165,"e":"Investiční zprostředkovatel by měl v souladu s § 15h odst. 1 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu před samotným poskytnutím investičních služeb získat od zákazníka informace o jeho odborných znalostech, zkušenostech, finančním zázemí, investičních cílech apod., a to obvykle ve formě investičního dotazníku.","k":2},{"id":"22367.5","t":"c","q":"Zákazník si na základě předložených nabídek vybral investici. Zvažuje nákup podílových listů, ale dotazuje se, o jaký druh investičního nástroje se jedná?","o":["O cenný papír představující podíl na podílovém fondu, jeho vlastník je podílníkem.","O cenný papír představující podíl na podílovém fondu, jeho vlastník je akcionářem.","O cenný papír představující účast na podfondu akciové společnosti s proměnným základním kapitálem.","O cenný papír představující podíl na svěřeneckém fondu."],"c":[0],"p":165,"e":"Podílový list je cenný papír představující účast na investičním fondu, který je podílovým fondem.","k":2},{"id":"22368.5","t":"c","q":"Investiční fond, do nějž má zákazník zájem investovat, je v informačních materiálech označen jako fond fondů. Co tento termín označuje?","o":["Investiční fond investující do účasti v jiných investičních fondech.","Investiční fond investující do akciového indexu.","Investiční fond, který obdržel zvláštní ocenění Asociace pro kapitálový trh.","Investiční fond, jehož investory mohou být výlučně finanční instituce."],"c":[0],"p":165,"e":"Jako fondy fondů jsou označeny investiční fondy, které investují do účastnických cenných papírů jiných investičních fondů.","k":2},{"id":"22369.5","t":"c","q":"Zákazník se v odborném periodiku dočetl o možnosti uplatnit tzv. časový test, nárok na osvobození od daně z příjmů v případě prodeje cenných papírů, které bude vlastnit zákonem stanovenou dobu. Zajímá jej, po jakou nejkratší dobu by cenné papíry musel vlastnit:","o":["Po dobu přesahující 3 roky.","Po dobu přesahující 6 měsíců.","Po dobu přesahující 5 let.","Po dobu přesahující 1 rok."],"c":[0],"p":165,"e":"Ustanovení §4 odst. 1 písm. x) zákona č. 586/1992 Sb., o daních z příjmů stanoví, že osvobozeny od daně jsou příjmy z úplatného převodu cenných papírů, pokud doba mezi nabytím a prodejem cenného papíru přesáhne dobu 3 let.","k":2},{"id":"22370.5","t":"c","q":"Pokud má podílový list zakoupený zákazníkem v okamžiku investice hodnotu 1 000 Kč a následně po dobu 3 let vzroste jeho hodnota vždy o 5 % p.a., jaká bude jeho hodnota zaokrouhlená na celé Kč po uplynutí 3 let od okamžiku investice? Ignorujte vstupní poplatky a průběžné poplatky za správu investice.","o":["1 158 Kč.","1 150 Kč.","1 155 Kč.","1 160 Kč."],"c":[0],"p":166,"e":"Pokud se investice zhodnotí každý rok o ideální hodnotu 5 %, po uplynutí 3 let má investice hodnotu 1157,63 Kč, tedy zaokrouhleně 1158 Kč. Při výpočtu se jedná o využití složeného úročení, protože doba úročení je delší než jeden rok, resp. než jedno (roční) úrokové období. FV = PV*(1+r)^t","k":2},{"id":"21908.1","t":"c","q":"Jakou roli hraje pro investičního zprostředkovatele z hlediska vyhodnocení finančního zázemí a investičních cílů zákazníka a poskytování investičních služeb skutečnost, že jej kontaktoval manželský pár s plánem investovat dle výše uvedeného modelu.","o":["Tato skutečnost nehraje žádnou roli.","Investované peněžní prostředky jsou s největší pravděpodobností součástí tzv. společného jmění manželů.","Komisionářská smlouva či obdobná smlouva, kterou podepíše pouze jeden z manželů je neplatná.","Komisionářská smlouva či obdobná smlouva, kterou podepíše pouze jeden z manželů je relativně neplatnou."],"c":[1],"p":167,"e":"Příjmy manželů v době trvání manželství jsou až na výjimky uvedené v zákoně č. 89/2012 Sb., občanský zákoník součástí tzv. společného jmění manželů.","k":3},{"id":"21909.1","t":"c","q":"Zákazníky na základě nabídek předložených investičním zprostředkovatelem zaujal jeden vybraný investiční fond, u kterého je uvedena zkratka UCITS. Poradce jim vysvětlí, že zkratka znamená:","o":["Investiční fond investující do převoditelných cenných papírů, který naplňuje směrnici Evropské komise, tzv. Undertakings for Collective Investment in Transferable Securities.","Investiční fond investující výhradně do nemovitostí - Useful Current Immovable Trust Securities fund.","Investiční fond v právní formě akciové společnosti s tzv. proměnným základním kapitálem - Underlying Company with Investment Transfer Switch.","Investiční fond obchodovaný na americkém regulovaném trhu, investující převážně do dluhopisů - United Common Investments Treasury Securities fund."],"c":[0],"p":167,"e":"UCITS je zavedenou anglickou zkratkou označující investiční fondy investující do převoditelných cenných papírů - Undertakings for the Collective Investment of Transferable Securities. Jedná se o tzv. standardní fondy, které tuto směrnici naplňují, kdy tato směrnice slouží především k ochraně drobných investorů, protože definuje např. maximální expozici fondu vůči jednomu emitentovi.","k":3},{"id":"21910.1","t":"c","q":"Tento fond je v dokumentech pro investory označen jako fond smíšený. Co toto označení znamená?","o":["Investiční fond investuje do kombinovaného portfolia akcií, dluhových cenných papírů, nástrojů peněžních trhu a jiných vhodných aktiv.","Investiční fond kombinujíce přítomnost kvalifikovaných a tzv. retailových investorů.","Investiční fond vydávající více druhů účastnických cenných papírů.","Investiční fond investující ve více světových regionech."],"c":[0],"p":167,"e":"Jako smíšený investiční fond je označen takový fond, který investuje do kombinovaného portfolia akcií, obligací a jiných aktiv","k":3},{"id":"21911.1","t":"c","q":"V jakém dokumentu investor nalezne stručné základní charakteristiky investičního fondu zpracované takovou formou, aby byly srozumitelné i pro běžného investora?","o":["Ve sdělení klíčových informací (KIID).","V depozitářské zprávě.","V investičním memorandu.","Ve smlouvě o úpisu cenných papírů kolektivního investování."],"c":[0],"p":167,"e":"Uvedené informace obsahuje dokument nazvaný sdělení klíčových informací","k":3},{"id":"21912.1","t":"c","q":"V informačních materiálech týkajících se předmětného investičního fondu je uvedeno, že tento vykázal za stávající tři roky své existence celkové zhodnocení investičních prostředků ve výši 15 %. Co z této informace lze usoudit ve vztahu ke zhodnocení investice těchto manželů?","o":["Na základě zhodnocení dosaženého v předchozích letech nelze zaručit zhodnocení v letech následujících.","Investiční fond tímto zaručuje zhodnocení investice o 5 % ročně.","Investiční fond tímto zaručuje zhodnocení investice nejméně o 5 % ročně.","Na základě uvedené informace nelze ve vztahu k budoucímu zhodnocení nic dovodit, nicméně UCITS fondy mají povinnost zaručit zhodnocení vždy nejméně ve výši inflace."],"c":[0],"p":168,"e":"Informace o výnosech v uplynulých nezaručují, že těchto výnosů bude dosaženo i v budoucnu. Žádné z ustanovení směrnice UCITS ani zákona č. 240/2013 Sb., o investičních společnostech a investičních fondech nicméně nepředepisuje UCITS fondům povinnost zajistit zhodnocení investice vždy nejméně o inflaci.","k":3},{"id":"20502.3","t":"c","q":"Jak má investiční poradce začít s klientem jednat?","o":["Nejprve s panem Sýkorou projde analýzu jeho současného stavu a plánů do budoucna a požádá ho, aby mu zodpovědně vyplnil investiční dotazník.","Nejprve sjedná a uzavře s panem Sýkorou smlouvu o investičním poradenství.","Nejprve sjedná a převezme požadovanou peněžní zálohu.","Nejprve sjedná a uzavře s panem Sýkorou smlouvu o investičním poradenství a nechá si zaplatit dohodnutou zálohu."],"c":[0],"p":169,"e":"Investiční poradce, který poskytuje službu investičního poradenství dle Zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu § 4 odst. 2 písm. e), musí od klienta získat informace o jeho finanční situaci, aby mohl vyhodnotit, jak případná ztráta ovlivní jeho finanční zázemí. Rovněž se bude zajímat o klientovy znalosti a zkušenosti v oblasti investic, jeho vztah k riziku a investiční cíle, kterých chce klient dosáhnout.","k":4},{"id":"20503.3","t":"c","q":"Z investičního dotazníku vyplynuly následující skutečnosti: pan Sýkora doposud nikdy neinvestoval do cenných papírů a této problematice příliš nerozumí. Je v současnosti zaměstnán a uvedenou částku nebude před odchodem do důchodu za normálních okolností potřebovat, přesto však chce, aby investiční aktivum bylo likvidní. Je konzervativního zaměření a zvažovaná investice by představovala hlavní část jeho současných úspor.","o":["Investiční poradce zařadil následně pana Sýkoru mezi neprofesionální zákazníky.","Investiční poradce zjistil, že pan Sýkora dobře ví co požaduje, nepotřebuje investiční poradenství, a proto mu navrhl služby investičního zprostředkovatele.","Investiční poradce zařadil pana Sýkoru mezi profesionální zákazníky.","Investiční poradce na základě pravdivě vyplněných údajů v investičním dotazníku klienta odmítl."],"c":[0],"p":169,"e":"Investiční poradce zařadí nezkušeného investora mezi neprofesionální zákazníky (klient nesplňuje zákonné podmínky Zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, § 2a odst. 1 a odst.2) a poskytne mu kvalifikované služby v jeho nejlepším zájmu.","k":4},{"id":"20504.3","t":"c","q":"Protože je pan Sýkora konzervativní, jeví se jako vhodná investice do dluhopisů. Poradce jej v takovém případě upozorní na úrokové riziko, s tím, že pokud úrokové sazby výrazně vzrostou:","o":["Vnitřní hodnota variabilně úročených dluhopisů se příliš nezmění.","Vnitřní hodnota fixně úročených dluhopisů se zvýší.","Vnitřní hodnota diskontovaných dluhopisů se zvýší.","Vnitřní hodnota variabilně úročených dluhopisů se zvýší."],"c":[0],"p":169,"e":"Při zvyšování úrokových sazeb se vnitřní hodnoty (a v návaznosti na to i kurzy) akcií a fixně úročených dluhopisů obchodovaných na sekundárním trhu cenných papírů sníží; pouze vnitřní hodnoty (a potažmo ceny) variabilně úročených dluhopisů se příliš nezmění.","k":4},{"id":"20505.3","t":"c","q":"Pan Sýkora se zalekl úrokového rizika. Investiční poradce, ale vysvětlí panu Sýkorovi, že se k jeho záměru investovat v současnosti téměř veškeré své úspory raději do amerických akcií staví takto:","o":["Zvažovaná investice je pro klienta vzhledem k jeho konzervativní povaze a znalostem nevhodná, nehledě k tomu, že by šlo o investování prakticky všech volných peněz nezkušeného investora do akciového portfolia zaměřeného na jednu oblast.","Zvažovaná investice je pro klienta velice vhodná, a to především vzhledem k očekávanému růstu kurzu USD vůči CZK, tedy posilování české koruny.","Zvažovaná investice je pro klienta vhodná, protože investování většiny peněz do amerických akcií mu jedině pomůže zajistit dostatek peněz do budoucna.","Zvažovaná investice je pro klienta vhodná, nicméně aby dosáhl vysokého zisku, tak by bylo vhodné nakoupit tyto akcie formou futures, a to minimálně s pákou č. 5."],"c":[0],"p":170,"e":"Zvažovaná investice je pro klienta vzhledem k jeho stáří a konzervativní povaze nevhodná, nehledě na to, že představuje prakticky veškeré volné peníze nezkušeného investora.","k":4},{"id":"20506.3","t":"c","q":"Jak v dané situaci správně investovat?","o":["Neschválí investorovi jeho představu a navrhne mu investovat prostřednictvím vhodných podílových fondů, jejichž statut zaručuje diverzifikovanou skladbu portfolia (variabilně úročené obligace, dluhopisy peněžního trhu a přiměřené množství akcií), která odpovídá konzervativní povaze klienta.","Doporučí klientovi několik titulů vhodných amerických akcií a klient nákup zaplatí v hotovosti.","Navrhne klientovi konkrétní investici do českých, fixně úročených kupónových dluhopisů obchodovaných na sekundárním trhu cenných papírů.","Navrhne klientovi koupi přesně definovaného fixně úročeného českého korporátního diskontovaného dluhopisu."],"c":[0],"p":170,"e":"Za nejdůležitější faktory lze v daném případě považovat správné rozložení portfólia (podle vyhodnocení klientova investičního profilu) a diverzifikaci prostřednictvím správně zaměřeného podílového fondu kolektivního investování.","k":4},{"id":"20508.1","t":"c","q":"O čem by měl investiční poradce se svým klientem jednat, když finanční situaci pana Fialy dopodrobna zná, má jeho aktuální investiční dotazník a neshledal žádné důvody, které by jeho záměru bránily?","o":["Jednání by se mělo přímo zaměřit na deklarovaný investiční záměr klienta, neboli na vyjasnění jeho investičních cílů a zamýšlené investiční strategie (neboli do jakých cenných papírů by chtěl investovat, jak dlouhý uvažuje investiční horizont, jakou má averzi k riziku, resp. jakých výsledků zamýšlí dosáhnout).","Investiční poradce by měl nejprve podepsat s panem Fialou dodatek smlouvy o investičním poradenství.","Investiční poradce by měl nejprve sjednat a převzít peněžní zálohu.","Jelikož profese investičního poradenství nedovoluje provádět obhospodařování klientova portfolia, nemůže investiční poradce panu Fialovi nijak pomoci. Tento důvod mu vysvětlí telefonicky a žádné osobní jednání v této věci proto neproběhne."],"c":[0],"p":171,"e":"Kdyby nebyl finanční poradce dlouhodobým poradcem pana Fialy, tak by mu dal nejprve k vyplnění investiční dotazník, z něhož by zjišťoval potřebné informace ohledně jeho investičních zkušeností, finančního zázemí a pod. Jelikož však všechny tyto informace má, bude v daném případě řešit pouze problematiku klientem zamýšlených investic.","k":5},{"id":"20509.1","t":"c","q":"Z jednání investičního poradce s panem Fialou vyplynulo, že klient problematice investic vcelku rozumí, je připraven nést odpovídající riziko a jeho investiční záměr je dlouhodobý. A pokud jde o investiční záměr, jeví se jako logický. Jaké stanovisko zaujme investiční poradce k žádosti svého klienta?","o":["Investiční poradce usoudil, že i když je pan Fiala neprofesionálním zákazníkem, tak jsou jeho investiční představy logické. Proto s ním pouze probere potenciální rizika a jeho záměr mu nebude vyvracet. Přitom bere v úvahu, že pan Fiala hodlá investovat ne příliš vysoké částky, jejichž případná ztráta by ani ho, ani jeho rodinu existenčně neohrozila.","Investiční poradce dospěl k názoru, že navržený investiční záměr pana Fialy je mimořádně riskantní, a proto bude svého klienta důrazně varovat, aby takto v žádném případě neinvestoval.","Investiční poradce na základě uskutečněného pohovoru zařadil pana Fialu mezi profesionální zákazníky, a tudíž se k jeho záměru nebude vůbec vyjadřovat a celý investiční záměr klienta sám jako investiční poradce osobně zajistí.","Investiční poradce shledal investiční záměr pana Fialy zcela nesmyslným a jakoukoli další spolupráci v této věci s ním odmítne."],"c":[0],"p":171,"e":"Z jednání investičního poradce s panem Fialou vyplynulo, že klient problematice investic vcelku rozumí, dobře ví, čeho chce dosáhnout a je si dobře vědom všech souvisejících rizik. Současně došlo k podrobnému dojasnění jeho investičního záměru. A jelikož pan Fiala nehodlá investovat příliš vysoké částky, jejichž případná ztráta by ho existenčně neohrozila, je zcela v pořádku, aby mu investiční poradce navrhl vhodné řešení.","k":5},{"id":"20510.1","t":"c","q":"Která odpověď je správná?","o":["Akcie evropských společností denominovaných v EUR lze nakupovat na mnoha akciových burzách v měnách příslušných států; v ČR na RM-systému v CZK; dluhopisy denominované v EUR lze nakupovat především na světovém dluhopisovém OTC- trhu. A pokud klient požaduje současně i aktivní správu portfolia, lze též využít vhodného licencovaného obchodníka s cennými papíry, který může drobným klientům odprodat některé cenné papíry ze svého vlastního portfolia.","Akcie denominované v EUR lze nakupovat pouze na evropských akciových burzách, dluhopisy denominované v EUR pouze na celoevropské dluhopisové burze ve Frankfurtu nad Mohanem.","Akcie denominované v EUR lze nakupovat pouze na akciových burzách zemí eurozóny; dluhopisy denominované v EUR lze získat pouze smluvně u obchodních bank.","Akcie denominované v EUR lze nakupovat pouze na národních akciových burzách zemí eurozóny, nebo na přepážkách obchodních bank; dluhopisy denominované v EUR lze získat pouze na OTC-trhu."],"c":[0],"p":171,"e":"Akcie denominované v EUR se týkají společností registrovaných v zemích eurozóny; mohou se však obchodovat celosvětově v domácích měnách jednotlivých zemí, a to jak burzovně, tak i na OTC- trhu. V ČR jsou některé tituly tohoto druhu obchodovány na burze \"RM-systém\". A pokud jde o dluhopisy denominované v EUR, může je emitovat prakticky kdokoli na světě, přičemž se nejčastěji obchodují prostřednictvím celosvětového OTC-trhu (případně i burzovně). A pokud jde o obchodování s drobnými investory, mohou je provádět přímo obchodníci s cennými papíry (resp. dealeři) s využitím svých vlastních portfolií.","k":5},{"id":"20511.1","t":"c","q":"Kdo má právo poskytovat trvalou všestrannou péči o investiční portfolio klientů, neboli \"obhospodařovat majetek zákazníků\"?","o":["Obchodníci s cennými papíry.","Investiční zprostředkovatelé.","Investiční poradci.","Obchodníci s cennými papíry, investiční poradci a investiční zprostředkovatelé."],"c":[0],"p":172,"e":"\"Aktivní správa investičního portfólia\" je hlavní investiční službou \"Obhospodařování majetku zákazníka\" a mohou ji provádět výhradně obchodníci s cennými papíry.","k":5},{"id":"20512.1","t":"c","q":"Jak má investiční poradce řešit požadavek pana Fialy, když jde současně o opakované nakupování malých množství vybraných akcií a dluhopisů denominovaných v EUR a zároveň o obhospodařování klientova portfolia (rovněž v EUR)? Který z návrhů investičního poradce lze považovat za správný?","o":["Investiční poradce doporučí svému klientovi vhodného licencovaného obchodníka s cennými papíry, který je schopen nakupovat akcie na německé burze a rovněž i prostřednictvím RM-systému a umožní mu s ním sjednat smlouvu o obhospodařování majetku zákazníka. Současně svému klientovi doporučí stanovit poměr akcií a dluhopisů v poměru 70 % ku 30 %, který by ovšem mohl v budoucnu podle potřeby změnit.","Investiční poradce doporučí klientovi uzavřít s určitým obchodníkem s cennými papíry komisionářskou smlouvu a začít sám nakupovat prostřednictvím jeho obchodního systému určité akciové tituly. Pokud se týká dluhopisů, vzhledem k malým investovaným částkám mu dluhopisové investice rozmluví.","Investiční poradce začne sám klientovi nakupovat na jeho účet vhodné akcie a dluhopisy a obhospodařovat jeho portfolio.","Investiční poradce navrhne klientovi, aby investoval prostřednictvím jím spravovaného podílového fondu, jehož statut přibližně odpovídá investičním záměrům klienta."],"c":[0],"p":172,"e":"Jelikož klient požaduje aktivní správu investičního portfolia, je správné, že mu investiční poradce doporučí, aby se obrátil na licencovaného obchodníka s cennými papíry a sjednal s ním smlouvu o obhospodařování majetku zákazníka. A pokud se týká jeho doporučení nakupovat vedle akcií evropských společností dluhopisy pouze v omezeném množství v poměru 70 % akcií vůči 30 % dluhopisů, který lze v budoucnu podle potřeby změnit, jeví se toto doporučení jako vhodné.","k":5},{"id":"20520.1","t":"c","q":"O čem má investiční poradce s klientem jednat?","o":["Jednání by se mělo přímo zaměřit na investiční požadavek klienta, neboli na podrobné vyjasnění jeho investičního záměru, především o jeho investičních cílech a finanční situaci.","Investiční poradce by měl nejprve s klientem sjednat a nechat si vyplatit peněžní zálohu.","Investiční poradce musí nejprve podepsat s panem Dvořákem dodatek smlouvy o investičním poradenství.","Investiční poradce by měl nejprve s klientem sjednat a podepsat dodatek smlouvy o investičním poradenství a následně si nechat vyplatit zálohu za své služby."],"c":[0],"p":173,"e":"Pokud by nebyl finanční poradce stávajícím poradcem pana Dvořáka, tak by mu dal nejprve k vyplnění investiční dotazník, z něhož by zjišťoval informace ohledně jeho investičních zkušeností, finančního zázemí apod. Jelikož však všechny tyto informace má, bude v daném případě řešit pouze problematiku klientova aktuálního investičního záměru.","k":6},{"id":"20521.1","t":"c","q":"Z jednání investičního poradce s klientem vyplynulo, že pan Dvořák by chtěl investovat (vzhledem k nízkému úročení bankovních vkladů) do dluhopisů. A po investičním poradci požaduje, aby mu doporučil vhodné dluhopisy a následně mu zprostředkoval jejich nákup. Časový horizont investice stanovil sice na pět let, přesto však požaduje, aby je bylo možno v případě potřeby kdykoli prodat. Výnos požaduje pouze o něco málo vyšší, než by získal z pětiletého termínového bankovního vkladu. Zároveň ovšem vyžaduje investici s co možná nejnižším rizikem. Jak může investiční poradce tento požadavek klienta splnit?","o":["Investiční poradce si je vědom toho, že pan Dvořák je nezkušeným neprofesionálním zákazníkem, který navíc nedisponuje silným finančním zázemím a v daném případě spoléhá především na něj. Proto provede podrobnou analýzu klientova investičního záměru a bude volit pouze co nejméně rizikové nástroje. Nicméně pokud jde o představu jeho klienta o investování do dluhopisů, tento jeho záměr nerozporuje.","Investiční poradce si je sice vědom toho, že pan Dvořák je nezkušeným neprofesionálním zákazníkem, který ovšem disponuje volnými peněžními prostředky v objemu větším než půl miliónu korun. Proto mu hodlá nabídnout průměrně výnosné a středně rizikové dluhopisy.","Investiční poradce si je sice vědom toho, že pan Dvořák je neprofesionálním zákazníkem, který však disponuje volnými peněžními prostředky v objemu větším než půl miliónu korun. Proto mu hodlá doporučit dostatečně výnosné, i když současně též rizikové dluhopisy.","Investiční poradce zařadil pana Dvořáka vzhledem k výši investované částky mezi profesionální zákazníky a proto mu hodlá nabídnout vysoce výnosné spekulativní dluhopisy."],"c":[0],"p":173,"e":"V daném případě se jeví jako zvláště důležité, aby investiční poradce provedl najen analýzu investorova záměru, ale i analýzu aktuálně existujících investičních možností, aby mohl klientovi navrhnout nákup vhodného druhu na trhu aktuálně dostupných dluhopisů.","k":6},{"id":"20522.1","t":"c","q":"Kterou investiční variantu lze považovat pro daný případ za nejvhodnější?","o":["Co nejméně rizikové investiční (strukturované) certifikáty.","\"Klasické\" podnikové (korporátní) dluhopisy středně velkých akciových společností.","Co nejvýnosnější investiční (strukturované) certifikáty.","\"Double Reverse Convertible Bonds\""],"c":[0],"p":173,"e":"Za nejdůležitější faktory vycházející z požadavků klienta lze v daném případě považovat: co možná nejnižší rizikovost a stálou likviditu.","k":6},{"id":"20523.1","t":"c","q":"Který druh investičních (strukturovaných) certifikátů lze považovat z hlediska jejich rizikově-výnosového profilu za nejméně rizikový?","o":["Garantované certifikáty.","Bonus certifikáty.","Sprint certifikáty.","Outperformance certifikáty."],"c":[0],"p":174,"e":"Za nejméně rizikové lze považovat tzv. \"garantované certifikáty\", které však musí být drženy až do splatnosti a nesmí být koupeny za vyšší cenu, než byla jejich cena upisovací, za kterou je prodával emitent při uvádění do oběhu v tzv. upisovacím období.","k":6},{"id":"20524.1","t":"c","q":"Jaké je nejvhodnější doporučení investičního poradce?","o":["Investiční poradce navrhl klientovi zakoupit pětiletý, do oběhu nově uváděný garantovaný investiční certifikát, jehož podkladovým aktivem by byl široce pojatý burzovní index, jenž by emitovala renomovaná investiční společnost významné obchodní banky, která jej bude rovněž kótovat na předem určené burze cenných papírů.","Investiční poradce navrhl klientovi zakoupit konkrétní titul již dříve do oběhu uvedeného pětiletého sprint investičního certifikátu, jehož podkladovým aktivem je koš deseti akcií. Certifikát emitovala renomovaná investiční společnost a aktuálně jej obchoduje na burze cenných papírů, kde se jeho cena oproti upisovací ceně již zvýšila o 5 %.","Investiční poradce navrhl klientovi zakoupit standardní, fixně úročené, průměrně výnosné korporátní obligace dvou středně velkých akciových společností.","Investiční poradce navrhl klientovi zakoupit nově emitované, dvouleté, vysoce úročené \"Double Reverse Convertible Bonds\". Po dovršení termínu jejich splatnosti pak klientovi předloží nový návrh, jak jeho disponibilní peníze znovu investovat podle budoucích aktuálních podmínek."],"c":[0],"p":174,"e":"\"Garantované (strukturované) certifikáty\" jednak garantují návratnost investorem vložené částky (pokud jsou zakoupeny v době jejich úpisu a drženy až do splatnosti), jednak jsou burzovně obchodovatelné, neboli vysoce likvidní. Jejich riziky pak bývají druh, nebo způsob konstrukce jejich podkladového aktiva a dále riziko kreditní (neboli riziko případného selhání jejich emitenta).","k":6},{"id":"20538.1","t":"c","q":"Při měření míry likvidity podkladového aktiva zjišťujeme hlavně:","o":["Schopnost přeměnit investiční nástroj v peněžní prostředky.","Schopnost přeměnit dluhopisy na akcie.","Schopnost přeměnit nástroje promptního trhu. na nástroje termínového trhu","Schopnost emitenta včasně platit své závazky."],"c":[0],"p":175,"e":"likvidita je definována jako míra schopnosti podkladového aktiva investice přeměnit se na peněžní prostředky","k":7},{"id":"20539.1","t":"c","q":"Jestliže klient jako neprofesionální investor chce na základě doporučení svých známých koupit akcie, s nimiž se obchoduje na Burze cenných papírů v Praze, poradím mu postupovat následovně:","o":["Obrátit se na člena burzy - obchodníka s CP, aby mu obchod navrhl a zajistil realizaci.","Obrátit se na Centrální depozitář cenných papírů (CDCP), aby mu doporučil nejlikvidnější akcie.","Poradím mu akcie koupit přímo od protistrany (OTC)","Doporučím mu možnost nakoupit akcie na veřejné aukci SPAD."],"c":[0],"p":175,"e":"Otázka se týká znalostí poradce k nepřímému ověření stupně znalostí klienta o procedurách a oprávněních na finančním trhu.","k":7},{"id":"20540.1","t":"c","q":"Komerční bankovnictví oproti investičnímu pracuje převážně na riziko a účet:","o":["Vlastní.","Cizí.","Kumulované.","Atrofované."],"c":[0],"p":175,"e":"komerční bankovnictví oproti investičnímu bankovnictví pracuje převážně na vlastní účet a vlastní riziko","k":7},{"id":"20541.1","t":"c","q":"Obchodníci s CP vyřizují pokyny svých zákazníků (investorů) pomocí pokynů, zadávaných do obchodního systému. Následující pokyn (order) - Fill or Kill znamená","o":["Pokyn splnit, nebo zrušit a je určený k okamžité realizaci obchodu.","Umožňuje i pouze částečné splnění pokynu zákazníka.","Vícedenní pokyn platný do předem určeného data.","Podle tohoto pokynu makléř postupně nakoupí či prodá veškeré požadované množství aktiva."],"c":[0],"p":175,"e":"Jde o zažité standardní pokyny na burze. Jedná se o inteligentní pokyn (objednávku), která musí být uspokojena buď okamžitě a zcela nebo vůbec. Není-li okamžité plné uspokojení možné, systém objednávku zamítne.","k":7},{"id":"20542.1","t":"c","q":"Investora zajímá vztah mezi současnou a budoucí hodnotou investice. Zůstaneme-li u období jednoho roku a označíme současnou hodnotu \"PV\", budoucí hodnotu \"FV\" a úrokovou míru \"i\", pak vztah mezi současnou hodnotou a budoucí hodnotou za jedno období se dá vyjádřit jako:","o":["PV=FV/(1+i)","PV=FV*i","PV=FV/i","PV=FV*(1-i)"],"c":[0],"p":176,"e":"Jedná se o standardní matematický vzorec výpočtu pro časovou změnu hodnoty aktiva v závislosti na úrokové míře.","k":7},{"id":"21381.1","t":"c","q":"Z hlediska ekonomického vývoje, které odvětví bude nejvíce citlivé?","o":["Cyklické odvětví.","Anticyklické odvětví.","Asynchronní odvětví.","Defenzivní odvětví."],"c":[0],"p":177,"e":"Otázka se týká ověření znalostí vázaného zástupce v oblasti rozlišení typů investice v závislosti na cyklický vývoj ekonomiky. Odpověď vychází z klasické Keynesiánské ekonomické teorie.","k":8},{"id":"21382.1","t":"c","q":"Analýzou a prognózováním vývoje ekonomiky, odvětví i jednotlivých firem se zabývá:","o":["Fundamentální analýza.","Technická analýza.","Psychologická analýza.","Vertikální analýza."],"c":[0],"p":177,"e":"Otázka se týká ověření znalostí vázaného zástupce v oblasti testování averze klienta k riziku v různých oblastech investování. Odpověď vychází z klasického složení typů investičních analýz.","k":8},{"id":"21383.1","t":"c","q":"Klient má záměr zajistit si pravidelný nízkorizikový zdroj k doplnění financování svého studia. Za fondy s minimálním stupněm rizika se považují:","o":["Fondy peněžního trhu.","Fondy komoditní.","Fondy akciové.","Fondy dluhopisové."],"c":[0],"p":177,"e":"Otázka vázaného zástupce se týká dalšího upřesněnít oblasti vhodné pro doporučení investice. Správná odpověď vychází ze současné ekonomické teorie a praktických zkušeností.","k":8},{"id":"21384.1","t":"c","q":"Obchodní pokyn \"Trailing Stop\" znamená:","o":["Plovoucí příkaz, spodní hranice pro minimalizaci ztráty, roste spolu s růstem ceny akcie.","Plovoucí příkaz, horní hranice pro minimalizaci ztráty, roste spolu s růstem ceny akcie.","Plovoucí příkaz, spodní hranice pro minimalizaci ztráty, klesá spolu s růstem ceny akcie.","Příkaz okamžité potopit (zrušit) pokyn k obchodu."],"c":[0],"p":177,"e":"Otázka se týká testování úrovně znalostí klienta pro základní pokyny k obchodování. Správná odpověď je dána logikou pokynu a praxí na burzách.","k":8},{"id":"21385.1","t":"c","q":"Investor s vysokou averzí vůči riziku se rozhoduje mezi koupí akcií letecké společnosti L a autobusového přepravce A. Po výpočtu rizikovosti pomocí statistických nástrojů v procentních bodech získá tyto hodnoty : L = 5 p.b., A = 0 p.b., což znamená:","o":["Takovou možnost nesmí vázaný zástupce investičního zprostředkovatele (VZIZ) s klientem řešit, protože obchod se týká akcií a VZ IZ je nesmí zahrnout do poskytovaných investičních služeb.","Letecká společnost L je spojena s nižší nejistotou.","Letecká společnost L je spojena s vyšší nejistotou.","Autobusová společnost A se nachází v kovariantním středu nejistoty."],"c":[0],"p":178,"e":"Z hlediska technické výpočetní teorie je sice správná odpověď č. 3, ale přednost má legislativní řešení, tedy správná je odpověď č. 1, neboť obchod se týká akcií a VZ IZ je nesmí zahrnout do poskytovaných investičních služeb - viz § 29 odst. 3 ZPKT č. 256/2004 Sb.","k":8},{"id":"20550.2","t":"c","q":"Pan Syrovátka by si měl před investičním rozhodnutím věcně charakterizovat svou základní afinitu ke třem nejdůležitějším faktorům investování, daným v tzv. magickém trojúhelníku investora. Ten vyjadřuje vztah mezi:","o":["Očekávaným výnosem, rizikem a likviditou.","Očekávaným výnosem, dobou investice a likviditou.","Likviditou, splatností a solventností.","Rizikem, stupněm diverzifikace portfolia a zajištěním (hedgingem) investice."],"c":[0],"p":179,"e":"Otázka se týká základního principu investování a prozkoumání stupně averze klienta k riziku. Správná odpověď je dána praxí.","k":9},{"id":"20551.2","t":"c","q":"Které informace potřebuje poradce od pana Syrovátka dále zjistit?","o":["Jeho znalosti a zkušenosti s investičními nástroji.","Žádné informace nepotřebuje zjistit, poradce pouze přijme a předá pokyn k nákupu investičních instrumentů.","Potřebuje zjistit jen časový horizont (za jak dlouho budou peníze potřebovat).","Potřebuje zjistit časový horizont a jejich zkušenosti, tzn. vyplnit investiční dotazník ve zkráceném rozsahu."],"c":[0],"p":179,"e":"Podle zákona o podnikání na kapitálovém trhu je investičním poradcem osoba, která vyhodnocuje informace získané od klienta a aktivně vybírá a nabízí nejvhodnější produkty. Před poskytnutím investiční služby musí být proveden test přiměřenosti, kdy poradce zajímají klientovi znalosti a zkušenosti z oblasti investičních nástrojů. Pokud je vyhodnotí jako dostatečné pro porozumění rizika, transakci provede. V opačném případě upozorní klienta na nepřiměřenost transakce, ale provede ji, budete-li na klient trvat. Riziko však v tomto případě padá na klienta.","k":9},{"id":"20552.2","t":"c","q":"Pro rozhodování o nákupu a prodeji dluhopisů (ale i např. akcií) lze využít základní investiční analýzu, která odhaluje, zda je daný investiční nástroj trhem nadhodnocený či podhodnocený. Jedná se o:","o":["Fundamentální analýzu.","Technickou analýzu.","Psychologickou analýzu.","Behaviorální analýzu trhu."],"c":[0],"p":179,"e":"Fundamentální analýza je základní investiční anlýzou s cíle stanovení vnitřní hodnoty investičního nástroje a následného srovnání této hodnoty s tržní cenou, čímž investor získá předsatvu zda trh instrument ocenil správně, nebo jej nadhodnotil či podhodnotil.","k":9},{"id":"20553.2","t":"c","q":"Kterou z následujících skupin modelů nemůže investor Syrovátka použít pro stanovení vnitřní hodnoty vytipovaného dluhopisu?","o":["Cash flow modely.","Ziskové modely.","Indikátor krátkých (prázdných) prodejů.","Dividendové diskontní modely."],"c":[2],"p":179,"e":"Otázka se týká testování úrovně znalostí klienta pro základní pojmy ke zhodnocování výsledků různých analýz. Správná odpověď vyplývá ze znalosti typů analýz v této oblasti.","k":9},{"id":"20554.2","t":"c","q":"Jestliže vnitřní hodnota dluhopisu XYZ vyplývající z fundamentální analýzy je menší, než jeho tržní cena (kurz) na trhu, potom:","o":["By investor měl dluhopis prodat, resp. nezařadit do svého portfolia.","By investor měl dluhopis koupit, resp. zařadit do svého portfolia.","Je dluhopis nejlepší držet, příp. převážit v portfoliu a sledovat další zprávy.","Jde o informaci, která nemá na rozhodování o nákupu žádný vliv."],"c":[0],"p":180,"e":"Otázka se týká testování úrovně znalostí klienta pro základní pojmy ke zhodnocování výsledků různých analýz. Správná odpověď je dána logikou srovnání obou cen.","k":9},{"id":"20556.1","t":"c","q":"Poradce by měl reagovat na požadavek klienta a poučit jej, že:","o":["Investice není spořicí produkt, protože na rozdíl od spořicího produktu je s investicí spojeno riziko ztráty hodnoty investice.","Investice na dlouhém investičním horizontu je de facto ekvivalentem spořicího produktu.","Investice s konzervativní investiční strategií je de facto ekvivalentem spořicího produktu.","Rozdíl mezi investicí a spořicím produktem je zanedbatelný, jelikož spořicí produkt v sobě zahrnuje i investici."],"c":[0],"p":181,"e":"Z pohledu regulatorního (ČNB) existuje zásadní rozdíl mezi investicí a spořicím produktem - základním prvkem spořicího produktu je nemožnost poklesu majetku pod vloženou částku (typicky u bankovních produktů), na rozdíl od investičních produktů, kde hodnota majetku může klesnout pod vloženou částku.","k":10},{"id":"20557.1","t":"c","q":"Klient souhlasí, že jeho potřeba bude realizována prostřednictvím investičního nástroje. Na základě úvodního rozhovoru a získání základních informací o klientovi, poradce:","o":["Určí, zda se jedná o profesionálního zákazníka či nikoliv a sdělí mu, že není považován za profesionálního zákazníka.","Určí, zda se jedná o profesionálního zákazníka či nikoliv - zařazení do příslušné kategorie není třeba klientovi sdělovat, avšak je nutné jej zohlednit při poskytování investičních služeb.","Určí, zda se jedná o profesionálního zákazníka či nikoliv a nabídne mu, že jej může považovat za zákazníka profesionálního, pokud o to má klient zájem.","Není povinen určovat, zda se jedná o profesionálního zákazníka či nikoliv, pakliže s ním následně vyplní test vhodnosti."],"c":[0],"p":181,"e":"Osoba jednající se zákazníky provede tzv. kategorizaci zákazníka (určí, zda se jedná o zákazníka profesionálního či nikoliv) dle znění § 2a zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu a o zařazení do příslušné kategorie klienta informuje.","k":10},{"id":"20558.1","t":"c","q":"Poradce je povinen upozornit klienta mimo jiné na rizika spojená s investicemi do inv. nástrojů. Tuto povinnost poradce musí splnit:","o":["V dostatečném časovém předstihu před poskytnutím investiční služby.","Nejpozději spolu s poskytnutím investiční služby.","Bezprostředně poté, co poskytl investiční službu.","Povinnost má primárně poskytovatel investičního nástroje, poradce povinnost tudíž splní tím, že klientovi předá produktovou smlouvu obsahující předmětné informace."],"c":[0],"p":181,"e":"Osoba jednající se zákazníky je povinna poskytnout přiměřená poučení a upozornění ohledně rizik spojených s investicemi do těchto investičních nástrojů nebo s určitými strategiemi pro investování v dostatečném časovém předstihu před poskytnutím investiční služby.","k":10},{"id":"20559.1","t":"c","q":"Poradce sdělí klientovi, že poskytuje inv. služby přijímání a předávání pokynů týkajících se investičních nástrojů a investiční poradenství týkající se investičních nástrojů. Za účelem posouzení zákazníkova investičního profilu poradce:","o":["Je povinen si vyžádat informace o jeho znalostech a zkušenostech v oblasti investic, o finančním zázemí a investičních cílech.","Dá klientovi k vyplnění investiční dotazník obsahující tzv. test přiměřenosti a vyplní s ním finanční bilanci.","Je povinen získat informace o požadovaných investičních strategiích klienta a délce jeho investičního horizontu, na základě čehož následně vyhodnotí klientův investiční profil.","Požádá klienta, aby na základě svých znalostí a zkušeností v oblasti investic určil svůj investiční profil, který následně porovná s výsledky v investičním dotazníku."],"c":[0],"p":181,"e":"Osoba jednající se zákazníky je povinna získat od zákazníka nezbytné informace o jeho odborných znalostech a zkušenostech v oblasti investic, finančním zázemí a investičních cílech, pokud poskytuje investiční poradenství.","k":10},{"id":"20560.1","t":"c","q":"Na základě vyhodnocení získaných informací je zákazníkovi přidělen konzervativní investiční profil. Klientovi byla mezitím doručena konkurenční nabídka investice do podílového fondu, jehož SRRI je 4 a který požaduje od poradce zařadit do portfolia. Poradce, který poskytuje kromě inv. služby přijímání a předávání pokynů také službu inv. poradenství:","o":["Smí uvedený produkt zprostředkovat, avšak pouze v případě, že je na základě individuálního posouzení pro klienta vhodný.","Smí uvedený produkt zprostředkovat, ale musí klienta upozornit, že pro něj není vhodný.","Smí uvedený produkt zprostředkovat i v případě, že není pro klienta vhodný, jelikož poradce v tomto případě posuzuje pouze přiměřenost.","Nesmí uvedený produkt zprostředkovat."],"c":[0],"p":182,"e":"Osoba jednající se zákazníky zajistí, aby konkrétní obchod, který doporučí, nebo který má být uzavřen, splňoval kritéria individuální vhodnosti.","k":10},{"id":"21638.2","t":"c","q":"Posuďte uvedený reklamní slogan (\"potenciál vysokých výnosů s nepřímo úměrným rizikem\") z hlediska jeho souladu s právními předpisy:","o":["Není v pořádku, jelikož je nepravdivý či případně též klamavý.","Není v pořádku, jelikož z něj není patrné, že se jedná o propagační sdělení.","Není v pořádku, jelikož neinformuje o očekávané výši výnosu s odkazem na historickou výkonnost investičního nástroje.","Není zcela srozumitelný, jako takový ale není v rozporu s právními předpisy."],"c":[0],"p":183,"e":"Propagační sdělení týkající se investičních služeb nebo investičních nástrojů, nesmí používat nejasné, nepravdivé, zavádějící nebo klamavé informace. Z jeho obsahu a formy musí být zřejmé, že jde o propagační sdělení. Propagační sdělení, které slibuje \"vysoký výnos s nepřímo úměrným rizikem\", tedy malým rizikem, je zřejmě nepravdivý, potažmo klamavý, jelikož potenciálně vysoký výnos je vždy spojen rovněž s vysokým rizikem.","k":11},{"id":"21639.2","t":"c","q":"Poradce klientovi potvrdí, že je skutečně nezávislým, tedy že investiční službu inv. poradenství poskytuje nezávisle. Znamená to, že:","o":["Je povinen posoudit dostatečné množství investičních nástrojů dostupných na trhu, které jsou dostatečně různorodé z hlediska jejich druhu a emitentů.","Je odměňován provizně investičním zprostředkovatelem.","Smí poskytnout pouze hlavní inv. službu investiční poradenství, doporučený investiční nástroj však nesmí zprostředkovat (poskytnout hlavní inv. službu přijímání a předávání pokynů týkajících se inv. nástrojů).","Lže, jelikož vázaný zástupce nemůže poskytovat investiční služby nezávisle."],"c":[0],"p":183,"e":"Informuje-li osoba jednající se zákazníky zákazníka o tom, že hlavní investiční službu uvedenou v § 4 odst. 2 písm. e) poskytuje nezávisle, je povinna posoudit dostatečné množství investičních nástrojů dostupných na trhu, které jsou dostatečně různorodé z hlediska jejich druhu a emitentů nebo osob, které vytvářejí investiční nástroje tak, aby mohly být odpovídajícím způsobem naplněny investiční cíle zákazníka.","k":11},{"id":"21640.2","t":"c","q":"Poradce souhlasil, že se s klientem sejde a poskytne mu inv. poradenství, v rámci kterého posoudí, jaké investiční nástroje by mu doporučil. Poradce postupoval správně, když:","o":["Dal klientovi k vyplnění investiční dotazník obsahující test (posouzení) vhodnosti.","Vyplnil s klientem finanční analýzu obsahující finanční bilanci a dotazy na klientovy požadavky (tzv. investiční cíle).","Vyžádal si od klienta informace o jeho znalostech a zkušenostech v oblasti investic, jelikož ty se mohly od poslední schůzky změnit.","Zjistil aktuální výši majetku klienta, ostatní informace již měl z doby, kdy pro klienta sjednal pojistnou ochranu."],"c":[0],"p":183,"e":"Osoba jednající se zákazníky je povinna získat od zákazníka nezbytné informace o jeho odborných znalostech a zkušenostech v oblasti investic, finančním zázemí a investičních cílech. Pro výše uvedené se obecně používá pojem test (posouzení) vhodnosti.","k":11},{"id":"21641.2","t":"c","q":"Předpokládejme, že klient dosud nemá žádné zkušenosti s investováním. Má však velmi dobré finanční zázemí, přičemž klient chce investovat pouze část svých volných prostředků. Klient je srozuměn s tím, že o část prostředků může přijít a je takové riziko ochoten podstoupit. Poradce postupoval správně, když klientovi sdělil, že:","o":["Může zainvestovat i do rizikovějších inv. nástrojů, pakliže se jedná pouze o menší část jeho volných prostředků; pro začátek by mu doporučil například akciové podílové fondy.","Může své prostředky zainvestovat i do rizikových inv. nástrojů, pakliže se jedná o dostatečně dlouhý investiční horizont; v takovém případě není problém ani investice do akcií, zlata, nebo finančních derivátů.","Vzhledem k jeho nulovým zkušenostem s investováním nelze investovat žádné prostředky do rizikovějších inv. nástrojů; vhodné pro něj budou konzervativnější inv. nástroje, například fondy peněžního trhu, zajištěné fondy, pokladniční poukázky atp.","Akcie nejsou v souladu s jeho investičním profilem; na trhu však neexistuje ani žádný jiný inv. nástroj, který by byl pro jeho investiční profil a požadavky přiměřený."],"c":[0],"p":184,"e":"Osoba jednající se zákazníky zajistí, aby konkrétní obchod, který doporučí, splňoval kritéria individuální vhodnosti. Investiční zprostředkovatel (potažmo vázaný zástupce) není oprávněn poskytovat inv. službu ve vztahu k akciím, derivátům.","k":11},{"id":"21642.2","t":"c","q":"Klient trvá na investici do akcií start-upových firem, na kterou viděl reklamu v metru. Poradce uvedený inv. nástroj:","o":["Nesmí zprostředkovat, protože není oprávněn poskytovat investiční služby ve vztahu k akciím.","Nesmí zprostředkovat, protože akcie nejsou pro klienta přiměřené.","Nesmí zprostředkovat, protože poskytuje investiční služby nezávisle.","Smí zprostředkovat, protože se jedná o inv. nástroj, který si klient sám vybral a poradce tudíž neposkytl inv. službu inv. poradenství."],"c":[0],"p":184,"e":"Investiční zprostředkovatel (potažmo vázaný zástupce) je oprávněn poskytovat investiční služby pouze ve vztahu k inv. nástrojům uvedeným v § 29 odst. 3 ZPKT; akcie sem nepatří.","k":11},{"id":"21325.4","t":"c","q":"Vázaný zástupce obchodníka s cennými papíry (VZ) poskytuje hlavní investiční službu přijímání a předávání pokynů týkajících se investičních nástrojů. Jakým způsobem provede vázaný zástupce tzv. test přiměřenosti?","o":["VZ je povinen zjišťovat znalosti a zkušenosti klienta. Klient má střední vzdělání nesouvisející s oborem financí či jemu příbuzným, nepracuje v oboru, který by byl podstatný pro posouzení znalostí či zkušeností s finančním trhem. Klient má však sjednány mj. finanční produkty, které jsou investičními nástroji či mají investiční nástroj jako podkladové aktivum. VZ považuje klienta s ohledem na výše uvedené za středně pokročilého a je tedy oprávněn doporučit mu investiční nástroje se střední mírou rizika např. dluhopisové či smíšené fondy.","VZ je povinen zjišťovat pouze znalosti a zkušenosti klienta a jeho finanční zázemí. Finanční zázemí klienta je dobré, finanční bilance klienta je kladná, má vytvořenou krátkodobou rezervu. Vzhledem k dobrému finančnímu zázemí nejsou informace o znalostech a zkušenostech klienta pro posouzení tak důležité. VZ považuje klienta s ohledem na výše uvedené za velmi pokročilého a je tedy oprávněn doporučit mu fondy kvalifikovaných investorů.","VZ je povinen zjišťovat pouze znalosti a zkušenosti klienta. Klient má střední vzdělání nesouvisející s oborem financí či jemu příbuzném, nepracuje v oboru, který by byl podstatný pro posouzení znalostí či zkušeností s finančním trhem. Klient má však sjednány mj. finanční produkty, které jsou investičními nástroji či mají investiční nástroj jako podkladové aktivum. VZ považuje klienta s ohledem na výše uvedené za velmi zkušeného a je tedy oprávněn doporučit mu konkrétní akciový fond.","VZ je povinen zjišťovat znalosti a zkušenosti klienta, finanční zázemí, investiční cíle a vztah k riziku. Vzhledem k tomu, že má klient sjednány finanční produkty, které jsou investičními nástroji či mají investiční nástroj jako podkladové aktivum, má vyhovující finanční zázemí, má v portfoliu konzervativní finanční produkty, není již nutné posuzovat vztah klienta k riziku a VZ je oprávněn doporučit jakýkoliv investiční nástroj včetně derivátů."],"c":[0],"p":185,"e":"Dle právní úpravy se při poskytování investiční služby přijímání a předávání pokynů zjišťují znalosti a zkušenosti klienta a není oprávněn zjišťovat další informace, které jsou vázány na poskytování investičního poradenství či obhospodařování. Z toho vyplývá, že vázáný zástupce není oprávněn doporučit konkrétní fond pouze skupinu či typ fondů. Finální výběr je na klientovi.","k":12},{"id":"21326.4","t":"c","q":"Vázaný zástupce obchodníka s cennými papíry (VZ) poskytuje hlavní investiční službu přijímání a předávání pokynů a investiční poradenství. Jakým způsobem provede VZ tzv. test vhodnosti za předpokladu, že klient má zájem investovat část (30 %) svých volných prostředků a hodlá si v horizontu 7 let koupit chatu za 300 000 Kč?","o":["VZ je povinen zjišťovat od klienta kromě informací o znalostech a zkušenostech také informace o finančním zázemí a investičních cílech. Součástí informací o investičních cílech je však také informace o rizikové toleranci klienta, kterou klient VZ nesdělil a VZ musí tuto informaci od klienta zjistit, protože bez ní není schopen posoudit, zda případný doporučený investiční nástroj bude pro klienta vhodný či nikoliv.","VZ je povinen zjišťovat od klienta kromě informací o znalostech a zkušenostech také informace o finančním zázemí a investičních cílech. Všechny tyto informace o klientovi jsou patrné ze zadání případové studie či této otázky a na základě těchto údajů je VZ oprávněn doporučit klientovi vhodný investiční nástroj.","VZ je povinen zjišťovat od klienta kromě informací o znalostech a zkušenostech také informace o finančním zázemí a investičních cílech. Klient však odmítl VZ sdělit informaci o jeho toleranci k riziku. VZ však i přes absenci této informace může klientovi doporučit vhodný investiční nástroj a následně mu ho zprostředkovat, pokud klient prohlásí, že se vzdává nároku požadovat náhradu škody, která mu hrozí z důvodu nedostatečného posouzení vhodnosti produktu.","VZ je povinen zjišťovat od klienta kromě informací o znalostech a zkušenostech také informace o finančním zázemí a investičních cílech. Vzhledem k tomu, že klienta je z údajů uvedených v zadání případové studie či této otázky možno považovat za profesionálního zákazníka, posouzení vhodnosti být provedeno nemusí, jelikož klient je schopen posoudit vhodnost, včetně souvisejících rizik, sám."],"c":[0],"p":185,"e":"Dle právní úpravy se při poskytování investičního poradenství zjišťují kromě znalostí a zkušeností také finanční zázemí, investiční cíle zákazníka, kam patří i tolerance k riziku, preference k délce držení investičního nástroje. V případě, že vázaný zástupce takové informace nezjistí, nemůže posoudit vhodnost nástroje a není oprávněn nástroj zprostředkovat. Zároveň zákazníka není možné považovat za profesionálního dle definice profesionálního zákazníka, která je uvedna v zákoně č. 256/2004 Sb.","k":12},{"id":"21327.6","t":"c","q":"Klient chce koupit investiční nástroj, který neodpovídá jeho znalostem a zkušenostem. Jakým způsobem může vázaný zástupce obchodníka s cennými papíry (VZ), který poskytuje investiční službu přijímání a předávání pokynů postupovat?","o":["VZ upozorní klienta na skutečnost, že požadovaný investiční nástroj neodpovídá jeho znalostem a zkušenostem, ale je oprávněn přijmout a předat pokyn k nákupu tohoto investičního nástroje, pokud i přes upozornění klient trvá na realizaci pokynu.","VZ není oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který neodpovídá znalostem a zkušenostem klienta.","VZ je oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který neodpovídá znalostem a zkušenostem klienta, ale společně s předáním pokynu je povinen informovat obchodníka s cennými papíry, který musí provedení pokynu schválit.","VZ je oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který neodpovídá znalostem a zkušenostem klienta, ale je povinen evidovat veškeré takové pokyny a na vyžádání ČNB je předložit v rámci výkonu dohledu."],"c":[0],"p":186,"e":"V případě, že je poskytována investiční služba investiční poradenství nesmí vázaný zástupce přijmout pokyn k nákupu investičního nástroje, pokud pro klienta není vhodný.","k":12},{"id":"21328.7","t":"c","q":"Klient chce koupit investiční nástroj, který pro něj není vhodný s ohledem na posouzení jeho situace. Jakým způsobem může vázaný zástupce obchodníka s cennými papíry (VZ), který poskytuje investiční služby přijímání a předávání pokynů a investiční poradenství postupovat?","o":["VZ není oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který není pro klienta vhodný.","VZ poučí klienta o nevhodnosti investičního nástroje a konkrétních rizicích, kterým je vystaven v případě, že se rozhodne koupit investiční nástroj, který pro něj není vhodný, ale je oprávněn přijmout a předat pokyn k nákupu tohoto investičního nástroje, pokud na jeho nákupu klient i přesto trvá.","VZ je oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který pro klienta není vhodný, ale společně s předáním pokynu je povinen informovat obchodníka s cennými papíry, který musí provedení pokynu schválit.","VZ je oprávněn přijmout a předat pokyn k nákupu investičního nástroje, který pro klienta není vhodný, ale je povinen evidovat veškeré takové pokyny a na vyžádání ČNB je předložit v rámci výkonu dohledu."],"c":[1],"p":186,"e":"V případě, že je poskytována investiční služba přijímání a předávání pokynů, může vázaný zástupce přijmout a předat pokyn, pokud klienta předem upozorní na to, že žádaný investiční nástroj neodpovídá jeho znalostem a zkušenostem a klient i přesto trvá na koupi takového investičního nástroje. V případě poskytování služby investičního poradenství pak klientovi nesmí doporučit nevhodný investiční nástroj.","k":12},{"id":"21329.6","t":"c","q":"Klient chce zrušit uzavřenou smlouvu na pravidelnou investici, u které již má zaplacený vstupní poplatek na celou dobu investice, a prostředky ve výši 70 000 Kč investovat jednorázově do totožného inv. nástroje, protože slyšel od souseda, že jednorázové investice mají nižší náklady než investice pravidelné. Jakým způsobem by měl vázaný zástupce (VZ) postupovat, poskytuje-li investiční službu přijímání a předávání pokynů?","o":["Vzhledem k tomu, že již má klient na pravidelné investici zaplacen vstupní poplatek na celou dobu investice, v případě zrušení smlouvy by o většinu zaplaceného poplatku přišel a náklady by sjednáním jednorázové investice zaplatil znovu. VZ je povinen jednat s odbornou péčí v nejlepším zájmu klienta a vysvětlit mu dopady jeho rozhodnutí. Vázaný zástupce by tedy neměl pokyn realizovat.","Vzhledem k tomu, že VZ poskytuje přijímání a předávání pokynů, neposuzuje vhodnost pokynu pro klienta a je povinen respektovat požadavek klienta a realizovat ho.","VZ je oprávněn požadavek klienta provést, ale pouze za předpokladu, že mu dá alespoň 50 % slevu na vstupním poplatku u jednorázové investice.","VZ je oprávněn požadavek klienta provést, ale pouze za předpokladu, že mu ho schválí obchodník s cennými papíry."],"c":[0],"p":186,"e":"Obecná pravidla jednání se zákazníky stanoví povinnost jednat v nejlepším zájmu zákazníků a vysvětlit informace ohledně investičního nástroje, investičních služeb, aby pochopil dopady svých rozhodnutí. Klient není schopen bez dalšího pochopit dopady svých rozhodnutí a provedením pokynu by VZ porušil uvedené pravidlo jednat v nejlepším zájmu klienta.","k":12},{"id":"20996.1","t":"c","q":"V jakém postavení a jakým způsobem může zprostředkovatel poskytovat investiční služby?","o":["Za předpokladu splnění zákonných podmínek může být investičním zprostředkovatelem a činnost může vykonávat osobně, prostřednictvím svých zaměstnanců, nebo vázaných zástupců.","Za předpokladu splnění zákonných podmínek může být investičním zprostředkovatelem, avšak v takovém případě může činnost vykonávat pouze osobně.","Za předpokladu splnění zákonných podmínek může být investičním zprostředkovatelem, avšak v takovém případě může činnost vykonávat pouze pro jednoho obchodního partnera (emitenta cenného papíru).","Fyzická osoba nemůže být investičním zprostředkovatelem. Za předpokladu splnění zákonných podmínek může činnost vykonávat jako vázaný zástupce."],"c":[0],"p":187,"e":"Fyzická osoba může být investičním zprostředkovatelem za předpokladu splnění zákonných podmínek uvedených v § 30 odst 2 ZPKT. Činnost smí vykonávat osobně, prostřednictvím svých zaměstnanců a vázaných zástupců.","k":13},{"id":"20997.1","t":"c","q":"Jakým způsobem je zprostředkovatel povinen informovat zákazníka o svém povolení k výkonu činnosti?","o":["V dostatečném předstihu před poskytnutím investiční služby sdělit zákazníkovi, že má příslušné povolení k výkonu činnosti, a název a kontaktní adresu orgánu, který toto povolení vydal.","Nejpozději při poskytnutí investiční služby sdělit zákazníkovi údaje o své osobě, kontaktní údaje a číslo svého oprávnění k výkonu činnosti.","Před poskytnutím investiční služby sdělit kontaktní údaje na zastoupeného, kterému zprostředkovatel předává pokyny, aby si u něj mohl zákazník existenci povolení k výkonu činnosti ověřit","Na žádost zákazníka sdělit, že povolení k výkonu činnosti si může zákazník ověřit v registru vedeném Českou národní bankou."],"c":[0],"p":187,"e":"Osoba jednající se zákazníky je povinna v dostatečném předstihu před poskytnutím investiční služby poskytnout zákazníkovi prohlášení, že má příslušné povolení k výkonu činnosti, a název a kontaktní adresu příslušného orgánu, který toto povolení vydal.","k":13},{"id":"20998.2","t":"c","q":"Jaké informace musí zprostředkovatel od zákazníka získat před poskytnutím investiční služby?","o":["Informace o odborných znalostech a zkušenostech v oblasti investic osoby, která bude při uzavírání smlouvy zákazníka zastupovat (jednatel, příp. pověřený zaměstnanec).","Pouze informace o zkušenostech zákazníka v oblasti investic, jelikož odborné znalosti nelze u právnické osoby posuzovat.","Informace o odborných znalostech a zkušenostech v oblasti investic osoby, která bude při uzavírání smlouvy zákazníka zastupovat (jednatel, příp. pověřený zaměstnanec) a informace o finančním zázemí a investičních cílech zákazníka.","Žádné informace není potřeba zjišťovat, jelikož právnická osoba je považována za profesionálního zákazníka, ledaže by sama požádala o změnu kategorizace (přeřazení do kategorie neprofesionální zákazník - spotřebitel)."],"c":[0],"p":187,"e":"Při poskytování investiční služby přijímání a předávání pokynů týkajících se investičních nástrojů je osoba jednající se zákazníkem povinna zjistit informace o odborných znalostech a zkušenostech zákazníka v oblasti investic. V případě, že je zákazníkem právnická osoba, posuzuje se výše uvedené ve vztahu k osobě, která v daném obchodě zákazníka zastupuje.","k":13},{"id":"20999.2","t":"c","q":"Předpokládejme, že ani zákazník, ani osoba zastupující zákazníka, dosud nemají žádné znalosti a zkušenosti v oblasti investic. Pakliže znáte záměry zákazníka uvedené v zadání, může zprostředkovatel doporučit zákazníkovi investici do dluhopisů společnosti SAZKA?","o":["Ne, jelikož zprostředkovatel neposkytuje investiční službu investiční poradenství.","Ne, jelikož zprostředkovatel není oprávněn poskytovat investiční služby ve vztahu ke korporátním dluhopisům.","Ne, jelikož korporátní dluhopisy nejsou pro zákazníka vzhledem k jeho individuálním charakteristikám vhodným investičním nástrojem.","Ano, uvedené dluhopisy jsou s ohledem na s nimi spojené (minimální) riziko a dostatečně dlouhý investiční horizont (5 let) pro zákazníka přiměřeným investičním nástrojem."],"c":[0],"p":188,"e":"Poskytnutí individualizovaného doporučení zákazníkovi ohledně obchodu s konkrétním investičním nástrojem je předmětem investiční služby investiční poradenství, nikoliv přijímání a předávání pokynů týkajících se investičních nástrojů. Zprostředkovatel by tedy žádné konkrétní investiční nástroje doporučovat neměl, může pouze převzít pokyn zákazníka.","k":13},{"id":"21000.2","t":"c","q":"Zákazníka zaujala možnost investovat do dluhopisů společnosti SAZKA a rozhodl se uvedenou investici zrealizovat (bez ohledu na skutečnost, zda zprostředkovatel mohl či nemohl uvedenou investici doporučit). Smí zprostředkovatel investici zákazníkovi zprostředkovat i v případě, že by se nejednalo o pro něj přiměřený investiční nástroj?","o":["Ano, je však povinen upozornit zákazníka na skutečnost, že se nejedná o pro něj přiměřený investiční nástroj.","Ano, musí si však vyžádat písemné prohlášení zákazníka o tom, že si předmětný investiční nástroj zvolil sám.","Ano, u právnických osob se přiměřenost neposuzuje, jelikož se považují za profesionální zákazníky (ledaže by zákazník sám požádal o změnu kategorizace).","Ne, zákazníkovi nelze zprostředkovat investiční nástroj, který pro něj není přiměřený."],"c":[0],"p":188,"e":"V případě, že osoba jednající se zákazníky vyhodnotí získané informace tak, že poskytnutí příslušné investiční služby neodpovídá jeho odborným znalostem nebo zkušenostem, upozorní zákazníka na takové zjištění. Zprostředkovatel tedy může zprostředkovat i takový investiční nástroj, který není pro zákazníka přiměřený za předpokladu, že jej o této skutečnosti informuje.","k":13},{"id":"22359.1","t":"c","q":"Při vyplňování Investičního dotazníku, se klient zarazil u dotazu na výši svého příjmu:","o":["Poradce klientovi vysvětlil, že tento údaj je nutné znát pro vyhodnocení jeho finančního zázemí. Bez tohoto údaje nelze provést vyhodnocení finanční situace klienta a poskytnout službu investičního poradenství.","Poradce se s klientem domluvil, že uvedou pouze údaj o aktuálním majetku klienta a jeho závazcích. Tento údaj je dostačující k vyhodnocení finanční situace klienta a k poskytnutí služby investičního poradenství.","Poradce klienta upokojil, že tento citlivý údaj nemusí uvádět. Na doporučení konkrétního investičního nástroje to nebude mít vliv. Znalost výše příjmu není nutná pro poskytnutí služby investičního poradenství.","Poradce klientovi vysvětlil, že tento údaj je nutné znát pro vyhodnocení finančního zázemí. Bez tohoto údaje nelze provést vyhodnocení finanční situace klienta. Lze tedy poskytnout službu investičního poradenství pouze, pokud předmětem doporučení budou výhradně konzervativní investiční nástroje."],"c":[0],"p":189,"e":"Výše příjmu slouží poradci pro vyhodnocení finančního zázemí klienta a pro výběr vhodného investičního nástroje.","k":14},{"id":"22360.1","t":"c","q":"Poradce chce v navrhovaném investičním portfoliu pro klienta eliminovat měnové riziko. Bude tedy vybírat mezi investičními fondy:","o":["Které využívají nástroje pro zajištění měnového rizika nebo investují pouze do nástrojů v domácí měně klienta.","Které investují pouze do investičních nástrojů v měnách USD a EUR.","Které mají ISIN začínající CZ.","Které investují do akcií a dluhopisů vydávaných pouze českými emitenty"],"c":[0],"p":189,"e":"Eliminace měnového rizika předpokládá investici do nástrojů vydaných v domácí měně nebo zajištěných proti pohybu měny.","k":14},{"id":"22361.1","t":"c","q":"Klient vyjádřil přání zařadit do svého investičního portfolia investici zaměřenou na akcie společností na rozvíjejících se trzích. Který fond bude pro klienta pravděpodobně nejvhodnější vzhledem k jeho geografickému požadavku?","o":["Emerging Markets Equity","Global Equity Diversification","Emerging Markets Corporate Bond","Asian High Yield"],"c":[0],"p":189,"e":"Rozvíjející se trhy jsou v názvech fondů označované jako \"emerging market\". Výraz Equity znamená investici do akcií. Global growth - bude investovat do akcií bez omezení regionuCorporate Bond, High Yield - názvy označují strategii investování do dluhopisů emitovaných korporátními subjekty ((zpravidla vyšší rizikovost než státní dluhopisy), resp. velmi rizikovými dluhopisy, mající rating ve spekulativním pásmu.","k":14},{"id":"22362.1","t":"c","q":"Klient podepisuje Smlouvu o obstarání nákupu cenných papírů, včetně pokynu k nákupu zvolených investičních fondů. Poradce:","o":["Musí tuto smlouvu předat příslušné investiční společnosti bezodkladně po podpisu klienta.","Musí tuto smlouvu předat příslušné investiční společnosti nejpozději do 15 dnů po podpisu klienta.","Musí tuto smlouvu předat příslušné investiční společnosti nejpozději do konce kalendářního měsíce následujícího po měsíci, v němž klient smlouvu podepíše.","Musí tuto smlouvu předat příslušné investiční společnosti nejpozději do konce kalendářního měsíce, v němž klient smlouvu podepíše."],"c":[0],"p":189,"e":"Zákon č. 256/2004 Sb., o podnikání na kapitálovém trhu stanovuje, že Obchodník s cennými papíry je povinen provést přijatý pokyn za co nejlepších podmínek, včetně rychlosti provedení pokynu. Toto ustanovení přiměřeně platí i pro Investiční zprostředkovatele. Co nejrychlejší předání pokynu tedy vyjadřuje provedení pokynu za nejlepších podmínek.","k":14},{"id":"22363.1","t":"c","q":"Poradce vybírá pro svého klienta do portfolia dva fondy investující do fixně úročených dlupisů. Fond A má duraci portfolia 1,8, fond B 3,6. Který bude méně rizikový s ohledem na předpoklad rostoucích úrokových sazeb v ekonomice?","o":["Fond A","Fond B","Na základě durace nelze určit míru rizika vyplývající ze změny úrokových sazeb.","Z pohledu rizika vyplývajícího ze změny úrokových sazeb jsou si oba fondy rovny."],"c":[0],"p":190,"e":"Durace dluhopisového portfolia měří citlivost změny ceny dluhopisů na změnu úrokových sazeb v ekonomice. Při předpokladu růstu sazeb je předpoklad poklesu cen, tedy i poklesu výnosu dluhopisového fondu. Protože vztah mezi vývojem ceny dluhopisu (hodnotou majetku fondu) inverzní, bude docházet s růstem sazeb k poklesu hodnoty. Čím vyšší durace, tím v tomto případě vyšší pokles hodnoty majetku fondu.","k":14},{"id":"22353.1","t":"c","q":"Klient nechce ztrácet příliš času s vyplňováním investičního dotazníku. Jakou míru součinnosti může pracovník obchodníka s cennými papíry poskytnout klientovi při vyplňování investičního dotazníku?","o":["Klient musí vždy odpovědi v dotazníku vyplnit sám na základě vlastních znalostí a zkušeností. K odpovědím nesmí být žádným způsobem nasměřován a odpovědi za něj nesmí být vyplňovány.","Jelikož se jedná o klienta, se kterým již v minulosti byl uzavřen obchod, může pracovník investiční dotazník vyplnit za něj, a to podle odpovědí v posledním platném investičním dotazníku.","Může mu poskytnout vzorově vyplněný investiční dotazník, který odpovídá předpokládanému rizikovému profilu klienta.","V případě, že odpovědi jsou hodnoceny body, smí ho odkázat na tyto body, které klientovi poskytnou vodítko k méně a k více rizikovému profilu a usnadní a urychlí vyplňování odpovědí."],"c":[0],"p":191,"e":"Investiční dotazník slouží především k tomu, aby byly získány informace vyžadované §15h odst. 1 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu. Pracovník proto nesmí klientovi radit nebo jej vést při odpovídání na dotazy v investičním dotazníku. Smí maximálně vysvětlit některé pojmy.","k":15},{"id":"22354.1","t":"c","q":"Klient by rád využil co nejvýnosnějších investičních nástrojů. Preferuje akcie. Jak by na tuto skutečnost měl pracovník zareagovat?","o":["Upozorní klienta, že vzhledem k požadovanému investičnímu horizontu nejsou akcie, kvůli své typicky vyšší volatilitě, vhodným nástrojem, protože se u nich doporučuje zpravidla 8-10letý horizont.","Požadavek zaznamenat, upozornit klienta jej na rizika spojená s investováním do akcií a doporučit mu vhodný akciový titul.","Vybrat a doporučit klientovi pouze akcie vydané emitenty z regionů vyspělých zemí.","Vzhledem ke sdělenému investičnímu horizontu by měl klientovi doporučit investici do podílových akciových fondů místo investice do konkrétních akciových titulů"],"c":[0],"p":191,"e":"Akciové nástroje jsou z podstaty dynamickou investicí, které odpovídá dostatečně dlouhý investiční horizont, minimálně 5 let. Zadaný investiční horizont klienta je výrazně kratší, taková investice pro něj není vhodná.","k":15},{"id":"22355.1","t":"c","q":"Vzhledem k výsledku odpovědí investičního dotazníku a požadovanému investičnímu horizontu zvolí poradce pro klienta konzervativní investiční strategii. Jaké druhy investičních fondů bude při tvorbě portfolia využívat?","o":["Fondy peněžního trhu, případně fondy krátkodobějších dluhopisů s efektivní durací do tří let.","Akciové fondy a smíšené fondy.","Private equity fondy.","Fondy korporátních dluhopisů s vysokým výnosem."],"c":[0],"p":191,"e":"Investiční fondy investující do akcie, do korporátní dluhopisy i fondy smíšené lze obecně považovat za rizikové kategorie investičních fondů a nelze je doporučit klientovi, pro něhož je vhodná konzervativní investiční strategie. Investice do private equity fondů jsou spojeny s vysokou mírou rizika a vyžadují dlouhý investiční horizont, proto se opět nejedná o investici vhodnou pro uvedený typ klienta.","k":15},{"id":"22356.1","t":"c","q":"Klient podepisuje Smlouvu o obstarání nákupu a prodeje podílových listů investičního fondu, která zároveň obsahuje Pokyn k nákupu podílových listů fondu. Za jakou cenu budou dané podílové listy nakoupeny?","o":["Za cenu předem neznámou, která bude platná ke dni, kdy administrátor fondu obdrží Smlouvu, resp. Pokyn.","Za cenu platnou ke dni podpisu Smlouvy, resp. Pokynu.","Za cenu, která bude platná 3 dny po podpisu Smlouvy, resp. Pokynu.","Za cenu předem známou, která bude platná ke dni, kdy administrátor fondu obdrží Smlouvu, resp. Pokyn."],"c":[0],"p":191,"e":"Datum podpisu Pokynu není rozhodující pro stanovení ceny nákupu. Rozhodující je datum přijetí pokynu Administrátorem fondu.","k":15},{"id":"22357.1","t":"c","q":"Klient si v dokumentu KIID (Klíčové informace pro klienta, Key INvestor Information Document) nabízeného investičního fondu všimne údaje o výši výkonnostní odměny, která je stanovena jako 10 % z překonání benchmarku. Pokud má benchmark za sledované období výkonnost 1,0 % a fond vykáže výnos 1,5 %, jaká bude výkonnostní odměna?","o":["0,0005.","0,001.","0,0015.","0,1."],"c":[0],"p":192,"e":"Výkonnostní odměna je počítána z nadvýnosu, tedy rozdílu mezi výnosem fondu a výnosem benchmarku. Tedy (1,5 - 1,0)*0,1.","k":15},{"id":"22372.1","t":"c","q":"Při prvním jednání poradce sdělí klientovi, že poskytuje službu investičního poradenství. Jako nezbytné minimální množství informací pro poskytnutí této služby musí od klienta zjistit jeho:","o":["Znalosti v oblasti investic, zkušenosti v oblasti investic, finanční zázemí a investiční cíle.","Znalosti v oblasti investic a zkušenosti v oblasti investic.","Znalosti v oblasti investic, zkušenosti v oblasti investic a finanční zázemí.","Znalosti v oblasti investic, zkušenosti v oblasti investic a investiční cíle."],"c":[0],"p":193,"e":"V souladu s § 15h odst. 1 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu je poradce povinen získat od klienta všechny informace uvedené pod písmeny a) až d) tohoto ustanovení.","k":16},{"id":"22373.1","t":"c","q":"Klient se zeptá, co se stane, pokud odmítne vyplnit investiční dotazník. Poradce odpoví:","o":["V takovém případě Vám nemohu poradit s výběrem vhodného investičního nástroje. Smím jej však pro Vás zprostředkovat, pokud si jej sám vyberete. Upozorňuji však, že nejsem schopen posoudit, zda je pro Vás vhodný.","V takovém případě pro Vás bohužel již dále nemohu nic udělat. Investiční dotazník je nutný dokument, bez něhož Vám nemohu nabídnout nic ze svých služeb.","V takovém případě Vás však upozorňuji, že moje rada ohledně investičního nástroje je bez záruky a veškerá rizika spojená s touto volbou přebíráte na sebe Vy.","V takovém případě Vám mohu poradit pouze pokud skutečnost, že jste odmítl vyplnit investiční dotazník bude uvedena v Záznamu z jednání, který mi podepíšete."],"c":[0],"p":193,"e":"Při neposkytnutí informací zákazníkem dle § 15h odst. 1 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu poradce nesmí poskytnout službu investičního poradenství, tedy investiční službu dle §4 odst. 2 písm. e) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu. V souladu s ustanovením §15i odst. 4 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu smí nabídnout pouze zprostředkování, tedy dle §4 odst. 2 písm. a) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu, ale s upozorněním, že on ani třetí strana nejsou odpovědni za jakékoliv ztráty klienta.","k":16},{"id":"22374.1","t":"c","q":"Klient by si přál investovat do dluhopisů, ovšem s co nejmenším rizikem jejich nesplacení. Poradce jej upozorní, že v takovém případě je oprávněn poskytovat investiční služby pouze ve vztahu k emisím dluhopisů, u nichž byl uveřejněn prospekt cenného papíru. Toto omezení klient akceptuje. U relevantních dluhopisů pak bude zkoumat, zda jsou:","o":["V investičním pásmu ratingového hodnocení, či mimo investiční pásmo ratingového hodnocení.","V domácí měně klienta.","S fixním úročením.","Pojištěny Garančním systémem finančního trhu."],"c":[0],"p":193,"e":"Kreditní riziko dluhopisu lze vyvodit ze skutečnosti, zda rating emitenta je v investičním pásmu, či již mimo investiční pásmo. Dvě varianty nesprávných odpovědí - tj. domácí měna klienta a údaj o fixním úročení - nejsou relevantní pro posouzení kreditního rizika dluhopisu, stejně jako garance poskytované Garančním systémem finančního trhu. Zadání otázky pak reflektuje skutečnost, že v souladu s § 29 odst. 3 písm. d) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu je investiční zprostředkovatel oprávněn poskytovat investiční služby pouze ve vztahu k emisím dluhopisů, ke kterým byl vydán prospekt.","k":16},{"id":"22375.1","t":"c","q":"Které z uvedených hodnot či parametrů ovlivní cenu, za kterou klient nakoupí doporučený dluhopis?","o":["Nominální hodnota, tržní kurz, datum splatnosti, datum výplaty kuponu, výše ročního kuponu a poplatky za nákup.","Nominální hodnota, emisní ažio, datum nákupu, datum výplaty kuponu a poplatky za nákup.","Nominální hodnota, výše základního kapitálu emitenta, tržní kurz, výnos do splatnosti a poplatky za nákup.","Nominální hodnota, hodnota vlastního kapitálu emitenta, tržní kurz, výše ročního kuponu a poplatky za nákup."],"c":[0],"p":194,"e":"Parametry uvedené ve správné odpovědi - tedy nominální hodnota dluhopisu, jeho tržní kurz, datum splatnosti, datum výplatu kuponů, výše ročního kuponů a poplatky za nákup - ovlivňují cenu, za kterou klient realizuje investici. A to v tom smyslu, že na jejich základě je vypočtena cena, za kterou je realizován předmětný nákup. Naopak hodnota emisního ážia, základního kapitálu a vlastního kapitálu emitenta není relevantní pro výpočet ceny dluhopisy, proto jsou odpovědi obsahující tyto údaje nesprávné.","k":16},{"id":"22376.1","t":"c","q":"Uvažujme dluhopis s jmenovitou hodnotou 3 000 000 Kč, tržní cenou 105 % ročním kuponem 3 % vypláceným vždy k 25. 11. Jaký bude alikvotní úrokový výnos, pokud klient dluhopis koupí 1. 1. (pro výpočet použijte metodu počtu dnů v roce ACT/360)?","o":["9 000 Kč.","8 550 Kč.","9 450 Kč.","8 100 Kč."],"c":[0],"p":194,"e":"Kupon = 90 000 Kč,Počet dní po poslední výplatě = 36,Počet dní v roce = 360,AÚV = 90 000 / 360 x 36 = 9 000 Kč.","k":16},{"id":"20604.1","t":"c","q":"Poradce pro vyhodnocení vhodnosti navrhované investice posuzuje odborné znalosti klienta:","o":["V oblasti investic a investičních nástrojů.","V oblasti investic a oblasti pojišťovnictví.","V oblasti finanční matematiky.","V oblasti ekonomických znalostí."],"c":[0],"p":195,"e":"Pro poskytnutí služby investičního poradenství je poradce povinnen od klienta získat informace o odborných znalostech a zkušenostech v oblasti investic, jeho finančním zázemí, investičních cílech a toleranci k riziku.","k":17},{"id":"20605.1","t":"c","q":"Po vyhodnocení investičního dotazníku byla klientovi navrhnuta vyvážená investiční strategie. Jak bude poradce řešit investiční portfolio?","o":["Sestaví vyvážené investiční portfolio složené z konzervativnějších typů aktiv (například dluhopisové fondy) a rizikovějších typů aktiv (například akciové fondy).","Sestaví vyvážené investiční portfolio složené z akciových fondů emerging markets.","Sestaví vyvážené investiční portfolio složené z nástrojů peněžního trhu a státních dluhopisů zemí s ratingem ve spekulativním pásmu.","Sestaví investiční portfolio s vyváženým poměrem fondů s českým a zahraničním domicilem."],"c":[0],"p":195,"e":"Vyvážená investiční strategie zpravidla předpokládá vytvoření portfolia s celkovým rizikem nižším než dynamické složky portfolia, typicky akcie a zároveň potenciálním výnosem vyšším než nejvíce konzervativní složky portfolia, typicky státní dluhopisy či nástroje peněžního trhu.","k":17},{"id":"20606.1","t":"c","q":"Poradce informuje klienta o rizicích spojených s danou investicí tím, že mu předá a vysvětlí údaje:","o":["Obsažené ve Sdělení klíčových informací.","Obsažené v měsíční zprávě portfolio manažera.","Obsažené ve Výroční zprávě fondu.","Obsažené v účetní závěrce fondu."],"c":[0],"p":195,"e":"Pro seznámení s riziky investování do fondu je určeno Sdělení klíčových informací, které obsahuje základní infomrace pro klienta, především informace o rizikovosti fondu, historickém výnosu, poplatcích a zaměření fondu a jeho investičních cílech.","k":17},{"id":"20607.1","t":"c","q":"Klient si ve Sdělení klíčových přečetl, že maximální vstupní poplatek do fondu je 5 %. Co toto číslo vyjadřuje a jak jej klientovi vysvětlí?","o":["Číslo vyjadřuje poplatek, který klient zaplatí při investici do fondu.","Číslo vyjadřuje maximální možný vstupní poplatek při investici do fondu. Jeho skutečná výše se však bude řídit ceníkem zvoleného distributora fondu a může být shodná nebo nižší.","Číslo vyjadřuje poplatek, který klient zaplatí při první investici do fondu, další investice již jsou bez poplatku.","Číslo vyjadřuje doporučený maximální vstupní poplatek při investici do fondu. Skutečná výše poplatku však bude záviset na volbě distributora, který stanoví poplatek nezávisle dle svého ceníku. Může tak být shodný, nižší, nebo vyšší."],"c":[1],"p":195,"e":"Nařízení komise definuje prezentaci poplatků jako nejvyšší možné procento, které může být investorovi strženo. Skutečná výše poplatku je pak určena ceníkem distributora. Nemůže však být vyšší.","k":17},{"id":"20608.1","t":"c","q":"Jeden ze zvolených dluhopisových fondů má v názvu spojení \"high yield\". Co tato slova znamenají?","o":["Odkazují na dluhopisy s kreditním ratingem spekulativního stupně.","Odkazují na dluhopisy, jejichž výnos je vyšší než 7 %.","Odkazují na dluhopisy s ideálním poměrem kreditního rizika a výnosu do splatnosti.","Odkazují na dluhopisy společností působících na rozvíjejících se trzích."],"c":[0],"p":196,"e":"High Yield je slovní spojení označující dluhopisy ze spekulativní části kreditního ratingu.","k":17},{"id":"20610.2","t":"c","q":"Poradce zkoumá finanční zázemí klienta. Získané údaje použije pro:","o":["Vyhodnocení dopadu případné ztráty na celkovou finanční situaci klienta.","Vyhodnocení, zda je pro něj výhodné klienta obsloužit.","Vyhodnocení, zda je pro klienta vhodnější investice spíše s kratším, nebo spíše s delším investičním horizontem.","Vyhodnocení, zda je klient spíše tolerantní k riziku, nebo má spíše averzi k riziku."],"c":[0],"p":197,"e":"Cílem je zjistit, zda doporučený nástroj odpovídá finančnímu zázemí klienta, včetně jeho schopnosti nést ztrátu.","k":18},{"id":"20611.1","t":"c","q":"Klient má dle investičního dotazníku velmi vysoké znalosti a zkušenosti v oblasti investic. Je také ochoten tolerovat vysokou míru rizika. Jakou poradce navrhne vhodnou investiční strategii?","o":["S ohledem na velmi krátký investiční horizont, spojený s investičním cílem, mu poradce doporučí konzervativní investiční strategii.","S ohledem na klientovy znalosti a zkušenosti, na jeho finanční zázemí a jeho postoj k riziku je jediná správná investiční strategie dynamická.","Investiční poradce není oprávněn navrhovat investiční strategii, tu si volí klient sám. Poradce následně vybere nástroje vhodné pro vybranou strategii.","Klientův postoj k riziku odkazuje na dynamickou strategii, jeho krátký investiční horizont spojený s investičním cílem zase na konzervativní strategii. Poradce tedy může vybrat jakoukoliv z těchto dvou strategií."],"c":[0],"p":197,"e":"Nehledě na klientův postoj k riziku a jeho znalosti a zkušenosti je nezbytné respektovat velmi krátký investiční horizont, který vylučuje doporučit dynamickou strategii.","k":18},{"id":"20612.2","t":"c","q":"Poradce navrhuje investiční portfolio s cílem omezit inflační riziko. O co se snaží?","o":["Zvolit takové investiční nástroje, jejichž potenciální výnos bude vyšší než očekávané tempo růstu cenové hladiny v ekonomice (inflace).","Zvolit takové investiční nástroje, které nemohou nést záporný výnos.","Zvolit takové investiční nástroje, které budou denominovány v české koruně nebo budou zajištěny proti vlivu vývoje kurzu měny investičního nástroje.","Zvolit takové investiční nástroje, které budou přinášet výnos i v případě nižší než očekávané inflace."],"c":[0],"p":197,"e":"Inflační riziko je riziko nízkého nebo záporného reálného výnosu investice. Je ovlivněno tempem růstu inflace v ekonomice.","k":18},{"id":"20613.2","t":"c","q":"Klient je spokojen s výběrem investičních nástrojů a přeje si zprostředkovat jejich nákup. V rámci urychlení nákupu chce poradci předat peníze v hotovosti, aby na účet klienta dané investiční nástroje nakoupil. Poradce:","o":["Vysvětlí klientovi, že z titulu zákona o podnikání na kapitálovém trhu není oprávněn přijímat peněžní prostředky od zákazníků a sdělí mu správný postup nákupu investičního nástroje.","Peníze přijme a bez zbytečného prodlení pro klienta zajistí nákup investičních nástrojů.","Peníze nepřijme, vysvětlí klientovi, že hotovost nesmí přijímat a požádá jej, aby peníze zaslal ze svého bankovního účtu na jeho (poradcův) bankovní účet.","Nejprve nechá klienta vyplnit příslušný AML dotazník (ke zjištění zdroje a původu peněžních prostředků), poté peníze přijme a bez zbytečného prodlení pro klienta zajistí nákup investičních nástrojů."],"c":[0],"p":197,"e":"Investiční zprostředkovatel, resp. vázaný zástupce investičního zprostředkovatele, nesmí v souvislosti s poskytováním investičních služeb přijímat peněžní prostředky nebo investiční nástroje zákazníků.","k":18},{"id":"20614.2","t":"c","q":"Jaký typ fondu je zpravidla z pohledu průměrné doby do splatnosti svého portfolia tím nejméně rizikovým?","o":["Krátkodobý fond peněžního trhu.","Dluhopisový fond investující do státních dluhopisů vyspělých zemí.","Fond peněžního trhu.","Dluhopisový fond investující do korporátních dluhopisů s ratingem investičního stupně."],"c":[0],"p":198,"e":"Krátkodobý fond do svého jmění může nabývat pouze nástroje peněnžího trhu se zbytkovou dobou splatnosti kratší než 397 dní, ostatní fondy takové omezení nemají.","k":18},{"id":"21243.1","t":"c","q":"V tomto případě by měl investiční poradce s klienty nejprve provést test vhodnosti a následně si vyjasnit:","o":["Přibližně jakou částku a v jakém časovém horizontu mají zájem investovat, jaké jsou jejich investiční cíle a finanční situace.","Zda chtějí investovat na páku.","Jestli mají v bance otevřen účet určený pro obchodování s cennými papíry.","Jestli mají zaveden majetkový účet v centrálním depozitáři."],"c":[0],"p":199,"e":"Součást komunikace se zákazníky - jde o základní rozhodnutí klientů, které má zásadní vliv na další kroky i činnost poradce.","k":19},{"id":"21244.2","t":"c","q":"V tomto případě by měl investiční poradce klientům vysvětlit, že:","o":["U akcií je možné dosáhnout výnosu v průběhu investice v podobě výplaty dividendy, proto by pro klienty byly vhodné akcie významných světových společností (large cap) s dlouhodobou dividendovou historií.","U akcií je možné dosáhnout výnosu v průběhu investice v podobě výplaty dividendy, proto by pro klienty byly vhodné akcie malých, začínajících společností (small cap) s krátkou historií, ale potenciálně vysokou budoucí dividendou.","U akcií pravidelný výnos nebývá běžný, takže v jejich případě je lepší zvážit investici do dluhopisů, a to i za cenu vyšších vstupních nákladů.","U akcií pravidelný výnos nebývá běžný, takže je výhodné najít si jednu emisi s vysokou dividendou a do té vložit svou investici."],"c":[0],"p":199,"e":"Součást komunikace se zákazníky - výnos z akcií v podobě dividendy není automaticky vyplácen u všech akcií, záleží na rozhodnutí valné hromady.","k":19},{"id":"21245.1","t":"c","q":"Investiční poradce se s klienty následně domluví na konečném výběru emisí akcií, přičemž je důležité zohlednit, zda:","o":["Se klienti chtějí orientovat spíše na tuzemské nebo zahraniční trhy.","Se klienti chtějí stát členy burzy.","Si klienti plánují pořídit obchodní SW.","Klienti chtějí mít možnost zasahovat do vypořádání svých obchodů."],"c":[0],"p":199,"e":"Součást komunikace se zákazníky - obzvlášť důležité rozhodnutí pro klienty bez znalosti trhu. Ostatní odpovědi jsou irelevantní.","k":19},{"id":"21246.1","t":"c","q":"Klienti by si rádi průběžně sledovali i situaci emitenta. Investiční poradce by měl klienty v tomto případě upozornit, že obecně nejvíce informací o situaci emitenta má veřejnost k dispozici v případě emisí akcií:","o":["Přijatých na regulovaný trh.","Přijatých na trh.","Zaknihovaných.","Veřejně obchodovatelných."],"c":[0],"p":199,"e":"Emitenti akcií přijatých na regulovaný trh mají informační povinnosti vyplývající ze zákona i z pravidel regulovaných trhů.","k":19},{"id":"21247.1","t":"c","q":"Investiční poradce následně uzavře s klienty smlouvu na nákup/zprostředkování nákupu akcií. Klientům by měl doporučit:","o":["Průběžně si sledovat vývoj cen daných akcií na trhu, aby měli základní informace o svých investicích.","Akcie prodat v případě jejich vyřazení z báze akciového indexu.","Kontaktovat emitenty akcií s dotazem, kdy a jak bude vyplácena dividenda.","Uzavřít smlouvu o pojištění vkladu."],"c":[0],"p":200,"e":"Součást komunikace se zákazníky - patří k základní informovanosti klientů. Ostatní odpovědi jsou irelevantní.","k":19},{"id":"20622.1","t":"c","q":"Investiční poradce takovému klientovi doporučí investovat do:","o":["Střednědobých dluhopisů.","Krátkodobých dluhopisů.","Dlouhodobých dluhopisů.","Státních pokladničních poukázek."],"c":[0],"p":201,"e":"Dluhopisy se splatností do 10 let jsou označovány jako střednědobé.","k":20},{"id":"20623.1","t":"c","q":"Klient nakonec uvažuje o státních dluhopisech o nominálu 10 000 Kč, s úrokem 1,5 %, výplata 2× ročně a to za cenu 110 %. Požádal investičního poradce o spočítání výnosů. Klientův výnos bude:","o":["2× ročně 75 Kč.","2× ročně 150 Kč.","2× ročně 90 Kč.","2× ročně 110 Kč."],"c":[0],"p":201,"e":"(10.000 × 0,015) = 150 na rok, na pololetí tedy 150/2 = 75 Kč","k":20},{"id":"20624.1","t":"c","q":"Klient se rozhodne a kupuje 5 ks dluhopisů dle zadání předchozí otázky. Celková nákupní cena bude:","o":["55 000 Kč + AÚV.","50 000 Kč + AÚV.","50 500 Kč + AÚV.","Z těchto údajů nelze určit."],"c":[0],"p":201,"e":"5 × (10.000 × 1,1) = 55.000 Kč","k":20},{"id":"20625.1","t":"c","q":"Klient zvažuje možnost prodeje dluhopisů tak, aby dostal výplatu výnosu za první rok. Žádá tedy investičního poradce o vysvětlení pojmu \"ex-kupon\".","o":["Pojmem \"ex-kupon\" se označuje první den, kdy majitel dluhopisu nemá nárok na výplatu výnosu.","Pojmem \"ex-kupon\" se označuje první den, kdy majitel dluhopisu získává nárok na výplatu výnosu.","Pojmem \"ex-kupon\" se rozumí proces odtržení kuponu od jistiny v den výplaty výnosu.","Pojem \"ex-kupon\" vyjadřuje kupon, který je obchodovatelný samostatně, tj. odtrženě od jistiny."],"c":[0],"p":201,"e":"Ex-kupón je označení prvního dne následujícího po dni rozhodném pro výplatu výnosu.","k":20},{"id":"20626.1","t":"c","q":"Investiční poradce by měl klientovi vysvětlit, že pokud chce výplatu výnosu, tak musí v tzv. rozhodný den:","o":["Být majitelem těchto dluhopisů.","Tyto dluhopisy nejpozději koupit.","Mít emitent přístup na jeho účet, aby výnos mohl být vyplacen.","Přinést kupony do centrálního depozitáře, kde slouží jako podklad k výplatě výnosu."],"c":[0],"p":202,"e":"Práva spojená s dluhopisem může vykonávat jeho majitel.","k":20},{"id":"20628.3","t":"c","q":"Investiční poradce klientovi vysvětlí, že AÚV znamená:","o":["Alikvotní úrokový výnos.","Aritmetický úrokový výpočet.","Alikvotní úročení pro vypořádání.","Absolutní úrokový výnos."],"c":[0],"p":203,"e":"Alikvotní úrokový výnos (AÚV) představuje část kuponové platby, která od okamžiku výplaty předchozího kuponu postupně \"naběhla\" a náleží prodávajícímu. Jedná se o poměrnou část kuponu, který si zaslouží předchozí majitel dluhopisu, který jej držel od okamžiku předchozí výplaty kuponu, ale dluhopis odprodal před nadcházejícím termínem výplaty kuponu. AÚV se přičítá ke kupní ceně dluhopisu, mění se stejně jako cena dluhopisu např,. každý den.","k":21},{"id":"20629.3","t":"c","q":"Dále by měl klienta informovat o základních principech průběhu AÚV. Zejména pak, že výše AÚV v období mezi dvěma výplatami kupónů:","o":["Lineárně narůstá.","Lineárně klesá.","Se nemění.","Se přesně stanovuje poměrně komplikovaně."],"c":[0],"p":203,"e":"Alikvotní úrokový výnos je v okamžiku výplaty kuponové platby nulový a následující dny, až do okamžiku výplaty další kuponové platby lineárně narůstá až do výplaty dalšího kuponu, kdy klesne na nulu (výplata kuponu) a potom opět narůstá. Pokud dojde k odprodeji dluhopisu před výplatou následujícího kuponu, náleží prodávajícímu část takto postupně narůstajícího AÚV, jako odměna, za to, že ještě po určitou dobu vlastnil dluhopis, přestože následující kupon bude celý vyplacen kupujícímu. Ten tak k tržní ceně dluhopisu musí uhradit prodávajícímu právě i AÚV.","k":21},{"id":"20630.4","t":"c","q":"Dále by měl klienta informovat o základních principech průběhu AÚV. Zejména pak, že v den ex-kuponu je výše AÚV:","o":["Minimální, může být i záporná.","Minimální, ale vždy kladná.","Nulová.","Maximální."],"c":[0],"p":203,"e":"Pokud dochází k odprodeji dluhopisu těsně před datem výplaty kuponu, resp. v den, kdy se již dluhopis obchoduje bez nároku na kupon (díky vypořádání např. T+2) již kupon nezíská kupující, může a bývá AÚV mírně záporný. Znamená to tedy, že přestože kupující koupil dluhopis ještě před výplatou kuponové platby, nestihne se díky vypořádání stát \"fyzickým majitelem\" dluhopisu a celý kupon ještě získá prodávající. Záporné AÚV potom pro kupujícího představuje \"slevu\" z kupní ceny.","k":21},{"id":"20631.3","t":"c","q":"Dále by měl klienta informovat o základních principech průběhu AÚV. Zejména pak, že v den výplaty kuponu je AÚV:","o":["Nulové.","Minimální (záporné).","Maximální.","Nelze stanovit."],"c":[0],"p":203,"e":"Internetový magazín Finanční matematika finmat.cz [online] ? Jitka Vachtová [cit. 2.5.2018]. Dostupné z: http://www.finmat.cz/urokova-doba/","k":21},{"id":"20632.3","t":"c","q":"A na závěr na konkrétním příkladu dluhopisu klientovi ukázat základní výpočet v praxi. Nominální hodnota dluhopisu je 10.000 Kč, kuponová sazba 1 % p. a., kupon vyplácený v roční frekvenci vždy k 1. červnu výše AÚV k 1. lednu tedy je přibližně:","o":["58,60 Kč.","99,50 Kč.","41,40 Kč.","50,00 Kč."],"c":[0],"p":204,"e":"1 % = 100 Kč, 7/12 ze 100 = 58,6 Kččíslo není absolutně přesné, protože záleží na metodě výpočtu (např. 30/E/360, ACT/360., apod.), což ale není pro tyto účely podstatné","k":21},{"id":"21237.4","t":"c","q":"Investiční poradce by měl klienta upozornit, že s ohledem na velmi dlouhou dobu od posledního pohybu na majetkové účtu je možné, že:","o":["Některé z akcií již budou téměř neprodejné a z některých akcií může mít klient ještě nárok na výplatu dividendy.","Jeho majetkový účet nepůjde dohledat.","Jeho majetkový účet už možná neexistuje.","Některé dluhopisy už mají po splatnosti. Z těchto dluhopisů už klientům nemůže plynout žádný příjem."],"c":[0],"p":205,"e":"Varianta 2 - 4 nejsou pravda. Dividenda může být vyplacena i se zpožděním, výnos z dluhopisů také.","k":22},{"id":"21238.4","t":"c","q":"Pokud se týká akcií, které jsou obchodovatelné, ale už ne na veřejném trhu, měl by poradce klientovi doporučit:","o":["Obrátit se na emitenta nebo většinového majitele akcií a zkusit se s ním domluvit na odkoupení akcií klienta (osobně nebo např. prostřednictvím obchodníka s cennými papíry).","Zkusit se domluvit s centrálním depozitářem, který vede evidenci akcií, zda by akcie neodkoupil (osobně nebo např. prostřednictvím obchodníka s cennými papíry).","Obrátit se na soud s požadavkem doplacení ušlých výnosů od emitenta daných akcií.","Nechat věc být, protože se s tím už bohužel nedá nic dělat - jde o chybu investora."],"c":[0],"p":205,"e":"V případě, že se emitent rozhodne vylistovat své akcie z veřejného trhu, má investor možnost tyto prodat pouze na neveřejném trhu. Problém ale bude ve stanovení ceny za kolik tyto na neveřejném trhu prodat, protože se neobchodují veřejně, není nabídka ani poptávka a tím pádem není cena. Proto se může dohodnout i s emitentem, který je může (nikoliv) musí od něj odkoupit.","k":22},{"id":"21239.4","t":"c","q":"Pokud se týká dluhopisů, které již mají po splatnosti, měl by poradce klientovi doporučit:","o":["Obrátit se na emitenta se žádostí o informaci, zda již uplynula lhůta pro vyplacení výnosů nebo zda je na výnosy ještě nárok (nebo se snažit tuto skutečnost zjistit z jiných relevantních informačních zdrojů).","Požádat centrální depozitář, který vede evidenci dluhopisů, o výplatu výnosů.","Obrátit se na soud s požadavkem doplacení ušlých výnosů od emitenta daných dluhopisů.","Nechat věc být, protože se s tím už bohužel nedá nic dělat - jde o chybu investora."],"c":[0],"p":205,"e":"Pokud má klient ve svém držení dluhopisy, které jsou již po splatnosti může se obrátit na emitenta, zda jsou dluhopisy skutečně již po splatnosti, resp. zda už skutečně uplynula lhůta pro výplatu jejich nominální hodnoty. Tyto informace jsou uvedeny i v podmínkách, kde je jasně stanoveno, jaké jsou termíny výplaty např. kuponů, ale i právě termín splatnoti dluhopisů (s případnou lhůtou pro vyplácení).","k":22},{"id":"21240.4","t":"c","q":"V případě veřejně obchodovatelných akcií a dluhopisů se poradce s klientem domluví na zadání pokynů k prodeji. Pokyny by ale měly být na trh zasílány po zohlednění okolností:","o":["a) Reálně dosažitelná cena, b) Vložení pokynu na trh, kde je odpovídající pravděpodobnost uspokojení (v časovém horizontu dle potřeb klienta), c) Poplatky za zobchodování (obchodník, trh, vypořádání).","a) Maximální cena, b) Vložení pokynu na trh, který má nejkratší termín vypořádání, c) Poplatky za zobchodování (obchodník, trh, vypořádání).","a) Vložení pokynu na trh, kde je odpovídající pravděpodobnost uspokojení (v časovém horizontu dle potřeb klienta), b) Nejnižší poplatky za vypořádání, c) Využít pouze garantované obchody.","a) Poplatky za zobchodování (obchodník, trh, vypořádání), b) Reálně dosažitelná cena na OTC trhu, c) Využít pouze garantované obchody."],"c":[0],"p":205,"e":"Pokynem zákazníka k nákupu či prodeji akcií je obchodník vždy povinen provést tzv. \"za nejlepších podmínek\": nejlepší možná dosažitelná cena, časové hledisko (bez neodůvodněného zpoždění), pravděpodobnost úspěšnosti, celkové poplatky, dodržení platné legislativy.","k":22},{"id":"21241.4","t":"c","q":"V případě indexových certifikátů by měl poradce klientovi vysvětlit, že:","o":["Nejspíše má právo na jejich zpětný odkup emitentem (tato možnost bývá uvedena v emisních podmínkách).","Má právo na výplatu úroků (tyto certifikáty bývají časově neomezené).","Mu náleží vyplacení tzv. zbytkové hodnoty.","Podle platné legislativy se již tento typ certifikátů (obdobně jako listinné akcie na doručitele) nesmí obchodovat."],"c":[0],"p":206,"e":"Obdobně jako u dluhopisů i v případě certifikátů, zálěží na emisních podmínkách, resp. na tom, kdy byla splatnost certifikátu a jaká byla lhůta pro vyplacení jejich nominální hodnoty ze strany emitenta.","k":22},{"id":"20652.1","t":"c","q":"Přestože jsou oba konzervativní, rozhodli se investovat volné peněžní prostředky tak, aby je s minimálním rizikem co nejvíce zhodnotili a využili k dofinancování vlastního bydlení, které plánují za 3-4 roky. Jejich požadavkům pravděpodobně bude nejvíce odpovídat:","o":["Dluhopisový fond Global Market Bond.","Akciový fond BRIC Top Equity.","Komoditní fond Oil and Gas.","Hedgový Private Equity fond."],"c":[0],"p":207,"e":"Vzhledem k jejich profilu, kdy o sobě tvrdí, že jsou konzervativní, postrádá smysl investovat do komodit či rizikovějších hedgových fondů. V případě akciové investice se jedná o úzce diverzifikovaný fond investující do vybraných ekonomik. Dluhopisový fond investuje do široce diverzifikovaného portfolia globálních (pravděpodobně) statátních dluhopisů.","k":23},{"id":"20653.1","t":"c","q":"Při první návštěvě jim investiční zprostředkovatel předložil investiční dotazník:","o":["Investiční dotazník je dokument, který zákon vyžaduje a slouží k ochraně klienta před investičními nabídkami, které neodpovídají znalostem a majetkovým poměrům potenciálního investora - klienta.","Investiční dotazník individuální investor nikdy nevyplňuje, protože by se mohl zaměstnanec zprostředkovatele dozvědět řadu informací o majetkových poměrech klienta.","Zaměstnanec zprostředkovatele opravdu neví, jaké znění má investiční dotazník mít, tak nemůže žádný dokument klientovi předložit.","Klienti se poradí se svým investičním poradcem, jak nejlépe investiční dotazník vyplnit, aby mohl investovat i do více rizikových nástrojů."],"c":[0],"p":207,"e":"Investiční dotazník musí vyplnit každý investor, kdo chce své prostředky zhodnotit v některém z investičních produktů. Klientům může poskytnout ochranu před investicemi do produktů, kterým nerozumí a mohly by je poškodit. Klient by měl dotazník vyplnit pravdivě tak, aby bylo možné mu nabídnout vhodný produkt. Pokud některým otázkám nerozumí, může se zeptat poradce, který mu může otázku vysvětlit, příp. uvést příklad, rozhodně ale nesmí klienta navádět, příp. mu doporučovat či radit co a jak má klient vyplnit.","k":23},{"id":"20654.1","t":"c","q":"Mladý pár se po určité době vrátil zpět za investičním zprostředkovatelem s tím, že si zvolili fond, který je široce diverzifikovaný a navíc investuje v amerických dolarech, což je silná a stabilní světová měna. Poradce by je měl upozornit, že:","o":["V případě posilování domácí měny (CZK) bude docházet ke snižování jejich korunového výnosu, pakliže není fond měnově zajištěn.","V případě oslabování domácí měny (CZK) bude docházet ke snižování jejich korunového výnosu, pakliže není fond měnově zajištěn.","Zvolili dobře, protože měnové riziko, kterému se vystavují, působí na celkový výnos investice pozitivně, navíc, při jimi zvoleném 3 - 4letém horizontu.","Že se do budoucna předpokládá oslabování dolaru, především kvůli postojům a činům D. Trumpa, což bude mít negativní vliv na jejich investici a raději by se měli orientovat na fond, který investuje v EUR, které je mnohem stabilnější a nevystavují se tak žádnému riziku."],"c":[0],"p":207,"e":"Posilování domácí měny působí v případě cizoměnové investice vždy na korunový výnos negativně, protože za jednotku cizí měny klient obdrží méně jednotek měny domácí.","k":23},{"id":"20655.1","t":"c","q":"Při rozhovoru s pracovníkem (zaměstnancem investičního zprostředkovatele) ohledně volby správného fondu jim tento spíše než investici do podílových fondů doporučil přímou investici do akcií Wendy''s, plc., které se aktuálně obchodují za 120 USD/kus a cílová cena analytiků je 165 USD.","o":["Investiční zprostředkovatel není oprávněn ke konkrétnímu doporučení akcie, je oprávněn poskytovat pouze omezený okruh služeb vztahující se k cenným papírům kolektivního investování a dluhopisům.","Investice není výhodná, akcie je trhem nadhodnocena.","Investice se jeví jako výhodná, akcie se dlouhodobě jeví jako podhodnocená.","Měli by jej poslechnout, v dnešní době nízkých úrokových sazeb, nemá smysl do ničeho jiného investovat a to i na krátkém horizontu."],"c":[0],"p":208,"e":"Investiční zprostředkovatel ze zákona nesmí poskytovat služby vztahující se k akciím, má pouze omezený okruh služeb. Pokud by toto činil ať už úmyslně či neúmyslně, rozhodně není při investici v cizí měně výhodné posilování měny domácí, které snižuje investorům výnos v domácí měně. Pokud je tržní cena akcie 120 USD a analytici ji cílují na 165, jedná spíše než o nadhodnocení trhem o její podhodnocení. Přestože se investice může jevit jako výhodná z důvodů nízkých úrokových sazeb na trhu, není tomu tak, především s ohledem na investiční profil klienta a délku investičního horizontu. Jednalo by se o investici do jednoho konkrétního titulu, navíc v zahraniční měně, čímž výrazně roste rizikovost (měnové riziko a nulová diverzifikace).","k":23},{"id":"20656.1","t":"c","q":"Po vyplnění investičního dotazníku vyšlo, že mladý pár je skutečně konzervativní:","o":["Mají možnost zvolit i více rizikovou alternativu, ale poradce je povinen upozornit je na to, že zvolená investice neodpovídá jejich profilu dle dotazníku a upozornit je na rizika.","Musejí zvolit pouze ze zúžené nabídky investic, které jim nabízí poradce, nesmí volit nic, co by neodpovídalo jejich profilu dle dotazníku.","Protože nemají žádné zkušenosti s investováním, musejí využít pouze spořicího účtu, příp. vkladu s výpovědní lhůtou.","Nemohou a nesmějí využít služeb jiného zprostředkovatele, protože investiční dotazník byl již vyplněn a platí exkluzivně pouze pro daného zprostředkovatele."],"c":[0],"p":208,"e":"Uplatnění výsledků dotazníku při výběru a rozvržení investic přispívá k odstranění nejčastějších příčin chybování v investičním chování, které následně mohou vést ke ztrátám. Výsledky dotazníku nejsou ale pro klienta závazné.","k":23},{"id":"20670.5","t":"c","q":"Poradce doporučí klientovi, aby pohotová finanční rezerva, zůstatek na běžném či spořicím účtu, kterým může klient krýt výpadek příjmů, byla alespoň:","o":["Přibližně 6× průměrného příjmu.","Přibližně 12× průměrného příjmu.","Přibližně 18× násobek průměrného příjmu.","Přibližně 24× násobek průměrného příjmu."],"c":[0],"p":209,"e":"Šestinásobek průměrného příjmu je dostatečný pro krytí nečekaných výdajů (někdy se v praxi doporučuje i trojnásobek, ale z důvodu opatrnosti je výhodnější vyšší částka), jako pohotová finanční rezerva. V případě skončení pracovního poměru se předpokládá, že klient do půl roku nalezne nové zaměstnání, navíc by měl nárok na podporu v nezaměstnanosti po dobu 5 měsíců.","k":24},{"id":"20671.5","t":"c","q":"Poradce klientovi potvrdí, že je skutečně nezávislým, tedy že investiční službu inv. poradenství poskytuje nezávisle. Znamená to, že:","o":["Je povinen posoudit dostatečné množství investičních nástrojů dostupných na trhu, které jsou dostatečně různorodé z hlediska jejich druhu a emitentů.","Je odměňován provizně investičním zprostředkovatelem.","Smí poskytnout pouze hlavní inv. službu investiční poradenství, doporučený investiční nástroj však nesmí zprostředkovat (poskytnout hlavní inv. službu přijímání a předávání pokynů týkajících se inv. nástrojů).","Lže, jelikož vázaný zástupce nemůže poskytovat investiční služby nezávisle."],"c":[0],"p":209,"e":"Informuje-li osoba jednající se zákazníky zákazníka o tom, že hlavní investiční službu uvedenou v § 4 odst. 2 písm. e) poskytuje nezávisle, je povinna posoudit dostatečné množství investičních nástrojů dostupných na trhu, které jsou dostatečně různorodé z hlediska jejich druhu a emitentů nebo osob, které vytvářejí investiční nástroje tak, aby mohly být odpovídajícím způsobem naplněny investiční cíle zákazníka.","k":24},{"id":"20672.5","t":"c","q":"Pro dlouhodobější ochranu kapitálu (přibližný horizont 30 let) doporučí poradce klientovi zvážit rozložení investice především mezi dluhopisový a akciový podílový fond:","o":["Diverzifikace může být provedena v poměru 50 : 50, příp. i vyšším ve prospěch akciového fondu s postupnou realokací kapitálu do fondu dluhopisového s blížícím se odprodejem podílových listů.","Diverzifikace může být provedena v poměru 50 : 50, příp. i vyšším ve prospěch dluhopisového fondu, s postupnou realokací kapitálu do fondu akciového s blížícím se odprodejem podílových listů.","Klient by měl preferovat především lokální small cap fondy, které mohou přinášet vyšší zhodnocení.","Klient by měl preferovat dluhopisové fondy, tzv. high yield fondy, které mohou přinášet vyšší zhodnocení."],"c":[0],"p":209,"e":"Vzhledem k dlouhému časovému horizontu si může dovolit klient investovat i do více rizikových investičních nástrojů (akcií) s tím, že s blížícím se koncem investičního horizontu bude docházet k postupné realokaci k méně rizkových nástrojům (dluhopisům).","k":24},{"id":"20673.5","t":"c","q":"V případě dluhopisového fondu by měl poradce upozornit klienta:","o":["Na úrokové riziko, kdy s růstem úrokových sazeb dochází ke snižování ceny dluhopisů a snižování hodnoty majetku fondu, potažmo ceny podílového listu.","Na úrokové riziko, kdy s růstem úrokových sazeb dochází k růstu ceny dluhopisů a růstu hodnoty majetku fondu, potažmo ceny podílového listu.","Na inflační riziko, kdy s růstem inflace dochází k růstu ceny dluhopisů a poklesu hodnoty majetku fondu, potažmo ceny podílového listu.","Na inflační riziko, kdy s poklesem inflace dochází k poklesu ceny dluhopisů a růstu hodnoty majetku fondu, potažmo ceny podílového listu."],"c":[0],"p":210,"e":"V okamžiku očekávání růstu úrokových sazeb, budou ceny dluhopisů klesat, na což je povinen poradce klienta upozornit (stejně jako na jakákoliv jiná rizika). Na růst úrokových sazeb budou citlivěji reagovat ceny dlouhodobých fixně úročených dluhopisů.","k":24},{"id":"20674.5","t":"c","q":"Pan Průměrný, který půjde do starobního důchodu v 62 letech, by rád jako přilepšení k němu pobíral 10.000 Kč měsíčně. Poradce jej upozorní na vliv 2% inflace.","o":["Reálná kupní síla 10 000 Kč bude na začátku vstupu do důchodu přibližně pouze 5 850 Kč a po dobu čerpání bude stále klesat.","Reálná kupní síla 10 000 Kč bude na začátku vstupu do důchodu přibližně pouze 9 800 Kč a po dobu čerpání bude stále klesat.","Reálná kupní síla 10 000 Kč bude na začátku vstupu do důchodu přibližně pouze 7 800 Kč a po dobu čerpání bude stále klesat.","Reálná kupní síla 10 000 Kč bude na začátku vstupu do důchodu přibližně pouze 6 500 Kč a po dobu čerpání bude stále klesat."],"c":[0],"p":210,"e":"Reálná kupní síla se vlivem inflace snižuje. Tzn. nominálních 10 000 Kč bude mít za 27 let nižší reálnou hodnotu, konkrétně 10000/(1+0,02)^27 = 5858 Kč","k":24},{"id":"20676.1","t":"c","q":"Poradce je povinen získat od klienta vždy informace o jeho znalostech a zkušenostech s investičními nástroji (test přiměřenosti), ale bude se zajímat i o finanční situaci a zázemí klienta a jeho investiční cíle (test vhodnosti).","o":["Zpravidla požádá klienta o vyplnění investičního dotazníku. Na základě výsledků investičního dotazníku upozorní klienta s předstihem na případná rizika.","Tyto informace získá poradce pomocí ústního rozhovoru s klientem a podle něj doporučí vhodnou investiční strategii a složení portfolia.","Poradce tyto informace nebude požadovat, protože je obeznámen s tím, že klient již má dva produkty (KŽP a transformovaný fond) a dohledá si je od předchozích zprostředkovatelů.","Poradce tyto informace nebude požadovat, protože je obeznámen s tím, že klient již má dva produkty (KŽP a transformovaný fond), pouze se jej zeptá, jaký byl jeho výsledek investičního dotazníku od předchozích zprostředkovatelů."],"c":[0],"p":211,"e":"Poradce je povinen získat od klienta vždy infomrace o jeho znalostech a zkušenostech s investičními nástroji (test přiměřenosti), ale bude se zajímat i o finanční situaci a zázemí klienta a jeho investiční cíle (test vhodnosti). §15 ZPKT","k":25},{"id":"20677.1","t":"c","q":"Poradce vznesl dotaz, zda si je pan Nedočkavý vědom rizik či výhod spojených s jednorázovou investicí:","o":["Rizikem je především špatné načasovaní jednorázové investice, které lze eliminovat pravidelnou investicí.","Výhodou jednorázové investice je úspora nákladů, kdy pravidelná investice je vždy nákladnější.","Při jednorázové investici dochází k průměrování nákladů, kdy v okamžiku vysoké ceny je nakoupeno méně investičních nástrojů, při nízké ceně naopak více.","Rizikem pravidelné investice je vyšší pravděpodobnost špatného načasování investice."],"c":[0],"p":211,"e":"Při jednorázové investici hrozí riziko špatného načasování, tzn. že se investice realizuje za vysokých tržních cen, kdy posléze ceny klesnou. Výhodnější je investovat nižší částku pravidelně, čímž dochází k průměrování ceny (v dobách vysokých cen se nakupuje méně instrumentů, v dobách poklesu naopak instrumentů více). Základními metodami pravidlené investice je dolar cost averaging a value averaging.","k":25},{"id":"20678.1","t":"c","q":"Pan Nedočkavý je nespokojený s výnosem svého transformovaného fondu, kam si spoří již 12 let.","o":["Pan Nedočkavý může přestoupit do účastnického fondu, kde si může zvolit investiční strategii a potenciálně dosáhnout vyšších výnosů, nicméně může dosáhnout i ztráty, což u transformovaného fondu nelze.","Poradce navrhl výběr poloviny naspořených prostředků a dofinancování k 250 000 Kč a provedení jednorázové investice.","Poradce navrhuje nic neměnit, protože i přes nízký výnos transformovaného fondu má pan Nedočkavý možnost získat vyšší státní podporu, než kdyby přestoupil do účastnického fondu, kde ale může dosáhnou potenciálně vyšších výnosů.","Pan Nedočkavý může bez sankcí vybrat až 50 % naspořených prostředků, protože uplynula 6letá vázací lhůta. Prostředky může využít k založení doplňkového penzijního spoření, aby mohl čerpat výhod předdůchodu."],"c":[0],"p":211,"e":"Transformované fondy se od roku 2013 transformovaly z původních penzijních připojištění se státním příspěvkem, s tím, že nadále u nich platí nemožnost dosažení ztráty, možnost čerpání výsluhové penze, ale nemožnost ovlivnění investiční strategie. Na rozdíl od účastnických, které je možné uzavírat od roku 2013, příp. do nich přestoupit z tranformovaných fondů, kdy má klient možnost zvolit si investiční strategii, čímž ale již nese riziko případných ztrát. Klient účastnického fondu nemá možnost čerpat výsluhovou penzi, na druhou stranu pokud splní podmínky, má možnost čerpat tzv. předdůchod.","k":25},{"id":"20679.1","t":"c","q":"Pan Nedočkavý nechce investovat v rámci České republiky, ale nechce být současně vystaven kurzovému riziku.","o":["Takové investici bude nejlépe vyhovovat fond, který je denominován v českých korunách, který investuje v zahraniční měně a je měnově zahedgován.","Takové investici bude nejlépe vyhovovat fond, který je denominován v českých korunách, který investuje v zahraniční měně a není měnově zahedgován.","V případě, že si pan Nedočkavý zvolí např. akciový fond, není nutné měnové riziko řešit, protože výnos fondu je ovlivněn především vývojem ceny podkladových aktiv, nikoliv měnového kurzu. V případě dluhopisové investice by již měnové riziko hrozilo, protože výnos dluhopisového fondu je ovlivněn především vývojem měnového kurzu, nikoliv podkladového aktiva.","Taková investice není možná, při zahraniční investici, bude pan Nedočkavý vždy vystaven kurzovému riziku."],"c":[0],"p":212,"e":"Denominace fondu není až tak rozhodující, důležité je v jaké měně fond investuje a zda je fond měnově zajištěn tak, aby kurzové riziko nenesl klient a nemusel se zajišťovat individuálně, např. měnovým forwardem, případně zajištěním se na úvěrovém trhu.","k":25},{"id":"20680.1","t":"c","q":"V měsíční zprávě jednoho fondu, který poradce prezentoval klientovi, byl uveden ukazatel efektivní durace ve výši 5,39.","o":["V portfoliu dluhopisového fondu pravděpodobně převažují střednědobé (5leté) dluhopisy.","Průměrný roční výnos akciového fondu od založení je 5,39 % p. a.","Maximální historická ztráta akciového fondu od založení je -5,39 % p. a.","Směrodatná odchylka (rizikovost) akciového fondu od průměrného výnosu je 5,39 %."],"c":[0],"p":212,"e":"Vzhledem k ukazateli durace v měsíční zprávě lze usuzovat, že se jedná o dluhopisový fond (durace je ukazatelem úrokového rizika u dluhopisů). S růstem doby do splatnosti dluhopisů narůstá i jejich durace, ale ne lineárně, proto bude pravděpodobná průměrná splatnost portfolia fondu okolo 5 - 5,5 let. ŠOBA, O. a Ing. Martin Širůček, Ph.D., M. Finanční matematika v praxi. 2. aktualizované a rozšíř. vyd. Praha: Grada Publishing, 2017. ISBN 978-80-271-0250-1. Od str. 239.","k":25},{"id":"20682.1","t":"c","q":"Přestože mají znalosti (především pan Uvážlivý) o fungování finančního trhu, překvapilo je, že poradce (investiční zprostředkovatel) se zajímá o jejich finanční poměry, resp. o jejich společnou bilanci.","o":["Poradce potřebuje získat informace o jejich finanční situaci pro provedení testu vhodnosti.","Poradce potřebuje získat informace o jejich finanční situaci pro provedení testu přiměřenosti.","Poradce potřebuje získat informace o jejich finanční situaci pro ověření skutečnosti, zda se nejedná o profesionálního zákazníka, který již má zkušenosti s investičními nástroji.","Poradce potřebuje získat informace o jejich finanční situaci pro ověření skutečnosti zda se nejedná o kvalifikovaného zákazníka, který již má zkušenosti s investičními nástroji."],"c":[0],"p":213,"e":"Poradce je povinen od klienta vždy získat informace o jeho znalostech a zkušenostech s investičními nástroji (test přiměřenosti), ale bude se zajímat i o finanční situaci a zázemí klienta a jeho investiční cíle (test vhodnosti). §15 ZPKT","k":26},{"id":"20683.1","t":"c","q":"Pro oba dva představuje investice především ochranu kapitálu před inflací a současně nástroj k zajištění příjmu v neproduktivním věku.","o":["Vzhledem k délce investičního horizontu, kdy hodlají peněžní prostředky využít, poradce doporučí spíše dynamickou (akciovou) investiční strategii s případnou následnou realokací.","Vzhledem k délce investičního horizontu, kdy hodlají peněžní prostředky využít, poradce doporučí spíše konzervativní (dluhopisy v kombinaci s nástroji peněžního trhu) investiční strategii s následnou případnou realokací.","Vzhledem k deficitnímu důchodovému účtu a potřebě kapitálu v důchodovém věku zvolí poradce vysoce rizikovou investiční strategii do derivátových nástrojů, aby tak byl prostor k vytvoření dostatečné finanční rezervy.","Vzhledem k historicky nízkým výnosům akciového i dluhopisového trhu, doporučí poradce spíše vyčkávat a prostředky využít spíše na spořicím účtu či termínovaném vkladu."],"c":[0],"p":213,"e":"S růstem délky investičního horizontu se doporučují více riziková aktiva do portfolia, která nesou sice vyšší riziko, resp. pradvěpodobnost ztráty, ale dlouhý časový horizont volatilitu jejich ceny \"vyhlazuje\". S blížícím se koncem investice, resp. očekávaným odprodejem investice, je vhodné postupně realokovat rizikovoou složku portfolia ke konzervativní.","k":26},{"id":"20684.1","t":"c","q":"Vzhledem k možnosti rizika špatného načasování investice poradce doporučuje spíše:","o":["Pravidelnou investici.","Jednorázovou investici.","Váženou investici.","Likvidní investici."],"c":[0],"p":213,"e":"Při jednorázové investici hrozí riziko špatného načasování, tzn. že se investice realizuje za vysokých tržních cen, kdy posléze ceny klesnou. Výhodnější je investovat nižší částku pravidelně, čímž dochází k průměrování ceny (v dobách vysokých cen se nakupuje méně instrumentů, v dobách poklesu naopak instrumentů více). Základními metodami pravidlené investice je dolar cost averaging a value averaging.","k":26},{"id":"20685.1","t":"c","q":"Investiční zprostředkovatel je oprávněn poskytovat pouze služby vztahující se k cenným papírům kolektivního investování a dluhopisům a rozhodně nesmí přijímat peněžní prostředky nebo investiční nástroje zákazníků.","o":["Poradce v žádném případě nesmí přijmout peníze.","Poradce převezme peníze, strhne si nákupní poplatek a klientům vystaví výpis o provedení investice (po odečtení poplatku), kde bude uvedeno o jaké investiční nástroje se jedná, jejich množství a jednotková cena.","Poradce převezme peníze a i když příkaz neodpovídá výsledkům testu přiměřenosti a vhodnosti, upozorní klienta na nepřiměřenost transakce, ale příkaz provede.","Poradce nepřevezme peníze, protože příkaz a přiměřenost transakce neodpovídá výsledkům získaným z testu přiměřenosti a vhodnosti."],"c":[0],"p":214,"e":"Zákon č. 256/2004, §32a, odst. (3)","k":26},{"id":"20686.1","t":"c","q":"Vybraný podílový fond v měsíční zprávě vykazuje dlouhodobý průměrný výnos 4 % p.a. při volatilitě 3 %. Poradce tedy vysvětlí klientům, že:","o":["Výnos takového fondu se v 68 % případů pohyboval od 1 % p. a. do 7 % p. a.","Výnos takového fondu se v 95 % případů pohyboval od 1 % p. a. do 7 % p. a.","Výnos takového fondu dosahoval ve 3 % nejlepších obchodních dní 4 % p.a.","Výnos takového fondu dosahoval ve 3 % nejhorších obchodních dní 4 % p. a."],"c":[0],"p":214,"e":"Volatilita představuje rizikovost investice, kterou lze stanovit např. směrodatnou odchylkou, která představuje odmocninu z rozptylu. Velikost směrodatné odchylky potom říká, že investor dosáhne v 68 % případů uváděného či historického průměrného výnosu (4 %) +/- jedna směrodatná odchylka (3 %). Pokud by investor aplikoval dvě směrodatné odchylky, pokryl by 95 % všech případů a jeho výnos by se potom pohyboval od -2 % (4 % - 3 % - 3 %) do 10 % (4 % + 3 % + 3 %). V takovém případě lze hovořit již o 100% jistotě, protože můžeme tvrdit, že klient dosáhne se 100% pravděpodobností buď zisku či ztráty. Proto je potřeba být při aplikaci většího počtu směrodatných odchylek uvážlivý.","k":26},{"id":"21463.2","t":"c","q":"Pan Vychytralý by si představoval výnos okolo 10 % ročně, a to s tím, aby byly peněžní prostředky poměrně rychle likvidní, protože neví, kdy bude peníze potřebovat.","o":["Poradce sdělí klientovi, že vybrat vhodnou investici a stanovit doporučení může až poté, co od něj získá potřebné informace o jeho znalostech a zkušenostech v oblasti investic, jeho finanční situaci a zázemí, ochotu nést ztrátu, averzi k riziku a jeho investiční cíle.","Poradce sdělí klientovi, že takovou investici ve svém portfoliu nemá a odkáže jej na služby obchodníka s cennými papíry.","Poradce rovnou nabídne klientovi sprint investiční certifikát, který v minulosti dosáhl i 20% výnosu.","Poradce sdělí klientovi, že jeho požadavkům, budou nejlépe vyhovovat státní dluhopisy Německa, které již od roku 2015 dosahují historicky maximálních výnosů okolo 7 - 8 % p. a. Navíc se jedná o státní dluhopisy, významného emitenta, kde je prakticky nulové riziko."],"c":[0],"p":215,"e":"Při poskytování investičních služeb uvedených v § 4 odst. 2 písm. d) a e) je investiční poradce povinen získat od klienta především informace o jeho znalostech a zkušenost s investováním finanční situaci, kvůli případným ztrátám, jeho postoj k riziku a investiční cíle.","k":27},{"id":"21464.2","t":"c","q":"Vzhledem k původu peněz, které hodlá pan Vychytralý investovat, potřebuje tyto prostředky investovat výhradně hotově k rukám uvedeného poradce.","o":["Poradce je povinen odmítnout, nesmí přijímat peněžní prostředky.","Poradce s tím nemá problém, pan Vychytralý může složit peníze přímo u něj, pouze musí vyplnit test AML.","Poradce může peněžní prostředky od klienta přijmout pouze do výše 100 000 Kč.","Poradce může peněžní prostředky od klienta přijmout pouze do výše 200 000 Kč."],"c":[0],"p":215,"e":"Vázaný zástupce nesmí přijímat peněžní prostředky a investiční nástroje klientů.","k":27},{"id":"21465.3","t":"c","q":"Pan Vychytralý se neustále vyhýbá otázkám týkajícím se jeho finanční situace, nerozumí tomu, když chce investovat \"takový balík\", proč to poradce zajímá.","o":["Poradce sdělí klientovi, že bez ohledu na výši investice je pro případ testu vhodnosti nutné znát klientovy investiční cíle a jeho finanční situaci.","Poradce sdělí klientovi, že bez ohledu na výši investice je pro případ testu přiměřenosti nutné znát klientovy investiční cíle a jeho finanční situaci.","Poradce sdělí klientovi, že bez ohledu na výši investice je pro případ AML testu nutné znát klientovy investiční cíle a jeho finanční situaci.","Poradce se klientovi omluví, pouze mu sdělí, že je obvyklé při investici nad 100 000 Kč zajímat se o finanční situaci klienta, tak aby investice neohrozila (v případě ztráty) jeho finanční situaci. Tyto informace jsou nicméně dobrovolné."],"c":[0],"p":215,"e":"Vázaného zástupce tato informace zajímá především z důvodu, aby mohl klientovi vysvětlit či vypočítat, jak by případná ztráta z investice ovlivnila jeho finanční situaci. Situaci o finančním zázemí je nutné znát z důvodu schopnosti klienta nést ztrátu.","k":27},{"id":"21466.3","t":"c","q":"Pan Vychytralý po měsíci volal, rozzlobený, svému poradci, jak je možné, že nákup podílových listů proběhl za vyšší cenu než byla cena v den, kdy společně zadávali příkaz k nákupu.","o":["Poradce vysvětlí klientovi, že je vše v pořádku, protože investiční společnost zpracuje nákupní pokyn až v okamžiku, kdy obdrží peněžní prostředky (zpravidla následující den či dva), čímž se může kurz podílového listu odlišovat.","Poradce se klientovi omluví a přezkoumá tuto skutečnost u investiční společnosti.","Poradce klienta uklidní s tím, že vyšší nákupní kurz byl způsoben přirážkou provize ke kurzu, který platil v den zadání příkazu.","Poradce klientovi vysvětlí, že v případě investice do 100 000 Kč má investiční společnost, dle statutu fondu, právo účtovat si poplatek za podlimitní investici v podobě přirážky ke kupní ceně."],"c":[0],"p":216,"e":"Rozhodný termín pro nákupy a odkupy podílových listů je okamžik (datum) připsání finančních prostředků podílníka na účet fondu. Řídí se statutem fondu či harmonogramem zpracování pokynů investiční společnosti.","k":27},{"id":"21467.3","t":"c","q":"Při kontrolní schůzce klienta s poradcem po roce od provedení investice nerozumí pan Vychytralý ukazateli Sharpe Ratio v měsíční zprávě fondu, který je nulový:","o":["Poradce klientovi vysvětlí, že fond dosáhl stejného výnosu jako bezriziková investice, tedy, že poměr výnosu nad bezrizikovou výnosovou míru a rizika (celkového rizika) je nulový.","Poradce klientovi vysvětlí, že během uplynulého roku byla rizikovost jeho investice nulová.","Poradce klientovi vysvětlí, že fond se v žádném ze sledovaných dnů (konkrétní data uvedena ve statutu fondu) nedostal pod historický průměrný výnos.","Poradce klientovi vysvětlí, že výnos fondu se naprosto shodoval s benchmarkem. Ani jej nepřekonal (kladné Sharpe ratio), ani nebyl horší (záporné Sharpe ratio)."],"c":[0],"p":216,"e":"Sharpe ratio je základním ukazatelem investice, který hodnotí poměr výnosu k rizikovosti investice. Jedná se o výnos investice nad bezrizikovou výnosovou míru (zpravidla výnos státních pokladničních poukázek), vztažený k celkovému riziku investice, tzn. riziku tržnímu, ale i riziku jedinečnému, měřenému směrodatnou odchylkou. Nulové Sharpe ratio tedy znamená, že výnos fondu byl shodný s výnosem bezrizikové investice (např. státní pokladniční poukázky), nikoli s výnosem benchmarku.","k":27},{"id":"20706.3","t":"c","q":"Jaké informace od zákazníka v tomto případě nemusíte vyžadovat?","o":["Informace o finančním zázemí zákazníka, včetně jeho schopnosti nést ztráty, a o investičních cílech, včetně tolerance k riziku.","Informace o jeho dosavadních zkušenostech s investováním do cenných papírů.","Informace o jeho odborných znalostech v oblasti investování do cenných papírů.","U této investiční služby nemusím od zákazníka požadovat žádné informace."],"c":[0],"p":217,"e":"V případě, že hlavní investiční službou je přijímání a předávání pokynů je vázaný zástupce povinen informovat se u klienta na jeho odborné znalosti v oblasti investic a zkušenosti v oblasti investic. V případě, že zákazník odmítne informace poskytnout nebo je neposkytne v požadovaném rozsahu, obchodník s cennými papíry poučí zákazníka o tom, že takový postoj mu neumožní vyhodnotit, zda poskytnutí příslušné investiční služby, rady ohledně investičního nástroje nebo provedení obchodu s investičním nástrojem v rámci investiční služby uvedené v odstavci 1 odpovídá jeho odborným znalostem nebo zkušenostem potřebným pro pochopení souvisejících rizik.","k":28},{"id":"20707.3","t":"c","q":"Zákazník se seznámil s historickými hodnotami výnosů nabízeného akciového fondu a zeptá se, zda může počítat s obdobným průběhem i v následujících letech. Co mu odpovíte?","o":["Upozorním zákazníka, že údaje o historické výkonnosti v žádném případě nezaručují obdobné hodnoty v budoucnu.","Sdělím zákazníkovi, že výraznější odchylky od dosavadního průběhu výnosnosti jsou v budoucnu málo pravděpodobné.","Sdělím zákazníkovi, že výraznější odchylky od dosavadního průběhu výnosnosti jsou v budoucnu hodně pravděpodobné.","Sdělím zákazníkovi, že mu neposkytuji službu investičního poradenství, tudíž mu nemohu na tuto otázku odpovědět."],"c":[0],"p":217,"e":"Vždy platí, že historické hodnoty výnosnosti nelze garantovat.","k":28},{"id":"20708.3","t":"c","q":"Zákazník vám při úvodním rozhovoru sdělí, že chce investovat jednorázově větší sumu peněz, kterou má připravenou na financování koupě bytu, který chce koupit příští rok v květnu a do té doby chce peníze co nejvíce zhodnotit. Co mu na tento požadavek nabídnete?","o":["Zákazníkovi vysvětlím, že pro tento případ je investice do cenných papírů nevhodná, neboť se jedná o krátký investiční horizont a je zde velké riziko, že by se investice spíše znehodnotila.","Nabídnu některý dluhopisový fond v CZK (je irelevantní, jestli fond státních dluhopisů nebo korporátních), oba typy dosahují dlouhodobě dobrých výsledků.","Nabídnu široce diverzifikovaný akciový fond stabilních společností.","Nabídnu kombinaci několika podílových fondů."],"c":[0],"p":217,"e":"V tak krátkém horizontu lze jen těžko dosáhnout zhodnocení, navíc je zde riziko nevhodného vývoje kapitálového trhu v okamžiku, kdy zákazník bude potřebovat investici vybrat. Pokud by fond měl navíc vstupní poplatek, je pravděpodobné, že za tuto dobu by nevydělal ani na tento poplatek.","k":28},{"id":"20709.3","t":"c","q":"Zákazník vám sdělí, že nemá zřízen běžný účet a požádá vás, zda by odkupy podílových listů mohl v budoucnu realizovat prostřednictvím vašeho účtu s tím, že byste mu příslušné částky vždy vyzvedl a předal v hotovosti. Vaše reakce?","o":["Tento postup důrazně odmítnu a vysvětlím zákazníkovi, že podle zákona nesmím nakládat s prostředky zákazníka.","Budu souhlasit za podmínky, že se se zákazníkem dohodnu za odměně za tuto službu.","Tuto službu zákazníkovi odmítnu poskytnout a vysvětlím mu, že za takovéto služby nejsem placen(a).","Budu souhlasit za předpokladu, že zákazník bude mým prostřednictvím investovat opakovaně."],"c":[0],"p":217,"e":"Investiční zprostředkovatel nesmí v souvislosti s poskytováním investičních služeb přijímat peněžní prostředky nebo investiční nástroje zákazníků.","k":28},{"id":"20710.3","t":"c","q":"Zákazník porovnává dosavadní výnosnost dvou fondů, z nichž jeden existuje 10 let a druhý 5 let a používá k tomu hodnotu absolutního výnosu od založení. Jak zareagujete?","o":["Vysvětlím zákazníkovi, že tento ukazatel lze použít pouze při porovnávání fondů, od jejichž založení uplynula stejná doba, u fondů s různou dobou od založení není tento ukazatel vypovídající.","Potvrdím zákazníkovi jeho úvahu a fond s vyšším absolutním výnosem označím za výnosnější a vhodnější pro zákazníka, bez ohledu na další faktory.","Vysvětlím zákazníkovi, že fondy nelze porovnávat, protože každý má jiné portfolio nakoupených cenných papírů, což se odráží i v odlišné rizikovosti fondů.","Vysvětlím zákazníkovi, že porovnávat historickou výnosnost nemá nejmenší význam, protože tento ukazatel o dosavadní úspěšnosti fondu vůbec nic nevypovídá."],"c":[0],"p":218,"e":"Absolutní výnos od založení fondu není možné srovnávat mezi fondy s odlišnou délkou existence. Dalo by se pouze v případě, že by se jednalo o anualizovanou výnosnost na stejně dlouhém časovém horizontu.","k":28},{"id":"20712.1","t":"c","q":"Jaké informace od zákazníka v tomto případě musíte vyžadovat?","o":["Informace o jeho dosavadních zkušenostech s investováním do cenných papírů, o jeho odborných znalostech v oblasti investování do cenných papírů, o finančním zázemí zákazníka, včetně jeho schopnosti nést ztráty, a o investičních cílech, včetně tolerance k riziku.","Pouze informace o jeho dosavadních zkušenostech s investováním do cenných papírů.","Pouze informace o jeho odborných znalostech v oblasti investování do cenných papírů.","Pouze informace o jeho dosavadních zkušenostech s investováním do cenných papírů a o jeho odborných znalostech v oblasti investování do cenných papírů."],"c":[0],"p":219,"e":"Při provádění služby investičního poradenství je vázaný zástupce povinen získat od klienta informace o jeho finanční situaci, resp. finančním zázemí, dosavadních znalostech a zkušenostech v oblasti investic ale i jeho rizikový profil, resp. ochotu nést ztráty, aby znal důsledky na jeho finanční situaci. Zástupce se bude rovněž zajímat o důvody investice, resp. investiční cíle klienta.","k":29},{"id":"20713.1","t":"c","q":"Zákazník vám sdělí, že investici chce využít jako pohotovostní rezervu, ze které bude chtít vybírat v případě nenadálé potřeby. Co mu poradíte?","o":["Doporučím akciové fondy, aby portfolio mělo potenciál co nejvyššího výnosu do doby, než bude případně zákazník potřebovat realizovat prodej.","Doporučím kombinaci garantovaných fondů","Doporučím co nejširší portfolio akciových fondů.","Upozorním zákazníka, že investice obecně není pro takovéto účely příliš vhodná, protože díky akutní potřebě získat zpět hotovost může dojít k realizaci ztráty kvůli aktuálnímu poklesu hodnoty cenných papírů na kapitálovém trhu, příp. se projeví negativní vliv spreadu."],"c":[3],"p":219,"e":"Potřeba rychlého výběru i v období nepříznivého vývoje trhu je pro tyto účely velký problém, nepomohou ani zajištěné fondy, u kterých zajištění funguje až v době splatnosti, nikoliv průběžně.","k":29},{"id":"20714.2","t":"c","q":"Zákazník vám při úvodním rozhovoru sdělí, že chce investici zahrnout do svého obchodního majetku a snížit tak letošní základ daně o pořizovací cenu cenných papírů. Co mu na tento požadavek sdělíte?","o":["Tento záměr zákazníkovi schválím jako dobrý nápad pro daňovou optimalizaci.","Tento záměr zákazníka budu respektovat a přizpůsobím tomu své poradenství.","Zákazníkovi sdělím, že nákupem cenných papírů daňový základ snížit v žádném případě nelze.","Zákazníkovi doporučím tento záměr konzultovat v každém případě s jeho daňovým poradcem, protože, podle mého názoru, nákupem cenných papírů nelze snížit základ daně v roce, kdy cenné papíry nakoupil, ale až v roce, kdy je bude prodávat."],"c":[3],"p":219,"e":"Záměr zákazníka není reálný, závěrečné slovo by ale vždy měl mít daňový poradce.","k":29},{"id":"20715.1","t":"c","q":"Zákazník vám sdělí, že v rámci investičního poradenství očekává, že vám dá dispoziční práva ke svému účtu cenných papírů a vy budete dle svého uvážení jeho jménem zadávat pokyny k nákupu a prodeji tak, aby jeho portfolio bylo co nejlépe zhodnocováno. Co mu odpovíte?","o":["Vysvětlím zákazníkovi, že jím požadovanou službu mu nesmím poskytovat protože se jedná o investiční službu obhospodařování majetku zákazníka, kterou investiční zprostředkovatel nesmí poskytovat.","Budu souhlasit za podmínky, že se se zákazníkem dohodnu na odměně za tuto službu.","Tuto službu zákazníkovi odmítnu poskytnout a vysvětlím mu, že za takovéto služby nejsem placen(a).","Budu souhlasit za předpokladu, že se zákazník zaváže investovat více jak 1 milion korun."],"c":[0],"p":220,"e":"Jako investiční zprostředkovatel nemám právo k provádění služby obhospodařování portfolia. Investiční zprostředkovatel je osoba, která je na základě povolení k činnosti investičního zprostředkovatele uděleného Českou národní bankou oprávněna poskytovat pouze hlavní investiční služby přijímání a předávání pokynů týkajících se investičních nástrojů a investiční poradenství týkající se investičních nástrojů.","k":29},{"id":"20716.1","t":"c","q":"Zákazník použije k posouzení výkonnosti fondů udávanou hodnotu p.a. od založení fondu a zeptá se, zda to tedy znamená, že tyto fondy se chovaly jako termínovaný účet a každý rok vykázaly deklarované zhodnocení. Co mu odpovíte?","o":["Potvrdím zákazníkovi jeho úvahu a chování fondu označím za srovnatelné s chováním termínovaného vkladu v bance.","Sdělím zákazníkovi, že fondy nelze vůbec hodnotit podle údaje p. a.","Sdělím zákazníkovi, že příliš vysoká hodnota tohoto ukazatele je signálem velkého rizika, že může o svoji investici přijít a uvedu příklad z historie kampeliček.","Vysvětlím zákazníkovi, že tento ukazatel je přepočten tak, jako by se počáteční investice zhodnocovala uváděným výnosem p. a., ovšem neznamená to, že každý rok bylo dosaženo tohoto výnosu, fond mohl vykazovat v určitém období i ztrátu a v jiném naopak výnos vyšší než deklarovaný, porovnání s termínovaným vkladem to tak není správné."],"c":[3],"p":220,"e":"Hodnota p. a. je v tomto případě zprůměrována, o volatilitě ani o riziku ztráty nevypovídá nic.","k":29},{"id":"20724.1","t":"c","q":"Emisní podmínky obsahují informaci, že dluhopis bude listinným dluhopisem a bude cenným papírem na řad.","o":["Takový dluhopis je možné převádět rubopisem a smlouvou k okamžiku jeho předání.","Takový dluhopis není možné převádět.","Takový dluhopis lze převádět pouze s předchozím písemným souhlasem jeho emitenta.","Takový dluhopis lze převádět pouhým předáním bez jakéhokoliv omezení."],"c":[0],"p":221,"e":"§ 2 odst. 3 zákona č. 190/2004 Sb., o dluhopisech ve znění pozdějších předpisů výslovně stanoví, že listinný dluhopis je cenným papírem na řad. § 1103 odst. 2 zákona č. 89/2012 Sb., občanský zákoník ve znění pozdějších předpisů dále stanoví, že cenný papír na řad lze převádět pouze jeho rubopisací a smlouvou k okamžiku jeho předání.","k":30},{"id":"20725.1","t":"c","q":"Propagační materiály doplňující prospekt cenného papíru dále uvádějí, že investice do této emise dluhopisů jsou plnohodnotným, avšak lépe úročeným ekvivalentem bankovního vkladu.","o":["Informace není správná. Bankovní vklady jsou ze zákona pojištěny Garančním systémem finančního trhu, investice do korporátního dluhopisů takové zajištění postrádá.","Informace není správná, neboť pouze investice do zaknihovaných dluhopisů jsou zaručeny Garančním systémem finančního trhu.","Informace je správná, neboť investice do dluhopisů je ze zákona zajištěna Garančním fondem obchodníků s cennými papíry.","Informace je správná, neboť bankovní vklady rovněž nejsou žádným způsobem pojištěny či zaručeny."],"c":[0],"p":221,"e":"Pohledávky z bankovních vkladů jsou v souladu se zákonem č. 21/1992 Sb., o bankách pojištěny Garančním systémem finančního trhu. Garanční fond obchodníků s cennými papíry je záručním systémem, z něhož se vyplácí náhrady zákazníkům obchodníka s cennými papíry, který není schopen plnit své dluhy vůči svým zákazníkům.","k":30},{"id":"20726.1","t":"c","q":"Propagační materiály doplňující prospekt cenného papíru také uvádějí, že emise je likvidní a veřejně obchodovatelnou, neboť emitent zajišťuje propojení zájemců o koupi a prodej již emitovaných dluhopisů prostřednictvím svých internetových stránek.","o":["Informace není správná, za veřejně obchodovatelnou lze považovat emisi dluhopisů, jež je přijata k obchodování na některý z organizovaných veřejných trhů, tedy obchodních systémů vymezených v Zákoně č. 256/2004 Sb., o podnikání na kapitálovém trhu ve znění pozdějších předpisů.","Informaci lze považovat za správnou, neboť za likvidní a veřejně obchodovatelnou emisi lze považovat takovou emisi, u niž existuje jakýkoliv mechanismus pro propojení zájemců o koupi a prodej.","Informace není správná, neboť dluhopisy vždy představují závazkový vztah mezi jejich vlastníkem a emitentem, který nelze převést či postoupit na další osobu.","Informace není správná, neboť dluhopisy vždy představují závazkový vztah mezi jejich vlastníkem a emitentem, který lze převést či postoupit na další osobu pouze se souhlasem emitenta."],"c":[0],"p":221,"e":"Právní předpisy výslovně nevymezují pojmy likvidní či veřejně obchodovatelný. Standardně je nicméně pojem veřejné obchodovatelnosti atributem, který je užíván pro investiční nástroje přijaté na některý z obchodních systémů vymezených v § 2 odst. 2 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu ve znění pozdějších předpisů. Listinný dluhopis je v souladu s § 2 odst. 3 zákona č. 190/2004 Sb., o dluhopisech cenným papírem na řad, který lze vždy převádět rubopisací a předáním.","k":30},{"id":"20727.1","t":"c","q":"Klient se po zhodnocení rizik spojených s investicí rozhodne pro nákup dluhopisů z dané emise. Zároveň požádá investičního zprostředkovatele o zprostředkování dané investice s tím, že mu peněžní prostředky předá na místě a v hotovosti.","o":["Investiční zprostředkovatel musí takový postup odmítnout, neboť při poskytování investičních služeb není oprávněn přijímat investiční prostředky nebo investiční nástroje zákazníků.","Investiční zprostředkovatel musí takový postup odmítnout, neboť není oprávněn poskytovat jakékoliv investiční služby týkající se dluhopisů, ke kterým byl vydán prospekt nebo srovnatelný dokument.","Takový postup je v pořádku a investiční zprostředkovatel je oprávněn investiční prostředky zákazníka přijmout.","Takový postup je v pořádku a investiční zprostředkovatel je oprávněn investiční prostředky zákazníka přijmout, pokud jejich výše nepřesáhne 1 000 000 Kč."],"c":[0],"p":222,"e":"V souladu s § 29 odst. 3 písm. e) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu ve znění pozdějších předpisů je investiční zprostředkovatel oprávněn poskytovat investiční služby uvedené v § 4 odst. 2 písm. a) nebo e) zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu ve znění pozdějších předpisů ve vztahu k dluhopisům, ke kterým byl vydán prospekt nebo srovnatelný dokument. Ustanovení § 29 odst. 2 zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu ve znění pozdějších předpisů ovšem zároveň stanoví, že investiční zprostředkovatel v souvislosti s poskytováním investičním služeb nesmí přijímat peněžní prostředky nebo investiční nástroje zákazníků.","k":30},{"id":"20728.1","t":"c","q":"Klienta, který je fyzickou osobou a daňovým rezidentem České republiky, zajímá, jaký roční výnos po zdanění by případně inkasoval při investici do těchto dluhopisů ve výši 100 000 Kč.","o":["Čistý roční výnos by činil 7 650 Kč, neboť výnosy z dluhopisů jsou v tomto případě předmětem srážkové daně ve výši 15 %.","Čistý roční výnos by činil 4 500 Kč, neboť výnosy z dluhopisů jsou předmětem srážkové daně ve výši 50 %.","Roční výnos by činil 9 000 Kč, neboť výnosy z dluhopisů jsou vždy osvobozeny od daně z příjmů.","Roční výnos by činil 9 000 Kč, neboť výnosy z dluhopisů jsou předmětem srážkové daně ve výši 15 % pouze v případě, že investorem je právnická osoba."],"c":[0],"p":222,"e":"Výnosy z dluhopisů ve vlastnictví fyzických osob, které jsou daňovými rezidenty České republiky, jsou dle aktuální legislativy předmětem 15% srážkové daně (§ 22 odst. 1 písm. g) bod 4 a § 36 odst. 1 písm.a) bod 1 zákona č. 586/1992 Sb., o daních z příjmů)","k":30},{"id":"20730.1","t":"c","q":"Je možné, aby akciová společnost se sídlem v České republice rozhodla o vyřazení akcií z obchodování tímto způsobem?","o":["Ano, v daném případě spadá rozhodnutí do působnosti valné hromady akciové společnosti.","Ne, o vyřazení akcií může rozhodnout výhradně organizátor regulovaného trhu, na kterém jsou přijaty k obchodování.","Ne, o vyřazení akcií může rozhodnout pouze Česká národní banka.","Ano, ale rozhodnutí musí následně schválit rovněž Česká národní banka."],"c":[0],"p":223,"e":"Rozhodnutí o vyřazení akcií náleží do působnosti valné hromady společnosti.","k":31},{"id":"20731.1","t":"c","q":"Klient se dále zajímá, zda v popsaném případě bude možné, aby jím vlastněné akcie ponechal obchodovatelné na regulovaném trhu.","o":["Ne, vyřazena je vždy celá emise akcií.","Ano, pokud o toto požádá alespoň 5 % akcionářů.","Ano, pokud jeho žádost schválí Česká národní banka.","Ne, pouze organizátor daného regulovaného trhu může rozhodnout o tom, že libovolná část emise zůstane veřejně obchodovatelné,"],"c":[0],"p":223,"e":"U emise zastupitelných akcií z povahy věci vždy dochází k vyřazení celé emise. Akcionáři, kteří nesouhlasí, mají možnost využít odkupu dle § 333 a násl. zákona č. 90/2012 Sb., o obchodních korporacích.","k":31},{"id":"20732.1","t":"c","q":"Bude mít uvedený klient nárok na dividendu (tj. na podíl na zisku, pokud bude rozdělován) i po vyřazení akcií z obchodování na regulovaném trhu?","o":["Ano, vyřazení akcií z obchodování neovlivňuje nárok na dividendu, pokud k její výplatě dojde.","Ano, ovšem výhradně pokud se bude účastnit valné hromady, která o výplatě dividendy rozhodne.","Ne, pokud nebude vlastnit akcie představující 10 % a větší podíl na základním kapitálu společnosti.","Ne, pokud nebude vlastnit akcie představující 15 % a větší podíl na základním kapitálu společnosti."],"c":[0],"p":223,"e":"Právo na podíl na zisku je jedním ze základních práv akcionáře. Účast na valné hromadě nebo výše podílu ve společnosti na tento nárok nemá vliv.","k":31},{"id":"20733.1","t":"c","q":"Klient byl zvyklý, že na internetových stránkách společnosti nalezl celou řadu dokumentů a informací, mimo jiné výroční zprávy, pololetní zprávy, čtvrtletní zprávy, informace o dividendách apod. Bude i po vyřazení akcií z obchodování daná společnost povinna uveřejňovat informace ve stejném rozsahu?","o":["Ne, společnost nebude povinna nadále plnit informační povinnosti emitenta ve stejném rozsahu.","Ne, nicméně v odůvodněných případech může Česká národní banka rozhodnout o tom, že společnost bude povinna pokračovat v plnění informačních povinností ve stávajících rozsahu.","Ano, a to po dobu 3 let od vyřazení akcií z obchodování.","Ano, a to po dobu 5 let od vyřazení akcií z obchodování."],"c":[0],"p":223,"e":"Informační povinnosti akciové společnosti se sídlem v České republice, jenž je přijata k obchodování na regulovaném trhu stanoví § 118 a následující zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu. Těmito ustanoveními se společnost řídí pouze po dobu, kdy jsou její akcie přijaty k obchodování na regulovaném trhu.","k":31},{"id":"20734.1","t":"c","q":"Klient akcie nakoupil za částku 800 Kč a vlastnil je 36 měsíců. Emitent dvakrát vyplatil dividendu v čisté výši 30 Kč. Nyní může akcie prodat za částku 1 100 Kč. Jaké průměrné zhodnocení vložených peněžních prostředků mu investice v případě prodeje vynesla (pokud nebereme v potaz poplatky spojené s nákupem a prodejem akcií, daňové odvody na straně investora a případné zisky z reinvestice dividend)?","o":["Průměrně 15 % ročně.","Průměrně 20 % ročně.","Průměrně 25 % ročně.","Průměrně 10 % ročně."],"c":[0],"p":224,"e":"Investice do jedné akcie ve výši 800 Kč se během tří let zhodnotila o 360 Kč na 1160 Kč, tedy průměrně o částku 120 Kč ročně. Částka 120 Kč představuje 15 % z původní investice do jedné akcie ve výši 800 Kč.","k":31},{"id":"20736.1","t":"c","q":"Může investiční zprostředkovatel nabízet cenné papíry kolektivního investování vydané fondem kvalifikovaných investorů?","o":["Ano.","Ne.","Ano, ale celková hodnota nabízených cenných papírů kolektivního investování nesmí přesáhnout ekvivalent 1 000 000 EUR.","Ano, ale celková minimální výše investice jednoho investora nesmí přesáhnout ekvivalent 100 000 EUR."],"c":[0],"p":225,"e":"Investiční zprostředkovatel je oprávněn nabízet cenné papíry kolektivního investování vydané fondem kvalifikovaných investorů nebo srovnatelným zahraničním investičním fondem bez ohledu na objem nabízených investičních nástrojů či na minimální výši investice.","k":32},{"id":"20737.1","t":"c","q":"Co pro investora mimo jiné znamená skutečnost, že investuje do fondu kvalifikovaných investorů?","o":["Investorem tohoto fondu může být pouze v zákoně vymezený okruh profesionálních investorů, nebo osoby, které do fondu investují minimálně částku stanovenou zákonem a splní další podmínky zákonem stanovené.","Investory mohou být výhradně osoby, které složí zvláštní zkoušku organizovanou Českou národní bankou, přičemž limity na výši investice do fondu již nejsou stanoveny.","Investory mohou být výlučně finanční instituce nebo stát.","Investice do tohoto fondu lze nabízet výhradně v případě, že je před zahájením nabízení uveřejněn prospekt."],"c":[0],"p":225,"e":"Podíl na fondu kvalifikovaných investorů může nabýt pouze osoba uvedená v § 272 odst. 1 zákona č. 240/2013 Sb., o investičních společnostech a investičních fondech. Okruh zde uvedených subjektů zahrnuje institucionální a profesionální investory a dále osoby, které investují ve výši stanovené zákonem a splní další podmínky stanovené § 272 odst. 1 zákona č. 240/2013 Sb., o investičních společnostech a investičních fondech.","k":32},{"id":"20738.1","t":"c","q":"Fond kvalifikovaných investorů má právní formu akciové společnosti s proměnným základním kapitálem (SICAV). Co to znamená?","o":["Fond je akciovou společností, jež je oprávněna stanovit základní kapitál v jakékoliv měně.","Fond je akciovou společností, jejíž základní kapitál či jeho část byly splaceny nepeněžitým vkladem.","Fond je akciovou společností, která může vydávat a odkupovat tzv. investiční akcie bez nutnosti provádět související zápisy do obchodního rejstříku.","Fond je akciovou společností, u níž byla část vlastního kapitálu poskytnuta ve formě tzv. příplatku mimo základní kapitál."],"c":[2],"p":225,"e":"Akciová společnost s proměnným základním kapitálem je oprávněna vydávat a odkupovat investiční akcie, aniž by bylo nutné zapisovat změny základního kapitálu (který je zároveň fondovým kapitálem investičního fondu) od obchodního rejstříku.","k":32},{"id":"20739.1","t":"c","q":"Pro nabízení investic do tohoto fondu kvalifikovaných investorů se investoři potřebují seznámit s dokumentem, který obsahuje investiční strategii, popis rizik spojených s investicí do fondu a další údaje nezbytné pro investory k zasvěcenému posouzení investice. Jak se tento dokument nazývá?","o":["Statut fondu.","Stanovy fondu.","Informační memorandum fondu.","Investiční doporučení fondu."],"c":[0],"p":225,"e":"Statut fondu kolektivního investování je dokument, který obsahuje investiční strategii fondu kolektivního investování, popis rizik spojených s investováním tohoto fondu a další údaje nezbytné pro investory k zasvěcenému posouzení investice, zpracované formou srozumitelnou běžnému investorovi.","k":32},{"id":"20740.1","t":"c","q":"Pokud se investor rozhodne investovat do tohoto fondu kvalifikovaných investorů, musí uhradit vstupní poplatek ve výši 3 %. Investor má k dispozici celkové investiční prostředky ve výši 5 000 000 Kč. Jaké výše tedy dosáhne samotná investice do fondu kvalifikovaných investorů (zaokrouhleno na stovky Kč). Ignorujte poplatky spojené s platbou a jiné náklady.","o":["Přibližně částky 4 854 400 Kč.","Přibližně částky 4 850 400 Kč.","Přibližně částky 8 544 400 Kč.","Přibližně částky 8 559 400 Kč."],"c":[0],"p":226,"e":"Pokud má potenciální investor k dispozici částku 5 000 000 Kč, pak tato částka bude při zohlednění vstupního poplatku představovat 103 % celkové realizované investice do fondu. Za využití trojčlenky (tj. 100*5 000 000/103) dojdeme k částce investice do fondu ve výši 4 854 368 Kč, tedy zaokrouhleně 4 854 400 Kč.","k":32},{"id":"21787.1","t":"c","q":"Jaké informace musí zákazníkovi na úvod poskytnout?","o":["Údaje o sobě jako vázaném zástupci, o obchodníkovi s cennými papíry, kterého zastupuje, o investičních službách, které poskytuje.","Identifikační údaje o obchodníkovi s cennými papíry, protože jeho jménem je uzavírána případná smlouva se zákazníkem.","Informace o investičních nástrojích, které hodlá zákazníkovi nabídnout.","Propagační materiály, jejich součástí musí být prospekt cenného papíru, o jehož nákupu se zákazníkem hodlá jednat."],"c":[0],"p":227,"e":"Zákon č. 256/2004 Sb. vyžaduje, aby osoba jednající se zákazníkem na úvod podala informace o sobě a investičních službách, které může zákazníkovi poskytnout, protože zákazník může mít zájem o jinou investiční službu, kterou konkrétní obchodník s cennými papíry neposkytuje.","k":33},{"id":"21788.1","t":"c","q":"Co musí zákazníkovi sdělit ohledně investičního nástroje, kterého se má investiční služba týkat?","o":["Poučení ohledně rizik spojených s investicí a zda je konkrétní investiční nástroj vhodný pro zákazníka, který není profesionálním zákazníkem, dále poučení o likviditě.","Poučení ohledně potřebných volných disponibilních zdrojů zákazníka.","Poučení týkající se konkurenčních investičních nástrojů.","Svoje zkušenosti a znalosti spojené s daným investičním nástrojem."],"c":[0],"p":227,"e":"Poučení o rizicích je základní požadavek na informování zákazníků, ve spojení s vhodností investičních nástrojů pro cílový trh neprofesionálních zákazníků je to další oblast ochrany zákazníků.","k":33},{"id":"21789.1","t":"c","q":"Jak by měl vyhodnotit investiční cíle zákazníka?","o":["Měl by hodnotit zaměření investice (dlouhodobá k budování majetku, krátkodobá ke zhodnocení volných prostředků, spekulativní) vždy ve vazbě na toleranci (averzi) zákazníka k riziku.","Měl by se zaměřit na averzi zákazníka k riziku a podle toho volit investiční instrument.","Měl by se zaměřit na konkrétní potřeby zákazníka (financování nemovitých nebo movitých věcí, budování renty apod.) a podle toho vybrat investiční nástroj (peněžního trhu, akcie nebo dluhopisy).","Měl by se zaměřit na toleranci zákazníka k riziku a podle toho volit jednoduché investiční nástroje nebo derivát."],"c":[0],"p":227,"e":"Investiční cíle zákazníka jsou současně s investičním horizontem základním předpokladem pro výběr vhodného investičního instrumentu při současném posouzení tolerance zákazníka k riziku.","k":33},{"id":"21790.1","t":"c","q":"Jak by zákazníkovi vysvětlil v souvislosti s jeho uvažovanou investicí pojem \"diverzifikace\"?","o":["Je to investování peněžních prostředků do většího počtu finančních nástrojů lišících se vlastnostmi a které jsou emitovány různými emitenty.","Je to investování pouze do střednědobých investičních nástrojů.","Je to investování peněžních prostředků v různých měnách, využívá kolísání směnného kurzu.","Je to investiční strategie vhodná pouze pro institucionální investory pro neprofesionálního zákazníka nevhodná."],"c":[0],"p":227,"e":"Jde o metodu snižování rizika investice, kdy je nakoupeno více různých investičních nástrojů lišících se mj. i z pohledu investičního horizontu.","k":33},{"id":"21791.1","t":"c","q":"Jak by zákazníkovi vysvětlil pojem \"výnosnost investice\"?","o":["Výnosnost je míra zhodnocení investovaných peněžních prostředků za určité časové období.","Výnosnost je rozdíl hrubých kapitálových výnosů a čistých kapitálových výnosů.","Výnosnost je daňová úspora investora.","Výnosnost je souhrn dividend vyplacených za určité časové období."],"c":[0],"p":228,"e":"U investičních nástrojů jako finančních investic je výnosnost považována za kritérium hodnocení efektivnosti vložených peněnžích prostředků.","k":33},{"id":"21793.1","t":"c","q":"Jaké základní dokumenty musí zpracovat?","o":["Investiční dotazník a záznam týkající se investiční služby a navrhovaných obchodů.","Identifikační údaje o obchodníkovi s cennými papíry, protože jeho jménem je uzavírána případná smlouva se zákazníkem.","Konkretizaci marketingových materiálů investiční společnosti.","Informační formulář pro hlášení o zamýšleném obchodu pro Českou národní banku."],"c":[0],"p":229,"e":"Základními dokumenty jsou investiční dotazník, ve kterém vázaný zástupce vyhodnocuje znalosti, a zkušenosti zákazníka s investicemi, a dále záznam k tomu, aby bylo možné následně vyhodnotit plnění informačních povinností podle zákona č. 256/2004 Sb.","k":34},{"id":"21794.1","t":"c","q":"Co především obsahují tyto dokumenty?","o":["Znalosti a zkušenosti zákazníka a jeho investiční cíle, dále záznamy telefonických hovorů a elektronické komunikace.","Komunikaci s Českou národní bankou.","Komunikaci s Finančním analytickým úřadem.","Komunikaci ohledně znalostí a zkušeností zákazníka s vnitřním auditem."],"c":[0],"p":229,"e":"Záznamy z jednání se zákazníkem je třeba vést v dostatečném rozsahu, aby následně Česká národní banka mohla sledovat dodržování požadavků zákona č. 256/2004 Sb.","k":34},{"id":"21795.2","t":"c","q":"Jak by měla být poskytována rada ohledně investičního nástroje, aby byl dodržel požadavek na objektivnost?","o":["Poradenství se musí zaměřovat na potřeby zákazníka a ne na výhody obchodníka s cennými papíry, banky nebo investiční společnosti.","Poradenství musí zohledňovat rodinnou situaci zákazníka.","Poradenství se musí zaměřovat na ochranu rizik v důsledku dohledu prováděného Českou národní bankou.","V rámci poradenství musí být zdůrazněna ochrana majetku zákazníka v důsledku působení vnitřního auditu."],"c":[0],"p":229,"e":"Požadavek na objektivitu investičního poradenství je stanoven jednak v základních zákonných povinnostech pro jednání se zákazníky, jednak je rozpracován i v teoretické literatuře a znamená jednání v nejlepším zájmu zákazníka bez prosazování určitých investičních nástrojů a zdůrazňování jejich výhod.","k":34},{"id":"21796.2","t":"c","q":"Jak by mělo vypadat investiční poradenství, aby byla dodržena zásada úplnosti?","o":["Poradenství se musí vztahovat na všechny vlastnosti investice, jež jsou pro zákazníka důležité, včetně upozornění ohledně rizik. Nesmějí být zamlčovány žádné nevýhody.","V rámci poradenství musí být zákazníkovi vysvětleny výhody investice.","V rámci poradenství musí být vysvětlena úloha garančního fondu obchodníků s cennými papíry.","V rámci poradenství musí být vysvětlena ochranná úloha dohledu České národní banky."],"c":[0],"p":229,"e":"Požadavek na úplnost poradenství souvisí s povinností poskytnout informace o investičních službách a nástrojích a možných rizicích.","k":34},{"id":"21797.2","t":"c","q":"Investiční poradenství je prováděno v souladu se zákonem o podnikání na kapitálovém trhu, jestliže se jedná o:","o":["Individualizované doporučení zákazníkovi ohledně konkrétního investičního nástroje.","Poradenství skupině potenciálních zákazníků ohledně konkrétního investičního nástroje.","Poradenství konkrétnímu zákazníkovi ohledně obecných zásad investování.","Poradenství skupině zákazníků ohledně obecných zásad investování."],"c":[0],"p":230,"e":"Je to jeden ze základních pojmů zákona č. 256/2004 Sb., podle definice vždy musí jít o individualizované doporučení.","k":34},{"id":"21799.1","t":"c","q":"Jaké informace musíte poskytnout na úvod?","o":["Údaje o sobě jako vázaném zástupci, o investičním zprostředkovateli, kterého zastupuje, o investičních službách, které poskytuje.","Identifikační údaje o bance z důvodu bankovního spojení pro zasílání plateb.","Informace o bankovním spojení obchodníka s cennými papíry.","Předání propagačních materiálů týkajících se investičních nástrojů."],"c":[0],"p":231,"e":"Zákon č. 256/2004 Sb. vyžaduje, aby osoba jednající se zákazníkem na úvod podala informace o sobě a investičních službách, které může zákazníkovi poskytnout, protože zákazník může mít zájem o jinou investiční službu, kterou konkrétní obchodník s cennými papíry neposkytuje.","k":35},{"id":"21800.1","t":"c","q":"Jaký první dokument se zákazníkem vyplníte?","o":["Investiční dotazník.","Poučení ohledně potřebných volných disponibilních zdrojů zákazníka.","Informaci o výnosu investičního nástroje.","Svoje zkušenosti a znalosti spojené s daným investičním nástrojem."],"c":[0],"p":231,"e":"Zjištění odborných znalostí a zkušeností zákazníka je východiskem pro další jednání a formulování nabídky investičních nástrojů. K tomuto zjištění slouží investiční dotazník.","k":35},{"id":"21801.2","t":"c","q":"Jakým způsobem je povinen obchodník s cenými papíry poskytovat zákazníkovi přiměřené informace o službách, které mu poskytl?","o":["Nemusí mu je poskytovat vůbec.","Na trvalém nosiči dat.","Pouze ústně.","V papírové podobě."],"c":[1],"p":231,"e":"Obchodník s cennými papíry je povinen poskytovat zákazníkovi na trvalém nosiči dat přiměřené informace o službách, které mu poskytl.","k":35},{"id":"21802.2","t":"c","q":"Kdy byste převzal od zákazníka peněžní částku v hotovosti na úhradu jeho investice?","o":["Investiční zprostředkovatel a jeho vázaný zástupce nesmí převzít od zákazníka žádné peněžní prostředky.","Převzal bych pouze menší částku v případě pravidelných investic.","Převzatou peněžní částku musím ještě týž den vložit na účet investičního zprostředkovatele.","Převzatou peněžní částku musím ještě týž den zaslat na účet obchodníka s cennými papíry nebo investiční společnosti, u níž zákazník hodlá investovat."],"c":[0],"p":231,"e":"Investiční zprostředkovatel ani jeho vázaný zástupce nesmí přijímat peněžní prostředky zákazníků.","k":35},{"id":"21803.2","t":"c","q":"Jaký dokument musíte mít z každého jednání se zákazníkem, aby mohla Česká národní banka prověřit dodržování pravidel jednání se zákazníkem?","o":["Telefonické a e-mailové spojení na zákazníka.","Žádný takový dokument není potřeba.","Záznam komunikace se zákazníkem týkající se poskytnuté investiční služby.","Výpis z účtu zákazníka prokazující, že zákazník má na investici dostatečné peněžní prostředky."],"c":[2],"p":232,"e":"Povinnost prokázat, že byl zákazník informován v souladu se zákonem č. 256/2004 Sb. a že byly splněny další povinnosti týkající se pravidel jednání se zákazníkem, má investiční zprostředkovatel, který odpovídá i za činnost vázaných zástupců.","k":35},{"id":"21805.1","t":"c","q":"Jaká situace představuje střet zájmů ve smyslu zákona o podnikání na kapitálovém trhu?","o":["Případ, kdy neprovedete svůj obchod.","Situace, kdy se zákazníkem projednáte možnost vašeho střetu zájmů.","Situace, kdy dosáhnete stejného zisku jako zákazník.","Případ, kdy dosáhnete zisku nebo předejdete svým ztrátám na úkor zákazníka (např. uzavřete svůj vlastní obchod v době, kdy je to výhodnější a obchod pro klienta zařídíte se zpožděním, kdy v důsledku změny tržní ceny investičního nástroje je obchod již méně výhodný)."],"c":[3],"p":233,"e":"Zákon o podnikání na kapitálovém trhu ukládá zapracovat do vnitřního řídicího a kontrolního systému oblast řízení střetu zájmů, což předpokládá i rozpracování do konkrétních situací.","k":36},{"id":"21806.1","t":"c","q":"V jakém případě nastává střet zájmů u stejného obchodu realizovaného pro zákazníka a pro vás?","o":["V případě, kdy máte zájem na výsledku stejného obchodu jako zákazník, přičemž vaše zájmy se liší.","V případě, kdy byste takový stejný obchod jako zákazník pro sebe neprovedl.","V případě, kdy byste informoval statutární orgán obchodníka s cennými papíry.","Taková situace nemůže nastat."],"c":[0],"p":233,"e":"Zákon o podnikání na kapitálovém trhu ukládá zapracovat do vnitřního řídicího a kontrolního systému oblast řízení střetu zájmů, což předpokládá i rozpracování do konkrétních situací.","k":36},{"id":"21807.1","t":"c","q":"V jakém z následujících případů nenastane střet zájmů?","o":["Pokud neupřednostníte před zákazníkovými zájmy zájmy jiných zákazníků.","Pokud je vaše provize závislá na prodejních cílech obchodníka s cennými papíry.","Pokud obchodník s cennými papíry, pro kterého pracujete, předejde svým ztrátám na úkor zákazníka.","Pokud v budoucnu získáte od třetí strany prospěch nad rámec běžné úplaty za poskytnuté služby."],"c":[0],"p":233,"e":"Zákon o podnikání na kapitálovém trhu ukládá zapracovat do vnitřního řídicího a kontrolního systému oblast řízení střetu zájmů, což předpokládá i rozpracování do konkrétních situací. Jednou ze zásad řízení střetu zájmů je neupřednostnit zájmy některých zákazníků nad zájmy jiných zákazníků.","k":36},{"id":"21808.1","t":"c","q":"Komu byste oznámil zjištění střetu zájmů?","o":["Zpravidla útvaru compliance, popř. statutárnímu orgánu, musí to být stanoveno ve vnitřním předpise a v každém případě zákazníkovi.","V každém případě musím informovat Českou národní banku.","Je třeba ve lhůtě 30 dnů informovat ministerstvo financí.","Střet zájmů nemusím nikomu oznamovat."],"c":[0],"p":233,"e":"V prováděcím právním předpise je stanovena povinnost osoby vykonávající compliance sledovat plnění povinností vyplývajících z řídicího a kontrolního systému, přičemž ten musí zahrnovat i oblast oznamování střetu zájmů.","k":36},{"id":"21809.1","t":"c","q":"Je informování zákazníka dostatečné opatření zamezující střetu zájmů?","o":["Ano, postačuje telefonické informování zákazníka, že vznikl konflikt zájmů.","Ne, zákon o podnikání na kapitálovém trhu takové řešení nepřipouští.","Vázaný zástupce nemá stanoveny žádné povinnosti v oblasti střetu zájmů.","Je to krajní řešení, které zákon o podnikání na kapitálovém trhu připouští, vázaný zástupce by se v souladu s vnitřním předpisem měl snažit zamezit vzniku střetu zájmů."],"c":[3],"p":234,"e":"Informování zákazníka o střetu zájmů lze považovat za řešení pouze v případě, kdy povaha daného střetu zájmů neumožňuje zajistit adekvátní preventivní (zabraňující) opatření, zákon o podnikání na kapitálovém trhu informování zákazníka připouští.","k":36},{"id":"21811.1","t":"c","q":"Zákazník zamýšlí upsat korporátní dluhopisy, k nimž není vyhotoven prospekt, jakým způsobem budete reagovat?","o":["Informuji zákazníka, že jakožto zaměstnanec investičního zprostředkovatele nejsem oprávněn přijímat ani předávat pokyny k dluhopisům, k nimž není prospekt vyhotoven.","Uzavřu se zákazníkem zprostředkovatelskou smlouvu za účelem úpisu dluhopisů.","Informuji zákazníka, že k úpisu korporátních dluhopisů, k nimž není vyhotoven prospekt, musí dát souhlas Česká národní banka.","Odkážu zákazníka na vázaného zástupce zaměstnavatele (investičního zprostředkovatele), který je k podobným úkonům oprávněn."],"c":[0],"p":235,"e":"Investiční zprostředkovatel má omezení u hlavní investiční služby v oblasti dluhopisů na dluhopisy vydané Českou republikou nebo dluhopisy, ke kterým byl vydán prospekt nebo srovnatelný dokument.","k":37},{"id":"21812.1","t":"c","q":"Zákazník je rozhodnut upsat konkrétní nezaknihované korporátní dluhopisy, ke kterým byl vydán (schválen) prospekt. Jaký další krok zákazníkovi doporučíte?","o":["Doporučím k prostudování emisní podmínky.","Doporučím k prostudování zápis z valné hromady emitenta.","Doporučím k prostudování vnitřní řídící a kontrolní systém emitenta.","Doporučím k prostudování stanovy emitenta."],"c":[0],"p":235,"e":"Zákon o dluhopisech definuje emisní podmínky jako dokument, kerý podrobně vymezuje práva a povinnosti emitenta a vlastníků dluhopisů, přičemž mohou i odkazovat na prospekt. Jsou tedy druhým důležitým dokumentem týkajícícm se dluhopisu.","k":37},{"id":"21813.1","t":"c","q":"Poté, co zákazník podepíše smlouvu o úpisu listinných dluhopisů, ke kterým byl vydán (schválen) prospekt, jaký je váš následující krok?","o":["Kontaktuji obchodníka s cennými papíry a předám mu pokyn k uskutečnění transakce.","Kontaktuji emitenta a předám mu pokyn k uskutečnění transakce.","Kontaktuji centrálního depozitáře cenných papírů a předám mu pokyn k uskutečnění transakce.","Kontaktuji osobu, která vede evidenci vlastníků dluhopisů a předám jí pokyn k uskutečnění transakce."],"c":[0],"p":235,"e":"Investiční zprostředkovatel může předávat pokyny pouze subjektům uvedeným v zákoně o podnikání na kapitálovém trhu, z nichž jedním z nich je obchodník s cennými papíry. V zákoně neuvedeným osobám pokyny zákazníka předávat nesmí.","k":37},{"id":"21814.1","t":"c","q":"Zákazník upisuje dluhopisy v celkové jmenovité hodnotě 1 mil. Kč, jde o konzervativního zákazníka, jaký postup zákazníkovi doporučíte z hlediska výnosu (kuponu)?","o":["Doporučím upsání krátkodobého dluhopisu s pevnou úrokovou sazbou (pevným kuponem), neboť zejména u dlouhodobých dluhopisů je kolísání úrokové sazby rizikem.","Úpis dluhopisů mu nedoporučím, protože to není konzervativní investiční nástroj.","Doporučím upsání podřízeného dluhopisu, který nahradí jednotlivé dluhopisy (pokud to emisní podmínky umožňují).","Doporučím mu upsání dlouhodobého dluhopisu, neboť úrokový výnos je u dluhopisu nepodstatný."],"c":[0],"p":235,"e":"Pevná úroková sazba představuje u dluhopisů konkrétní informaci o budoucích výnosech, což konzervativní zákazníci preferují. Výjimka by byla v situaci velmi nízkých úrokových sazeb, kdy by dlouhodobá fixace nebyla výhodná, zejména pokud by úrokový výnos nepokrýval inflaci. I přesto by se jednalo o výhodnější produkt než spořicí účty u bank.","k":37},{"id":"21815.1","t":"c","q":"Zákazník, který má zájem o upsání dluhopisů slyšel, že existují tzv. zero bond, jak byste mu je vysvětlil/a?","o":["Jde o dluhopisy s nulovým kuponem, kde je emisní kurz snížen oproti jmenovité hodnotě.","Jde výlučně o americké dluhopisy.","Tyto dluhopisy mu nedoporučím, protože jsou dražší.","Pro prodej těchto dluhopisů je potřeba speciální souhlas České národní banky, proto jsou pro zákazníka z důvodu zdlouhavého postupu takové dluhopisy nevhodné."],"c":[0],"p":236,"e":"Výnos dluhopisu lze mj. určit jako rozdíl mezi jmenovitou hodnotou dluhopisu a jeho nižším emisním kurzem, \"výnos\" je tedy zákazníkovi vyplacen při odprodeji dluhopisu, který probíhá za jmenovitou hodnotu, přičemž na začátku zákazník dluhopis kupuje s diskontem.","k":37},{"id":"20772.1","t":"c","q":"Informace o výši investice a jeho cíle ohledně inflace a investičního horizontu:","o":["Jsou jedním ze vstupů do testu přiměřenosti.","Jsou jedním ze vstupů do testu vhodnosti.","Jsou jedním ze vstupů do testu výhodnosti.","Nejsou pro investiční rozhodování důležitá."],"c":[1],"p":237,"e":"Spadá pod test vhodnosti, kde je cílem zjistit u zákazníka: 1) znalosti a zkušenosti ve vztahu k produktu, 2) finanční situaci a 3) investčiní cíle. Informace spadá do 2) a 3) kategorie.","k":38},{"id":"20773.1","t":"c","q":"Pan Svoboda před návštěvou poradce dostal nabídku nakupovat zlato jako vhodný spořicí nástroj s ochranou proti inflaci. Zajímá ho, jaké jsou charakteristiky investice do zlata ve srovnání s investováním do fondů akcií vyspělých trhů v dlouhodobém horizontu.","o":["Zlato má vyšší výnosy a více kolísá než akciové fondy.","Zlato má vyšší výnosy a méně kolísá než akciové fondy.","Zlato má nižší výnosy a více kolísá než akciové fondy.","Zlato má nižší výnosy a méně kolísá než akciové fondy."],"c":[2],"p":237,"e":"Zlato má historicky nízké reálné výnosy, ale kolísá podstatně více, než vyspělé akciové trhy. Důvodem pro menší výnosy je, že výnosy závisí jen na poptávce a nabídce. Na rozdíl od firem (akcií) negeneruje zisky.","k":38},{"id":"20774.1","t":"c","q":"Cílem pana Svobody je ochránit prostředky před trvalou ztrátou reálné hodnoty i v období vysoké inflace. Jaká aktiva nejlépe splňují tento cíl?","o":["Akciové fondy.","Fondy státních dluhopisů České republiky.","Stavební spoření.","Spořicí účty."],"c":[0],"p":237,"e":"V případě vysoké inflace jsou vhodným nástrojem akcie, protože růst cen a jevy způsobujicí inflaci tlačí i jejich ceny vzhůru. Naopak dluhové cenné papíry ztrácejí v reálném vyjádření na hodnotě.","k":38},{"id":"20775.1","t":"c","q":"V Jackson Steinem s.r.o. řeknou Svobodovi, že mají licenci obchodníka s cennými papíry, a proto Svobodovi poskytnou nezávislé investiční poradenství. Rada od Jackson Steinem s.r.o. je dle jejich vyjádření navíc zdarma, protože odměnu dostane společnost od distributorů fondů, které panu Svobodovi doporučí. Je takový postup v pořádku?","o":["Je to v pořádku, protože obchodník s cennými papíry může poskytovat nezávislé investiční poradenství","Není to v pořádku, protože obchodník s cennými papíry nemůže přijímat provize ani platby od třetích stran.","Není to v pořádku, protože obchodník s cennými papíry nemůže poskytovat investiční poradenství, ale v tomto případě jen předání pokynu.","Není to v pořádku, protože pokud dostane odměnu od distributora fondu, nemůže poskytovat investiční poradenství nezávisle."],"c":[3],"p":237,"e":"Citace zákona: Informuje-li obchodník s cennými papíry zákazníka o tom, že hlavní investiční službu uvedenou v § 4 odst. 2 písm. e) (investiční poradenství) poskytuje nezávisle nesmí si obchodník s cennými papíry v souvislosti s poskytováním těchto služeb ponechat pobídku ve formě úplaty nebo jiné peněžité výhody ani nesmí přijmout pobídku ve formě nepeněžité výhody; To sice neplatí pro menší nepeněžní pobídku, ale v zadání je, že obchodník bude čerpat provizi - což je v rozporu z nezávislostí a nejde o menší pobídku, protože je to zdroj obživy obchodníka.","k":38},{"id":"20776.1","t":"c","q":"Pan Svoboda mimo jiné investuje do fondu českých státních dluhopisů. Po jednom roce se rozhodne investici vyhodnotit. Vstupní poplatek je 2 % a celková roční nákladovost byla 1,5 %. Z výpisu se dozví, že výnos fondu za rok byl 3,5 %. Inflace byla 2,5 %. Jaká je přibližná výše čistého reálného výnosu?","o":["Reálný výnos pana Svobody je kladný ve výši 1 %. Jde o výnos fondu po odečtení inflace.","Reálný výnos pana Svobody je 0 %. Výnos fondu po odečtení inflace a celkové roční nákladovosti.","Reálný výnos pana Svobody je záporný ve výši (-1 %). Jde o výnos fondu po odečtení vstupních nákladů a po odečtení inflace.","Reálný výnos pana Svobody je záporný ve výši (-2,5 %). Jde o výnos fondu po odečtení vstupních nákladů, celkové roční nákladovosti a po odečtení inflace."],"c":[2],"p":238,"e":"Reálný výnos je -1 %. Od výnosu se odečte náklad fondu a inflace protože jde o reálný výnos. Neodečítá se celková roční nákladovost, protože ta je již započtena ve výnosu fondu.","k":38},{"id":"21959.2","t":"c","q":"Poradce zjistil, že Adam má 5leté zkušenosti s investicemi do českých akcií. Podle investičního dotazníku má dynamický profil. Co by měl poradce doporučit?","o":["Přestože Adam již má zkušenosti s akciemi, doporučí poradce vzhledem k nízkým úrokovým sazbám Adamovi nákup státních dluhopisů s co nejdelším časovým horizontem.","Poradce doporučí Adamovi uzavřít penzijní připojištění se státním příspěvkem, protože u této smlouvy má zaručeno, že v žádném roce jeho majetek nebude znehodnocen.","Poradce doporučí Adamovi investovat do široce diverzifikovaných akciových fondů.","Poradce doporučí Adamovi do několika na sobě nezávislých kryptoměn (např. bitcoinu, erethea, monera), protože tato investice je velmi zisková a riziko diverzifikuje."],"c":[2],"p":239,"e":"Adam je dynamický investor, proto jsou pro něj vhodné dlouhodobé akciové fondy. Investice do českých akcií je příliš riziková (zaměření na velmi úzký trh). Kryptoměny jsou vysoce spekulativní, neměly by tvořit základ pro splnění jejich finanční nezávislosti. Penzijní připojištění již dnes nelze uzavírat, proto jde o špatnou odpověď.","k":39},{"id":"21960.1","t":"c","q":"Adam s Evou mohou na finanční nezávislost odkládat měsíčně 2 000 Kč. Rádi by investovali do akciových otevřených podílových fondů, dosud s nimi ale nemají zkušenosti. Měl by jim poradce doporučit akciové fondy?","o":["Poradce jim v žádném případě akciové fondy nedoporučí, protože nemají odpovídající zkušenosti.","Poradce jim v žádném případě akciové fondy nedoporučí, protože mají krátký investiční horizont.","Poradce jim akciové fondy nedoporučí, protože Eva nemá zkušenosti s akciovými investicemi (byť Adam zkušenosti má).","Poradce jim doporučí investovat do akciových fondů, protože Adam má dynamický profil a mají dostatečně dlouhý investiční horizont."],"c":[3],"p":239,"e":"Nezkušenost s akciovými fondy není překážkou investic do akciových fondů. Adam má zkušenosti s akciemi, mají dostatečně dlouhý investiční horizont a investovanou částku mohou (a chtějí) investovat dlouhodobě.","k":39},{"id":"21961.1","t":"c","q":"Vzhledem ke znalostem Adama a Evy (oba vystudovali VŠ s ekonomickým zaměřením) a požadovanému cíli (finanční nezávislost) jim poradce doporučí:","o":["Globální akciový fond.","Fond evropských akcií.","Fond investující do akcií zemí BRICS.","Fond investující do akcií perspektivních firem v oboru nanotechnologií s vysokým výnosem."],"c":[0],"p":239,"e":"Pro dlouhodobé investice (zde 30 let) je nejvhodnější fond globální. Zaměřit se na část trhu (Evropa, BRICS, nanotechnologie) nevhodně zvyšuje investiční riziko.","k":39},{"id":"21962.1","t":"c","q":"Adam s Evou chtějí předat první investovanou částku 2 000 Kč poradci. Může poradce peníze přijmout?","o":["Poradce peníze může přijmout, protože je vázaným zástupcem investičního zprostředkovatele.","Poradce by peníze mohl přijmout v případě, kdyby měl oprávnění ČNB k činnosti investičního zprostředkovatele.","Peníze může přijímat jen obchodník s cennými papíry, který má oprávnění ČNB přijímat peněžní prostředky.","Peníze může přijímat jen obchodník s cennými papíry, a to vždy."],"c":[2],"p":239,"e":"Peníze může přijímat obchodník s cennými papíry, který má oprávnění ČNB přijímat peněžní prostředky. Vázaný zástupce ani investiční zprostředkovatel toto oprávnění nemá.","k":39},{"id":"21963.2","t":"c","q":"Adama a Evu zajímá, kolik by asi měli pravidelně měsíčně investovat, aby za 30 let měli naspořeny cca 3 mil. Kč v nominální hodnotě, při průměrném zhodnocení investice včetně výnosů 6 % p. a. (použijte složené úročení).","o":["500 Kč.","1 500 Kč.","3 000 Kč.","5 000 Kč."],"c":[2],"p":240,"e":"Pro výpočty dlouhodobých investic je v praxi nutno použít složené úročení (složené úročení anuity, resp. budoucí hodnota anuity). Pro odhad správné odpovědi stačí spočítat vklady za 30 let (včetně jejich zúročení): 1. odpověď: 500 000 Kč, 2. odpověď: přibližně 1,5 mil. Kč, 3. odpověď: přibližně 3 mil. Kč, 4. odpověď: přibližně 5 mil. Kč. Poradce by měl díky své praxi vyloučit špatné odpovědi (1., 2. a 4.). Platí tedy pravidlo, že při pravidelné investici 1000 Kč měsíčně a prům. výnosu 6 % p. a. bude mít po 30 letech klient cca 1 mil. Kč. Pro získání 3 mil. Kč tak musí investovat přibližně 3 tis. Kč.","k":39},{"id":"21705.1","t":"c","q":"Dvořákovi navštíví bankovního poradce a ten jim udělá investiční dotazník. Klienti vyjdou jako vyvážení. Bankovní poradce na základě informací navrhne klientům portfolio skládající se ze zajištěných fondů - fondů, kde je garance výplaty 90-100 % investovaných prostředků. Fondy emituje bankéřova domovská banka a jsou kvůli diverzifikaci navázány na různá podkladová aktiva.","o":["Řešení je správné, protože klienti jsou ve vysokém věku a jsou pro ně vhodné garantované produkty, nehledě na to jak vyjde investiční dotazník.","Řešení je správné, protože garantované produkty jsou vhodné pro klienty s vyváženým profilem a plní stanovený cíl.","Řešení není správné, protože některé z produktů garantují jen 90 % hodnoty a vhodné by bylo aby všechny garantovaly 100 %.","Řešení není správné, protože garantované produkty neplní stanovený cíl."],"c":[3],"p":241,"e":"Řešení není správné. Garantované produkty jsou na úrovni bezpečných dluhopisů. Pro dlouhodobé investování (což je cíl klientů - stále mohou pobírat rentu desítky let) by portfolio mělo obsahovat i jiné strategie (expozici na akciové trhy apod.) To není v rozporu s investičním dotazníkem.","k":40},{"id":"21706.1","t":"c","q":"Další poradce na kterého se obrátí navrhne diverzifikované portfolio skládající se z různých tříd aktiv. Dvořákovy zajímá, jaké riziko může dlouhodobě nejvíce ohrožovat jejich cíl dlouhodobé vyplácení renty.","o":["Tržní riziko.","Riziko inflace.","Měnové riziko.","Úrokové riziko."],"c":[1],"p":241,"e":"V dlouhodobém horizontu znamená největší ohrožení riziko inflace. Tržní riziko v případě dobře diverzifikovaného portfolia způsobuje spíše krátkodobé kolísání. Úrokové riziko a měnové riziko má rovněž krátkodobý vliv.","k":40},{"id":"21707.1","t":"c","q":"Dvořákovi by chtěli z portfolia dostávat dividendy a úroky na pokrytí renty. Jaké produkty mají i distribuční varianty?","o":["Pouze OPF - Otevřené podílové fondy.","pouze ETF - exchange-traded fund.","OPF i ETF.","Ani OPF, ani ETF."],"c":[2],"p":241,"e":"Distribuční varianty mají i OPF i ETF. U obou typů instrumentů jsou tyto třídy dostupné i v ČR.","k":40},{"id":"21708.1","t":"c","q":"Jak je to s daněmi v případě, že Dvořákovi (jako fyzické osoby) budou dostávat dividendy ze zahraničních cenných papírů v portfoliu?","o":["Dividendy jsou od daní osvobozeny.","Dividendy jsou od daní osvobozeny při držení cenného papíru déle než 3 roky a nebo v objemu do 100 tis. Kč.","Dividendy jsou zdaněny srážkovou daní a není je třeba uvádět do daňového přiznání.","Dividendy je třeba uvádět do daňového přiznání."],"c":[3],"p":241,"e":"I přes to, že dojde k zaplacení daně z dividend je povinnost uvádět dividendy ze zahraničních cenných papírů v daňovém přiznání.","k":40},{"id":"21709.1","t":"c","q":"Podobný cíl jako Dvořákovi má i portfolio Nobelovy nadace, která z výnosů portfolia vyplácí odměny pro oceněné vědce. V jakém rozmezí se obvykle pohybuje podíl akciové složky v portfoliu Nobelovy nadace?","o":["0 - 20 %.","20 - 40 %.","40 - 60 %.","60 - 80 %."],"c":[2],"p":242,"e":"Nobelova nadace je praktickou ukázkou dlouhodobého investování portfolia, ze kterého se zároveň čerpají prostředky na odměny spojené s předáváním cen. Nobelova nadace funguje více než 100 let. V počátku v portfoliu akcie neměla což vedlo k významnému propadu odměn. Teprve po zřazení akcií do portfolia se dařilo zvyšovat reálnou hodnotu vyplácených odměn. Nobelova nadace má v portfoliu dlouhodobě 40 - 60 % akcií. Vyznamný podíl akcií je totiž důležitý pro dlouhodobý růst portfolia a jeho odolávání inflaci.","k":40},{"id":"21965.1","t":"c","q":"Tomáš zvažuje investici do dluhopisových fondů a uvědomuje si, že úrokové sazby v ČR i v Evropě budou zřejmě v nejbližší době růst a tím vydělá více.","o":["Poradce nedoporučí Tomášovi investici do dluhopisových fondů, protože růst úrokových sazeb má negativní vliv na kurzy dluhopisových fondů.","Poradce doporučí Tomášovi investici do dluhopisových fondů, protože růst úrokových sazeb má pozitivní vliv na kurzy dluhopisových fondů.","Poradce vysvětlí Tomášovi, že úrokové sazby neovlivňují kurzy dluhopisových fondů, podstatná je výše kuponů dluhopisů, které fond nabývá do svého portfolia.","Poradce doporučí Tomášovi dluhopisový fond investující v Evropě se zajištěním měnového rizika. Tohoto fondu se růst úrokových sazeb nedotkne."],"c":[0],"p":243,"e":"Růst úrokových sazeb má negativní vliv na kurzy podílových listů dluhopisových podílových listů. Proto poradce Tomášovi investici do dluhopisových fondů nedoporučí.","k":41},{"id":"21966.1","t":"c","q":"Tomáš Marný se zeptal poradce na zdaňování dividend podílových fondů.","o":["Dividendy jsou zdaňovány srážkovou daní ve výši 15 %, daň Tomáš nemusí odvádět, odvede ji za něj investiční společnost spravující fond.","Dividendy jsou zdaňovány srážkovou daní ve výši 15 %, dividendu musí Tomáš (nebo jeho zaměstnavatel) zahrnout do svého daňového přiznání a daň odvést.","Dividendy jsou zdaňovány daní z příjmu fyzických osob ve výši 15 %, dividendu musí Tomáš (nebo jeho zaměstnavatel) zahrnout do svého daňového přiznání a daň odvést.","Dividendy jsou zdaňovány jen při držení podílových listů do 3 let, poté již nejsou zdaňovány. Navíc dividendy do výše 100 000 Kč ročně nemusí zdaňovat ani v průběhu prvních 3 let."],"c":[0],"p":243,"e":"Dividendy jsou zdaňovány srážkovou daní 15 % u zdroje, tzn. Tomáš obdrží již dividendu po zdanění a nemusí nic odvádět.","k":41},{"id":"21967.1","t":"c","q":"Pro naspoření vlastních prostředků potřebných pro koupi bytu do 3 let by měl Tomáš investovat do (i vzhledem k očekávanému růstu úrokových sazeb):","o":["Globálního akciového fondu.","Dynamického smíšeného fondu.","Fondu private equity.","Fondu peněžního trhu, spořicí účet či vklad s výpovědní lhůtou."],"c":[3],"p":243,"e":"Pro krátkodobý investiční horizont (Tomáš chce koupit byt nejpozději do 3 let) je nutné investovat velmi konzervativně - z uvedených je nejvhodnější fond peněžního trhu nebo spořicí účet.","k":41},{"id":"21968.1","t":"c","q":"Poradce na žádost Tomáše před uzavřením smlouvy doporučil Tomášovi fond NN (L) International Czech Money Market.","o":["Tomáš by měl poradce poslechnout, jde o fond s dlouhou historií a nadprůměrnou výnosností.","Tomáš by neměl poradce poslechnout, jde o fond s krátkou historií (5 let).","Tomáš by neměl poradce poslechnout, jde o fond se zápornou výnosností za období posledních 10 let.","Poradce nesmí doporučovat koupi konkrétního podílového fondu."],"c":[3],"p":243,"e":"Poradce nesmí poskytovat doporučení ke koupi konkrétního podílového fondu.","k":41},{"id":"21969.1","t":"c","q":"Kolik peněz si je schopen Tomáš za 3 roky naspořit? Je jeho cíl reálný?","o":["Ano, je reálný, stačí investovat 4 000 Kč měsíčně. Za 3 roky si tak naspoří potřebných 20 % vlastních zdrojů.","Ano, je reálný, může investovat cca 10 000 Kč měsíčně. Za 3 roky si tak naspoří potřebných 20 % vlastních zdrojů.","Ano, je reálný za předpokladu, že ušetří dalších 6 000 Kč měsíčně. Musí totiž investovat cca 16 000 Kč, aby za 3 roky měl potřebných 20 % vlastních zdrojů.","Ne, není reálný, musel by investovat alespoň 26 000 Kč, aby za 3 roky měl potřebných 20 % vlastních zdrojů."],"c":[2],"p":244,"e":"Tomáš má příjmy 60 000 Kč, výdaje 50 000 Kč. Může odkládat 10 000 Kč. Za 3 roky si tak naspoří 360 000 Kč. Banka však pravděpodobně bude požadovat 20 % vlastních zdrojů = 600 000 Kč. Pro splnění cíle tak musí Tomáš ušetřit dalších 6 000 Kč měsíčně a odkládat 16 000 Kč.","k":41},{"id":"21971.1","t":"c","q":"Které informace potřebuje poradce od manželů Šetrných dále zjistit?","o":["Žádné informace nepotřebuje zjistit, poradce pouze přijme a předá pokyn k nákupu podílových listů vybraných manželi Šetrnými.","Potřebuje zjistit jen časový horizont (za jak dlouho budou peníze potřebovat).","Potřebuje zjistit časový horizont a jejich zkušenosti, tzn. vyplnit investiční dotazník ve zkráceném rozsahu.","Potřebuje zjistit znalosti, zkušenosti, finanční zázemí a investiční cíle manželů Šetrných."],"c":[3],"p":245,"e":"Protože poradce bude muset doporučit vhodný fond, jedná se o hlavní investiční službu podle § 4 odst. 2, písm. e) Zákona č. 256/2004 Sb., o podnikání na kapitálovém trhu. Poradce je tak povinen (dle § 15h) zjistit znalosti, zkušenosti, finanční zázemí a investiční cíle manželů Šetrných.","k":42},{"id":"21972.3","t":"c","q":"Jaký typ investice poradce pravděpodobně manželům doporučí pro splnění jejich investičních cílů?","o":["Akciový fond zaměřený na frontier markets.","Akciový fond zaměřený na emerging markets.","Široce diverzifikovaný akciový fond.","Konzervativní smíšený fond."],"c":[2],"p":245,"e":"Akciové fondy zaměřené na emerging a frontier markets jsou pro vyvážené investory a pro investiční horizont cca 10 let nevhodné. Konzervativní smíšené fondy jsou vhodné pro střednědobou až dlouhodobou investici v investičním horizontu 3 roky a déle dle míry kolísání hodnoty jejich podílových listů. Nejvhodnějším fondem pro Šetrné je široce diverzifikovaný akciový fond, v němž se obvykle investuje do mnoha akcií, čímž významně snižují riziko poklesu jednotlivého akciového titulu","k":42},{"id":"21973.2","t":"c","q":"Pro vzdělání Mařenky (investiční horizont 16 let) chtějí manželé Šetrní využít méně rizikové akciové fondy. Poradce jim pravděpodobně doporučí:","o":["Globální akciový fond akcií large cap.","Globální akciový fond akcií small cap.","Fond investující do akcií zemí BRIC.","Globální fond investující do akcií perspektivních firem v oboru nanotechnologií s vysokým výnosem."],"c":[0],"p":245,"e":"Pro dlouhodobé investice (18 let) je nejvhodnější fond globální. Zaměřit se na část trhu (malé firmy (small cap), BRIC, nanotechnologie) nevhodně zvyšuje investiční riziko.","k":42},{"id":"21974.2","t":"c","q":"Manželé Šetrní mají ještě listinné akcie z kuponové privatizace, které chtějí prodat na burze. Může tyto akcie poradce přijmout a předat investičnímu zprostředkovateli?","o":["Vázaný zástupce investičního zprostředkovatele může přijímat jak peníze klientů, tak listinné cenné papíry.","Vázaný zástupce investičního zprostředkovatele nesmí přijímat peníze, ale může přijímat listinné cenné papíry.","Listinné cenné papíry může přijímat jen investiční zprostředkovatel, ne jeho vázaný zástupce.","Vázaný zástupce investičního zprostředkovatele, ani investiční zprostředkovatel nesmí přijímat listinné cenné papíry."],"c":[3],"p":245,"e":"Listinné cenné papíry (investiční nástroje) nemůže přijímat ani IZ, ani VZ.","k":42},{"id":"21975.2","t":"c","q":"P/E fondu, který si manželé Šetrní vybrali, je 28. Je tento fond levný nebo drahý?","o":["Fond je velmi levný, čímž dosahuje průměrné výnosnosti 28 %.","Fond je levný (P/E mezi 20 a 30 indikuje, že je fond je účastníky trhu podhodnocený).","Fond je poměrně rizikový s průměrnou volatilitou 28 %, které dosahuje v 68 % případů.","Fond je drahý (P/E nad 20 indikuje, že je fond účastníky trhu nadhodnocený)."],"c":[3],"p":246,"e":"P/E fondu by mělo být mezi 10 a 20. P/E nad 20 znamená, že fond je nadhodnocený.","k":42},{"id":"21699.1","t":"c","q":"Je správné, aby poradce zahrnul do poradenského procesu také pojištění?","o":["Pojištění majetku, osob a doplňkové penzijní spoření poradce s klientem probere, objasní charakteristiky základních produktů a doporučí jako základ pro optimalizaci finanční situace a potenciálních rizik zákazníka.","Pojištění poradce doporučí pouze jako specifickou nadstavbu finančního hospodaření domácnosti a navrhne řešit ji až později (kromě pojištění vyžadovaných zákonem).","Poradce doporučí, že nezávisle na možnostech různé alokace aktiv domácnosti je pro rodinu nejdůležitější uzavřít životní pojištění pro děti nejvíc ohrožené těžkými úrazy, tedy již v předškolním věku.","Poradce o pojištění nediskutuje, protože souvisí jen s různými riziky, nikoliv s optimalizací alokace aktiv."],"c":[0],"p":247,"e":"Jednoznačně. Poradce, pokud poskytuje službu poradenství, by neměl izolovaně řešit pouze investice, ale dívat se na klienta komplexně, kdy je v první řadě především zajištění - tedy eliminace rizik spojených se zraněním či ztrátě na životě živitele/ů, rizika spojená s finančními důsledky spojené s majetkem, tedy pojištění movitého a nemovitého majetku proti vhodným rizikům se správně nastavenými pojistnými částkami.","k":43},{"id":"21700.1","t":"c","q":"Je účelné zahrnout do poradenského procesu také využívání bankovních produktů?","o":["Poradce musí zvážit případné zadlužení klienta (prioritně řešit možné problémy se splácením) a může doporučit vkladové produkty se státním příspěvkem. Připomene existenci pojištění vkladů.","Poradenství se v tomto případě týká podnikání na kapitálovém trhu a k tomu nemají bankovní produkty jako úvěry a vklady žádný vztah.","Žádný z produktů na finančních trzích není pojištěný a investování slibuje vyšší výnosy než vkladové produkty. Vkladové produkty bank jsou tedy pro klienta nezajímavé.","Klient, který hodlá uskutečnit první investice si může vzít v bance půjčku, aby jeho investice byla větší a výnos z růstu ceny akcie zajímavější. Úlohou poradce je klienta podpořit a poradit mu vhodnou formulaci žádosti o úvěr."],"c":[0],"p":247,"e":"Poradce by se měl při analýze stávajícího portfolia věnovat i např. příp. zadlužení klienta, resp. doporučit vhodnou alokaci zdrojů, kterou klient disponuje na běžném účtu, který slouží k běžným transakcím. Na základě diskuze s klientem, by poradce mohl zmínit spořicí účty, které mají veškeré výhody běžných účtů, ovšem s vyšším výnosem, příp. se zaměřit na \"bankovní\" produkty, kde je možné získat určitou státní podporu - např. účelová spoření typu stavebního spoření. Opět je vhodné vzhledem k diverzifikaci, postupovat tak, aby se poradce zajímal především o vhodné zajištění (likvidní rezerva + nastavení pojistných částek), část vkladů na spořicí účet, část např. na \"konzervativní\" důchodový produkt, část přebytečného cash flow potom dle rizikového profilu klienta je potom možné investovat do podílových fondů či přímou investicí do cenných papírů.","k":43},{"id":"21701.1","t":"c","q":"Jak mohou v procesu optimalizace alokace aktiv figurovat otevřené podílové fondy?","o":["Poradce v diskusi s klientem uvede, že podílové fondy mohou být z pohledu likvidity chápány jako produkty konkurenční k bankovním vkladům. Nejsou pojištěné, a to je jejich nevýhoda, výhodou ale je zpravidla vyšší výnos.","Poradce zdůrazní nevýhody otevřených podílových fondů, mimo jiné výši poplatků za nákup, poplatek za management a případně i poplatek výstupní. Doporučí produkty sice rizikovější, ale s potenciálně vyšší návratností.","Poradce otevřené podílové fondy nedoporučí, protože neexistují žádné veřejně dostupné informace o jejich investiční strategii, chybí jejich kontrola a dohled nad jejich podnikáním.","Poradce diskutuje s klientem o tom, že manažeři fondů vedou na investičním účtu dohromady prostředky všech klientů spolu s prostředky fondu. Takový způsob účetnictví je rizikový, a proto není vhodné do otevřených podílových fondů investovat."],"c":[0],"p":247,"e":"Podílové fondy, zejména otevřené podílové fondy mohou být základním kamenem klientova portfolia, kdy správu zajišťuje investiční společnost, resp. portfolio manažer, klient si tak pouze dle svého rizikového profilu zvolí vhodný typ fondu (od garantovaného, přes fondy dluhopisový, akciový či komoditní) a zainvestuje. Klient navíc ušetří peníze a čas, kdy nemusí denně sledovat dění na trhu a upravovat složení portfolia.","k":43},{"id":"21702.1","t":"c","q":"Jak může při poskytování služby přijímání a předávání pokynů prospět k efektivní alokaci aktiv klienta v procesu nákupu akcií, investičních certifikátů nebo derivátů na trhu?","o":["Poradce diskutuje s klientem o rizicích a potenciálních výnosech jednotlivých produktů. Doporučovat konkrétní nákupy nesmí, ale téma počtu aktiv v portfoliu a optimalizace jejich podílu na majetku klienta jsou důležitým tématem poradenství.","Poradce s nadšením prezentuje klientovi výhody různých skupin investičních nástrojů. Porovnání s ostatními variantami alokace aktiv vyznívá jednoznačně pro akcie a hlavně pro deriváty. Poradce s klientem neřeší volatilitu cen produktů a související riziko ztrát.","Poradce nadiktuje klientovi názvy a identifikaci několika akciových titulů, které se v následujících dvanácti měsících určitě zhodnotí.","Poradce převezme od klienta hotovost s tím, že bude jeho jménem a na jeho účet ivestovat optimálně podle teorie H. Markowitze."],"c":[0],"p":248,"e":"Důležité jsou vždy výsledky \"investičního dotazníku\", kdy poradce mimo jiné získává informace o klientových znalostech a zkušenostech z oblasti fungování trhu a investic. V tomto ohledu je důležité věnovat se oblasti diverzifikace (napříč kontinenty, měnami, obory). Je zbytečné mít v portfoliu akcie z určitého odvětví a certifikát či derivát navázaný na obdobná podkladová aktiva. V případě derivátů a certifikátů je nutné upozornit klienta na možný pákový efekt, kdy dochází k násobení ztrát a zisků.","k":43},{"id":"21703.1","t":"c","q":"Je pro klienta - investora výhodnější často a aktivně upravovat složení portfolia, nebo by bylo výhodnější držet jednou vybrané portfolio dlouhodobě a provádět jen minimální korekce jeho složení?","o":["Celkové náklady klienta na nákup investičních nástrojů do portfolia jsou výrazně větší, než jejich nákupní cena. Podle statistik aktivní správa portfolia negeneruje ani u fondů dlouhodobě vyšší výnos než tržní portfolio. Proto je výhodnější obchodovat jen minimálně, provádět pouze drobné korekce ve složení portfolia.","Volatilita cen investičních nástrojů, především akcií, je na burzách relativně velká. Pokud investor nevyužije všechny nákupní a prodejní příležitosti (nejlépe při intradenním obchodování), potom se připravuje o významné zhodnocení svých aktiv.","Pokud investor nechce nebo nemůže aktivně spravovat své portfolio, potom je zbytečné, aby investoval na kapitálovém trhu. Vkladové bankovní produkty jsou pro něho vhodnější.","Nejlepší strategie je aktivní obchodování. Realizuje se v současnosti ve formě vysokofrekvenčního obchodování. Lze uplatnit nejen na trzích futures a Forex. Rozšiřuje se také na akciových trzích."],"c":[0],"p":248,"e":"Zda je výhodnější aktivní či pasivní správa portfolia je nekonečná otázka nejen akademiků, ale i obchodníků z praxe. Aktivní správa může přinášet vyšší zhodnocení, nicméně je nákladnější, kdy po odpočtu nákladů a poplatků třetím stranám je výkon aktivní a pasivní strategie srovnatelný. Nicméně v dobách velkých propadů trhu či nárůstů, vykazuje aktivní strategie nižší ztráty, resp. vyšší výnosy než strategie pasivní. Na dlouhodobém investičním horizontu, tzn. 5 a více let se jako vhodná jeví spíše pasivní strategie.","k":43},{"id":"20831.1","t":"c","q":"Poradce z nedávno vyplněného investičního dotazníku ví, že klienti jsou konzervativního zaměření a zvažovaná investice by představovala významnou část jejich úspor.","o":["Zvažovaná investice je pro klienty spíše nevhodná, klienti by měli investovat raději do státních dluhopisů.","Zvažovaná investice je pro klienty spíše vhodná.","Zvažovaná investice je pro klienty spíše nevhodná, klienti by měli investovat raději do akcií.","Zvažovaná investice je pro klienty spíše nevhodná, klienti by měli investovat raději do derivátových nástrojů."],"c":[0],"p":249,"e":"Korporátní dluhopisy emitované firmami s neprůkaznou podnikatelskou historií představují velmi rizikovou investici.","k":44},{"id":"21856.1","t":"c","q":"Klienti se v diskuzi obrátili na poradce s dotazem, zda by ekonomickou věrohodnost emitenta zvýšilo, pokud by dluhopis byl vybaven prospektem schváleným ČNB.","o":["Ne, vydání prospektu znamená, že emitent pouze splnil formální náležitosti požadované zákonem o dluhopisech.","Ano, vydání prospektu znamená, že ČNB poskytuje garanci na výplatu úroků v případě insolvence emitenta.","Ano, vydání prospektu znamená, že ČNB dohlíží podnikání emitenta.","Ano, vydání prospektu znamená, že ČNB pozitivně hodnotí podnikatelský plán emitenta."],"c":[0],"p":249,"e":"ČNB prospekt vydá za předpokladu, že emitent splní náležitosti stanovené zákonem.","k":44},{"id":"21857.1","t":"c","q":"Pokud by pan Novák vystudoval VŠ zaměřenou na finance a pracoval v bance na pozici portfolio manažera, znamenalo by to bez dalšího:","o":["Že díky jeho znalostem a zkušenostem jsou pro něho přiměřené i složitější a rizikovější investiční nástroje.","Že je automaticky tzv. profesionálním zákazníkem.","Že mu nemůže být poskytnuto investiční poradenství","Že jeho investiční profil je automaticky dynamický."],"c":[0],"p":249,"e":"Vyšší úroveň znalostí a zkušeností znamená, že pro daného klienta jsou přiměřené i složitější a rizikovější investiční nástroje.","k":44},{"id":"21858.1","t":"c","q":"Novákovi při své další návštěvě zadali poradci ke zpracování pokyn pro nákup podílových listů investičního fondu. Aby jej poradce a jeho nadřízený investiční zprostředkovatel zpracovali bez zbytečného průtahu, musí jej za normálních okolností:","o":["Předat obchodníkovi s cennými papíry bez zbytečných průtahů, nejpozději však do 2 dnů.","Předat obchodníkovi s cennými papíry nejpozději do 2 hodin.","Předat obchodníkovi s cennými papíry nejpozději do 2 týdnů.","Předat obchodníkovi s cennými papíry nejpozději do 2 měsíců."],"c":[0],"p":249,"e":"Za nejzazší dobu, kdy by měl IZ předat pokyn OCP, lze za normálních okolností považovat dva dny.","k":44},{"id":"21859.1","t":"c","q":"Při své poslední návštěvě seznámili Novákovi poradce s dalším korporátním dluhopisem, do kterého zamýšlejí investovat. Pan Novák přitom na internetu zjistil, že původní dluhopis (A) má duraci ve výši 5,1, nový dluhopis (B) ve výši 3,7.","o":["Průměrná doba návratnosti dluhopisu A je delší než dluhopisu B; cena dluhopisu A je více citlivá na změnu úrokových sazeb.","Průměrná doba návratnosti dluhopisu A je delší než dluhopisu B; cena dluhopisu B je více citlivá na změnu úrokových sazeb.","Průměrná doba návratnosti dluhopisu B je delší než dluhopisu A; cena dluhopisu A je více citlivá na změnu úrokových sazeb.","Průměrná doba návratnosti dluhopisu B je delší než dluhopisu A; cena dluhopisu B je více citlivá na změnu úrokových sazeb."],"c":[0],"p":250,"e":"Durace je průměrná doba splatnosti (návratnosti) dluhopisu a zároveň jeho citlivost na změnu úrokových sazeb, v obou případech přímo úměrná.","k":44},{"id":"20814.1","t":"c","q":"Z investičního dotazníku vyplynulo, že pan Smetana má vysokou averzi k riziku, investované prostředky představují významnou část jeho majetku a jeho celkový investiční horizont je krátký.","o":["Stávající produkty jsou pro pana Smetanu spíše nevhodné.","Stávající produkty jsou pro pana Smetanu spíše vhodné.","Poradce nemůže posuzovat investiční cíle, toleranci k riziku a finanční zázemí klienta.","Stávající investice je pro klienta spíše nevhodná, měl by investovat raději do derivátových nástrojů se zabudovanou finanční pákou."],"c":[0],"p":251,"e":"Parametry dosavadní investice (akciového fondu) s vysokou pravděpodobností neodpovídají inv. cílům, toleranci k riziku a finančnímu zázemí (podílu na majetku) klienta.","k":45},{"id":"20815.2","t":"c","q":"Z dotazníku dále vyplynulo, že pan Smetana potřebuje peníze z fondů vybrat do jednoho roku, jeho horizont je tudíž velmi krátký. Jaké investiční nástroje pravděpodobně poradce doporučí?","o":["Fondy peněžního trhu jsou pro klienta vhodnou volbou.","Akciové fondy bez předplaceného vstupního poplatku jsou pro klienta vhodnou volbou.","Nástroje životního cyklu jsou pro klienta vhodnou volbou.","Stávající akciové fondy s předplaceným vstupním poplatkem jsou pro klienta vhodnou volbou."],"c":[0],"p":251,"e":"Fondy peněžního trhu obvykle vykazují nejnižší míru rizika a jsou tak vhodné pro krátký investiční horizont.","k":45},{"id":"20816.2","t":"c","q":"Poradce uvažuje, že by panu Smetanovi doporučil portfolio realokovat, tj. ukončit stávající investice a sjednat vhodnější produkty.","o":["Předplacené poplatky by v takovém případě zpravidla snížily hodnotu zůstatku investice, poradce tudíž musí do úvahy zahrnout i tyto náklady.","Předplacené poplatky by klientovi v takovém případě byly zpravidla refundovány a zůstatek tak neovlivní.","Předplacené poplatky vůbec neovlivňují hodnotu klientovy investice.","Předplacené poplatky jsou klientovi odečítány průběžně po celou dobu trvání investice, nikoliv kumulovaně na počátku (up- front)."],"c":[0],"p":251,"e":"Předplacené poplatky jsou odečítány kumulativně na počátku investice, tudíž při předčasném ukončení výrazně snižují její hodnotu.","k":45},{"id":"20817.2","t":"c","q":"Poradce dále zjistil, že pan Smetana drží stávající portfolio teprve 11 měsíců, přičemž toto má hodnotu 400 000 Kč.","o":["Při předčasném odprodeji investic by panu Smetanovi vznikla daňová povinnost.","Délka, po kterou pan Smetana drží portfolio dané hodnoty, nemá na jeho daňovou povinnost vliv.","Panu Smetanovi by daňová povinnost vznikla při odprodeji investic vždy.","Při předčasném odprodeji investic by panu Smetanovi vznikla daňová povinnost, pokud by však investice držel déle než 12 měsíců, tato povinnost by nevznikla."],"c":[0],"p":251,"e":"Zákazník musí cenné papíry vlastnit min. 3 roky, v opačném případě z jejich prodeje bude hradit daň z příjmů (pro drobné investory platí roční limit 100 000 Kč).","k":45},{"id":"20818.2","t":"c","q":"Pan Smetana při další schůzce informoval poradce, že pojal úmysl investovat do investičních certifikátů (derivátových produktů).","o":["Taková investice je nepřiměřená klientovým znalostem a zkušenostem. Jedná-li poradce jménem a na účet investičního zprostředkovatele, nemůže k derivátovým produktům poskytovat služby.","Taková investice je nepřiměřená klientovým znalostem a zkušenostem. Jedná-li poradce jménem a na účet investičního zprostředkovatele, může k derivátovým produktům poskytovat služby.","Taková investice je přiměřená klientovým znalostem a zkušenostem. Jedná-li poradce jménem a na účet investičního zprostředkovatele, nemůže k derivátovým produktům poskytovat služby.","Taková investice je přiměřená klientovým znalostem a zkušenostem. Jedná-li poradce jménem a na účet investičního zprostředkovatele, může k derivátovým produktům poskytovat služby."],"c":[0],"p":252,"e":"Derivátové produkty jsou z podstaty určeny pouze pro klienty s vysokou úrovní znalostí a zkušeností, investiční zprostředkovatelé nejsou oprávněni k nim poskytovat služby.","k":45},{"id":"20820.1","t":"c","q":"Distributor je povinen o klientovi zjistit a vyhodnotit následující údaje:","o":["Znalosti a zkušenosti klienta.","Investiční cíle klienta.","Klientova tolerance k riziku.","Finanční zázemí klienta."],"c":[0],"p":253,"e":"Služba přijímání a předávání pokynu je spojena pouze s tzv. testem přiměřenosti (znalostí a zkušeností klienta).","k":46},{"id":"20821.1","t":"c","q":"Klient se na distributora obrátí s žádostí o doporučení konkrétního produktu (nástroje).","o":["Distributor nemůže poskytnout individuální doporučení.","Distributor může poskytnout individuální doporučení bez omezení.","Distributor může poskytnout individuální doporučení, ale pouze do dluhopisových nástrojů.","Distributor může poskytnout individuální doporučení, ale pouze do nástrojů vydaných podle českého práva."],"c":[0],"p":253,"e":"Při službě přijímání a předávání pokynu nemůže být poskytnuto individualizované doporučení, to je vyhrazeno službě investičního poradenství.","k":46},{"id":"20822.2","t":"c","q":"Klient požaduje provedení obchodu, který je dle názoru distributora pro něho nepřiměřený.","o":["Distributor musí na tuto skutečnost klienta výslovně upozornit. Pokud však klient na provedení obchodu stále trvá, musí jej distributor provést.","Distributor musí odmítnout provést obchod.","Distributor musí trvat na svém a obchod neprovést.","Ani jedna z uvedených odpovědí není správná."],"c":[0],"p":253,"e":"Není-li obchod pro zákazníka přiměřený, musí jej distributor na tuto skutečnost výslovně upozornit.","k":46},{"id":"20823.2","t":"c","q":"Distributor zvažuje zařadit do své nabídky fondy kvalifikovaných investorů. Tyto nástroje jsou z podstaty:","o":["Nepřiměřené pro zákazníky s minimálními znalostmi a zkušenostmi s kapitálovým trhem.","Přiměřené pro zákazníky s minimálními znalostmi a zkušenostmi s kapitálovým trhem.","Přiměřené pouze pro zákazníky s vysokoškolským vzděláním.","Přiměřené pouze pro zákazníky právnické osoby."],"c":[0],"p":253,"e":"Fondy kvalifikovaných investorů jsou z podstaty vhodné pouze pro kvalifikované investory, s dostatečnou zkušeností pro posouzení souvisejících rizik, s ohledem na nižší úroveň dohledu ČNB.","k":46},{"id":"20824.2","t":"c","q":"Klient požádal distributora o informaci stran nákladů zvažované investice. Distributor nahlédl do produktových dokumentů a nalezl řadu indikátorů. Nákladovost (poplatky) produktu z nich vyjadřuje:","o":["TER ukazatel.","Volatilita.","Sharpe ratio.","SRRI ukazatel."],"c":[0],"p":254,"e":"Ukazatel TER (Total Expense Ratio) vyjadřuje poměr celkových nákladů produktu.","k":46},{"id":"21862.2","t":"c","q":"Je s ohledem na investiční horizont klientů konzervativní fond DPS vhodnou investicí?","o":["Ano.","Nikoliv, klienti by měli minimálně část svých investic směřovat do dynamičtějších aktiv, která ji lépe zhodnotí.","Ano, ale pouze jde-li o konzervativní fond státních dluhopisů.","Nikoliv, klienti by měli DPS zcela zrušit a peníze vložit do produktu s nulovým investičním rizikem, např. na běžný účet."],"c":[1],"p":255,"e":"Vzhledem k dlouhému investičnímu horizontu (30 let) by klienti měli investovat do fondu s vyšším podílem dynamických aktiv, a tudíž vyšším potenciálním výnosem.","k":47},{"id":"21863.1","t":"c","q":"Klienti se v diskuzi s poradcem dotázali na minulé kolísání hodnoty podílového listu dynamického investičního fondu, který jim poradce předestřel jako alternativu pro dodatečnou investici.","o":["Kolísání hodnoty vyjadřuje tzv. volatilita, přičemž čím vyšší má hodnotu, tím vyšší kolísavost.","Kolísání hodnoty vyjadřuje tzv. volatilita, přičemž ččím vyšší má hodnotu, tím nižší kolísavost.","Kolísání hodnoty vyjadřuje tzv. TER ukazatel, přičemž čím vyšší má hodnotu, tím vyšší kolísavost.","Kolísání hodnoty vyjadřuje tzv. TER ukazatel, přičemž čím vyšší má hodnotu, tím nižší kolísavost."],"c":[0],"p":255,"e":"Kolísání hodnoty vyjadřuje tzv. volatilita, nejčastěji ve formě směrodatné odchylky.","k":47},{"id":"21864.1","t":"c","q":"Klienti v další diskuzi poradci sdělili, že zřejmě budou chtít část prostředků z dodatečné investice vybrat již za několik let, s cílem odjet na zahraniční dovolenou.","o":["Tento fakt by měl poradce promítnout do spíše konzervativního doporučení, aby minimalizoval riziko propadu hodnoty investice před event. výběrem.","Tento fakt by měl poradce ignorovat a klientům sdělit, že zahraniční dovolenou si nemohou dovolit.","Tento fakt by měl poradce promítnout do více dynamického doporučení, aby klienti na kratším horizontu dosáhli na vyšší potenciální zhodnocení.","Poradce v takovém případě vůbec nesmí klientům poskytnout investiční službu."],"c":[0],"p":255,"e":"Relativně krátký investiční horizont, odpovídající pravděpodobnému ukončení investice v řádu několika let, musí poradce promítnout do spíše konzervativního doporučení.","k":47},{"id":"21865.1","t":"c","q":"Investiční zprostředkovatel, jehož poradce zastupuje, realizuje i službu přijímání a předávání pokynu. Může v obecné rovině manželům Procházkovým zprostředkovat i nákup investičních nástrojů?","o":["Ano, ale pouze investičních fondů, fondů kvalifikovaných investorů a dluhopisů s prospektem.","Ano, všech investičních nástrojů bez omezení.","Ano, ale pouze akcií, investičních fondů a dluhopisů s prospektem.","Ne, klienti mohou nástroje nakoupit pouze přímo u obchodníka s cennými papíry / banky."],"c":[0],"p":255,"e":"Investiční zprostředkovatel může poskytovat služby (vč. přijímání a předávání pokynů k nákupu CP) pouze k investičním fondům, fondům kvalifikovaných investorů a dluhopisům s prospektem či obdobným dokumentem.","k":47},{"id":"21866.1","t":"c","q":"Fond, který poradce nakonec klientům pro dodatečnou investici doporučil, vykazuje hodnotu SRRI ve výši 2.","o":["Jde o produkt s nízkým rizikem.","Jde o produkt se středním rizikem.","Jde o produkt s vysokým rizikem.","Tento ukazatel vůbec nevyjadřuje míru rizikovosti fondu."],"c":[0],"p":256,"e":"Ukazatel SSRI (Synthetic Risk and Reward Indicator) vyjadřuje míru rizikovosti fondu, přičemž hodnota 2 představuje druhou nejnižší rizikovost na typizované škále.","k":47},{"id":"22461.1","t":"c","q":"Poradce se sešel s klientem a získal od něj informace uvedené v zadání. Na základě toho mu doporučil pravidelně investovat část volných prostředků (cca 5 000 Kč/měsíc) do nemovitostního podílového fondu s předpokládaným očekávaným zhodnocením cca 7 % p.a.. Poradce s klientem nevyplnil inv. dotazník. Postupoval poradce v souladu se zákonem?","o":["Ne, jelikož poradce opomněl získat informace o odborných znalostech klienta v oblasti investic a o jeho investičních cílech.","Ne, investiční dotazník nemusí být vyplněn, ale klient musí být upozorněn na rizika související s nevyplněním investičního dotazníku.","Ano, vyplnění investičního dotazníku není zákonný požadavek a poradce měl dostatek informací k určení investičního profilu a vhodné investiční strategie.","Ano, poradce nemá povinnost vyplnit investiční dotazník, ale doporučit vhodný investiční produkt, což bylo vzhledem k pokročilým zkušenostem klienta zcela zjevně splněno."],"c":[0],"p":257,"e":"Osoba jednající se zákazníky a poskytující inv. službu inv. poradenství týkající se inv. nástrojů má povinnost získat od zákazníka informace o jeho odborných znalostech a zkušenostech v oblasti investic, finančním zázemí a investičních cílech. Druhá odpověď není správně, protože sice poradce skutečně nepostupoval správně, nicméně nikoliv z důvodu, že by neupozornil klienta na rizika, ale z toho důvodu, že nezjistil znalosti klienta v případě, že poskytuje hlavní investiční službu investiční poradenství, nemůže službu poskytnout bez těchto informací.","k":48},{"id":"22462.2","t":"c","q":"Klient se po půl roce sešel opět s poradcem a pochlubil se mu, že má novou přítelkyni. Současně si ale postěžoval, že bývá na konci měsíce stále častěji v mínusu a minulý měsíc si musel dokonce půjčit 60 000 Kč, aby zvýšené nároky pokryl. Požaduje, aby mu poradce sjednal (v předchozí otázce) doporučenou investici, aby alespoň něco \"neutratil\". Poradce:","o":["Nesmí uvedenou investici sjednat, protože klientovi nezbývá dostatek prostředků na úhradu nákladů a sjednání pravidelné investice by náklady ještě více zvýšilo a bylo by to tak v rozporu s povinností poradce jednat s odbornou péčí.","Musí nejdříve vyplnit s klientem investiční dotazník, aby mohl posoudit přiměřenost investice.","Ano, vyplnění investičního dotazníku není zákonný požadavek a poradce měl dostatek informací k určení investičního profilu a vhodné investiční strategie.","Ano, poradce nemá povinnost vyplnit investiční dotazník, ale doporučit vhodný investiční produkt, což bylo vzhledem k pokročilým zkušenostem klienta zcela zjevně splněno."],"c":[0],"p":257,"e":"Osoba jednající se zákazníky by nejednala s odbornou péčí a v nejlepším zájmu klienta, kdyby sjednala investici v rozporu s výsledkem posouzení finančního zázemí klienta, tedy v případě, kdy klientovi nezbývají žádné volné prostředky na realizaci investice. Taková investice by pro klienta nebyla vhodná. Doporučení by naopak mělo směřovat k co nejrychlejšímu splacení stávajícího úvěru.","k":48},{"id":"22463.3","t":"c","q":"Poradce postupem uvedeným v předchozích otázkách doporučil výše uvedený nemovitostní fond. Klient se tímto doporučením řídil. Doporučený nemovitostní fond však nevydělával předpokládaných 7 % p.a., ale i po 3 letech byl ve ztrátě - 5 % p.a. Nárok na náhradu škody:","o":["By měl klient uplatnit po obchodníkovi s cennými papíry, pro kterého vázaný zástupce, jehož je poradce zaměstnancem, vykonává činnost.","By měl klient uplatnit po vázaném zástupci, pro kterého poradce vykonává jako zaměstnanec činnost.","By měl klient uplatnit po poradci, který příslušnou investici sjednal.","Ano, poradce nemá povinnost vyplnit investiční dotazník, ale doporučit vhodný investiční produkt, což bylo vzhledem k pokročilým zkušenostem klienta zcela zjevně splněno."],"c":[0],"p":257,"e":"Poradce resp. obchodník s cennými papíry, jehož jménem a na jehož účet poradce jedná, porušil povinnost tím, že nezjistil znalosti klienta a doporučil mu přesto investiční nástroj. Škodu, která realizací nákupu nástroje klientovi vznikla v důsledku porušení povinnosti poradce, může klient nárokovat. Vyplývá z obecné právní úpravy zastoupení (Kdo při své činnosti použije zmocněnce, zaměstnance nebo jiného pomocníka, nahradí škodu jím způsobenou stejně, jako by ji způsobil sám.) Pakliže obchodníka s cennými papíry zastupuje vázaný zástupce, který vykonává činnost prostřednictvím zaměstnance, odpovídá za výkon činnosti stále obchodník s cennými papíry.","k":48},{"id":"22464.2","t":"c","q":"Klient s poradcem diskutoval také možnost pokusit se vydělat si chybějící peníze rychle pomocí obchodu s akciovými opcemi, o kterém si přečetl na jistém diskuzním fóru. Poradce ho však varoval, že při tomto obchodu by mohl nést riziko neomezené ztráty. O jaký obchod šlo?","o":["Prodej call opce.","Nákup call opce.","Nákup put opce.","Prodej put opce."],"c":[0],"p":258,"e":"Short call je jediná ze čtyř základních opčních pozic, kde je možnost neomezené ztráty při růstu podkladového aktiva, protože cena může růst do \"nekonečna\".","k":48},{"id":"22465.3","t":"c","q":"Klient je krátkodobě ve finanční nouzi a přemýšlí, jakým způsobem by zvýšil svůj příjem. Zvažoval, že se pokusí vydělat peníze krátkodobým nákupem akcií na úvěr. Poradce ho varoval následujícím příkladem. Vlastní prostředky 100 tisíc Kč, nákup 50 tisíc ks akcií ABC a.s. po 20 Kč. Prodej za 19 Kč/akcii. Výnos klientova investovaného kapitálu by při zanedbání úroků z úvěru byl:","o":["-50 %.","-5 %.","+5 %.","+50 %."],"c":[0],"p":258,"e":"Finanční páka je 10, pohyb 5 % znamená ztrátu 50 %. Alternativně stačí vyjádřit klientům čistý majetek na konci: akcie za 950 tisíc Kč mínus splacení úvěru 900 tisíc.","k":48},{"id":"22473.1","t":"c","q":"Který parametr není pro sestavení investičního doporučení poradce významný?","o":["Původ prostředků.","Podíl prostředků na celkovém majetku.","Investiční horizont.","Tolerance k riziku."],"c":[0],"p":259,"e":"Při poskytování inv. poradenství poradce hodnotí jak finanční zázemí klienta, tak investiční cíle a toleranci k riziku. Původ prostředků (z hlediska např. AML) nikoliv.","k":49},{"id":"22474.1","t":"c","q":"Klient se u jedné ze zvažovaných investic poradce dotázal, co znamená tzv. riziko defaultu emitenta.","o":["Riziko bankrotu emitenta a tím neschopnosti dostát svým závazkům.","Riziko poruchy informačního systému emitenta a tím přechodné neschopnosti informovat o stavu investice.","Měnové riziko, kdy pohyb měnových kurzů může ovlivnit hodnotu investice.","Legislativní riziko, které značí možnost udělení pokuty Českou národní bankou."],"c":[0],"p":259,"e":"Riziko defaultu představuje riziko bankrotu emitenta, a tudíž jeho neschopnosti dostát svým závazkům.","k":49},{"id":"22475.1","t":"c","q":"Poradce zjistil, že investované prostředky představují významnou část klientova majetku a že tento je plánuje investovat pouze na horizontu dvou let.","o":["Vhodným nástrojem jsou v takovém případě konzervativní fondy, např. dluhopisové.","Vhodným nástrojem jsou v takovém případě dynamické fondy, např. akciové.","Vhodným nástrojem je v takovém případě fond kvalifikovaných investorů, investující do uměleckých děl.","Vhodným nástrojem jsou v takovém případě korporátní dluhopisy, bez prospektu schváleného ČNB."],"c":[0],"p":259,"e":"Krátký investiční horizont a významnou váhu investovaných peněz v majetku klienta musí poradce promítnout do spíše konzervativního doporučení.","k":49},{"id":"22476.1","t":"c","q":"Může poradce zprostředkovat (přijmout a předat pokyn) nákup akcií na burze, pokud by jej klient požadoval?","o":["Nemůže, zákon mu to neumožňuje.","Může, ale pouze bez poskytnutí investičního poradenství.","Může, ale pouze přes obchodníka s cennými papíry.","Může, ale pouze přes investiční společnost."],"c":[0],"p":259,"e":"Poskytování investičních služeb ve vztahu k akciím zákon inv. zprostředkovatelům nepovoluje.","k":49},{"id":"22477.1","t":"c","q":"Klient pro doporučenou investici požaduje sdělit tzv. ISIN zvoleného fondu. Jedná se o:","o":["Identifikační kód fondu.","Indikátor kolísavosti (volatility) fondu.","Indikátor nákladovosti fondu.","Identifikátor administrátora fondu."],"c":[0],"p":260,"e":"ISIN (International Securities Identification Number) je jedinečné mezinárodní identifikační číslo cenného papíru.","k":49}],"cases":[{"id":"20375.1","text":"Na pracovníka obchodníka s cennými papíry se obrátí nový zákazník, který má zájem investovat volné finanční prostředky. Tento nový zákazník má zájem jak o investiční poradenství, tak i o samotné zprostředkování nabytí investičních nástrojů. Preferuje investice do veřejně obchodovaných akcií.","qs":[741,742,743,744,745]},{"id":"20381.2","text":"Na investičního zprostředkovatele se obrátí starší manželský pár, kterému investiční zprostředkovatel v minulosti zprostředkoval investici do listinných dluhopisů vydaných developerskou společností ABC, a.s. Manželé nyní dostali dopis, v němž jim emitent nabízí možnost zpětného odkoupení těchto dluhopisů. Manželé mají o odkup zájem a volné finanční prostředky by využili na rekonstrukci domku. Chtějí tedy, aby jim investiční zprostředkovatel pomohl zpětný odkup vyřídit.","qs":[746,747,748,749,750]},{"id":"20387.5","text":"Investičního zprostředkovatele osloví nový zákazník, který má zájem investovat část svých úspor.","qs":[751,752,753,754,755]},{"id":"20393.1","text":"Na investičního zprostředkovatele se obrátí mladý manželský pár, který má zájem o pravidelné investice menší části jejich měsíčních příjmů pocházejících ze zaměstnaneckých poměrů. Odpovězte na následující otázky.","qs":[756,757,758,759,760]},{"id":"20501.3","text":"Šedesátiletý pan Sýkora se obrátil na investičního poradce, který je vázaným zástupce investičního zprostředkovatele a poskytuje službu investičního poradenství, o posouzení svého záměru investovat na dobu cca 10 let jeden milion Kč do amerických akcií. Pan Sýkora se stal nedávno vdovcem a tyto peníze našetřili společně se svou ženou na přilepšení, až budou v důchodu. Pan Sýkora se již znovu ženit nehodlá, chce zůstat sám a tento způsob investice mu poradili jeho přátelé, kteří takto investovali již před pěti roky.","qs":[761,762,763,764,765]},{"id":"20507.1","text":"Pan Fiala se obrátil na svého investičního poradce se žádostí o posouzení svého záměru začít dlouhodobě pravidelně investovat do veřejně obchodovatelných akcií a dlouhodobých dluhopisů denominovaných v EUR. Tento jeho požadavek vyplývá z toho, že byl jmenován do vedoucí funkce, čímž se mu výrazně zvýšil jeho plat, ze kterého hodlá měsíčně proinvestovat 5000 Kč, a současně se chce připravit na vstup ČR do eurozóny (neboli na přechod z CZK na EUR). Proto také hodlá investovat výhradně do akcií a dluhopisů denominovaných v EUR. Uvedený investiční poradce s ním spolupracuje dlouhodobě, zná podrobně jeho celkovou finanční situaci a má k dispozici jeho aktualizovaný investiční dotazník.","qs":[766,767,768,769,770]},{"id":"20519.1","text":"Pan Dvořák požádal svého investičního poradce o návrh a následné zprostředkování nákupu dluhopisů, do kterých hodlá investovat dočasně volných 600 000 Kč, které nečekaně získal dědictvím. Tyto peníze bude potřebovat až za 5 let. Investiční poradce má k dispozici jeho aktuální investiční dotazník, přičemž ví, že nejde o příliš zkušeného investora, který však v daném případě přes svoji konzervativní povahu zamýšlí uskutečnit nákup dluhopisů, s jejichž výběrem chce poradit.","qs":[771,772,773,774,775]},{"id":"20537.1","text":"Dle poznatků z praxe se většina požadavků klientů investičního poradce (zde míněn VZIZ) týká kapitálových nebo peněžních trhů. Jak a s jakým cílem by měl poradce s klientem probrat následující otázky k doplnění jeho investičního profilu?","qs":[776,777,778,779,780]},{"id":"20543.1","text":"Potenciální klient oslovil vázaného zástupce investičního zprostředkovatele s žádostí o návrh investice v období ekonomické konjunktury.","qs":[781,782,783,784,785]},{"id":"20549.2","text":"Pan Syrovátka je svobodný muž středního věku a rozhodl se své úspory zhodnotit investováním na finančních trzích. Finanční investování je však vždy provázeno řadou různých rizik, což většina klientů sice teoreticky uznává, ale důsledky odmítá reálně akceptovat a vysvětlování rizik považuje za zdržovací techniku vázaných zástupců investičních zprostředkovatelů.","qs":[786,787,788,789,790]},{"id":"20555.1","text":"Předpokládejme následující modelovou situaci: Finanční poradce, který je vázaným zástupcem investičního zprostředkovatele a poskytuje investiční služby přijímání a předávání pokynů týkajících se investičních nástrojů (zprostředkování) a investiční poradenství (dále jen \"poradce\"), se sejde se svým klientem, který požaduje \"investovat do nějakého výhodného spoření na stáří\". Klientovi je 30 let, dosud nemá žádné zkušenosti s investováním, jeho příjem je mírně podprůměrný, z finančních produktů využívá pouze bankovní produkty a životní pojištění.","qs":[791,792,793,794,795]},{"id":"20561.2","text":"Oldřich Novák je majitelem několika prodejen se šperky, kterým se nadprůměrně daří. V současné době má značné množství volných finančních prostředků deponováno na spořicích účtech a termínovaných vkladech v bankách. Pan Novák už delší dobu přemýšlí, jak s těmito prostředky nejlépe naložit. Jednou zahlédl v odborném časopise nabídku na investice do akcií tzv. \"start- upových\" firem, přičemž reklama slibovala \"potenciál vysokých výnosů s nepřímo úměrným rizikem\". Pan Novák (dále jen \"klient\") si vzpomněl na svého kamaráda z dětství, který se mu před cca 8 lety prezentoval jako \"nezávislý finanční poradce\" a sjednal mu kompletní majetkové pojištění všech prodejen a podnikatelské odpovědnosti. Neváhal a kontaktoval jej s žádostí o konzultaci. \"Nezávislý finanční poradce\" je vázaným zástupcem investičního zprostředkovatele, který poskytuje hlavní inv. služby investiční poradenství a přijímání a předávání pokynů týkajících se inv. nástrojů (dále jen \"poradce\").","qs":[796,797,798,799,800]},{"id":"20567.7","text":"Uvažujte: Klient František Fošna, věk 40 let, vzdělání - střední škola stavební s maturitou, zaměstnán jako stavbyvedoucí s příjmem 35 000 Kč čistého měsíčně, příjmy z pronájmu bytu 10 000 Kč měsíčně, hodnota bytu k pronájmu 2 mil Kč. Náklady 30 000 Kč měsíčně, vlastní bydlení v hodnotě 2.5 mil Kč. Sjednané finanční produkty - stavební spoření (5 let) - aktuální hodnota 180 000 Kč, doplňkové penzijní spoření (4 roky) - aktuální hodnota 65 000 Kč, spořicí účet - 120 000 Kč, investiční životní pojištění (8 let) - kapitálová hodnota 220 000 Kč, pravidelná investice - 2 000 Kč/měsíčně do 60 let věku - aktuální hodnota - 70 000 Kč.","qs":[801,802,803,804,805]},{"id":"20579.2","text":"Společnost Silesian Wood s.r.o. je malá rodinná firma, která se zabývá vyřezáváním ozdobných ornamentů do dřeva. V současné době má na účtech u bank uloženo cca 2 miliony korun, které slouží jako rezerva pro případ nenadálých událostí. Společnost nicméně nepočítá s tím, že by je v blízké budoucnosti potřebovala využít na nějaký konkrétní účel, protože z pravidelného příjmu se společníci i zaměstnanci dobře uživí a do dalšího rozvoje firma investovat neplánuje. Pan Rostislav Rychlý, který o sobě tvrdí, že je investiční zprostředkovatel (dále jen \"zprostředkovatel\"), nabídl společnosti Silesian Wood s.r.o. (dále jen \"zákazník\"), že by jí část volných prostředků pomohl zainvestovat na kapitálovém trhu tak, aby dosáhla lepšího zhodnocení než na bankovních účtech. Zprostředkovatel se se zákazníkem domluvil na investici ve výši 1 milionu Kč na investiční horizont cca 5 let. Uvedené zadání se vztahuje ke všem následujícím otázkám.","qs":[806,807,808,809,810]},{"id":"20585.1","text":"Finanční poradce, vázaný zástupce investičního zprostředkovatele, který poskytuje službu investičního poradenství, se setkává s novým klientem, jehož požadavkem je vytvoření rezervy na stáří. Klientovi je 35 let, pracuje ve středním managementu nadnárodní stavební firmy v Praze.","qs":[811,812,813,814,815]},{"id":"20591.1","text":"Pracovník obchodníka s cennými papíry se setkává svým stávajícím klientem, jehož požadavkem je krátkodobé uložení prostředků v hodnotě 500 000 Kč, které potřebuje za tři roky použít na doplacení hypotéky ve stejné výši. Klient nemá jiné volné prostředky ani úspory.","qs":[816,817,818,819,820]},{"id":"20597.1","text":"Finanční poradce, vázaný zástupce investičního zprostředkovatele, který poskytuje službu investičního poradenství, se setkává s novým klientem, který by rád investoval do fixně úročených investičních nástrojů.","qs":[821,822,823,824,825]},{"id":"20603.1","text":"Finanční poradce, vázaný zástupce investičního zprostředkovatele, který poskytuje službu investičního poradenství, se setkává s novým klientem, jehož přáním je vytvořit finanční rezervu, která bude sloužit k finančnímu zabezpečení vysokoškolského studia jeho dnes nezletilé dcery.","qs":[826,827,828,829,830]},{"id":"20609.2","text":"Finanční poradce, vázaný zástupce investičního zprostředkovatele, který poskytuje službu investičního poradenství se setkává s novým klientem, jehož přáním je zainvestovat volné peníze, které nyní drží na svém běžném účtu a které použije v horizontu 12 až 18 měsíců na nákup pozemku.","qs":[831,832,833,834,835]},{"id":"20615.2","text":"Klienti sdělují investičnímu poradci, že jsou bez znalosti trhu a mají zájem investovat hlavně do akcií. Přivítali by také výnos v průběhu investice.","qs":[836,837,838,839,840]},{"id":"20621.2","text":"Klient má zájem investovat spíše konzervativně, preferuje dluhopisy a investici předpokládá pro časový horizont maximálně do 10 let.","qs":[841,842,843,844,845]},{"id":"20627.4","text":"Klient jde za svým investičním poradcem s žádostí o vysvětlení pojmu AÚV a praktickou ukázku výpočtu.","qs":[846,847,848,849,850]},{"id":"20633.4","text":"Klient je ve finanční tísni, chce v horizontu několika dní prodat akcie, dluhopisy a nepákové indexové certifikáty ze svého účtu. Nejde o profesionálního zákazníka a cenné papíry na účtu leží asi 10 let bez pohybu a klient se o své investice nijak nestaral. Jde proto za investičním zprostředkovatelem.","qs":[851,852,853,854,855]},{"id":"20651.1","text":"Mladý pár Petr (34) a Jana (32) se rozhodli využít služeb investičního zprostředkovatele. Oba jsou v zaměstnaneckém poměru na dobu neurčitou, kdy Petrův čistý měsíční příjem činí 23 500 Kč a Jana přispívá do společné kasy částkou 21 800 Kč čistého. Průměrné měsíční výdaje (bez jakýchkoliv finančních produktů) činí přibližně 18-19 000 Kč. Oba dva o sobě tvrdí, že jsou spíše konzervativními klienty, navíc s investováním nemají prakticky žádné zkušenosti. Jejich jediné působení na finančním trhu bylo, že si Petr založil stavební spoření a Jana má Doplňkové penzijní spoření s vyváženou strategií.","qs":[856,857,858,859,860]},{"id":"20669.5","text":"Pan Průměrný (35 let) se poprvé obrátil na svého finančního poradce, vázaného zástupce investičního zprostředkovatele, který poskytuje službu investičního poradenství. Potřebuje s poradcem vyřešit dvě základní věci - nastavení finanční rezervy a zajištění rezervy (ochranu) kapitálu na stáří.","qs":[861,862,863,864,865]},{"id":"20675.1","text":"Pan Nedočkavý se obrátil na finančního poradce, který je vázaným zástupcem investičního zprostředkovatele, s tím, že by chtěl jednorázově investovat 250 000 Kč, které získal jako náhradu škody po vítězném soudním řízení. Pan Nedočkavý dosud žádné investice nerealizoval, má zkušenosti s KŽP a je účastníkem transformovaného fondu.","qs":[866,867,868,869,870]},{"id":"20681.1","text":"Pan Uvážlivý (42 let) by rád se svojí manželkou (40 let) začal zhodnocovat peněžní prostředky na finančním trhu. V současné době jsou nespokojeni s téměř nulovým či procentním výnosem na jejich běžném či spořicím účtu. Oba dva mají uzavřené doplňkové penzijní spoření, do kterého přestoupili již v roce 2014.","qs":[871,872,873,874,875]},{"id":"20687.3","text":"Pan Vychytralý (45 let), který provozuje restauraci a síť rychlých občerstvení (10 poboček v krajských městech) by rád využil služeb finančního poradce, který je vázaným zástupcem investičního zprostředkovatele, k zainvestování a dosažení zajímavého výnosu.","qs":[876,877,878,879,880]},{"id":"20705.3","text":"Jako vázaný zástupce investičního zprostředkovatele poskytujete zákazníkovi investiční službu přijímání a předávání pokynů. Obsah této služby jste zákazníkovi náležitě vysvětlil(a).","qs":[881,882,883,884,885]},{"id":"20711.2","text":"Jako vázaný zástupce investičního zprostředkovatele poskytujete zákazníkovi investiční službu investiční poradenství. Obsah této služby jste zákazníkovi náležitě vysvětlil(a).","qs":[886,887,888,889,890]},{"id":"20723.1","text":"Představte si modelovou situaci: Investiční zprostředkovatel je osloven s žádostí o radu ze strany svého klienta, který obdržel nabídku na investici do dluhopisů o objemu až 50 milionů Kč a úrokovým výnosem ve výši 9 % p. a., vypláceným jednou ročně, jež budou vydány dle českého práva menší akciovou společností realizující developerský projekt. Prospekt cenného papíru schválený příslušnou veřejnoprávní autoritou a další dokumenty týkající s emise dluhopisů jsou uveřejněny i na internetových stránkách emitenta. Zhodnoťte tuto situaci a také investici na základě níže uvedených informací obsažených v nabídkové dokumentaci.","qs":[891,892,893,894,895]},{"id":"20729.1","text":"Na příslušného zaměstnance obchodníka s cennými papíry se obrátí klient, který prostřednictvím tohoto obchodníka v minulosti nabyl akcie vydané akciovou společností se sídlem v České republice. Akcie jsou přijaty k obchodování na regulovaný trh v České republice a klient obdržel pozvánku na valnou hromadu, která má přijmout usnesení o vyřazení daných akcií z obchodování na regulovaném trhu, tedy o ukončení obchodování s těmito akciemi na regulovaném trhu na žádost emitenta.","qs":[896,897,898,899,900]},{"id":"20735.2","text":"Investiční zprostředkovatel je osloven ze strany obhospodařovatele fondu kvalifikovaných investorů, usídleného v České republice, s žádostí o zajištění distribuce účastnických cenných papírů tohoto fondu. Zodpovězte následující:","qs":[901,902,903,904,905]},{"id":"20741.1","text":"Občan navštívil vázaného zástupce obchodníka s cennými papíry za účelem nákupu investičního nástroje (poskytuje investiční poradenství).","qs":[906,907,908,909,910]},{"id":"20747.2","text":"Vázaný zástupce investičního zprostředkovatele jedná se zákazníkem - poskytuje radu týkající se investičního nástroje z oblasti kolektivního investování.","qs":[911,912,913,914,915]},{"id":"20753.2","text":"Jaký bude váš postup v postavení vázaného zástupce investičního zprostředkovatele při prvním jednání se zákazníkem (potenciálním zákazníkem) při poskytování služby investiční poradenství týkající se investičních nástrojů?","qs":[916,917,918,919,920]},{"id":"20759.1","text":"Jako vázaný zástupce obchodníka s cennými papíry přijímáte pokyny zákazníků, popř. uzavíráte se zákazníky smlouvy o nákupu a prodeji cenných papírů. Zároveň prostřednictvím tohoto obchodníka s cennými papíry uzavíráte svoje vlastní obchody.","qs":[921,922,923,924,925]},{"id":"20765.1","text":"Jakým způsobem budete postupovat v situaci, kdy váš stávající zákazník projevuje zájem o úpis listinných tuzemských korporátních dluhopisů, a to z pohledu pracovníka (osoby jednající se zákazníkem) investičního zprostředkovatele?","qs":[926,927,928,929,930]},{"id":"20771.1","text":"Pan Svoboda prodal významnou část podílu ve své firmě. Nyní hledá nezávislého poradce, který mu poskytne investiční poradenství ohledně získaných prostředků. Určitě je nebude potřebovat v následujících 15 letech a pak by z nich chtěl začít čerpat rentu. Obává se však, že mohou nastat období vysoké inflace. Jde mu především o to, aby jeho portfolio přinášelo výnosy vyšší než inflace. Obrátí se na poradenskou společnost Jackson Steinem s.r.o.","qs":[931,932,933,934,935]},{"id":"20777.3","text":"Na investičního poradce (vázaného zástupce investičního zprostředkovatele) se obrátili Adam a Eva. Oba mají 30 let a plánují společný život. Chtějí poradit s naplněním své finanční nezávislosti, což pro ně znamená mít ve svých 60 letech 3 mil. Kč. Adam má čistý příjem 30 000 Kč měsíčně, Eva 20 000 Kč měsíčně. Jejich výdaje jsou celkem 40 000 Kč měsíčně (včetně splátky hypotéky 15 000 Kč měsíčně).","qs":[936,937,938,939,940]},{"id":"20783.1","text":"Dvořákovi mají k dispozici 15 milionů z úspor a prodeje nemovitostí. Je jim 55 let. Z těchto peněz chtějí čerpat rentu. Ideálně takovou, aby dlouhodobě majetek neubýval a zdědily ho následně jejich děti. S žádostí o radu se obrátí na několik poradců.","qs":[941,942,943,944,945]},{"id":"20789.1","text":"Na investičního poradce (vázaného zástupce investičního zprostředkovatele) se obrátil Tomáš Marný (45 let). Jeho příjem je 60 000 Kč měsíčně, výdaje 50 000 Kč měsíčně. Do 3 let si chce koupit vlastní byt v hodnotě kolem 3 000 000 Kč. Poradce nemá povolení k poskytování služby investičního poradenství. Uvažujte s tím, že banky poskytují hypotéky s LTV 80 %.","qs":[946,947,948,949,950]},{"id":"20795.3","text":"Manželé Šetrní (oba 37 let) mají 2 děti: Jeníčka (10 let) a Mařenku (2 roky). Na investičního poradce (vázaného zástupce investičního zprostředkovatele) se obrátili s požadavkem na investování do podílových fondů na vzdělání obou dětí. S poradcem se znají, investují s ním již 10 let do dluhopisových fondů.","qs":[951,952,953,954,955]},{"id":"20801.1","text":"Poradce by měl být schopen zpracovat analýzu finanční situace (portfolio) zákazníka, vyhodnotit ji a vypracovat nezávislou optimalizaci způsobů alokace jeho aktiv.","qs":[956,957,958,959,960]},{"id":"20807.1","text":"Manželé Novákovi se obrátili na investičního poradce (vázaného zástupce investičního zprostředkovatele) s žádostí o posouzení nabídky spočívající v nákupu dluhopisu společnosti 1. Dluhopisová a.s. Nabídka jim byla učiněna v rámci tzv. neveřejného nabízení dluhopisu (private placement), přičemž emitent má jen velmi krátkou podnikatelskou historii s omezenými veřejně dostupnými informacemi o svém hospodaření, k dluhopisu nebyl vystaven tzv. prospekt.","qs":[961,962,963,964,965]},{"id":"20813.2","text":"Pan Smetana se na investičního poradce (vázaného zástupce obchodníka s cennými papíry) obrátil s žádostí o optimalizaci svého investičního portfolia. Poradce z předložených dokumentů zjistil, že pan Smetana drží převážně akciové fondy s předplaceným vstupním poplatkem.","qs":[966,967,968,969,970]},{"id":"20819.2","text":"Distributor neposkytuje službu investičního poradenství, ale pouze přijímání a předávání pokynu.","qs":[971,972,973,974,975]},{"id":"20825.2","text":"Investiční poradce (vázaný zástupce investičního zprostředkovatele) oslovil manžele Procházkovy, kteří mají zájem pravidelně investovat s cílem akumulace kapitálu na důchod. Odchod do důchodu svorně plánují v horizontu 30 let a mají přitom již založeno doplňkové penzijní spoření (DPS) s úložkou 2 000 Kč měsíčně, investované v konzervativním fondu. Na další investici mohou uvolnit maximálně 500 Kč měsíčně.","qs":[976,977,978,979,980]},{"id":"22460.3","text":"Pan Jaroslav Vokurka (dále jen \"klient\") je mechanik ve společnosti Robozone s.r.o., která se zabývá montáží robotických pracovišť a jejich vývozem zejména do Německa a Francie. Klient vydělává cca 30 000 Kč čistého měsíčně, má hypoteční úvěr (HÚ) na 10 000 Kč/měs. a platí alimenty na své dvě děti ve výši 8 000 Kč/měs. Klient již má určité zkušenosti s investováním, protože na střední škole zkoušel nakupovat a prodávat akcie, čímž si přivydělával na živobytí - v průměru vydělal cca 5 000 Kč/měs. Klientovi nedávno zavolal jeho bývalý spolužák, který \"dělá do financí\" (dále jen \"poradce\") s tím, že by mu rád představil nové možnosti zhodnocení volných finančních prostředků. Poradce je zaměstnanec vázaného zástupce obchodníka s cennými papíry a poskytuje mj. inv. službu investiční poradenství týkající se investičních nástrojů.","qs":[981,982,983,984,985]},{"id":"22472.1","text":"Na poradce (vázaného zástupce investičního zprostředkovatele) se obrátil pan Strnad, který zamýšlí investovat jednorázově prostředky získané dědictvím po prarodičích.","qs":[986,987,988,989,990]}]};
